INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct, client_needs_category, client_needs_subcategory, nursing_subject, body_system, topic, subtopic, difficulty, bloom_level, tags, marks, is_published, is_builder_visible, is_free_sample, batch_id, question_ref
) VALUES
('NCLEX_MAT_399001', 'MATRIX', 'For each finding, click to specify whether it is associated with hypothyroidism or hyperthyroidism.', 'Hypothyroidism slows metabolism; hyperthyroidism accelerates it.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Weight gain"},{"id":"r2","text":"Heat intolerance"},{"id":"r3","text":"Bradycardia"},{"id":"r4","text":"Exophthalmos"}],"columns":[{"id":"c1","text":"Hypothyroidism"},{"id":"c2","text":"Hyperthyroidism"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Thyroid disorders', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_399001', 'MATRIX_MR', 'For each medication, select all appropriate routes of administration (may support more than one).', 'Routes reflect each drug''s approved administration options.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Regular insulin"},{"id":"r2","text":"Ondansetron"},{"id":"r3","text":"Ceftriaxone"}],"columns":[{"id":"c1","text":"Oral"},{"id":"c2","text":"IV"},{"id":"c3","text":"IM"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1","c2","c3"],"r3":["c2","c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication routes', NULL, 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_399001', 'HIGHLIGHT', 'Highlight the findings that require immediate follow-up. Client reports feeling a little better. Temperature [[37.0°C]]. SpO2 93% on 4L. BP [[184/96]]. HR [[118]]. Urine output [[15 mL/hr]]. Reports [[new-onset chest pressure]].', 'Elevated BP/HR, oliguria, and new chest pressure are all concerning cues.', '{"chunks":[{"id":"h1","text":"37.0°C"},{"id":"h2","text":"184/96"},{"id":"h3","text":"118"},{"id":"h4","text":"15 mL/hr"},{"id":"h5","text":"new-onset chest pressure"}]}'::jsonb, '{"correct_ids":["h2","h3","h4","h5"],"feedback":{"h1":"Normal temperature — no follow-up needed.","h2":"Hypertensive range — needs follow-up.","h3":"Tachycardia — needs follow-up.","h4":"Oliguria — needs follow-up.","h5":"Possible cardiac ischemia — urgent."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Assessment cues', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_399001', 'BOWTIE', 'Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'HF exacerbation is managed with diuresis and positioning, monitoring weight and oxygenation.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer prescribed diuretic"},{"id":"lt2","text":"Position upright"},{"id":"lt3","text":"Restrict fluids to 3 L/day"},{"id":"lt4","text":"Encourage ambulation"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Heart failure exacerbation"},{"id":"ct2","text":"Pulmonary embolism"},{"id":"ct3","text":"Pneumothorax"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Daily weight"},{"id":"rt2","text":"Oxygen saturation"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Pupil size"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Heart failure', NULL, 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357001', 'MCQ', 'A client receiving continuous nasogastric tube feedings has a gastric residual volume of 280 mL, faint bowel sounds, and reports mild nausea. The head of the bed is at 30 degrees. Which action should the nurse take FIRST?', 'With delayed gastric emptying and nausea, raising the head of the bed is the fastest independent action to reduce aspiration risk before further steps.', '{"options":[{"id":"A","text":"Stop the feeding and reassess residual in one hour"},{"id":"B","text":"Raise the head of the bed to at least 45 degrees"},{"id":"C","text":"Flush the tube with 60 mL of water"},{"id":"D","text":"Notify the provider to request a prokinetic agent"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. A single elevated residual with symptoms warrants first reducing aspiration risk, not automatic cessation before repositioning.","B":"Correct. Optimizing head elevation immediately reduces aspiration risk while the nurse continues assessing tolerance.","C":"Incorrect. Flushing does not address the immediate aspiration risk from delayed emptying.","D":"Incorrect. Notification may follow, but the immediate priority is reducing aspiration risk."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral tube feeding', 'Aspiration prevention', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357002', 'MCQ', 'A nurse assesses a bedbound client and finds an area over the sacrum with intact skin that is non-blanchable, deep red-purple, and boggy compared with surrounding tissue. How should the nurse document this finding?', 'Non-blanchable deep discoloration over intact, boggy skin describes a deep tissue pressure injury, distinct from stage 1 erythema.', '{"options":[{"id":"A","text":"Stage 1 pressure injury"},{"id":"B","text":"Stage 2 pressure injury"},{"id":"C","text":"Deep tissue pressure injury"},{"id":"D","text":"Unstageable pressure injury"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. Stage 1 is non-blanchable erythema without the deep discoloration and tissue change suggesting deeper damage.","B":"Incorrect. Stage 2 involves partial-thickness skin loss, not intact skin.","C":"Correct. Intact skin with persistent deep red/purple discoloration and boggy texture indicates a deep tissue pressure injury.","D":"Incorrect. Unstageable involves full-thickness loss obscured by slough or eschar, not intact skin."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Integumentary', 'Pressure injury prevention', 'Staging', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357003', 'MCQ', 'A client in balanced skeletal traction for a femur fracture states the weights are dragging on the floor after the bed was moved. What should the nurse do?', 'Traction weights must hang freely and continuously; the nurse repositions the bed to restore free-hanging pull without removing or altering weights.', '{"options":[{"id":"A","text":"Reposition the bed so the weights hang freely"},{"id":"B","text":"Remove the weights until the provider evaluates alignment"},{"id":"C","text":"Add padding under the weights to keep them off the floor"},{"id":"D","text":"Reduce the amount of weight to relieve tension"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Weights must hang freely to maintain the prescribed pull; the nurse restores this immediately.","B":"Incorrect. Skeletal traction weights are never removed by the nurse; doing so disrupts the therapeutic pull.","C":"Incorrect. Supporting the weights negates the traction force.","D":"Incorrect. The nurse does not alter prescribed weight."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal', 'Orthopedic devices', 'Skeletal traction', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357004', 'MCQ', 'A client with continuous bladder irrigation after a transurethral prostate resection has bright-red drainage with clots, and the output in the collection bag is less than the volume of irrigant infused. The client reports bladder fullness and spasms. What is the nurse''s priority action?', 'Output less than irrigant infused plus clots and fullness indicates obstruction; the nurse clears the catheter to restore outflow and relieve distension.', '{"options":[{"id":"A","text":"Administer the prescribed antispasmodic"},{"id":"B","text":"Increase the irrigation flow rate"},{"id":"C","text":"Assess for and manually irrigate to clear catheter obstruction"},{"id":"D","text":"Clamp the catheter and notify the provider"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. Spasms here signal obstruction; relieving the blockage comes before treating the symptom.","B":"Incorrect. Increasing inflow into an obstructed system worsens distension.","C":"Correct. Output less than inflow with clots and fullness indicates catheter obstruction, which must be cleared to prevent bladder distension.","D":"Incorrect. Clamping an obstructed, distended bladder increases pressure and injury risk."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Bladder irrigation', 'Continuous bladder irrigation', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357005', 'MCQ', 'A client with chronic low back pain that flares with activity asks about nondrug options. The client bruises easily on anticoagulation and has diminished lower-extremity sensation. Which nonpharmacologic measure is MOST appropriate for the nurse to recommend?', 'Given anticoagulation and sensory deficit, relaxation techniques are the safest nonpharmacologic option, avoiding bleeding and thermal-injury risks.', '{"options":[{"id":"A","text":"Deep tissue massage over the lumbar region"},{"id":"B","text":"Application of a heating pad on the highest setting"},{"id":"C","text":"Guided imagery and paced breathing during flares"},{"id":"D","text":"Ice packs applied directly to bare skin for 30 minutes"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. Vigorous massage risks bruising in an anticoagulated client.","B":"Incorrect. High heat with diminished sensation risks burns.","C":"Correct. Cognitive-behavioral relaxation carries no bleeding or thermal-injury risk and is appropriate for this client.","D":"Incorrect. Prolonged direct cold with sensory deficit risks tissue injury."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Nonpharmacologic pain management', 'Cutaneous stimulation', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357006', 'MCQ', 'A client recovering from a stroke has dysphagia. During lunch the nurse observes coughing after thin liquids, a wet-sounding voice, and pocketing of food in the affected cheek. Which action best addresses the underlying problem?', 'Coughing on thin liquids, a wet voice, and pocketing indicate aspiration risk; thickened liquids plus checking for retained food are the appropriate interventions.', '{"options":[{"id":"A","text":"Encourage the client to drink water quickly to clear the throat"},{"id":"B","text":"Request evaluation for thickened liquids and check for pocketed food after each bite"},{"id":"C","text":"Have the client tilt the head backward to ease swallowing"},{"id":"D","text":"Offer larger bites to trigger a stronger swallow reflex"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Rapid thin-liquid intake increases aspiration in dysphagia.","B":"Correct. Thickened liquids and checking for pocketing directly reduce aspiration risk in this client.","C":"Incorrect. A chin-tuck, not head extension, protects the airway.","D":"Incorrect. Smaller bites are safer with dysphagia."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Nutrition status', 'Dysphagia diet', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357007', 'MCQ', 'A client with left-sided knee osteoarthritis is being taught to use a single-point cane. Which instruction indicates the nurse''s teaching is correct?', 'A cane is held on the side opposite the affected limb and advanced simultaneously with the weaker leg to offload the affected joint.', '{"options":[{"id":"A","text":"Hold the cane in the left hand and advance it with the left leg"},{"id":"B","text":"Hold the cane in the right hand and advance it with the left leg"},{"id":"C","text":"Hold the cane in the right hand and advance it with the right leg"},{"id":"D","text":"Hold the cane in either hand as long as it feels comfortable"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. The cane is held on the stronger (right) side for a left-sided weakness.","B":"Correct. The cane is held opposite the affected leg and moves together with the weaker leg to share the load.","C":"Incorrect. The cane advances with the weaker leg, not the stronger one.","D":"Incorrect. Correct side placement is essential for stability and load-sharing."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', 'Cane use', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357008', 'MCQ', 'A client has died and the family has consented to corneal donation. Which nursing action best supports the donation while providing postmortem care?', 'For corneal donation, closing the eyelids and applying cool compresses with the head flat helps preserve tissue integrity.', '{"options":[{"id":"A","text":"Lower the head of the bed flat and apply cold compresses over the eyes with the eyelids closed"},{"id":"B","text":"Instill antibiotic ointment into both eyes and tape the lids open"},{"id":"C","text":"Elevate the head of the bed 30 degrees and place warm packs over the eyes"},{"id":"D","text":"Remove all tubes and lines immediately before the donation team arrives"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Elevating is not needed; closing the lids and applying cold compresses preserve corneal tissue for donation.","B":"Incorrect. Ointment and open lids can damage or contaminate corneal tissue.","C":"Incorrect. Warmth accelerates tissue degradation.","D":"Incorrect. Lines are generally left in place per policy until confirmed."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Postmortem care', 'Organ donation', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357009', 'MCQ', 'Over an 8-hour shift a client had oral intake of 480 mL, IV fluids of 600 mL, and 200 mL of tube-feed flushes. Output was urine 900 mL, emesis 150 mL, and drain output 120 mL. The client''s daily weight rose 0.9 kg. How should the nurse interpret these findings?', 'Intake (480+600+200=1280) exceeds output (900+150+120=1170) by 110 mL; combined with a 0.9 kg gain this indicates positive balance and possible fluid retention.', '{"options":[{"id":"A","text":"Net positive balance consistent with the weight gain, warranting monitoring for fluid overload"},{"id":"B","text":"Net negative balance indicating dehydration"},{"id":"C","text":"Balanced intake and output with no clinical concern"},{"id":"D","text":"Output error, since output cannot include emesis and drainage"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Intake 1280 mL exceeds output 1170 mL, a net positive that aligns with the ~0.9 kg gain and signals possible retention.","B":"Incorrect. Intake exceeds output, so the balance is positive.","C":"Incorrect. There is a net positive balance plus weight gain.","D":"Incorrect. Emesis and drainage are legitimate measured output."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Intake and output', 'Fluid balance calculation', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357010', 'MCQ', 'An older adult hospitalized client reports frequent night awakenings and daytime fatigue. Which intervention should the nurse implement FIRST to promote sleep?', 'Environmental modifications such as clustering care and reducing noise and light are the first-line, lowest-risk sleep-promotion strategy for hospitalized older adults.', '{"options":[{"id":"A","text":"Request a prescription for a benzodiazepine hypnotic"},{"id":"B","text":"Cluster nighttime care and reduce noise and light during sleep hours"},{"id":"C","text":"Encourage a long afternoon nap to make up lost sleep"},{"id":"D","text":"Offer caffeinated tea in the evening to prevent early awakening"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Hypnotics, especially benzodiazepines, carry fall and delirium risk in older adults and are not first-line.","B":"Correct. Nonpharmacologic environmental measures address the modifiable cause of fragmented hospital sleep first.","C":"Incorrect. Extended daytime naps further disrupt the sleep-wake cycle.","D":"Incorrect. Caffeine impairs sleep onset and maintenance."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Sleep and rest', 'Sleep hygiene', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_357011', 'MCQ', 'Six hours after a below-the-knee fiberglass cast is applied, a client reports increasing deep pain unrelieved by opioids, and the toes are cool with sluggish capillary refill. Which action should the nurse take FIRST?', 'Deep, unrelieved pain with neurovascular compromise after casting indicates compartment syndrome, a surgical emergency requiring immediate provider notification.', '{"options":[{"id":"A","text":"Elevate the extremity and apply ice over the cast"},{"id":"B","text":"Reassure the client that pain is expected after casting"},{"id":"C","text":"Notify the provider immediately of possible compartment syndrome"},{"id":"D","text":"Administer an additional dose of the prescribed opioid"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. These worsening neurovascular signs suggest compartment syndrome; elevation above heart level and cold can reduce perfusion further.","B":"Incorrect. Escalating, opioid-unrelieved pain with poor perfusion is an emergency, not expected.","C":"Correct. Increasing unrelieved pain with cool, poorly perfused toes signals compartment syndrome requiring urgent provider notification.","D":"Incorrect. Medicating masks a limb-threatening emergency."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal', 'Orthopedic devices', 'Cast care', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_357012', 'TF', 'When a nasogastric feeding tube''s placement is being verified before an intermittent feeding, a pH of 6.5 from the aspirate reliably confirms correct gastric placement.', 'Gastric aspirate is typically acidic (pH 5 or less); a higher pH of 6.5 raises concern for respiratory or intestinal placement and does not confirm gastric position.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral tube feeding', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_357013', 'TF', 'For a client with hemiparesis after a stroke, performing passive range-of-motion on the affected limb helps prevent contractures but does not maintain muscle strength in that limb.', 'Passive ROM preserves joint mobility and prevents contractures; because the client is not actively contracting the muscle, it does not build or maintain strength in the affected limb.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Mobility and range of motion', NULL, 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_357014', 'SATA', 'A nurse plans care for an immobile, incontinent, undernourished client to prevent pressure injuries. Which interventions are appropriate? Select all that apply.', 'Repositioning, moisture and skin protection, nutritional optimization, and gentle skin care prevent pressure injuries; high elevation, vigorous massage, and direct trochanter pressure increase risk.', '{"options":[{"id":"A","text":"Reposition at least every 2 hours and offload bony prominences"},{"id":"B","text":"Use a barrier cream and change incontinence products promptly"},{"id":"C","text":"Elevate the head of the bed to 90 degrees for most of the day"},{"id":"D","text":"Consult dietitian for protein and calorie optimization"},{"id":"E","text":"Massage reddened bony prominences vigorously to improve circulation"},{"id":"F","text":"Keep the skin clean and dry using pH-balanced cleansers"},{"id":"G","text":"Place the client directly on the trochanter in the side-lying position"}]}'::jsonb, '{"answers":["A","B","D","F"],"feedback":{"C":"Incorrect. High elevation increases shear and sacral pressure.","E":"Incorrect. Massaging compromised tissue over bony prominences can worsen damage.","G":"Incorrect. Use a 30-degree lateral tilt to avoid direct pressure on the trochanter."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Integumentary', 'Pressure injury prevention', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_357015', 'SATA', 'A nurse develops a plan to manage constipation for an older adult client on opioid therapy. Which interventions should the nurse include? Select all that apply.', 'Fiber with fluids, scheduled toileting, mobility, and a prophylactic stimulant laxative address opioid-induced constipation; fluid restriction and routine enemas are inappropriate.', '{"options":[{"id":"A","text":"Increase dietary fiber gradually with adequate fluid intake"},{"id":"B","text":"Encourage a scheduled toileting routine, ideally after meals"},{"id":"C","text":"Promote physical activity and ambulation as tolerated"},{"id":"D","text":"Withhold all fluids to firm the stool"},{"id":"E","text":"Anticipate a prescribed stimulant laxative regimen for opioid-induced constipation"},{"id":"F","text":"Encourage routine daily use of enemas as first-line therapy"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"D":"Incorrect. Restricting fluids worsens constipation.","F":"Incorrect. Routine enemas are not first-line and can cause dependence and injury."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Bowel elimination', 'Constipation', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_357016', 'SATA', 'A nurse assesses pain in a nonverbal client with advanced dementia. Which observations are valid behavioral indicators of pain? Select all that apply.', 'In nonverbal clients, facial expressions, body movements, vocalizations, and agitation are valid behavioral pain indicators.', '{"options":[{"id":"A","text":"Grimacing and furrowed brow"},{"id":"B","text":"Guarding and rubbing a body area"},{"id":"C","text":"Restlessness and agitation"},{"id":"D","text":"Slow, deep, regular respirations at rest"},{"id":"E","text":"Moaning or crying out during repositioning"},{"id":"F","text":"Increased social engagement and smiling"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"D":"Incorrect. Relaxed regular breathing is not an indicator of pain.","F":"Incorrect. These are not pain behaviors."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Pain assessment', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_357017', 'SATA', 'A postoperative client has not voided 7 hours after catheter removal, reports lower abdominal fullness, and has a palpable bladder. Which nursing measures should the nurse try before catheterization? Select all that apply.', 'Positioning, sensory triggers, privacy, and perineal warmth promote spontaneous voiding; forceful pressure and fluid restriction are inappropriate.', '{"options":[{"id":"A","text":"Assist the client to a normal voiding position"},{"id":"B","text":"Run warm water or provide the sound of running water"},{"id":"C","text":"Provide privacy and unhurried time to void"},{"id":"D","text":"Apply firm continuous suprapubic pressure to force voiding"},{"id":"E","text":"Pour warm water over the perineum"},{"id":"F","text":"Restrict oral fluids until the client voids"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"D":"Incorrect. Forceful pressure on a distended bladder risks injury and reflux.","F":"Incorrect. Fluid restriction does not help and may not be indicated."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Bladder elimination', 'Urinary retention', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_357018', 'SATA', 'A nurse provides perineal care for a dependent adult client. Which actions preserve the client''s dignity and privacy? Select all that apply.', 'Ensuring privacy, explaining care, minimizing exposure, and promoting participation protect client dignity; public discussion and unnecessary exposure do not.', '{"options":[{"id":"A","text":"Close the door and pull the privacy curtain before beginning"},{"id":"B","text":"Explain each step and obtain the client''s cooperation"},{"id":"C","text":"Expose only the area being cleaned and keep the rest draped"},{"id":"D","text":"Discuss the client''s incontinence with the roommate present"},{"id":"E","text":"Offer the client the option to assist with any part of care they can"},{"id":"F","text":"Leave the client uncovered to speed the procedure"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"D":"Incorrect. Discussing private matters within earshot breaches confidentiality and dignity.","F":"Incorrect. Unnecessary exposure violates dignity."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Dignity and privacy', NULL, 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_357019', 'SELECT_N', 'A nurse screens a frail older adult for undernutrition. Which 3 findings most strongly support a nutritional deficit requiring intervention?', 'Significant unintentional weight loss, declining albumin with impaired healing, and muscle/fat wasting are strong indicators of undernutrition needing intervention.', '{"options":[{"id":"A","text":"Unintentional loss of 6% body weight over one month"},{"id":"B","text":"Serum albumin trending downward with poor wound healing"},{"id":"C","text":"Temporal wasting and loss of subcutaneous fat"},{"id":"D","text":"Stable weight with a balanced appetite"},{"id":"E","text":"Recent 1 kg weight gain from prescribed supplements"},{"id":"F","text":"Normal hand-grip strength and energy level"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"D":"Incorrect. This suggests adequate nutrition.","E":"Incorrect. Gain from supplementation is a favorable response.","F":"Incorrect. Preserved function argues against significant deficit."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Nutrition status', 'Malnutrition indicators', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_357020', 'SELECT_N', 'A nurse positions an unconscious client in the lateral recovery position. Which 2 actions best prevent complications of immobility and positioning?', 'Supporting the upper limbs in alignment and maintaining neutral ankle position prevent joint strain, contracture, and footdrop in the lateral position.', '{"options":[{"id":"A","text":"Support the upper arm and leg with pillows to maintain alignment"},{"id":"B","text":"Place a small pillow or roll to keep the ankle in a neutral position preventing footdrop"},{"id":"C","text":"Position the dependent arm trapped beneath the trunk"},{"id":"D","text":"Allow the head to hyperextend without support"},{"id":"E","text":"Keep the knees fully extended and pressed together"},{"id":"F","text":"Leave the client in one position for the entire shift"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{"C":"Incorrect. A trapped dependent arm compromises circulation and nerves.","D":"Incorrect. An unsupported hyperextended neck risks airway and strain.","E":"Incorrect. This causes pressure between the knees and poor alignment.","F":"Incorrect. Prolonged single positioning causes pressure injury."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Positioning', 'Immobility complications', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_357021', 'MATRIX', 'For each nursing action, click to indicate whether it applies to an ear irrigation or an eye irrigation.', 'Eye irrigation flows from inner to outer canthus with a basin at the cheek; ear irrigation uses body-temperature fluid aimed along the canal with the pinna pulled up and back in adults.', '{"row_label":"Action","rows":[{"id":"r1","text":"Direct the solution toward the inner canthus flowing to the outer canthus"},{"id":"r2","text":"Pull the pinna up and back for an adult to straighten the canal"},{"id":"r3","text":"Aim the fluid along the side of the canal, not directly at the eardrum"},{"id":"r4","text":"Have the client hold an emesis basin against the cheek below the eye"},{"id":"r5","text":"Warm the solution to near body temperature to prevent vertigo"}],"columns":[{"id":"c1","text":"Ear irrigation"},{"id":"c2","text":"Eye irrigation"}]}'::jsonb, '{"cells":{"r1":"c2","r2":"c1","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Irrigations', 'Ear and eye irrigation', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_357022', 'MATRIX_MR', 'For each nonpharmacologic comfort measure, select all mechanisms by which it is thought to relieve pain (more than one may apply).', 'Cold provides cutaneous stimulation and reduces swelling; imagery works cognitively; TENS uses gate-control; massage combines cutaneous stimulation with relaxation.', '{"row_label":"Comfort measure","rows":[{"id":"r1","text":"Cold application to an acute ankle sprain"},{"id":"r2","text":"Guided imagery during a painful dressing change"},{"id":"r3","text":"TENS unit over the lower back"},{"id":"r4","text":"Massage of tense shoulder muscles"}],"columns":[{"id":"c1","text":"Gate-control / cutaneous stimulation"},{"id":"c2","text":"Cognitive-behavioral / distraction"},{"id":"c3","text":"Reduces local inflammation/swelling"}]}'::jsonb, '{"cells":{"r1":["c1","c3"],"r2":["c2"],"r3":["c1"],"r4":["c1","c2"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Nonpharmacologic comfort measures', NULL, 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_357023', 'CLOZE', 'A client on continuous enteral feeding develops frequent loose stools. The nurse suspects the diarrhea is most likely caused by {1}, and the priority initial nursing response is to {2}.', 'Enteral-feeding diarrhea is commonly from a rapid rate or hyperosmolar formula; the nurse first slows the rate and assesses formula and contributing medications before other measures.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"a rapid formula infusion rate or hyperosmolar formula"},{"id":"c2","text":"inadequate free-water flushes"},{"id":"c3","text":"cold formula temperature alone"}]},{"id":"b2","choices":[{"id":"c1","text":"slow the infusion rate and assess the formula and medications"},{"id":"c2","text":"stop all feedings permanently"},{"id":"c3","text":"administer an antidiarrheal before assessment"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'GI', 'Enteral tube feeding', 'Complication management', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_357024', 'HIGHLIGHT', 'The nurse reviews a bedbound client''s skin assessment for findings that increase pressure-injury risk and require intervention. Skin is [[warm and dry with intact turgor]]. There is [[non-blanchable redness over the right heel]]. The sacrum shows [[moist, macerated skin from incontinence]]. Nutrition note: [[albumin 2.4 g/dL]]. The client is [[repositioned every 2 hours]]. There is [[a friction blister on the left elbow]].', 'Non-blanchable heel redness, maceration, low albumin, and a friction blister are risk findings needing intervention; intact skin and 2-hourly repositioning are not concerns.', '{"chunks":[{"id":"h1","text":"warm and dry with intact turgor"},{"id":"h2","text":"non-blanchable redness over the right heel"},{"id":"h3","text":"moist, macerated skin from incontinence"},{"id":"h4","text":"albumin 2.4 g/dL"},{"id":"h5","text":"repositioned every 2 hours"},{"id":"h6","text":"a friction blister on the left elbow"}]}'::jsonb, '{"correct_ids":["h2","h3","h4","h6"],"feedback":{"h1":"Normal skin — not a risk finding.","h2":"Stage 1 pressure injury — requires intervention.","h3":"Moisture-associated damage increases breakdown risk.","h4":"Low albumin impairs healing and raises risk.","h5":"This is an appropriate preventive measure, not a risk finding.","h6":"Friction injury indicates existing tissue damage."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Integumentary', 'Skin and tissue integrity', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_357025', 'BOWTIE', 'A postoperative client has not voided for 8 hours, reports suprapubic discomfort, and a bladder scan shows 620 mL. Complete the diagram by selecting the condition, priority actions, and parameters to monitor.', 'A 620 mL bladder with no voiding is acute urinary retention; the nurse tries noninvasive measures then catheterizes, monitoring bladder-scan and voided volumes.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Attempt noninvasive voiding-promotion measures"},{"id":"lt2","text":"Perform intermittent catheterization if measures fail"},{"id":"lt3","text":"Restrict all oral fluids indefinitely"},{"id":"lt4","text":"Apply firm downward pressure to force urination"},{"id":"lt5","text":"Encourage the client to hold urine longer"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Acute urinary retention"},{"id":"ct2","text":"Urinary tract infection"},{"id":"ct3","text":"Bladder rupture"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Post-void bladder scan volume"},{"id":"rt2","text":"Voided volume and voiding pattern"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Pupillary response"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Bladder elimination', 'Urinary retention', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_357026', 'DRAG_CLOZE', 'A severely malnourished client is started on nutrition support. The nurse monitors closely for refeeding syndrome, whose hallmark electrolyte abnormality is [1]. If it develops, the client is at greatest risk for [2] complications.', 'Refeeding syndrome is characterized by hypophosphatemia as glucose drives phosphate intracellularly, placing the client at risk for cardiac and respiratory compromise.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"hypophosphatemia"},{"id":"t2","text":"hyperphosphatemia"},{"id":"t3","text":"cardiac and respiratory"},{"id":"t4","text":"constipation-related"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t3"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Nutrition status', 'Refeeding syndrome', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_357027', 'DRAG_ORDER', 'A nurse is to administer an intermittent feeding through an established gastrostomy tube. Place the steps in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"},{"id":"s6","target_text":"6th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene and position the client upright"},{"id":"t2","text":"Verify tube placement and check gastric residual"},{"id":"t3","text":"Flush the tube with water before the feeding"},{"id":"t4","text":"Administer the feeding at the prescribed rate"},{"id":"t5","text":"Flush the tube with water after the feeding"},{"id":"t6","text":"Keep the client upright for 30 to 60 minutes"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5","s6":"t6"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral tube feeding', 'Intermittent feeding procedure', 'Hard', 'Apply', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358001', 'MCQ', 'A client receiving continuous enteral feeding through a nasogastric tube develops a respiratory rate of 28, coughing, and an SpO2 drop to 88%. Which action should the nurse take FIRST?', 'With suspected aspiration during enteral feeding, stopping the feed is the first action to prevent further instillate reaching the lungs.', '{"options":[{"id":"A","text":"Stop the tube feeding immediately"},{"id":"B","text":"Check the gastric residual volume"},{"id":"C","text":"Auscultate the lung fields"},{"id":"D","text":"Notify the respiratory therapist"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Aspiration is suspected; stopping the feeding halts further instillation before any other step.","B":"Incorrect. Residual check does not protect the airway in an acute event.","C":"Incorrect. Assessment follows stopping the source of aspiration.","D":"Incorrect. Stopping the feed precedes escalation."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', 'Aspiration risk', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358002', 'MCQ', 'A nurse assesses a sacral wound with full-thickness skin loss where subcutaneous fat is visible but no bone, tendon, or muscle is exposed, and there is no slough obscuring the base. How should the nurse stage this pressure injury?', 'Visible adipose without exposed bone, tendon, or muscle and an unobscured base defines a Stage 3 pressure injury.', '{"options":[{"id":"A","text":"Stage 3"},{"id":"B","text":"Stage 2"},{"id":"C","text":"Stage 4"},{"id":"D","text":"Unstageable"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Full-thickness loss with visible fat and no exposed deeper structures is Stage 3.","B":"Incorrect. Stage 2 is partial-thickness with a viable pink wound bed, no fat visible.","C":"Incorrect. Stage 4 exposes bone, tendon, or muscle.","D":"Incorrect. Unstageable requires slough/eschar obscuring the base, which is absent."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Integumentary', 'Pressure-injury prevention', 'Staging', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358003', 'MCQ', 'A client in skeletal traction for a femur fracture reports the affected foot feels cold and numb, and the nurse notes weak pedal pulses and pallor. Which action is the priority?', 'Cold, numb, pale extremity with diminished pulses signals neurovascular compromise; the provider must be notified urgently and weights are not removed by the nurse.', '{"options":[{"id":"A","text":"Notify the provider immediately"},{"id":"B","text":"Remove the traction weights"},{"id":"C","text":"Reposition the client toward the foot of the bed"},{"id":"D","text":"Apply a warm blanket to the foot"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These are signs of neurovascular compromise requiring urgent provider intervention.","B":"Incorrect. The nurse never removes skeletal traction weights without an order.","C":"Incorrect. Repositioning delays care for a limb-threatening finding.","D":"Incorrect. Warming masks but does not address impaired perfusion."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal', 'Orthopedic devices', 'Skeletal traction', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358004', 'MCQ', 'A client with left-sided weakness after a stroke is learning to use a cane. Which instruction indicates the nurse understands correct technique?', 'The cane is held on the strong side and advances together with the weak leg to widen the base of support and offload the affected side.', '{"options":[{"id":"A","text":"Hold the cane in the right hand and advance it with the left leg"},{"id":"B","text":"Hold the cane in the left hand and advance it with the left leg"},{"id":"C","text":"Hold the cane in the right hand and advance it with the right leg"},{"id":"D","text":"Hold the cane in whichever hand feels comfortable"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The cane goes on the strong side and moves with the weak leg for a wide base of support.","B":"Incorrect. The cane is held on the strong (right) side.","C":"Incorrect. The cane advances with the weak leg, not the strong leg.","D":"Incorrect. Cane placement is prescribed by biomechanics, not comfort."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Assistive devices', 'Cane gait', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358005', 'MCQ', 'A client has continuous bladder irrigation after a transurethral prostate resection. Over one shift 3000 mL of irrigant infused and the drainage bag collected 3400 mL. What is the true urine output the nurse documents?', 'True urine output during continuous bladder irrigation equals total drainage minus the irrigant instilled (3400 - 3000 = 400 mL).', '{"options":[{"id":"A","text":"400 mL"},{"id":"B","text":"3400 mL"},{"id":"C","text":"6400 mL"},{"id":"D","text":"3000 mL"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Total output minus irrigant instilled equals true urine output: 3400 - 3000 = 400 mL.","B":"Incorrect. This includes the irrigant, not true urine.","C":"Incorrect. Irrigant is subtracted, not added.","D":"Incorrect. This is the irrigant volume, not the urine."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Renal/Genitourinary', 'Bladder irrigation', 'Continuous irrigation output', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358006', 'MCQ', 'A nurse cares for a nonverbal client with advanced dementia who is grimacing, guarding the abdomen, and resisting repositioning. Which assessment approach is most appropriate?', 'For nonverbal clients with dementia, a validated behavioral tool such as PAINAD assesses pain through observed behaviors rather than self-report.', '{"options":[{"id":"A","text":"Use a behavioral pain scale such as PAINAD"},{"id":"B","text":"Ask the client to rate pain on a 0-to-10 numeric scale"},{"id":"C","text":"Assume the behavior is unrelated to pain"},{"id":"D","text":"Wait until the family arrives to interpret the behavior"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Observational/behavioral scales are validated for nonverbal cognitively impaired clients.","B":"Incorrect. A nonverbal client cannot reliably self-report a number.","C":"Incorrect. Grimacing and guarding are recognized pain behaviors.","D":"Incorrect. Pain assessment should not be delayed."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Pain assessment', 'Nonverbal pain', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358007', 'MCQ', 'A nurse repositions an immobile client and wishes to prevent external hip rotation and footdrop. Which combination of devices best achieves both goals?', 'A trochanter roll blocks external hip rotation while a foot support or high-top sneaker keeps the ankle at 90 degrees to prevent footdrop.', '{"options":[{"id":"A","text":"Trochanter roll and a foot support/high-top sneaker"},{"id":"B","text":"Two pillows under the knees and a bed cradle"},{"id":"C","text":"Wrist splints and a trapeze bar"},{"id":"D","text":"Abduction pillow and heel protectors"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A trochanter roll prevents external hip rotation and a foot support prevents footdrop.","B":"Incorrect. Knee pillows promote flexion contractures and do not address footdrop.","C":"Incorrect. These do not address the hip or foot.","D":"Incorrect. An abduction pillow is post-hip-replacement; heel protectors do not prevent footdrop."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Positioning', 'Immobility complications', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358008', 'MCQ', 'A severely malnourished client is started on nutritional support. On day two the nurse notes a phosphate of 1.2 mg/dL, magnesium of 1.1 mg/dL, and new muscle weakness. Which condition should the nurse suspect?', 'Reintroducing nutrition to a malnourished client drives phosphate, magnesium, and potassium intracellularly, producing refeeding syndrome.', '{"options":[{"id":"A","text":"Refeeding syndrome"},{"id":"B","text":"Dumping syndrome"},{"id":"C","text":"Hyperosmolar hyperglycemic state"},{"id":"D","text":"Metabolic alkalosis"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Hypophosphatemia and hypomagnesemia after reintroducing nutrition define refeeding syndrome.","B":"Incorrect. Dumping causes GI and vasomotor symptoms, not this electrolyte pattern.","C":"Incorrect. HHS involves severe hyperglycemia and dehydration.","D":"Incorrect. The findings point to electrolyte shifts, not primarily an acid-base disorder."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Nutrition status', 'Refeeding syndrome', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358009', 'MCQ', 'A client with a signed organ-donor card is declared dead. The family is distraught and objects to donation. What is the nurse''s most appropriate action?', 'The organ procurement organization is the designated authority to approach families and reconcile donor wishes; the nurse facilitates by notifying them.', '{"options":[{"id":"A","text":"Notify the organ procurement organization and involve them in family discussion"},{"id":"B","text":"Proceed with postmortem preparation for donation over the family''s objection"},{"id":"C","text":"Tell the family the donor card legally overrides their wishes"},{"id":"D","text":"Cancel the donation because the family objects"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The OPO is legally responsible for approaching the family and coordinating consent.","B":"Incorrect. The nurse does not independently override the situation; the OPO handles it.","C":"Incorrect. This is confrontational and outside the nurse''s role.","D":"Incorrect. The nurse does not unilaterally cancel; the OPO manages the process."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Postmortem care', 'Organ donation', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358010', 'MCQ', 'Six hours after a long-leg plaster cast is applied, a client reports deep, unrelenting pain unrelieved by opioids and pain on passive toe extension. What should the nurse suspect and do first?', 'Pain out of proportion, unrelieved by opioids, and worsened by passive stretch signals compartment syndrome requiring immediate provider notification.', '{"options":[{"id":"A","text":"Compartment syndrome; notify the provider immediately"},{"id":"B","text":"Normal cast tightening; elevate the limb and reassure"},{"id":"C","text":"Opioid tolerance; request a higher dose"},{"id":"D","text":"Anxiety; provide relaxation techniques"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Pain with passive stretch unrelieved by opioids is a hallmark of compartment syndrome, a surgical emergency.","B":"Incorrect. Unrelenting pain with passive stretch is not normal.","C":"Incorrect. Escalating analgesia would mask an emergency.","D":"Incorrect. The presentation is a perfusion emergency, not anxiety."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal', 'Orthopedic devices', 'Cast care', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358011', 'MCQ', 'An older adult reports chronic insomnia. Which nurse recommendation reflects the best evidence-based nonpharmacologic sleep-hygiene measure?', 'Stimulus-control (leaving the bed when not sleeping and returning when sleepy) is a first-line nonpharmacologic insomnia intervention.', '{"options":[{"id":"A","text":"Get out of bed if unable to fall asleep within about 20 minutes and return when sleepy"},{"id":"B","text":"Take a long daytime nap to make up for lost sleep"},{"id":"C","text":"Have a nightcap of alcohol to fall asleep faster"},{"id":"D","text":"Exercise vigorously right before bedtime"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stimulus-control therapy strengthens the bed-sleep association.","B":"Incorrect. Daytime napping reduces sleep drive at night.","C":"Incorrect. Alcohol fragments sleep architecture.","D":"Incorrect. Late vigorous exercise is stimulating."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Sleep and rest', 'Sleep hygiene', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358012', 'MCQ', 'During a cleansing enema the client reports sudden cramping. Which nurse action is most appropriate?', 'Cramping during an enema is relieved by lowering the container and pausing flow, then resuming slowly once the sensation passes.', '{"options":[{"id":"A","text":"Lower the solution container and temporarily stop the flow"},{"id":"B","text":"Immediately remove the tubing and end the procedure"},{"id":"C","text":"Raise the container higher to finish faster"},{"id":"D","text":"Have the client bear down to speed instillation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Slowing or pausing the flow relieves cramping while allowing the enema to continue.","B":"Incorrect. Cramping is managed by slowing flow, not abandoning the procedure.","C":"Incorrect. Raising the container increases flow and worsens cramping.","D":"Incorrect. Bearing down expels the solution prematurely."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Bowel elimination', 'Enema administration', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_358013', 'SATA', 'A nurse plans care for an immobile, incontinent client to prevent pressure injuries. Which interventions are appropriate? Select all that apply.', 'Repositioning, low HOB, moisture barriers, and pressure-redistribution surfaces reduce risk; massaging reddened areas and donut cushions cause further tissue injury.', '{"options":[{"id":"A","text":"Reposition on an individualized schedule"},{"id":"B","text":"Keep the head of the bed at the lowest elevation consistent with the plan of care"},{"id":"C","text":"Apply a moisture-barrier product after incontinence care"},{"id":"D","text":"Use a pressure-redistribution support surface"},{"id":"E","text":"Vigorously massage reddened bony prominences"},{"id":"F","text":"Place a ring/donut cushion under the sacrum"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure-injury prevention', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_358014', 'SATA', 'A nurse administers a bolus feeding through a gastrostomy tube. Which actions reduce the risk of aspiration and complications? Select all that apply.', 'HOB elevation, placement verification, residual checks, and flushing reduce aspiration and clogging; lying flat and prolonged hang times increase risk.', '{"options":[{"id":"A","text":"Elevate the head of the bed 30 to 45 degrees during and after feeding"},{"id":"B","text":"Verify tube placement before feeding"},{"id":"C","text":"Check gastric residual per protocol"},{"id":"D","text":"Flush the tube with water before and after feeding"},{"id":"E","text":"Lay the client flat immediately after the feeding"},{"id":"F","text":"Hang a single formula bag open at room temperature for 24 hours"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_358015', 'SATA', 'A client with chronic low back pain wishes to reduce reliance on opioids. Which nonpharmacologic measures should the nurse include in the plan? Select all that apply.', 'Heat/cold, relaxation, repositioning, and TENS are evidence-based nonpharmacologic strategies; prolonged bed rest and delaying reporting worsen outcomes.', '{"options":[{"id":"A","text":"Application of heat or cold"},{"id":"B","text":"Guided imagery and relaxation breathing"},{"id":"C","text":"Repositioning and gentle stretching"},{"id":"D","text":"Transcutaneous electrical nerve stimulation (TENS)"},{"id":"E","text":"Strict bed rest for two weeks"},{"id":"F","text":"Withholding all pain reports until they are severe"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Nonpharmacologic comfort', NULL, 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_358016', 'SATA', 'A nurse manages an indwelling urinary catheter to prevent catheter-associated urinary tract infection. Which actions are correct? Select all that apply.', 'Dependent drainage, securement, a closed system, and early removal reduce CAUTI; routine antibiotic irrigation and floor contact do not.', '{"options":[{"id":"A","text":"Keep the drainage bag below the level of the bladder"},{"id":"B","text":"Secure the catheter to the thigh to prevent traction"},{"id":"C","text":"Maintain a closed drainage system"},{"id":"D","text":"Review daily whether the catheter is still indicated"},{"id":"E","text":"Routinely irrigate the catheter with antibiotic solution"},{"id":"F","text":"Rest the drainage bag on the floor for stability"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Renal/Genitourinary', 'Bladder elimination', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_358017', 'SATA', 'A nurse provides personal hygiene care to a dependent adult client. Which actions preserve the client''s dignity and privacy? Select all that apply.', 'Privacy screening, selective draping, explanation with choices, and promoting self-care preserve dignity; loud disclosure and unnecessary exposure violate it.', '{"options":[{"id":"A","text":"Close the door and curtain before beginning care"},{"id":"B","text":"Drape the client, exposing only the area being cleaned"},{"id":"C","text":"Explain each step and offer choices when possible"},{"id":"D","text":"Discuss the client''s incontinence loudly with a colleague at the bedside"},{"id":"E","text":"Allow the client to do as much self-care as able"},{"id":"F","text":"Leave the client uncovered to finish care faster"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Dignity and privacy', NULL, 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_358018', 'SELECT_N', 'A nurse totals a client''s 8-hour intake and output. Which 3 items are counted as fluid intake?', 'Items liquid at room temperature (gelatin, IV fluids, ice chips) count as intake; solid food is not measured and urine/NG drainage are output.', '{"options":[{"id":"A","text":"120 mL of gelatin dessert"},{"id":"B","text":"200 mL of IV normal saline infused"},{"id":"C","text":"90 mL of ice chips (measured as 45 mL)"},{"id":"D","text":"A slice of toast"},{"id":"E","text":"150 mL of urine voided"},{"id":"F","text":"50 mL of nasogastric drainage"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Intake and output', NULL, 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_358019', 'TF', 'When performing passive range-of-motion exercises on a client with hemiplegia, the nurse should move each joint past the point of resistance to maximize flexibility.', 'Passive ROM is performed only to the point of resistance or slight discomfort; moving past it risks tissue and joint injury.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Mobility and ROM', NULL, 'Hard', NULL, '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_358020', 'MATRIX', 'For each assessment finding, click to indicate whether it suggests adequate nutrition or protein-energy malnutrition.', 'Normal albumin and healthy healing reflect adequate nutrition, whereas muscle wasting, weight loss, and low prealbumin with edema indicate malnutrition.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Serum albumin 4.2 g/dL"},{"id":"r2","text":"Temporal muscle wasting"},{"id":"r3","text":"Unintentional 10% weight loss in 3 months"},{"id":"r4","text":"Intact skin with brisk wound healing"},{"id":"r5","text":"Bilateral pitting edema with low prealbumin"}],"columns":[{"id":"c1","text":"Adequate nutrition"},{"id":"c2","text":"Malnutrition"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c2","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Nutrition status', NULL, 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_358021', 'MATRIX_MR', 'For each comfort measure, select all comfort goals it directly supports (a measure may support more than one).', 'Relaxation techniques and massage broadly address pain, sleep, and anxiety, while heat mainly targets pain and environmental control mainly targets sleep and anxiety.', '{"row_label":"Measure","rows":[{"id":"r1","text":"Guided imagery"},{"id":"r2","text":"Warm compress to a sore joint"},{"id":"r3","text":"Quiet, darkened environment"},{"id":"r4","text":"Back massage at bedtime"}],"columns":[{"id":"c1","text":"Pain relief"},{"id":"c2","text":"Improved sleep"},{"id":"c3","text":"Anxiety reduction"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c1"],"r3":["c2","c3"],"r4":["c1","c2","c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Nonpharmacologic comfort', NULL, 'Hard', 'Apply', '{}', 9, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_358022', 'CLOZE', 'The nurse checks a gastric residual of 350 mL before a scheduled bolus feed. According to most protocols the nurse should first {1} and then {2}.', 'A high gastric residual warrants holding the feed and reassessing, escalating to the provider if residuals stay elevated, to reduce aspiration risk.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"hold the feeding and reassess"},{"id":"c2","text":"double the feeding volume"},{"id":"c3","text":"flush with 200 mL of juice"}]},{"id":"b2","choices":[{"id":"c1","text":"notify the provider if residuals remain elevated"},{"id":"c2","text":"clamp the tube permanently"},{"id":"c3","text":"remove the feeding tube"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', NULL, 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_358023', 'HIGHLIGHT', 'Highlight the findings that indicate the client is at high risk for a pressure injury. The client is [[bedbound and unable to reposition independently]]. Skin is [[moist from incontinence]]. Braden score is [[12]]. Appetite is [[good with full meals eaten]]. There is [[nonblanchable erythema over the sacrum]]. Ambulates in the hallway twice daily.', 'Immobility, moisture, a low Braden score, and nonblanchable erythema all signal high pressure-injury risk; adequate intake is protective.', '{"chunks":[{"id":"h1","text":"bedbound and unable to reposition independently"},{"id":"h2","text":"moist from incontinence"},{"id":"h3","text":"12"},{"id":"h4","text":"good with full meals eaten"},{"id":"h5","text":"nonblanchable erythema over the sacrum"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h5"],"feedback":{"h1":"Immobility is a primary risk factor.","h2":"Moisture macerates skin and raises risk.","h3":"A Braden score of 12 indicates high risk.","h4":"Good nutrition is protective, not a risk.","h5":"This is an early (Stage 1) pressure injury."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Integumentary', 'Skin and tissue integrity', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_358024', 'BOWTIE', 'A client on long-term opioids for cancer pain reports no bowel movement for 4 days, abdominal distension, and small hard stool. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Chronic opioids slow gut motility causing constipation, managed with laxatives plus fluids/fiber and monitored by stool output and abdominal assessment.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer a prescribed stimulant laxative"},{"id":"lt2","text":"Increase fluid and fiber intake"},{"id":"lt3","text":"Withhold all pain medication indefinitely"},{"id":"lt4","text":"Restrict oral fluids"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Opioid-induced constipation"},{"id":"ct2","text":"Viral gastroenteritis"},{"id":"ct3","text":"Small-bowel obstruction from adhesions"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Stool frequency and consistency"},{"id":"rt2","text":"Abdominal distension and bowel sounds"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Pupillary response"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'GI', 'Bowel elimination', NULL, 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_358025', 'DRAG_CLOZE', 'When teaching a client to descend stairs with crutches, the nurse instructs the client to move the [1] first, followed by the [2].', 'Going down stairs, the crutches and the weak leg lead, then the strong leg follows: ''down with the bad.''', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"crutches and affected leg"},{"id":"t2","text":"strong (unaffected) leg"},{"id":"t3","text":"wheelchair"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', NULL, 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_358026', 'DRAG_ORDER', 'After a client''s death with no autopsy or organ donation required, place the nurse''s postmortem care actions in the correct sequence.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Confirm the pronouncement of death is documented"},{"id":"t2","text":"Provide the family time with the body"},{"id":"t3","text":"Remove tubes and lines per policy"},{"id":"t4","text":"Bathe and position the body in natural alignment"},{"id":"t5","text":"Apply identification tags and prepare for transport"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Postmortem care', NULL, 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_358027', 'MCQ', 'A nurse prepares to irrigate an adult client''s ear to remove impacted cerumen. Which technique is correct?', 'Adult ear irrigation straightens the canal by pulling the pinna up and back, uses body-temperature solution, and directs fluid along the canal wall without occluding it.', '{"options":[{"id":"A","text":"Pull the pinna up and back and direct the solution toward the canal wall"},{"id":"B","text":"Pull the pinna down and back and aim directly at the tympanic membrane"},{"id":"C","text":"Use ice-cold irrigation solution to reduce swelling"},{"id":"D","text":"Occlude the canal fully with the syringe tip for maximum pressure"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. In adults the pinna is pulled up and back and fluid is aimed at the canal wall, not the eardrum.","B":"Incorrect. Down-and-back is for young children, and aiming at the eardrum can rupture it.","C":"Incorrect. Cold solution causes vertigo and nausea; use body-temperature fluid.","D":"Incorrect. Occluding the canal traps pressure and can injure the eardrum."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Irrigations', 'Ear irrigation', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353001', 'MCQ', 'A woman at 11 weeks gestation asks which screening will best estimate her risk for a fetus with Down syndrome at this visit. Which combination should the nurse identify as the appropriate first-trimester option?', 'Combined first-trimester screening uses nuchal translucency plus PAPP-A and beta-hCG at 11-13 weeks.', '{"options":[{"id":"A","text":"Nuchal translucency ultrasound with maternal serum PAPP-A and beta-hCG"},{"id":"B","text":"Maternal serum alpha-fetoprotein alone"},{"id":"C","text":"Amniocentesis for fetal karyotype"},{"id":"D","text":"Quad screen of AFP, hCG, estriol, and inhibin A"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Combined first-trimester screening pairs nuchal translucency with PAPP-A and beta-hCG at 11-13 weeks.","B":"Incorrect. MSAFP alone is a second-trimester test and screens for neural tube defects.","C":"Incorrect. Amniocentesis is diagnostic and typically performed after 15 weeks, not first-line screening.","D":"Incorrect. The quad screen is a second-trimester screen (15-20 weeks)."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal care', 'First-trimester screening', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353002', 'MCQ', 'A postpartum client who is breastfeeding reports one breast has a firm, reddened, tender wedge-shaped area, and she feels feverish and achy. Which instruction should the nurse prioritize?', 'Mastitis is managed by continued emptying of the breast and provider evaluation for antibiotics; weaning worsens stasis.', '{"options":[{"id":"A","text":"Continue frequent breastfeeding or pumping on the affected side and contact the provider"},{"id":"B","text":"Stop breastfeeding on the affected side until symptoms resolve"},{"id":"C","text":"Apply tight binding to suppress milk production"},{"id":"D","text":"Restrict fluids to reduce milk supply until the area softens"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Continued emptying plus provider evaluation manages mastitis; abrupt weaning worsens stasis.","B":"Incorrect. Stopping promotes milk stasis and worsens mastitis.","C":"Incorrect. Binding increases stasis and the risk of abscess.","D":"Incorrect. Fluid restriction does not treat mastitis and risks dehydration."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Postpartum education', 'Breastfeeding', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353003', 'MCQ', 'During a well-child visit, which finding in a 9-month-old should the nurse flag as needing further developmental evaluation rather than reassurance?', 'Sitting unsupported and hand-to-hand transfer are expected by 9 months; their absence is a red flag.', '{"options":[{"id":"A","text":"Unable to sit without support and does not transfer objects hand to hand"},{"id":"B","text":"Shows stranger anxiety toward the nurse"},{"id":"C","text":"Cannot yet stand alone without holding on"},{"id":"D","text":"Babbles repetitive consonant sounds like ''mama'' nonspecifically"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. By 9 months sitting unsupported and hand-to-hand transfer are expected; their absence warrants evaluation.","B":"Incorrect. Stranger anxiety is expected at this age.","C":"Incorrect. Standing alone is not expected until around 11-12 months.","D":"Incorrect. Nonspecific babbling is normal at 9 months."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Developmental milestones', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353004', 'MCQ', 'A nurse reviews four children due for the MMR vaccine. Which child requires the provider to be notified before administration?', 'MMR is a live vaccine and is contraindicated in significantly immunosuppressed children such as those on high-dose corticosteroids.', '{"options":[{"id":"A","text":"A child receiving high-dose corticosteroids for nephrotic syndrome"},{"id":"B","text":"A child with a mild upper respiratory infection and low-grade fever"},{"id":"C","text":"A child whose sibling is receiving chemotherapy"},{"id":"D","text":"A child with a history of localized egg allergy causing hives"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Live vaccines are contraindicated with significant immunosuppression such as high-dose steroids.","B":"Incorrect. Minor illness is not a contraindication.","C":"Incorrect. A household contact''s immunosuppression does not contraindicate MMR for a healthy child.","D":"Incorrect. MMR is not contraindicated in egg allergy."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Immune', 'Immunizations', 'Contraindications', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353005', 'MCQ', 'A 68-year-old woman asks which routine preventive screening she still needs. She had a normal colonoscopy 3 years ago and normal Pap tests through age 64. Which recommendation is most appropriate?', 'Osteoporosis DXA screening is recommended beginning at age 65 for women; colonoscopy and Pap intervals here are already met.', '{"options":[{"id":"A","text":"Bone mineral density screening for osteoporosis"},{"id":"B","text":"Repeat colonoscopy now"},{"id":"C","text":"Resume routine Pap testing"},{"id":"D","text":"Annual chest radiograph for lung cancer"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. DXA screening is recommended for women 65 and older; she is due.","B":"Incorrect. After a normal colonoscopy, the usual interval is 10 years.","C":"Incorrect. Cervical cancer screening can stop after 65 with adequate prior normal results.","D":"Incorrect. Lung cancer screening uses low-dose CT and only for eligible smokers, not routine chest x-ray."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Older adult screening', 'Preventive care', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353006', 'MCQ', 'A client says, ''I''ve thought about quitting smoking and I''m planning to set a quit date next month.'' Using the transtheoretical model, which nursing action best matches the client''s stage?', 'Intending to act within a month is the preparation stage, where concrete planning (quit date, coping strategies) is appropriate.', '{"options":[{"id":"A","text":"Help the client identify a specific quit date and coping strategies for triggers"},{"id":"B","text":"Provide facts about the risks of smoking to raise awareness"},{"id":"C","text":"Reinforce relapse-prevention strategies for maintenance"},{"id":"D","text":"Congratulate the client on successfully quitting"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Planning to act within a month is the preparation stage; concrete planning fits.","B":"Incorrect. Awareness-raising fits precontemplation, which the client has passed.","C":"Incorrect. Maintenance applies after 6 months of abstinence.","D":"Incorrect. The client has not yet quit."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Respiratory', 'High-risk behavior education', 'Smoking cessation', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353007', 'MCQ', 'A newly diagnosed diabetic client is scheduled for insulin teaching but is tearful and says, ''I can''t believe this is happening to me.'' Which nursing action is most appropriate first?', 'Emotional distress is a barrier to learning; the nurse addresses readiness before delivering content.', '{"options":[{"id":"A","text":"Acknowledge the client''s feelings and defer detailed teaching until readiness improves"},{"id":"B","text":"Proceed with the insulin demonstration to use the scheduled time"},{"id":"C","text":"Provide written pamphlets and leave the client to read"},{"id":"D","text":"Tell the client that many people manage diabetes well and begin teaching"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Emotional distress is a barrier to learning; addressing it precedes content teaching.","B":"Incorrect. Distress blocks retention; teaching now will be ineffective.","C":"Incorrect. This ignores the emotional barrier and readiness.","D":"Incorrect. This offers false reassurance and dismisses feelings."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Readiness to learn', 'Barriers to learning', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353008', 'MCQ', 'A woman at 8 weeks gestation with a normal BMI asks about weight gain and nutrition. Which statement indicates she needs further teaching?', '''Eating for two'' is a myth; pregnancy adds only about 340-450 kcal/day in later trimesters.', '{"options":[{"id":"A","text":"''I should eat for two, roughly doubling my calories now.''"},{"id":"B","text":"''A total weight gain of about 25 to 35 pounds is expected for me.''"},{"id":"C","text":"''I need adequate folic acid to help prevent neural tube defects.''"},{"id":"D","text":"''I should avoid undercooked meats and unpasteurized cheese.''"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This is a misconception; only about 340-450 extra calories are needed and not in the first trimester.","B":"Incorrect. This is the recommended range for a normal BMI.","C":"Incorrect. This is accurate.","D":"Incorrect. This correctly reduces Listeria and Toxoplasma risk."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Antepartum care', 'Nutrition education', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353009', 'MCQ', 'During a newborn assessment the nurse notes asymmetric thigh skinfolds and a palpable clunk when the hips are abducted. Which action is most appropriate?', 'A positive Ortolani (clunk on abduction) with asymmetric skinfolds indicates developmental hip dysplasia and warrants referral.', '{"options":[{"id":"A","text":"Report the finding as a positive Ortolani sign suggesting hip dysplasia"},{"id":"B","text":"Document it as a normal newborn variant needing no follow-up"},{"id":"C","text":"Reassure the parents the finding resolves with tight swaddling"},{"id":"D","text":"Apply gentle traction and recheck in one week"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A clunk on abduction (Ortolani) with asymmetric folds indicates developmental dysplasia of the hip and requires referral.","B":"Incorrect. These are abnormal findings requiring evaluation.","C":"Incorrect. Tight swaddling with extended legs worsens hip dysplasia.","D":"Incorrect. This delays needed orthopedic referral."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Musculoskeletal', 'Newborn assessment', 'Hip screening', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353010', 'MCQ', 'A 16-year-old comes to the clinic and asks to be seen without a parent present to discuss contraception. Which nursing response best supports adolescent health promotion?', 'Adolescents can generally receive confidential reproductive counseling; the nurse also clarifies confidentiality limits.', '{"options":[{"id":"A","text":"Provide confidential counseling while explaining the limits of confidentiality"},{"id":"B","text":"Require a parent to be present before any discussion"},{"id":"C","text":"Refuse to discuss contraception with a minor"},{"id":"D","text":"Call the parent to obtain consent before counseling"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Adolescents can generally access confidential reproductive care; explaining limits builds trust.","B":"Incorrect. This is a barrier to needed reproductive care for adolescents.","C":"Incorrect. This withholds appropriate health promotion.","D":"Incorrect. This breaches the adolescent''s confidentiality."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Adolescent health', 'Confidentiality', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353011', 'MCQ', 'A client who speaks limited English needs discharge teaching. The client''s adult son offers to interpret. Which action best supports safe, equitable education?', 'A qualified medical interpreter provides accurate, confidential communication; untrained family members risk errors.', '{"options":[{"id":"A","text":"Arrange a qualified medical interpreter for the teaching"},{"id":"B","text":"Allow the son to interpret to save time"},{"id":"C","text":"Give the client written materials in English only"},{"id":"D","text":"Speak slowly and loudly in English with gestures"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A trained medical interpreter ensures accuracy and confidentiality; family members may filter or err.","B":"Incorrect. Family interpreters risk errors, bias, and confidentiality breaches.","C":"Incorrect. This does not address the language barrier.","D":"Incorrect. This does not ensure comprehension of critical teaching."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Communication barriers', 'Interpreter use', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_353012', 'MCQ', 'A nurse conducts routine screening at a primary-care clinic. Which client should the nurse prioritize for a validated depression screening tool?', 'Postpartum women are a recommended screening population, and reported anhedonia and sleep disturbance raise priority.', '{"options":[{"id":"A","text":"A woman at her 6-week postpartum visit reporting poor sleep and loss of interest"},{"id":"B","text":"A man completing a pre-employment physical who reports feeling well"},{"id":"C","text":"A teenager with a sports injury who is eager to return to play"},{"id":"D","text":"An older adult presenting for an annual flu vaccination and feeling upbeat"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Postpartum depression screening is recommended, and her symptoms heighten priority.","B":"Incorrect. No symptoms or elevated risk are present.","C":"Incorrect. No depressive risk indicators are noted here.","D":"Incorrect. No risk indicators are present."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Depression screening', 'Targeted screening', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_353013', 'SATA', 'A home-health nurse assesses a 78-year-old for fall risk. Which findings should the nurse identify as modifiable environmental or health risk factors to address? Select all that apply.', 'Rugs, polypharmacy causing orthostasis, poor lighting, and unsafe footwear are modifiable; age and past stroke are non-modifiable.', '{"options":[{"id":"A","text":"Loose throw rugs in the hallway"},{"id":"B","text":"Taking four antihypertensives with reported dizziness on standing"},{"id":"C","text":"Dim lighting on the stairway"},{"id":"D","text":"Wearing loose backless slippers indoors"},{"id":"E","text":"Age of 78 years"},{"id":"F","text":"History of a prior stroke five years ago"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Older adult home safety', 'Fall risk', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_353014', 'SATA', 'A nurse teaches a postpartum client about signs to report after discharge. Which findings should the client be taught to report immediately? Select all that apply.', 'Heavy bleeding, DVT signs, endometritis, and severe headache with visual changes are danger signs; lochia progression and afterpains are normal.', '{"options":[{"id":"A","text":"Saturating a perineal pad within one hour"},{"id":"B","text":"A calf that is red, warm, and painful"},{"id":"C","text":"Fever of 38.5°C with foul-smelling lochia"},{"id":"D","text":"A sudden severe headache with visual changes"},{"id":"E","text":"Lochia changing from red to pinkish-brown over several days"},{"id":"F","text":"Afterpains during breastfeeding in the first days"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Postpartum education', 'Warning signs', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_353015', 'SATA', 'A nurse provides anticipatory guidance to parents of a 15-month-old. Which teaching points are appropriate for this developmental stage? Select all that apply.', 'Poison, burn, and car-seat safety fit toddlers; nuts/popcorn are choking hazards and prone sleep is unsafe.', '{"options":[{"id":"A","text":"Keep cleaning products and medications in locked cabinets"},{"id":"B","text":"Turn pot handles toward the back of the stove"},{"id":"C","text":"Use a rear-facing car seat until the height or weight limit is reached"},{"id":"D","text":"Set the water heater no higher than 120°F (49°C)"},{"id":"E","text":"Introduce whole nuts and popcorn as finger foods"},{"id":"F","text":"Place the child to sleep in the prone position"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Toddler safety', 'Anticipatory guidance', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_353016', 'SATA', 'A nurse screens a 45-year-old adult at a community health fair. Which findings would support a diagnosis of metabolic syndrome? Select all that apply.', 'Central obesity, elevated fasting glucose, high triglycerides, and elevated BP are metabolic-syndrome criteria; high HDL and normal BMI are not.', '{"options":[{"id":"A","text":"Waist circumference of 105 cm"},{"id":"B","text":"Fasting glucose of 108 mg/dL"},{"id":"C","text":"Triglycerides of 180 mg/dL"},{"id":"D","text":"Blood pressure of 138/88 mmHg"},{"id":"E","text":"HDL cholesterol of 65 mg/dL"},{"id":"F","text":"BMI of 22 kg/m2"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Endocrine', 'Adult lifestyle', 'Metabolic syndrome', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_353017', 'SATA', 'A nurse reviews immunization needs for a healthy 65-year-old with no chronic illness. Which vaccines are appropriate to recommend at this visit? Select all that apply.', 'Zoster, pneumococcal, influenza, and tetanus boosters are recommended for older adults; routine MMR and meningococcal are not indicated here.', '{"options":[{"id":"A","text":"Recombinant zoster (shingles) vaccine"},{"id":"B","text":"Pneumococcal vaccination per current adult schedule"},{"id":"C","text":"Annual influenza vaccine"},{"id":"D","text":"Tdap or Td booster if due"},{"id":"E","text":"Routine MMR revaccination"},{"id":"F","text":"Meningococcal ACWY as a routine dose"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Immune', 'Adult immunizations', 'Preventive care', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_353018', 'SELECT_N', 'Which 3 findings would the nurse expect in a typically developing 4-year-old?', 'Hopping, drawing a multi-part person, and multi-word sentences are 4-year milestones; the others emerge later.', '{"options":[{"id":"A","text":"Hops on one foot"},{"id":"B","text":"Draws a person with three or more parts"},{"id":"C","text":"Uses sentences of four or more words"},{"id":"D","text":"Ties own shoelaces independently"},{"id":"E","text":"Reads simple sentences"},{"id":"F","text":"Understands conservation of mass"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Preschool development', 'Milestones', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_353019', 'SELECT_N', 'A community health nurse assesses population risk in a low-income urban neighborhood. Which 4 factors most directly increase the community''s health risk?', 'Food deserts, old housing, provider shortages, and transport barriers raise risk; recreation access and high immunization rates are protective.', '{"options":[{"id":"A","text":"Limited access to fresh produce (food desert)"},{"id":"B","text":"High density of housing built before 1978 (lead paint)"},{"id":"C","text":"Few primary-care providers per capita"},{"id":"D","text":"Unreliable public transportation to clinics"},{"id":"E","text":"A newly opened recreation center with walking trails"},{"id":"F","text":"A high childhood immunization completion rate"}],"select_count":4}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Community risk assessment', 'Vulnerable populations', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_353020', 'TF', 'A woman who has had a total hysterectomy with removal of the cervix for benign fibroids still requires routine Pap smear screening.', 'After hysterectomy with cervix removal for benign disease and no history of high-grade cervical lesions, routine Pap screening is not needed.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Reproductive', 'Cancer screening', 'Cervical screening', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_353021', 'MATRIX', 'For each behavior, click to indicate the age at which it is first typically expected.', 'Social smile appears around 2 months, first steps and first words around 12 months, and tricycle riding and three-word sentences around 3 years.', '{"row_label":"Behavior","rows":[{"id":"r1","text":"Social smile in response to a caregiver"},{"id":"r2","text":"Walks a few steps independently"},{"id":"r3","text":"Pedals a tricycle"},{"id":"r4","text":"Says one or two words with meaning"},{"id":"r5","text":"Speaks in three-word sentences"}],"columns":[{"id":"c1","text":"2 months"},{"id":"c2","text":"12 months"},{"id":"c3","text":"3 years"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c2","r5":"c3"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Age-appropriate behavior', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_353022', 'MATRIX_MR', 'For each screening, select all age groups for whom it is routinely recommended.', 'BP and depression screening span all ages; DXA and one-time AAA screening for at-risk men apply to older adults.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Blood pressure screening"},{"id":"r2","text":"Bone mineral density (DXA)"},{"id":"r3","text":"Depression screening"},{"id":"r4","text":"Abdominal aortic aneurysm ultrasound (men who ever smoked)"}],"columns":[{"id":"c1","text":"Adolescent (13-17y)"},{"id":"c2","text":"Adult (18-64y)"},{"id":"c3","text":"Older adult (65y+)"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c3"],"r3":["c1","c2","c3"],"r4":["c3"]},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Preventive screening', 'Age-based recommendations', 'Hard', 'Analyze', '{}', 8, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_353023', 'CLOZE', 'A laboring woman is 6 cm dilated with contractions every 3 minutes lasting 60 seconds. She is in the {1} phase of the {2} stage of labor.', '6 cm dilation with regular strong contractions is the active phase of the first stage of labor.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"active"},{"id":"c2","text":"latent"},{"id":"c3","text":"transition"}]},{"id":"b2","choices":[{"id":"c1","text":"first"},{"id":"c2","text":"second"},{"id":"c3","text":"third"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Labor assessment', 'Stages of labor', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_353024', 'HIGHLIGHT', 'A nurse reviews a 34-week prenatal note. Highlight the findings that require immediate follow-up. The client reports [[a severe headache unrelieved by rest]]. Blood pressure [[158/98]]. She notes [[mild ankle swelling by evening]]. She reports [[blurred vision and seeing spots]]. Fetal heart rate 140. She states she feels [[regular fetal movement]].', 'Severe headache, elevated BP, and visual changes indicate possible severe preeclampsia; mild dependent edema and normal fetal movement are expected.', '{"chunks":[{"id":"h1","text":"a severe headache unrelieved by rest"},{"id":"h2","text":"158/98"},{"id":"h3","text":"mild ankle swelling by evening"},{"id":"h4","text":"blurred vision and seeing spots"},{"id":"h5","text":"regular fetal movement"}]}'::jsonb, '{"correct_ids":["h1","h2","h4"],"feedback":{"h1":"Severe persistent headache is a preeclampsia warning sign.","h2":"Elevated BP suggests preeclampsia.","h3":"Dependent edema is a common normal finding in late pregnancy.","h4":"Visual disturbances signal severe preeclampsia.","h5":"Regular fetal movement is reassuring."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal assessment', 'Danger signs', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_353025', 'BOWTIE', 'A 50-year-old with a blood pressure of 134/86 mmHg, BMI 31, and a sedentary lifestyle seeks help lowering cardiovascular risk. Complete the diagram.', 'Stage 1 hypertension with obesity is addressed by DASH diet and exercise, monitoring BP and weight.', '{"left":{"label":"Actions to recommend","tokens":[{"id":"lt1","text":"Adopt a DASH-style diet lower in sodium"},{"id":"lt2","text":"Begin regular moderate aerobic activity"},{"id":"lt3","text":"Start a high-protein, high-sodium diet"},{"id":"lt4","text":"Increase saturated fat intake"},{"id":"lt5","text":"Remain sedentary and monitor only"}]},"centre":{"label":"Client risk state","tokens":[{"id":"ct1","text":"Elevated cardiovascular risk (stage 1 hypertension, obesity)"},{"id":"ct2","text":"Hypotension with dehydration"},{"id":"ct3","text":"Normal risk requiring no change"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Blood pressure trend"},{"id":"rt2","text":"Body weight and BMI"},{"id":"rt3","text":"Serum ammonia"},{"id":"rt4","text":"Deep tendon reflexes"},{"id":"rt5","text":"Pupillary response"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Cardiovascular', 'Adult risk reduction', 'Hypertension prevention', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_353026', 'DRAG_CLOZE', 'The nurse teaches new parents that iron-fortified complementary foods should begin around [1] of age, and cow''s milk as a main drink should be delayed until [2] of age.', 'Complementary foods start around 6 months; whole cow''s milk as a main drink is delayed until 12 months.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"6 months"},{"id":"t2","text":"12 months"},{"id":"t3","text":"2 months"},{"id":"t4","text":"3 years"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Infant nutrition', 'Feeding milestones', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_353027', 'DRAG_ORDER', 'A nurse plans discharge teaching for a client newly prescribed warfarin. Place the steps of the teaching process in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Assess the client''s current knowledge and readiness to learn"},{"id":"t2","text":"Set mutual learning goals with the client"},{"id":"t3","text":"Deliver the teaching using appropriate methods"},{"id":"t4","text":"Have the client demonstrate or teach back the content"},{"id":"t5","text":"Evaluate learning and document outcomes"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Patient education', 'Teaching process', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354001', 'MCQ', 'A nurse is teaching a woman at 30 weeks gestation about warning signs to report. The client reports several sensations. Which statement indicates a finding that requires the client to seek care IMMEDIATELY rather than routine follow-up?', 'Sustained decreased fetal movement can signal fetal compromise and requires prompt evaluation, unlike the other expected third-trimester changes.', '{"options":[{"id":"A","text":"\"I feel my baby move less than usual and it has been most of the day.\""},{"id":"B","text":"\"I get short of breath when I climb the stairs quickly.\""},{"id":"C","text":"\"I have occasional tightening that stops when I rest and drink water.\""},{"id":"D","text":"\"My ankles are a little swollen at the end of the day.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Decreased fetal movement over hours warrants immediate evaluation for fetal compromise.","B":"Incorrect. Mild exertional dyspnea from the enlarging uterus is expected in the third trimester.","C":"Incorrect. These are Braxton Hicks contractions that resolve with hydration and rest.","D":"Incorrect. Mild dependent edema without other signs is a normal late-pregnancy change."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal care', 'Danger signs education', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354002', 'MCQ', 'A nurse assesses a 10-month-old infant at a well-child visit. Which finding should the nurse recognize as a developmental red flag requiring further evaluation?', 'Inability to sit unsupported or bear weight by 9-10 months is a gross-motor red flag, whereas the other findings are age-appropriate.', '{"options":[{"id":"A","text":"Does not sit without support and cannot bear weight on the legs"},{"id":"B","text":"Uses a raking grasp rather than a neat pincer grasp"},{"id":"C","text":"Shows anxiety when approached by an unfamiliar visitor"},{"id":"D","text":"Babbles repetitive consonant sounds but says no clear words"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. By 9-10 months an infant should sit unsupported and bear weight; absence suggests a motor delay.","B":"Incorrect. A mature pincer grasp typically emerges around 10-12 months; a raking grasp is still acceptable.","C":"Incorrect. Stranger anxiety is an expected finding beginning around 6-8 months.","D":"Incorrect. First true words usually appear around 12 months; babbling at 10 months is normal."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Developmental milestones', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354003', 'MCQ', 'A nurse reviews the charts of four children due for the MMR vaccine. For which child should the nurse hold the vaccine and consult the provider?', 'Live vaccines such as MMR are contraindicated during significant immunosuppression like high-dose corticosteroid therapy.', '{"options":[{"id":"A","text":"A child receiving high-dose corticosteroids for nephrotic syndrome"},{"id":"B","text":"A child with a mild upper respiratory infection and low-grade fever"},{"id":"C","text":"A child whose sibling is not up to date on vaccines"},{"id":"D","text":"A child with a documented egg allergy causing hives"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. MMR is a live vaccine and is contraindicated in significant immunosuppression, including high-dose steroids.","B":"Incorrect. Minor illness with low-grade fever is not a contraindication to vaccination.","C":"Incorrect. A household contact''s status does not contraindicate this child''s vaccine.","D":"Incorrect. MMR can be given to children with egg allergy; it is not egg-based."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Immune', 'Immunizations', 'Contraindications', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354004', 'MCQ', 'A nurse in a community clinic is prioritizing preventive screening for a 68-year-old man who has smoked one pack of cigarettes daily for 40 years and quit 8 years ago. Which screening is MOST important to arrange based on his history?', 'His pack-year history and quit interval meet criteria for annual low-dose CT lung cancer screening, the highest-yield targeted screen.', '{"options":[{"id":"A","text":"Low-dose CT scan of the chest for lung cancer"},{"id":"B","text":"Abdominal ultrasound only if he reports back pain"},{"id":"C","text":"Fasting lipid panel repeated every 6 months"},{"id":"D","text":"Prostate-specific antigen testing without discussion"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A 50-80 year old with a 20+ pack-year history who quit within 15 years meets criteria for annual low-dose CT lung screening.","B":"Incorrect. One-time AAA screening is recommended for men who ever smoked, but it is not driven by symptoms and lung screening is higher yield here.","C":"Incorrect. Lipid screening is appropriate but not this frequent and is not the priority given his smoking history.","D":"Incorrect. PSA screening requires shared decision-making and is not the highest priority here."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Older adult screening', 'Preventive care', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354005', 'MCQ', 'A nurse screens a woman at her 6-week postpartum visit using a validated depression tool. Which response should prompt the nurse to escalate care most urgently?', 'Passive suicidal ideation on a postpartum depression screen indicates safety risk and requires the most urgent escalation.', '{"options":[{"id":"A","text":"\"I have had thoughts that the baby would be better off without me.\""},{"id":"B","text":"\"I cry more easily than I used to and feel tired.\""},{"id":"C","text":"\"I worry about being a good mother sometimes.\""},{"id":"D","text":"\"I have less interest in hobbies than before delivery.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Thoughts of self-harm or that others are better off signal risk and require immediate escalation.","B":"Incorrect. Tearfulness and fatigue are common and warrant monitoring but not urgent escalation.","C":"Incorrect. Some worry about parenting is common; it should be explored but is not an emergency.","D":"Incorrect. Reduced interest is a depressive symptom to follow but does not indicate immediate danger."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Mental Health', 'Psychiatric/Mental Health', 'Depression screening', 'Postpartum', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354006', 'MCQ', 'A nurse plans discharge teaching for a newly diagnosed diabetic client. Which observation indicates the client is NOT yet ready to learn, requiring the nurse to defer detailed teaching?', 'Emotional denial signals the client is not psychologically ready to learn, so the nurse should address feelings before detailed teaching.', '{"options":[{"id":"A","text":"The client says, \"I just cannot believe any of this is happening to me right now.\""},{"id":"B","text":"The client asks how the glucometer stores previous readings"},{"id":"C","text":"The client requests a family member be present for teaching"},{"id":"D","text":"The client asks for written material to review later"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Being in denial or emotional shock is a barrier to learning; readiness must be addressed first.","B":"Incorrect. Asking detailed questions shows engagement and readiness to learn.","C":"Incorrect. Involving support persons facilitates, rather than blocks, learning.","D":"Incorrect. Wanting reference material reflects motivation to learn."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Readiness to learn', 'Barriers to learning', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354007', 'MCQ', 'A parent of a healthy 14-month-old asks about feeding. Which statement by the parent indicates a need for further teaching?', 'More than ~24 oz of milk daily in toddlers displaces solid, iron-rich foods and predisposes to iron-deficiency anemia.', '{"options":[{"id":"A","text":"\"I give him about 30 ounces of whole milk each day so he grows well.\""},{"id":"B","text":"\"I offer him the same foods the family eats, cut into small pieces.\""},{"id":"C","text":"\"I let him decide how much of a meal he eats.\""},{"id":"D","text":"\"I avoid giving whole grapes and hot dogs unless they are cut up.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Excessive milk (over ~24 oz/day) displaces solids and iron-rich foods, risking iron-deficiency anemia.","B":"Incorrect. Offering appropriately sized table foods is developmentally correct at this age.","C":"Incorrect. Allowing the toddler to regulate intake respects appetite and is appropriate.","D":"Incorrect. Modifying choking-hazard foods is correct safety practice."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'GI', 'Infant nutrition', 'Toddler feeding', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354008', 'MCQ', 'A nurse assesses a woman 2 days postpartum who is breastfeeding. Which finding is expected and does NOT require intervention?', 'Normal involution shows a firm midline fundus descending steadily with rubra lochia; the other findings indicate atony, hemorrhage, or infection.', '{"options":[{"id":"A","text":"Fundus firm, midline, 2 fingerbreadths below the umbilicus with moderate red lochia"},{"id":"B","text":"Fundus boggy and displaced to the right with heavy lochia"},{"id":"C","text":"Saturating one perineal pad every 30 minutes"},{"id":"D","text":"Foul-smelling lochia with a temperature of 38.6 C"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A firm midline fundus descending about one fingerbreadth per day with moderate rubra lochia is normal involution.","B":"Incorrect. A boggy, displaced fundus suggests a full bladder or atony and needs intervention.","C":"Incorrect. Saturating a pad within an hour signals hemorrhage requiring immediate action.","D":"Incorrect. Foul lochia and fever suggest endometritis and require intervention."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Postpartum care', 'Involution assessment', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354009', 'MCQ', 'A nurse conducts a health-maintenance visit with a 16-year-old. To best promote candid disclosure of high-risk behaviors, which approach should the nurse take?', 'Confidential one-on-one interviewing, with limits explained, is the evidence-based way to elicit adolescent risk-behavior disclosure.', '{"options":[{"id":"A","text":"Interview the adolescent alone for part of the visit after explaining confidentiality and its limits"},{"id":"B","text":"Keep the parent present throughout to ensure accurate history"},{"id":"C","text":"Ask sensitive questions only if the adolescent raises the topic first"},{"id":"D","text":"Provide a written questionnaire and file it without discussion"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Time alone with clear confidentiality boundaries encourages honest disclosure of risk behaviors.","B":"Incorrect. Parental presence often inhibits disclosure of sensitive behaviors.","C":"Incorrect. Screening should be proactive; waiting misses risks the teen may not volunteer.","D":"Incorrect. A form without dialogue misses the chance to counsel and clarify."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Adolescent health', 'Confidentiality', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354010', 'MCQ', 'A nurse must teach a client who speaks little English about a new medication. Which action best ensures accurate, ethical communication?', 'A trained interpreter with the nurse addressing the client directly is the standard for accurate, confidential cross-language teaching.', '{"options":[{"id":"A","text":"Arrange a trained medical interpreter and address the client directly"},{"id":"B","text":"Ask the client''s teenage child to interpret the instructions"},{"id":"C","text":"Speak slowly and loudly in English using gestures"},{"id":"D","text":"Give translated printed material and skip verbal teaching"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A qualified interpreter ensures accuracy and confidentiality; the nurse speaks to the client, not the interpreter.","B":"Incorrect. Family members, especially minors, risk errors and breach of privacy.","C":"Incorrect. This does not overcome the language barrier and risks misunderstanding.","D":"Incorrect. Written material alone assumes literacy and prevents questions."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Communication barriers', 'Interpreter use', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354011', 'MCQ', 'A home-health nurse evaluates a 79-year-old woman living alone after a fall. Which finding most strongly indicates she may be unsafe to continue living independently without added support?', 'Inability to reliably self-manage medications with evidence of dosing errors is a key indicator of unsafe independent living.', '{"options":[{"id":"A","text":"She cannot recall whether she has taken her morning medications and has duplicate open bottles"},{"id":"B","text":"She uses a cane and moves slowly but steadily through the home"},{"id":"C","text":"She keeps a list of emergency numbers by the telephone"},{"id":"D","text":"She prefers to bathe in the evening rather than morning"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Impaired medication self-management with evidence of errors signals a safety risk to independent living.","B":"Incorrect. Slow, steady ambulation with an assistive device is safe adaptation.","C":"Incorrect. Having emergency contacts accessible reflects preparedness.","D":"Incorrect. Bathing time preference is not a safety concern."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Musculoskeletal', 'Older adult safety', 'Home-care ability', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_354012', 'MCQ', 'A nurse counsels a client who says, "I know I should quit smoking but I have tried before and just cannot." Using motivational interviewing, which response is most therapeutic?', 'Eliciting the client''s own reasons for change with open questions builds motivation and self-efficacy, central to motivational interviewing.', '{"options":[{"id":"A","text":"\"What has changed for you that makes quitting feel important to think about now?\""},{"id":"B","text":"\"You really need to quit before you have a heart attack.\""},{"id":"C","text":"\"Most people who try as often as you eventually give up entirely.\""},{"id":"D","text":"\"I will schedule you for a cessation class starting tomorrow.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An open, evocative question exploring the client''s own motivation aligns with motivational interviewing.","B":"Incorrect. Warning and scare tactics tend to increase resistance.","C":"Incorrect. This is discouraging and undermines self-efficacy.","D":"Incorrect. Directing action before assessing readiness ignores the client''s ambivalence."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Cardiovascular', 'Lifestyle modification', 'Smoking cessation', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_354013', 'SATA', 'A nurse teaches a woman in her first trimester about nutrition and health maintenance. Which statements by the client indicate correct understanding? Select all that apply.', 'Folic acid, food-safety precautions, caffeine limits, and avoiding high-mercury fish are correct; calorie needs rise only modestly and moderate exercise is encouraged.', '{"options":[{"id":"A","text":"\"I will take a supplement with at least 400 micrograms of folic acid daily.\""},{"id":"B","text":"\"I should avoid raw fish, unpasteurized cheese, and deli meats unless heated.\""},{"id":"C","text":"\"I can keep my daily caffeine below about 200 milligrams.\""},{"id":"D","text":"\"I need to eat for two, so I will roughly double my calories now.\""},{"id":"E","text":"\"I should stop all physical activity to protect the pregnancy.\""},{"id":"F","text":"\"I will limit high-mercury fish such as swordfish and king mackerel.\""}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Antepartum education', 'Nutrition', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_354014', 'SATA', 'A nurse provides discharge teaching to first-time parents of a healthy newborn. Which instructions should the nurse include? Select all that apply.', 'Back-to-sleep, a bare firm crib, adequate wet diapers, and reporting fever are correct; prone sleep and cereal in the bottle are unsafe.', '{"options":[{"id":"A","text":"Place the infant on the back to sleep on a firm, flat surface"},{"id":"B","text":"Keep soft bedding, pillows, and bumpers out of the crib"},{"id":"C","text":"Expect several wet diapers a day once feeding is established"},{"id":"D","text":"Report a rectal temperature of 38 C or higher to the provider"},{"id":"E","text":"Position the infant on the stomach to reduce spit-up during sleep"},{"id":"F","text":"Add rice cereal to the bottle at night to help the baby sleep"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Newborn care', 'Discharge teaching', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_354015', 'SATA', 'A nurse reviews the profile of a 45-year-old adult at a wellness visit. Which findings should the nurse identify as modifiable risk factors to target in a health-promotion plan? Select all that apply.', 'Central obesity, inactivity, heavy alcohol use, and poor diet are modifiable; family history and age are non-modifiable risk factors.', '{"options":[{"id":"A","text":"Waist circumference of 108 cm (42 in)"},{"id":"B","text":"Sedentary job with no regular exercise"},{"id":"C","text":"Reports 3 to 4 alcoholic drinks most evenings"},{"id":"D","text":"Family history of type 2 diabetes in both parents"},{"id":"E","text":"Diet high in processed foods and sugary drinks"},{"id":"F","text":"Age of 45 years"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Endocrine', 'Adult health maintenance', 'Metabolic risk', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_354016', 'SATA', 'A school nurse plans health screening for elementary students. Which observations warrant referral for further evaluation? Select all that apply.', 'Squinting, needing repetition, a rapid BMI rise, and holding materials very close warrant referral; quiet reading and normal tooth loss are expected.', '{"options":[{"id":"A","text":"A child squints and tilts the head to see the board"},{"id":"B","text":"A child frequently asks the teacher to repeat instructions"},{"id":"C","text":"A child''s BMI has crossed from the 60th to the 95th percentile in a year"},{"id":"D","text":"A child reads quietly and prefers independent activities"},{"id":"E","text":"A child sits close to the television and holds books very near the face"},{"id":"F","text":"A child lost two primary teeth this school year"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'School-age screening', 'Vision and hearing', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_354017', 'SATA', 'A nurse plans preventive care for a healthy 66-year-old woman with no significant history. Which age-appropriate screenings or immunizations should the nurse recommend? Select all that apply.', 'Influenza vaccine, DEXA, colorectal screening, and zoster vaccine are recommended; routine chest x-rays are not, and BP monitoring should continue.', '{"options":[{"id":"A","text":"Annual influenza vaccination"},{"id":"B","text":"Bone mineral density (DEXA) screening for osteoporosis"},{"id":"C","text":"Colorectal cancer screening"},{"id":"D","text":"Routine annual chest x-ray for all older adults"},{"id":"E","text":"Recombinant zoster (shingles) vaccine"},{"id":"F","text":"Discontinuation of all blood pressure monitoring"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Older adult health maintenance', 'Preventive screening', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_354018', 'SELECT_N', 'A nurse provides anticipatory guidance to the parent of a 2-year-old. Which 3 pieces of guidance are appropriate for this developmental stage?', 'Autonomy-seeking, readiness-based toilet training, and consistent limits fit the toddler; parallel (not cooperative) play and simpler speech are the norm.', '{"options":[{"id":"A","text":"Expect the child to assert independence and say \"no\" frequently"},{"id":"B","text":"Begin toilet training when the child shows readiness signs"},{"id":"C","text":"Provide consistent limits and use brief time-outs for discipline"},{"id":"D","text":"Expect the child to share toys willingly with peers"},{"id":"E","text":"Introduce a rear-facing to forward-facing car seat only after age 8"},{"id":"F","text":"Anticipate fluent sentences of 8 to 10 words"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Toddler development', 'Anticipatory guidance', 'Hard', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_354019', 'SELECT_N', 'During a comprehensive health assessment of an adult, which 2 findings should the nurse flag for follow-up rather than documenting as normal variants?', 'Unexplained weight loss and an ABCDE-positive mole warrant follow-up; the others are benign or expected findings.', '{"options":[{"id":"A","text":"An unintentional weight loss of 6 kg over 2 months"},{"id":"B","text":"A new asymmetric mole with irregular borders and color variation"},{"id":"C","text":"A single palpable, soft, mobile 0.5 cm lymph node"},{"id":"D","text":"Physiologic splitting of the second heart sound on inspiration"},{"id":"E","text":"Symmetric 1+ pitting ankle edema after a long flight"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Health assessment', 'Comprehensive assessment', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_354020', 'TF', 'A healthy adult who received a tetanus-diphtheria (Td) booster 3 years ago and now has a clean minor wound requires another tetanus booster before the wound can be treated.', 'For clean minor wounds, a booster is needed only if it has been 10 or more years since the last dose, so a booster is not required here.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Immune', 'Immunizations', NULL, 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_354021', 'MATRIX', 'A nurse uses the transtheoretical (stages of change) model. For each client statement, click to indicate whether it reflects the Precontemplation or the Preparation stage.', 'Precontemplation involves no intent to change and often denial; preparation involves concrete plans and small steps toward action.', '{"row_label":"Behavior","rows":[{"id":"r1","text":"\"I don''t see why my drinking is a problem for anyone.\""},{"id":"r2","text":"\"I''ve set a quit date for next Monday and bought nicotine patches.\""},{"id":"r3","text":"\"My weight is fine; I have no plans to change my diet.\""},{"id":"r4","text":"\"I''ve joined a gym and scheduled my first session this week.\""}],"columns":[{"id":"c1","text":"Precontemplation"},{"id":"c2","text":"Preparation"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Health behavior change', 'Stages of change', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_354022', 'MATRIX_MR', 'For each age group, select all screening or assessment activities that are routinely appropriate (each row may have more than one).', 'Milestones apply to children/teens, depression screening from adolescence onward, and fall-risk assessment is prioritized in older adults.', '{"row_label":"Age group","rows":[{"id":"r1","text":"12-month-old infant"},{"id":"r2","text":"15-year-old adolescent"},{"id":"r3","text":"40-year-old adult"},{"id":"r4","text":"80-year-old older adult"}],"columns":[{"id":"c1","text":"Developmental milestone check"},{"id":"c2","text":"Depression screening"},{"id":"c3","text":"Fall-risk assessment"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c1","c2"],"r3":["c2"],"r4":["c2","c3"]},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Lifespan screening', 'Age-appropriate assessment', 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_354023', 'CLOZE', 'A woman in labor is 4 cm dilated with contractions every 4 minutes. The nurse determines she is in the {1} phase of the {2} stage of labor and plans care accordingly.', 'Dilation of 4-7 cm with regular contractions marks the active phase of the first stage of labor.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"active"},{"id":"c2","text":"latent"},{"id":"c3","text":"transition"}]},{"id":"b2","choices":[{"id":"c1","text":"first"},{"id":"c2","text":"second"},{"id":"c3","text":"third"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Labor assessment', 'Stages of labor', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_354024', 'HIGHLIGHT', 'A nurse reviews notes from a 4-year-old''s well-child visit and highlights findings that require further evaluation. The child [[cannot hop on one foot or balance briefly]]. Speech is [[understood by strangers about half the time or less]]. He [[draws a person with three body parts]]. Parents report he [[does not play interactive games with other children]]. He [[rides a tricycle and climbs stairs with alternating feet]].', 'Inability to hop, poor speech intelligibility, and absent interactive play are red flags at age 4; drawing a person and tricycle riding are normal.', '{"chunks":[{"id":"h1","text":"cannot hop on one foot or balance briefly"},{"id":"h2","text":"understood by strangers about half the time or less"},{"id":"h3","text":"draws a person with three body parts"},{"id":"h4","text":"does not play interactive games with other children"},{"id":"h5","text":"rides a tricycle and climbs stairs with alternating feet"}]}'::jsonb, '{"correct_ids":["h1","h2","h4"],"feedback":{"h1":"By age 4 a child should hop on one foot; inability is a motor concern.","h2":"By age 4 speech should be largely intelligible to strangers; poor intelligibility warrants referral.","h3":"Drawing a person with a few parts is expected at this age.","h4":"Lack of cooperative/interactive play by 4 is a social-developmental concern.","h5":"These are expected gross-motor skills for a 4-year-old."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Well-child visit', 'Preschool assessment', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_354025', 'BOWTIE', 'A nurse supports a first-time mother struggling with breastfeeding on postpartum day 2. Complete the diagram by selecting the priority need, supportive actions, and outcomes to monitor.', 'Effective breastfeeding is established by correcting latch and feeding frequently, with diaper counts and weight trend as key indicators of adequate intake.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Assess and correct the infant''s latch position"},{"id":"lt2","text":"Encourage frequent feeding every 2 to 3 hours"},{"id":"lt3","text":"Recommend switching to formula to reduce stress"},{"id":"lt4","text":"Advise limiting feeds to 5 minutes per side"},{"id":"lt5","text":"Instruct to supplement with water between feeds"}]},"centre":{"label":"Priority need","tokens":[{"id":"ct1","text":"Establishing effective breastfeeding"},{"id":"ct2","text":"Preventing newborn hypoglycemia crisis"},{"id":"ct3","text":"Treating suspected mastitis"}]},"right":{"label":"Outcomes to monitor","tokens":[{"id":"rt1","text":"Number of wet and soiled diapers"},{"id":"rt2","text":"Infant weight trend"},{"id":"rt3","text":"Maternal deep tendon reflexes"},{"id":"rt4","text":"Infant head circumference daily"},{"id":"rt5","text":"Maternal fasting glucose"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Postpartum health promotion', 'Breastfeeding support', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_354026', 'DRAG_CLOZE', 'During anticipatory guidance the nurse explains that a typically developing child first walks independently around [1] and speaks in two-word phrases around [2].', 'Independent walking emerges around 12 months and two-word phrases around 24 months in typical development.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"12 months"},{"id":"t2","text":"24 months"},{"id":"t3","text":"6 months"},{"id":"t4","text":"48 months"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Growth and development', 'Milestone timing', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_354027', 'DRAG_ORDER', 'A community-health nurse plans a health-promotion teaching session for a client with newly diagnosed hypertension. Place the steps of the teaching process in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Assess the client''s readiness, literacy, and learning needs"},{"id":"t2","text":"Set mutual learning goals with the client"},{"id":"t3","text":"Select and deliver teaching methods matched to the client"},{"id":"t4","text":"Have the client demonstrate or teach back the content"},{"id":"t5","text":"Evaluate outcomes and document the response to teaching"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Patient teaching', 'Teaching process', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346001', 'MCQ', 'A charge nurse receives four clients at shift change. Which client should the nurse assess FIRST?', 'New neurologic change combined with a significant drop in oxygen saturation indicates an unstable client needing first assessment.', '{"options":[{"id":"A","text":"A client 2 days post-op who reports incisional pain rated 6/10"},{"id":"B","text":"A client with new-onset confusion and a SpO2 that dropped from 96% to 88%"},{"id":"C","text":"A client awaiting discharge who wants education on wound care"},{"id":"D","text":"A client with chronic stable heart failure whose morning weight is unchanged"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Expected post-op pain is a priority but not the most unstable.","B":"Correct. New confusion plus falling oxygenation signals acute deterioration requiring immediate assessment.","C":"Incorrect. Stable and awaiting teaching — not urgent.","D":"Incorrect. Stable baseline, no acute change."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', 'Assessment sequencing', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346002', 'MCQ', 'A registered nurse is planning assignments on a busy medical unit. Which task is MOST appropriate to delegate to a licensed practical/vocational nurse (LPN/LVN)?', 'LPNs may administer routine medications and reinforce teaching for stable clients; assessment, planning, and initial teaching remain with the RN.', '{"options":[{"id":"A","text":"Developing the plan of care for a newly admitted client"},{"id":"B","text":"Administering a scheduled oral antibiotic to a stable client"},{"id":"C","text":"Performing the initial admission assessment"},{"id":"D","text":"Providing discharge teaching about a new insulin regimen"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Care planning is within the RN scope.","B":"Correct. Administering routine oral medication to a stable client is within LPN scope.","C":"Incorrect. Initial assessment requires the RN.","D":"Incorrect. Initial teaching is an RN responsibility."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation and supervision', 'LPN scope', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346003', 'MCQ', 'Just before surgery, a client tells the nurse, "I signed the form, but I''m still not sure what they are actually going to remove." The consent is already signed. What should the nurse do FIRST?', 'Valid informed consent requires client understanding; the nurse must notify the provider to clarify rather than proceed or explain the procedure themselves.', '{"options":[{"id":"A","text":"Reassure the client that the surgeon is highly experienced"},{"id":"B","text":"Witness that the client wants to proceed and send them to the OR"},{"id":"C","text":"Notify the surgeon that the client has questions before proceeding"},{"id":"D","text":"Explain the surgical steps to the client in detail"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. This does not address the lack of understanding.","B":"Incorrect. Consent is not informed if the client does not understand the procedure.","C":"Correct. Explaining the procedure is the provider''s duty; consent is not valid without understanding.","D":"Incorrect. Disclosing procedure specifics is the surgeon''s responsibility, not the nurse''s."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', 'Nurse role', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346004', 'MCQ', 'A nurse posts on a personal social media account: "Long day — lost a young patient in room 12 to an overdose, so sad." No name is used. Which statement about this post is correct?', 'Protected health information includes any combination of details that could identify a client; the post breaches confidentiality despite omitting the name.', '{"options":[{"id":"A","text":"It is acceptable because the client''s name was not included"},{"id":"B","text":"It violates confidentiality because identifiable details were disclosed"},{"id":"C","text":"It is acceptable because it was on a personal account off duty"},{"id":"D","text":"It is acceptable because the client is deceased"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Room number, age, and circumstances can identify the client.","B":"Correct. Combining room, age, and cause of death is identifying and breaches privacy.","C":"Incorrect. Privacy obligations apply regardless of account or timing.","D":"Incorrect. Confidentiality extends after death."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality and privacy', 'HIPAA and social media', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346005', 'MCQ', 'A client with a valid do-not-resuscitate (DNR) order becomes pulseless. The client''s adult daughter, who is not the healthcare proxy, tearfully demands that the nurse start CPR. What should the nurse do?', 'A valid DNR reflects the client''s autonomous wishes and must be honored; the nurse''s role is to support the family, not resuscitate.', '{"options":[{"id":"A","text":"Begin CPR because a family member requested it"},{"id":"B","text":"Honor the DNR and provide comfort and support to the daughter"},{"id":"C","text":"Call a code and let the team decide"},{"id":"D","text":"Ask the daughter to sign a form reversing the DNR"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Family cannot override a valid DNR.","B":"Correct. A valid DNR must be honored; the nurse supports the grieving family.","C":"Incorrect. Initiating a code contradicts the valid directive.","D":"Incorrect. A non-proxy family member cannot reverse the client''s directive."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', 'DNR conflict', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346006', 'MCQ', 'A nurse notes a new order reading "heparin 25,000 units subcutaneous every 12 hours." The usual prophylactic dose is 5,000 units. What is the nurse''s BEST action?', 'The nurse is accountable for recognizing and clarifying an order that appears erroneous and dangerous before administering it.', '{"options":[{"id":"A","text":"Administer the dose as written since a provider ordered it"},{"id":"B","text":"Hold the dose and clarify the order with the prescriber before giving it"},{"id":"C","text":"Administer 5,000 units instead, assuming that was intended"},{"id":"D","text":"Ask another nurse to co-sign and then administer 25,000 units"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Nurses must question clearly unsafe orders.","B":"Correct. The nurse holds and clarifies an apparently erroneous, potentially lethal dose.","C":"Incorrect. The nurse may not unilaterally alter a prescribed dose.","D":"Incorrect. Co-signing does not make an unsafe dose safe."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying and implementing orders', 'Questionable order', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346007', 'MCQ', 'An alert, oriented client with decision-making capacity refuses a scheduled blood transfusion for religious reasons, though the provider says it is medically indicated. What is the nurse''s priority action?', 'A client with capacity has the legal and ethical right to refuse treatment; the nurse advocates by documenting and communicating the refusal.', '{"options":[{"id":"A","text":"Administer the transfusion because it is medically necessary"},{"id":"B","text":"Document the refusal and notify the provider, honoring the client''s decision"},{"id":"C","text":"Have a family member consent on the client''s behalf"},{"id":"D","text":"Tell the client they will die without it to change their mind"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. A competent client''s refusal must be respected.","B":"Correct. A competent client has the right to refuse; the nurse documents and informs the provider.","C":"Incorrect. Family cannot override a competent client''s decision.","D":"Incorrect. Coercion violates client autonomy."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy and rights', 'Refusal of treatment', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346008', 'MCQ', 'During an SBAR handoff, a nurse wants to communicate the "Recommendation" component. Which statement fits that element?', 'In SBAR, the Recommendation states the requested action or next step, distinct from Situation, Background, and Assessment.', '{"options":[{"id":"A","text":"\"The client''s blood pressure is 88/50 and heart rate is 122.\""},{"id":"B","text":"\"I think the client needs a fluid bolus and provider evaluation now.\""},{"id":"C","text":"\"The client was admitted yesterday with pneumonia.\""},{"id":"D","text":"\"I am calling about the client in room 4 who looks unwell.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This is the Assessment/current data.","B":"Correct. Suggesting the next step is the Recommendation.","C":"Incorrect. This is Background.","D":"Incorrect. This is the Situation."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff communication', 'SBAR', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346009', 'MCQ', 'A home-health nurse observes bruising in various stages of healing on a dependent older adult and notes the caregiver answers all questions for the client. The client denies any problem. What should the nurse do?', 'Nurses are mandatory reporters who must report reasonable suspicion of abuse to protective services; proof is not required.', '{"options":[{"id":"A","text":"Respect the client''s denial and take no further action"},{"id":"B","text":"Report the suspected abuse to the appropriate protective agency"},{"id":"C","text":"Confront the caregiver directly and threaten to call police"},{"id":"D","text":"Wait for more evidence before reporting"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Objective signs of possible abuse require reporting.","B":"Correct. Nurses are mandatory reporters and act on reasonable suspicion, not proof.","C":"Incorrect. Confrontation can escalate risk and is not the nurse''s role.","D":"Incorrect. Reporting is based on reasonable suspicion, not certainty."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', 'Suspected abuse', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346010', 'MCQ', 'A client who lives alone and uses a walker is being discharged after a hip repair with new prescriptions and twice-weekly outpatient physical therapy. Which action BEST supports a safe transition of care?', 'Effective care coordination anticipates barriers (mobility, transport, home support) and arranges resources before discharge to prevent readmission.', '{"options":[{"id":"A","text":"Give the client written instructions and confirm they can read"},{"id":"B","text":"Arrange home-care services and confirm transportation to therapy before discharge"},{"id":"C","text":"Tell the client to call the clinic if any problems arise"},{"id":"D","text":"Schedule a follow-up appointment in six weeks"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Written instructions alone don''t ensure the resources are in place.","B":"Correct. Coordinating home support and transport addresses the client''s real barriers to safe recovery.","C":"Incorrect. Reactive advice does not proactively coordinate care.","D":"Incorrect. A single distant appointment does not address immediate needs."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Continuity of care', 'Discharge planning', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346011', 'MCQ', 'Two clients need the last available ICU bed: one is a young trauma victim with a survivable injury, the other an elderly client with an advanced terminal illness and a comfort-care plan. Which ethical principle should MOST guide the allocation decision?', 'Justice is the principle governing fair distribution of limited resources based on likelihood of benefit and need.', '{"options":[{"id":"A","text":"Autonomy — whichever client requests the bed first"},{"id":"B","text":"Justice — allocating the resource to maximize benefit given each client''s needs"},{"id":"C","text":"Fidelity — keeping a promise made earlier to a client"},{"id":"D","text":"Veracity — telling both clients the truth"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Autonomy addresses self-determination, not scarce-resource allocation.","B":"Correct. Justice governs fair, benefit-based distribution of scarce resources.","C":"Incorrect. Fidelity concerns promise-keeping, not allocation.","D":"Incorrect. Veracity concerns truthfulness, not distribution."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Ethics and ethical dilemmas', 'Resource allocation', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_346012', 'MCQ', 'A medical-surgical nurse is floated to a labor-and-delivery unit and assigned to independently manage a laboring client on an oxytocin infusion. The nurse has no obstetric training. What is the BEST initial action?', 'A nurse must not abandon clients but should communicate competency limits and be reassigned to tasks within their scope, such as basic care, while trained staff manage the high-risk elements.', '{"options":[{"id":"A","text":"Refuse the float assignment entirely and leave the unit"},{"id":"B","text":"Inform the charge nurse of the competency limitation and request a modified assignment"},{"id":"C","text":"Accept and manage the oxytocin titration as ordered"},{"id":"D","text":"Ask another med-surg nurse to take the assignment by phone"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Outright abandonment can constitute patient abandonment.","B":"Correct. The nurse communicates the limitation and negotiates tasks within their competence.","C":"Incorrect. Titrating oxytocin without competency is unsafe and outside demonstrated scope.","D":"Incorrect. This does not resolve the unsafe assignment appropriately."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Legal scope of practice', 'Float assignment', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_346013', 'SATA', 'A nurse is deciding which tasks to delegate to unlicensed assistive personnel (UAP) for a group of clients. Which tasks are appropriate to delegate? Select all that apply.', 'UAP may perform standardized, stable-client tasks and data collection; assessment, evaluation, and initial teaching stay with the nurse.', '{"options":[{"id":"A","text":"Measuring and recording vital signs on a stable client"},{"id":"B","text":"Assisting a stable client to ambulate to the bathroom"},{"id":"C","text":"Reinforcing previously taught instructions to drink fluids"},{"id":"D","text":"Evaluating a client''s response to a new pain medication"},{"id":"E","text":"Assessing a wound during a dressing change"},{"id":"F","text":"Documenting the client''s oral intake and output"},{"id":"G","text":"Teaching a newly diagnosed diabetic to self-inject insulin"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation to UAP', 'Five rights of delegation', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_346014', 'SATA', 'A nurse serves on a unit quality-improvement committee reviewing a medication error. Which actions reflect appropriate quality/performance-improvement practice? Select all that apply.', 'Quality improvement uses a nonpunitive, systems focus: report facts, analyze contributing factors, change the process, and measure results; incident reports are not filed in the chart.', '{"options":[{"id":"A","text":"Analyze the system factors that contributed to the error"},{"id":"B","text":"Complete an incident/occurrence report describing the facts"},{"id":"C","text":"Focus on identifying and disciplining the individual to assign blame"},{"id":"D","text":"Implement a process change to prevent recurrence"},{"id":"E","text":"File the incident report in the client''s medical chart"},{"id":"F","text":"Track outcome data to evaluate whether the change worked"}]}'::jsonb, '{"answers":["A","B","D","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Quality and performance improvement', 'Sentinel events', 'Hard', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_346015', 'SATA', 'A nurse is reinforcing a client''s rights during a hospital stay. Which statements accurately reflect client rights the nurse should uphold? Select all that apply.', 'Client rights include refusal of care, access to records, knowing caregivers, privacy, and participating in care decisions; restraints require justification and orders, and information is protected.', '{"options":[{"id":"A","text":"The client may refuse treatment even against medical advice"},{"id":"B","text":"The client may request a copy of their medical record"},{"id":"C","text":"The client may be restrained whenever staff feel it is convenient"},{"id":"D","text":"The client is entitled to know the names and roles of caregivers"},{"id":"E","text":"The client''s information may be shared freely with visitors"},{"id":"F","text":"The client may participate in decisions about their plan of care"}]}'::jsonb, '{"answers":["A","B","D","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client rights', 'Advocacy', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_346016', 'SATA', 'A nurse is coordinating care for a client recovering from a stroke with dysphagia, left-sided weakness, and difficulty coping. Which referrals are appropriate for the nurse to initiate or recommend? Select all that apply.', 'Coordinating multidisciplinary referrals (SLP, PT, OT, social work, psychosocial) addresses the client''s complex, interrelated needs after stroke.', '{"options":[{"id":"A","text":"Speech-language pathology for swallowing evaluation"},{"id":"B","text":"Physical therapy for mobility and strengthening"},{"id":"C","text":"Occupational therapy for activities of daily living"},{"id":"D","text":"Social work for discharge resources and coping support"},{"id":"E","text":"No referrals, since the nurse should manage all needs alone"},{"id":"F","text":"Pastoral/psychosocial support if the client desires it"}]}'::jsonb, '{"answers":["A","B","C","D","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary collaboration', 'Referrals', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_346017', 'SATA', 'A nurse is documenting care in the electronic health record. Which documentation practices are appropriate? Select all that apply.', 'Legally sound documentation is timely, factual/objective, corrected transparently, and signed; pre-charting and unsupported labels are unacceptable.', '{"options":[{"id":"A","text":"Record objective findings and the client''s own words in quotes"},{"id":"B","text":"Document interventions promptly after they are performed"},{"id":"C","text":"Chart planned care in advance to save time later"},{"id":"D","text":"Correct an error by drawing a single line through it and initialing"},{"id":"E","text":"Use subjective labels like ''uncooperative'' without supporting facts"},{"id":"F","text":"Include the date, time, and signature with each entry"}]}'::jsonb, '{"answers":["A","B","D","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Documentation', 'Legal documentation principles', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_346018', 'SELECT_N', 'A nurse is triaging clients after a mass-casualty event. Which 3 clients should be tagged as the highest priority for immediate treatment?', 'Immediate (red) tags go to survivable life threats to airway, breathing, and circulation; minor injuries are delayed and unsalvageable clients are expectant.', '{"options":[{"id":"A","text":"A client with a tension pneumothorax and respiratory distress"},{"id":"B","text":"A client with an uncontrolled arterial hemorrhage"},{"id":"C","text":"A client with an airway obstruction from swelling"},{"id":"D","text":"A client with a closed fracture of the forearm, distal pulse present"},{"id":"E","text":"A client with superficial abrasions who is walking and talking"},{"id":"F","text":"A client without a pulse or respirations after repositioning the airway"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', 'Rapid triage', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_346019', 'SELECT_N', 'Two staff nurses openly disagree about a client''s care plan at the bedside, upsetting the client. Which 2 actions by the charge nurse best manage the conflict constructively?', 'Constructive conflict management moves the discussion to privacy and refocuses on client-centered, evidence-based problem solving rather than blame or avoidance.', '{"options":[{"id":"A","text":"Move the discussion away from the bedside to a private area"},{"id":"B","text":"Facilitate a focus on the client''s needs and the evidence for each view"},{"id":"C","text":"Direct the nurse with less seniority to defer immediately"},{"id":"D","text":"Report both nurses to administration without discussion"},{"id":"E","text":"Ignore the disagreement since staff should resolve it themselves"},{"id":"F","text":"Tell the client to disregard what they heard"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Conflict management', 'Assertive communication', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_346020', 'TF', 'When a registered nurse delegates a task to unlicensed assistive personnel, accountability for the outcome of that task transfers entirely to the assistive personnel.', 'The RN who delegates retains accountability for the delegation decision and supervision; the UAP is responsible for performing the task correctly, but overall accountability is not transferred.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation and supervision', 'Accountability', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_346021', 'MATRIX', 'For each task, click to indicate the least-qualified team member who may appropriately perform it.', 'Assessment and care planning are RN-only; medication administration and reinforcing teaching fit the LPN; standardized ADLs and data recording fit the UAP.', '{"row_label":"Task","rows":[{"id":"r1","text":"Initial head-to-toe admission assessment"},{"id":"r2","text":"Administering a routine oral medication to a stable client"},{"id":"r3","text":"Assisting a stable client with a bed bath"},{"id":"r4","text":"Developing the nursing plan of care"},{"id":"r5","text":"Recording a stable client''s intake and output"},{"id":"r6","text":"Reinforcing standardized teaching already provided by the RN"}],"columns":[{"id":"c1","text":"RN only"},{"id":"c2","text":"LPN/LVN"},{"id":"c3","text":"UAP"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1","r5":"c3","r6":"c2"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice', 'RN vs LPN vs UAP', 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_346022', 'MATRIX_MR', 'For each scenario, select all responsible actions the nurse should take (more than one may apply).', 'Client protection and appropriate reporting mechanisms (chain of command, occurrence reports) vary by event; impaired staff and unsafe orders require immediate action and escalation, while errors/near-misses require documentation for QI.', '{"row_label":"Scenario","rows":[{"id":"r1","text":"A colleague appears impaired and smells of alcohol before a shift"},{"id":"r2","text":"A client fell while ambulating with a UAP"},{"id":"r3","text":"A near-miss where a wrong dose was caught before administration"},{"id":"r4","text":"A provider gives a verbal order that seems unsafe"}],"columns":[{"id":"c1","text":"Report through chain of command"},{"id":"c2","text":"Complete an occurrence/incident report"},{"id":"c3","text":"Take immediate action to protect the client"}]}'::jsonb, '{"cells":{"r1":["c1","c3"],"r2":["c2","c3"],"r3":["c2"],"r4":["c1","c3"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Reporting obligations', 'Advocacy and safety', 'Hard', 'Analyze', '{}', 7, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_346023', 'CLOZE', 'When prioritizing among several clients, the nurse first attends to the client with a threat to {1}, and among clients with stable physiology, prioritizes the one whose condition is {2}.', 'Life-threatening airway/breathing/circulation problems come first, then acute/unstable conditions over chronic/stable ones.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"airway, breathing, or circulation"},{"id":"c2","text":"comfort or sleep"},{"id":"c3","text":"discharge readiness"}]},{"id":"b2","choices":[{"id":"c1","text":"acute and unstable"},{"id":"c2","text":"chronic and stable"},{"id":"c3","text":"fully resolved"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation', 'ABC framework', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_346024', 'HIGHLIGHT', 'The nurse receives handoff on a client: The client is [[resting comfortably]]. Vital signs are [[stable]]. There is a [[new order for a blood transfusion]] that has not been verified. The [[fall-risk armband is missing]] despite a documented fall-risk score. The [[IV site is red and swollen]]. Diet is [[regular as tolerated]]. Highlight the items in the report that require the oncoming nurse''s follow-up before proceeding.', 'Unverified orders, a missing fall-risk identifier, and an abnormal IV site are safety issues requiring follow-up; comfort, stable vitals, and a standard diet are not.', '{"chunks":[{"id":"h1","text":"resting comfortably"},{"id":"h2","text":"stable"},{"id":"h3","text":"new order for a blood transfusion"},{"id":"h4","text":"fall-risk armband is missing"},{"id":"h5","text":"IV site is red and swollen"},{"id":"h6","text":"regular as tolerated"}]}'::jsonb, '{"correct_ids":["h3","h4","h5"],"feedback":{"h1":"No concern — a normal finding.","h2":"Stable vitals require no immediate follow-up.","h3":"Unverified order must be checked before administration.","h4":"A missing safety identifier for a fall-risk client must be corrected.","h5":"Possible phlebitis/infiltration needs assessment and intervention.","h6":"A standard diet order — no follow-up needed."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff report', 'Identifying priority follow-up', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_346025', 'BOWTIE', 'A client who lives alone is being discharged with a new tracheostomy and tube feedings but has no caregiver and unreliable transportation. Complete the diagram by selecting the priority problem, actions to take, and outcomes to evaluate.', 'An unsafe discharge is remedied by coordinating home-health and transportation, then evaluating that safe self-care and resources are secured before discharge.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Arrange skilled home-health nursing services"},{"id":"lt2","text":"Coordinate reliable transportation and follow-up"},{"id":"lt3","text":"Discharge immediately with written instructions only"},{"id":"lt4","text":"Cancel the discharge indefinitely without a plan"}]},"centre":{"label":"Priority problem","tokens":[{"id":"ct1","text":"Unsafe discharge due to inadequate home support"},{"id":"ct2","text":"Noncompliance with the plan of care"},{"id":"ct3","text":"Knowledge deficit unrelated to safety"}]},"right":{"label":"Outcomes to evaluate","tokens":[{"id":"rt1","text":"Client/caregiver demonstrates safe tracheostomy and feeding care"},{"id":"rt2","text":"Home services and follow-up appointments are in place"},{"id":"rt3","text":"Client reports satisfaction with the meal menu"},{"id":"rt4","text":"Client''s roommate learns the call-light system"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Case management', 'Unsafe discharge', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_346026', 'DRAG_CLOZE', 'When organizing the shift, the nurse should first assess the [1] client, cluster care to promote [2], and delegate stable, standardized tasks to the [3].', 'Priority goes to the least stable client, clustering care improves efficiency, and standardized stable-client tasks are delegated to the UAP.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""},{"id":"s3","target_text":""}],"tokens":[{"id":"t1","text":"least stable"},{"id":"t2","text":"efficiency"},{"id":"t3","text":"UAP"},{"id":"t4","text":"most stable"},{"id":"t5","text":"documentation"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Time management', 'Assignment sequencing', 'Hard', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_346027', 'DRAG_ORDER', 'A provider gives a telephone order for a new medication. Place the nurse''s steps in the correct sequence.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Write down the complete order as given"},{"id":"t2","text":"Read the order back to the provider to verify"},{"id":"t3","text":"Obtain the provider''s confirmation of accuracy"},{"id":"t4","text":"Enter and implement the order per policy"},{"id":"t5","text":"Ensure the provider signs the order within the required timeframe"},{"id":"t6","text":"Discard the handwritten note immediately"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying and implementing orders', 'Telephone order process', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347001', 'MCQ', 'A charge nurse receives report on four clients at shift change. Which client should the charge nurse assess FIRST?', 'Post-thyroidectomy hypocalcemia (Trousseau/Chvostek signs) can cause laryngospasm, making airway risk the top priority over stable or routine concerns.', '{"options":[{"id":"A","text":"A client 1 day post-thyroidectomy reporting tingling around the mouth and hand spasms"},{"id":"B","text":"A client with pneumonia whose oral temperature rose from 38.1°C to 38.4°C"},{"id":"C","text":"A client 2 days post-op requesting the next scheduled dose of oral analgesia"},{"id":"D","text":"A client awaiting discharge whose ride has not yet arrived"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Perioral tingling and carpopedal spasm signal acute hypocalcemia, which can progress to laryngospasm — an airway threat requiring immediate assessment.","B":"Incorrect. A modest temperature rise in a known infection is expected and not the highest priority.","C":"Incorrect. Routine pain medication is important but not immediately life-threatening.","D":"Incorrect. A logistics delay carries no physiologic risk."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', 'Charge-nurse rounding', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347002', 'MCQ', 'An RN is working with an LPN and a UAP on a medical unit. Which assignment is MOST appropriate for the RN to keep and NOT delegate?', 'Initial assessment, care-plan creation, and initial teaching are RN-only functions; reinforcement, routine meds, and data collection may be delegated.', '{"options":[{"id":"A","text":"Developing the teaching plan for a newly diagnosed client with type 1 diabetes"},{"id":"B","text":"Reinforcing previously taught insulin injection technique"},{"id":"C","text":"Administering a scheduled oral antibiotic to a stable client"},{"id":"D","text":"Obtaining and recording a set of routine vital signs on a stable client"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Initial client teaching and care-plan development require RN-level assessment and cannot be delegated to the LPN or UAP.","B":"Incorrect. Reinforcing established teaching is within the LPN scope.","C":"Incorrect. Administering routine oral medications is within the LPN scope in most jurisdictions.","D":"Incorrect. Routine vital signs on a stable client may be delegated to the UAP."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation and supervision', 'RN vs LPN scope', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347003', 'MCQ', 'A client scheduled for a splenectomy tells the nurse, ''I signed the form, but I still don''t understand why they can''t just fix it with medicine.'' Which action should the nurse take?', 'The nurse witnesses consent and confirms understanding; when the client lacks understanding, the provider must be notified to re-explain before surgery.', '{"options":[{"id":"A","text":"Notify the surgeon that the client has additional questions before proceeding"},{"id":"B","text":"Explain the surgical risks and alternatives to the client in detail"},{"id":"C","text":"Reassure the client that the surgeon is highly experienced and proceed"},{"id":"D","text":"Document that the client verbalized understanding of the procedure"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Informed consent requires client understanding; unresolved questions mean consent is not truly informed and the provider must clarify.","B":"Incorrect. Disclosing risks and alternatives is the provider''s legal responsibility, not the nurse''s.","C":"Incorrect. Reassurance does not restore informed consent and dismisses the client''s concern.","D":"Incorrect. Documenting understanding that does not exist is inaccurate and unsafe."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', 'Nurse role', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347004', 'MCQ', 'A client with a valid do-not-resuscitate (DNR) order becomes unresponsive and pulseless. The client''s adult daughter, who is not the designated healthcare proxy, demands that the team ''do everything.'' What should the nurse do?', 'A valid DNR expresses the client''s autonomous wishes; a non-proxy relative cannot revoke it, and the nurse must honor the directive.', '{"options":[{"id":"A","text":"Honor the existing DNR order and provide comfort-focused care"},{"id":"B","text":"Begin cardiopulmonary resuscitation because a family member requested it"},{"id":"C","text":"Wait for the healthcare proxy to arrive before deciding whether to resuscitate"},{"id":"D","text":"Ask the daughter to sign a form assuming responsibility for the decision"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A valid DNR reflects the client''s own legally documented wishes and remains in effect regardless of a non-proxy family member''s demand.","B":"Incorrect. A family member cannot override the client''s valid advance directive.","C":"Incorrect. Even the proxy cannot override a valid, current DNR that reflects the client''s wishes.","D":"Incorrect. This is not a legally valid mechanism and delays appropriate care."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', 'DNR conflict', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347005', 'MCQ', 'A nurse is giving an SBAR handoff to the intensive care unit about a deteriorating client. Which statement belongs in the ''Recommendation'' component?', 'In SBAR, the Recommendation states the requested action or next step the nurse believes the client needs.', '{"options":[{"id":"A","text":"''I think this client needs an arterial line and a critical care evaluation now.''"},{"id":"B","text":"''The client is a 58-year-old admitted yesterday with sepsis.''"},{"id":"C","text":"''The blood pressure has dropped to 82/44 despite two fluid boluses.''"},{"id":"D","text":"''I am calling about the client in room 12 who is deteriorating.''"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stating what the nurse believes is needed and requesting specific action is the Recommendation element of SBAR.","B":"Incorrect. This is Background.","C":"Incorrect. This is Assessment/current status.","D":"Incorrect. This is Situation."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff communication', 'SBAR', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347006', 'MCQ', 'A nurse discovers that a colleague accessed the electronic health record of a celebrity admitted to another unit and discussed the diagnosis in the break room. What is the nurse''s MOST appropriate action?', 'Accessing a record without a care relationship and disclosing it violates HIPAA; the nurse must report it to management or the privacy officer.', '{"options":[{"id":"A","text":"Report the privacy violation to the nurse manager or privacy officer"},{"id":"B","text":"Ask the colleague to delete the information they viewed"},{"id":"C","text":"Remind the colleague to be more discreet in the future"},{"id":"D","text":"Take no action because the nurse did not access the record personally"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Unauthorized access and disclosure is a reportable HIPAA violation that must be escalated through the proper channel.","B":"Incorrect. Access is already logged; asking for deletion does not address the breach and is not the nurse''s remedy.","C":"Incorrect. A private reminder fails to address a reportable violation of client privacy.","D":"Incorrect. Witnessing a breach and failing to report it is itself a professional failure."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality and privacy', 'HIPAA breach', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347007', 'MCQ', 'A prescriber writes an order for ''heparin 25,000 units subcutaneously every 12 hours.'' The usual prophylactic subcutaneous dose is 5,000 units. What should the nurse do FIRST?', 'Heparin is a high-alert medication; a dose five times the usual prophylactic amount must be held and clarified with the prescriber before administration.', '{"options":[{"id":"A","text":"Hold the dose and contact the prescriber to clarify the order"},{"id":"B","text":"Administer the dose as written because a prescriber ordered it"},{"id":"C","text":"Administer 5,000 units instead, assuming the extra digits were a typo"},{"id":"D","text":"Ask another nurse whether the dose seems reasonable and then proceed"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The dose is far outside the safe prophylactic range; the nurse must clarify a questionable high-risk medication order before administering.","B":"Incorrect. Nurses are accountable for questioning unsafe orders; blindly following a written order does not remove liability.","C":"Incorrect. The nurse cannot independently alter a dose; the order must be clarified.","D":"Incorrect. A peer opinion does not resolve an unsafe order; the prescriber must clarify."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying and implementing orders', 'Questionable order', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347008', 'MCQ', 'An alert, oriented adult client with decision-making capacity refuses a prescribed blood transfusion for religious reasons, despite a hemoglobin of 6.2 g/dL. Which action best demonstrates client advocacy?', 'A competent adult may refuse treatment; the advocate ensures the informed refusal is respected and clearly documented for the care team.', '{"options":[{"id":"A","text":"Support the client''s decision and ensure the refusal is documented and communicated to the team"},{"id":"B","text":"Persuade the client that the transfusion is necessary to survive"},{"id":"C","text":"Administer the transfusion once the client falls asleep"},{"id":"D","text":"Request a court order to compel the transfusion"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A competent client has the right to refuse treatment; advocacy means honoring the informed decision and ensuring the team respects it.","B":"Incorrect. Coercion violates the client''s autonomy.","C":"Incorrect. This is battery and a serious violation of the client''s rights.","D":"Incorrect. A competent adult''s informed refusal generally cannot be overridden by court order."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy and rights', 'Refusal of treatment', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347009', 'MCQ', 'A nurse is preparing to discharge four clients. Which client''s situation should the nurse address BEFORE discharge can safely proceed?', 'Safe discharge requires that the client can manage high-risk therapy; inability to describe warning signs for warfarin bleeding must be corrected first.', '{"options":[{"id":"A","text":"A client going home on warfarin who cannot state when to seek help for bleeding"},{"id":"B","text":"A client who asks to keep the hospital gown as a souvenir"},{"id":"C","text":"A client whose ride is running 30 minutes late"},{"id":"D","text":"A client who wants a printed copy of the discharge summary emailed as well"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Inability to verbalize critical safety information about a high-risk medication indicates an unmet teaching need that must be resolved before discharge.","B":"Incorrect. This is a harmless request unrelated to safety.","C":"Incorrect. A short transport delay is a logistics issue, not a safety barrier.","D":"Incorrect. Providing an additional copy is easily accommodated and not a safety concern."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Admission, transfer, and discharge', 'Discharge readiness', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347010', 'MCQ', 'A home health nurse notices an older adult client with unexplained bruising, an untreated pressure injury, and a caregiver who answers all questions for the client. What is the nurse''s priority action?', 'Nurses are mandatory reporters of suspected abuse; reasonable suspicion of elder abuse must be reported promptly to protective services.', '{"options":[{"id":"A","text":"Report the suspected elder abuse to adult protective services per mandatory reporting requirements"},{"id":"B","text":"Confront the caregiver directly about the suspected abuse"},{"id":"C","text":"Wait to gather definitive proof of abuse before making any report"},{"id":"D","text":"Document the findings and re-evaluate at the next scheduled visit"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Nurses are mandatory reporters; reasonable suspicion of abuse must be reported to the appropriate agency, and proof is not required.","B":"Incorrect. Confrontation may escalate risk to the client and is not the nurse''s role.","C":"Incorrect. Reasonable suspicion, not proof, triggers the reporting duty.","D":"Incorrect. Delaying the report leaves a vulnerable client at risk."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', 'Suspected abuse', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347011', 'MCQ', 'Two nurses on a unit are in an ongoing disagreement over the assignment, and it is affecting client care. Which approach by the nurse manager reflects an effective collaborative conflict-resolution strategy?', 'Collaboration addresses both parties'' interests to reach a mutually acceptable outcome and is the most effective conflict-resolution style when client care is affected.', '{"options":[{"id":"A","text":"Meet with both nurses together to identify shared goals and a mutually acceptable solution"},{"id":"B","text":"Assign one nurse to a different unit to keep them apart"},{"id":"C","text":"Decide the outcome unilaterally and instruct both nurses to comply"},{"id":"D","text":"Tell the nurses to work it out privately without management involvement"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Collaboration brings both parties together to address underlying interests and reach a win-win solution, the most constructive approach.","B":"Incorrect. Avoidance does not resolve the underlying conflict.","C":"Incorrect. Competing/forcing may resolve the moment but breeds resentment and does not address the root issue.","D":"Incorrect. Because client care is affected, the manager must facilitate resolution."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Conflict management', 'Staff conflict', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347012', 'MCQ', 'A client recovering from a stroke has slurred speech, coughs when drinking water, and is losing weight. Which referral should the nurse prioritize to address the most immediate safety risk?', 'Post-stroke coughing with fluids indicates possible dysphagia; a speech-language pathologist swallowing evaluation addresses the immediate aspiration risk.', '{"options":[{"id":"A","text":"Speech-language pathologist for a swallowing evaluation"},{"id":"B","text":"Dietitian for a weight-gain meal plan"},{"id":"C","text":"Physical therapist for gait and mobility training"},{"id":"D","text":"Social worker for discharge-planning resources"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Coughing with fluids after a stroke suggests dysphagia and aspiration risk; the swallowing evaluation addresses the most immediate safety threat.","B":"Incorrect. Nutrition matters, but aspiration risk must be evaluated before oral intake is optimized.","C":"Incorrect. Mobility is important but not the most immediate safety threat here.","D":"Incorrect. Discharge planning is appropriate later, not the immediate safety priority."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary collaboration', 'Referral', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_347013', 'MCQ', 'A nurse withholds full information about a poor prognosis because a family requests it, even though the alert client has repeatedly asked to know the truth. Which ethical principle is MOST directly violated?', 'A capable client''s request for truthful information is grounded in autonomy; withholding it at the family''s request overrides the client''s self-determination.', '{"options":[{"id":"A","text":"Autonomy"},{"id":"B","text":"Nonmaleficence"},{"id":"C","text":"Justice"},{"id":"D","text":"Beneficence"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Denying a capable client truthful information they have requested violates their right to self-determination (autonomy).","B":"Incorrect. Nonmaleficence concerns avoiding harm; the central violation here is the client''s right to decide with accurate information.","C":"Incorrect. Justice concerns fairness in distribution of care, not truth-telling to an individual.","D":"Incorrect. Beneficence is acting in the client''s benefit; the primary breach here is overriding the client''s own informed choice."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Ethics and ethical dilemmas', 'Ethical principles', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_347014', 'SATA', 'An RN is delegating to unlicensed assistive personnel (UAP) on a busy unit. Which tasks are appropriate to delegate to the UAP? Select all that apply.', 'UAP may perform stable ADLs, routine data collection, and scheduled repositioning; assessment, evaluation, and initial teaching remain RN functions.', '{"options":[{"id":"A","text":"Assisting a stable client to the bathroom"},{"id":"B","text":"Measuring and recording a client''s oral intake and output"},{"id":"C","text":"Repositioning a client with a stage 2 pressure injury on a schedule"},{"id":"D","text":"Evaluating whether a client''s pain has decreased after medication"},{"id":"E","text":"Providing the first teaching session on ostomy self-care"},{"id":"F","text":"Assessing lung sounds on a newly admitted client with dyspnea"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation to UAP', 'Scope limits', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_347015', 'SATA', 'After a medication error reaches a client, the nurse participates in the facility''s response. Which actions reflect appropriate quality-improvement and safety practice? Select all that apply.', 'Just-culture quality improvement focuses on client protection, objective reporting, provider notification, and system-level root-cause analysis, not chart references to reports or individual blame.', '{"options":[{"id":"A","text":"Complete an incident/occurrence report describing the facts objectively"},{"id":"B","text":"Assess and monitor the client for effects of the error"},{"id":"C","text":"Participate in a root-cause analysis focused on system factors"},{"id":"D","text":"Notify the prescriber of the error"},{"id":"E","text":"Document ''incident report completed'' in the client''s chart"},{"id":"F","text":"Identify the individual to blame and note it in the report"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Quality and performance improvement', 'Sentinel event response', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_347016', 'SATA', 'A nurse is reviewing situations that involve protecting client rights. In which situations is the nurse acting as an effective client advocate? Select all that apply.', 'Advocacy protects the client''s autonomy, informed choice, and access to communication resources; coercion and unauthorized disclosure violate client rights.', '{"options":[{"id":"A","text":"Arranging a medical interpreter for a client with limited English before consent is obtained"},{"id":"B","text":"Ensuring a client''s request to change providers is communicated to management"},{"id":"C","text":"Honoring a competent client''s decision to leave against medical advice after risks are explained"},{"id":"D","text":"Pausing a procedure when a client withdraws previously given consent"},{"id":"E","text":"Convincing a hesitant client to accept a treatment the nurse believes is best"},{"id":"F","text":"Sharing a client''s diagnosis with a visiting friend at the client''s bedside without asking"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client rights', 'Advocacy scenarios', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_347017', 'SATA', 'During a mass-casualty event using a color-coded triage system, which clients should the nurse tag as ''red'' (immediate) priority? Select all that apply.', 'Immediate (red) tags go to survivable life threats needing rapid intervention; stable injuries are delayed (yellow/green) and the pulseless client is expectant (black).', '{"options":[{"id":"A","text":"An adult with a tension pneumothorax and severe respiratory distress"},{"id":"B","text":"A client with active, uncontrolled arterial hemorrhage"},{"id":"C","text":"A client with an open airway obstruction that is relieved by repositioning"},{"id":"D","text":"A client with a closed femur fracture, stable vital signs, and good perfusion"},{"id":"E","text":"A client with no pulse and no respirations after airway repositioning"},{"id":"F","text":"A client with minor lacerations who is walking and following commands"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Disaster triage', 'Mass-casualty prioritisation', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_347018', 'SATA', 'A nurse is documenting care in the electronic health record. Which practices reflect legally sound documentation? Select all that apply.', 'Sound documentation is timely, factual, objective, uses the client''s own words, and corrects errors transparently; pre-charting and subjective labeling are unacceptable.', '{"options":[{"id":"A","text":"Charting the client''s own words in quotation marks for subjective reports"},{"id":"B","text":"Recording events in the order they occurred as soon as possible"},{"id":"C","text":"Documenting objective, factual observations rather than opinions"},{"id":"D","text":"Correcting an error by using the system''s tracked-amendment function"},{"id":"E","text":"Charting anticipated care before it is actually performed to save time"},{"id":"F","text":"Using labels such as ''the client was uncooperative and difficult''"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Documentation', 'Legally sound charting', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_347019', 'SELECT_N', 'A nurse begins a shift with six clients and multiple pending tasks. Which 3 actions should the nurse complete FIRST, before the others?', 'Unstable cardiac rhythm, acute respiratory distress, and active hemorrhage are life-threatening and take priority over supply, administrative, and routine tasks.', '{"options":[{"id":"A","text":"Assess the client whose telemetry now shows a new run of ventricular tachycardia"},{"id":"B","text":"Evaluate the client reporting sudden shortness of breath and chest tightness"},{"id":"C","text":"Check the postoperative client whose dressing is becoming saturated with bright red blood"},{"id":"D","text":"Restock the supply cart in an empty room"},{"id":"E","text":"Return a phone call to a pharmacy about a nonurgent formulary question"},{"id":"F","text":"Reposition a stable client who was turned 30 minutes ago"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation of care', 'Time management', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_347020', 'TF', 'When an RN delegates a task to a UAP, the accountability for the outcome of that task transfers entirely to the UAP.', 'The RN retains accountability for the delegation decision and supervision; delegation transfers the task, not overall accountability for the client''s care.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Legal scope of practice', 'Delegation accountability', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_347021', 'MATRIX', 'For each task, click the most appropriate personnel to whom it can be assigned within scope of practice.', 'Care-plan development and blood-product initiation are RN-only; medication administration and catheter insertion may go to the LPN; ADLs and routine vitals may go to the UAP.', '{"row_label":"Task","rows":[{"id":"r1","text":"Initiating a blood transfusion for a client"},{"id":"r2","text":"Developing the nursing plan of care on admission"},{"id":"r3","text":"Administering an oral antihypertensive to a stable client"},{"id":"r4","text":"Inserting an indwelling urinary catheter in a stable client"},{"id":"r5","text":"Feeding a stable client who has no swallowing difficulty"},{"id":"r6","text":"Obtaining a routine blood pressure on a stable client"}],"columns":[{"id":"c1","text":"RN only"},{"id":"c2","text":"LPN or RN"},{"id":"c3","text":"UAP, LPN, or RN"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c1","r3":"c2","r4":"c2","r5":"c3","r6":"c3"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation and scope', 'RN / LPN / UAP', 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_347022', 'MATRIX_MR', 'A charge nurse is making assignments. For each client, select all appropriate management actions (more than one may apply).', 'High-acuity/unstable clients need an experienced RN; airborne and contact precautions require appropriate room placement; stable ADLs may be delegated to the UAP.', '{"row_label":"Client","rows":[{"id":"r1","text":"A newly admitted client with active tuberculosis and hemoptysis"},{"id":"r2","text":"A stable client with Clostridioides difficile who needs help bathing"},{"id":"r3","text":"A hemodynamically unstable client on a titrated vasopressor drip"},{"id":"r4","text":"A stable client 2 days post-op needing assistance to ambulate"}],"columns":[{"id":"c1","text":"Assign to experienced RN"},{"id":"c2","text":"Requires private/isolation room"},{"id":"c3","text":"Suitable to delegate ADLs to UAP"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c2","c3"],"r3":["c1"],"r4":["c3"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Transmission-based assignment', 'Cohorting and delegation', 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_347023', 'CLOZE', 'When several clients need attention at once, the nurse first applies the {1} framework to identify life threats, and among clients who are otherwise stable, gives priority to {2} needs before higher-level ones.', 'Life threats are triaged by ABC; among stable clients, Maslow places physiological needs above psychosocial and self-actualization needs.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"airway-breathing-circulation"},{"id":"c2","text":"first-come, first-served"},{"id":"c3","text":"alphabetical-by-name"}]},{"id":"b2","choices":[{"id":"c1","text":"physiological"},{"id":"c2","text":"self-esteem"},{"id":"c3","text":"self-actualization"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation frameworks', 'ABC and Maslow', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_347024', 'HIGHLIGHT', 'Highlight each finding in the shift observation that represents a practice concern the charge nurse should follow up on. A nurse [[scanned the client''s wristband before administering medication]]. Another nurse [[documented an assessment on a client she has not yet seen]]. A UAP [[reported a blood pressure of 78/40 promptly to the RN]]. A nurse [[borrowed a coworker''s computer login to chart quickly]]. A nurse [[left a controlled-substance waste unwitnessed and undocumented]]. A nurse [[performed hand hygiene between clients]].', 'Falsified charting, shared logins, and unwitnessed controlled-substance waste are reportable practice concerns; the other actions reflect correct practice.', '{"chunks":[{"id":"h1","text":"scanned the client''s wristband before administering medication"},{"id":"h2","text":"documented an assessment on a client she has not yet seen"},{"id":"h3","text":"reported a blood pressure of 78/40 promptly to the RN"},{"id":"h4","text":"borrowed a coworker''s computer login to chart quickly"},{"id":"h5","text":"left a controlled-substance waste unwitnessed and undocumented"},{"id":"h6","text":"performed hand hygiene between clients"}]}'::jsonb, '{"correct_ids":["h2","h4","h5"],"feedback":{"h1":"This is correct practice — barcode verification is appropriate.","h2":"Falsified documentation is a serious practice concern.","h3":"This is appropriate escalation of an abnormal finding.","h4":"Sharing login credentials violates security and documentation integrity.","h5":"Controlled-substance waste requires a witness and documentation — a diversion risk.","h6":"This is correct infection-control practice."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Reporting unsafe practice', 'Recognising concerns', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_347025', 'BOWTIE', 'A client on a med-surg unit becomes acutely confused with BP 84/50, HR 128, and SpO2 88%. Complete the diagram by selecting the priority management focus, the immediate coordinating actions, and the parameters to reassess.', 'An acutely deteriorating client needs rapid response activation and ABC stabilization, with close reassessment of oxygenation and hemodynamic parameters.', '{"left":{"label":"Immediate actions to take","tokens":[{"id":"lt1","text":"Call the rapid response team"},{"id":"lt2","text":"Apply supplemental oxygen and stay with the client"},{"id":"lt3","text":"Send the client to radiology for a routine scan"},{"id":"lt4","text":"Wait until the scheduled provider rounds"},{"id":"lt5","text":"Discharge teaching for the client"}]},"centre":{"label":"Priority management focus","tokens":[{"id":"ct1","text":"Stabilize airway, breathing, and circulation"},{"id":"ct2","text":"Complete the admission paperwork"},{"id":"ct3","text":"Update the family newsletter"}]},"right":{"label":"Parameters to reassess","tokens":[{"id":"rt1","text":"Oxygen saturation and respiratory rate"},{"id":"rt2","text":"Blood pressure and heart rate"},{"id":"rt3","text":"Preferred meal choices"},{"id":"rt4","text":"Visitor schedule"},{"id":"rt5","text":"Television channel selection"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Rapid response coordination', 'Deteriorating client', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_347026', 'DRAG_CLOZE', 'To provide cost-effective care, the nurse coordinates discharge early with the [1] to arrange home services, and avoids waste by [2] rather than routinely opening extra sterile supplies.', 'Cost-effective case management coordinates early discharge planning with the case manager and conserves resources by gathering only needed supplies.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"case manager"},{"id":"t2","text":"gathering only the supplies needed"},{"id":"t3","text":"ordering duplicate tests"},{"id":"t4","text":"delaying the discharge indefinitely"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Cost-effective and case management', 'Resource stewardship', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_347027', 'DRAG_ORDER', 'A nurse identifies a critical lab value that the covering resident dismisses, and the client is deteriorating. Place the nurse''s escalation actions in the correct priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Reassess the client and confirm the critical finding"},{"id":"t2","text":"Communicate the concern to the covering resident using SBAR"},{"id":"t3","text":"Notify the charge nurse and escalate up the chain of command"},{"id":"t4","text":"Contact the attending physician or rapid response as indicated"},{"id":"t5","text":"Document the escalation steps taken and outcomes"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff and escalation', 'Chain of command', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348001', 'MCQ', 'A charge nurse receives four clients simultaneously after a rapid response was called on the unit. Which client should the charge nurse assess FIRST?', 'Airway/breathing compromise (possible pneumothorax post-thoracentesis) outranks metabolic, pain, and febrile concerns.', '{"options":[{"id":"A","text":"A client 2 hours post-thoracentesis with new sudden dyspnea and absent breath sounds on the affected side"},{"id":"B","text":"A client with a potassium of 5.6 mEq/L awaiting a repeat draw"},{"id":"C","text":"A postoperative client reporting incisional pain rated 8/10"},{"id":"D","text":"A client with a temperature of 38.4°C awaiting blood culture results"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These findings suggest a re-expanding pneumothorax — an airway/breathing emergency taking priority.","B":"Incorrect. Concerning but not immediately life-threatening compared with a possible pneumothorax.","C":"Incorrect. Pain is urgent but not life-threatening; airway/breathing outranks it.","D":"Incorrect. Fever needs attention but does not outrank a suspected pneumothorax."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', 'Charge nurse triage', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348002', 'MCQ', 'A registered nurse is planning assignments on a medical unit staffed with an LPN and unlicensed assistive personnel (UAP). Which client is MOST appropriate to assign to the LPN?', 'The LPN can care for stable, predictable clients and reinforce teaching; assessment, unstable clients, and high-risk first doses remain with the RN.', '{"options":[{"id":"A","text":"A stable client with a chronic wound requiring a sterile dressing change and reinforcement of teaching"},{"id":"B","text":"A newly admitted client requiring an initial admission assessment"},{"id":"C","text":"A client receiving a first dose of IV antibiotic with a history of anaphylaxis"},{"id":"D","text":"A client requiring blood transfusion initiation and monitoring"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Reinforcing established teaching and performing a sterile dressing change on a stable client are within LPN scope.","B":"Incorrect. Initial assessment and care planning are RN responsibilities.","C":"Incorrect. First-dose administration with high allergy risk requires RN evaluation.","D":"Incorrect. In most jurisdictions blood initiation and the first-15-minute assessment are RN tasks."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation and supervision', 'LPN scope', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348003', 'MCQ', 'Just before a scheduled surgery, a client tells the nurse, ''I signed the form, but I''m still not sure what they''re removing or why.'' The surgeon has already left the unit. What is the nurse''s BEST action?', 'The nurse witnesses consent and confirms understanding; when understanding is lacking, the provider must be notified to clarify before proceeding.', '{"options":[{"id":"A","text":"Notify the surgeon that the client has unanswered questions before proceeding"},{"id":"B","text":"Explain the surgical procedure and its risks to the client"},{"id":"C","text":"Reassure the client that signing the form means consent is complete"},{"id":"D","text":"Document that the client is anxious and proceed with pre-op preparation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Valid informed consent requires understanding; the provider must clarify before the procedure continues.","B":"Incorrect. Disclosing the procedure, risks, and alternatives is the provider''s duty, not the nurse''s.","C":"Incorrect. A signature without understanding does not constitute valid consent.","D":"Incorrect. Proceeding despite an invalid consent violates the client''s rights."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', 'Nurse role', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348004', 'MCQ', 'A client with a valid Do Not Resuscitate (DNR) order becomes unresponsive with agonal breathing. The adult daughter at the bedside shouts, ''Do everything! Start CPR!'' What is the nurse''s BEST action?', 'A valid DNR expresses the competent client''s autonomous choice; the nurse honors it and supports the grieving family.', '{"options":[{"id":"A","text":"Honor the DNR order, provide comfort measures, and support the daughter"},{"id":"B","text":"Begin CPR because the family member present has requested it"},{"id":"C","text":"Call the provider to obtain permission to rescind the DNR"},{"id":"D","text":"Perform only rescue breathing as a compromise"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A valid DNR reflects the client''s autonomous wishes and remains in effect regardless of family objection.","B":"Incorrect. Family cannot override a valid advance directive made by a competent client.","C":"Incorrect. There is no legal basis to rescind the client''s directive during the event.","D":"Incorrect. Partial resuscitation still violates the DNR order."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', 'Conflicting wishes', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348005', 'MCQ', 'A nurse reviews several situations at the end of a shift. Which action represents a breach of client confidentiality requiring intervention?', 'Identifiable client data in a social media post is a confidentiality breach; disclosures to the care team and authorized parties are permitted.', '{"options":[{"id":"A","text":"Posting a photo of the unit team on social media that shows a client''s whiteboard with names in the background"},{"id":"B","text":"Providing a verbal SBAR handoff to the oncoming nurse in a private report room"},{"id":"C","text":"Discussing a client''s plan of care with the consulting physical therapist"},{"id":"D","text":"Releasing records to the client''s insurer after the client signed an authorization"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Identifiable client information visible in a public post is a HIPAA breach even without naming the client directly.","B":"Incorrect. Report to the assuming caregiver is a permitted disclosure for continuity of care.","C":"Incorrect. Sharing with the treatment team is a permitted use.","D":"Incorrect. Authorized release for payment purposes is permitted."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality and privacy', 'HIPAA / social media', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348006', 'MCQ', 'A nurse receives an order reading ''heparin 25,000 units IV bolus now.'' The usual bolus dose is far lower, and the client weighs 60 kg. What should the nurse do FIRST?', 'The nurse must question and clarify any order that appears erroneous or unsafe before implementing it.', '{"options":[{"id":"A","text":"Hold the dose and clarify the order with the prescriber"},{"id":"B","text":"Administer the dose as written because a provider ordered it"},{"id":"C","text":"Reduce the dose to a weight-based amount and administer it"},{"id":"D","text":"Ask the pharmacist to change the order in the system"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An order that appears unsafe must be clarified before administration; the nurse is accountable for the drugs given.","B":"Incorrect. Following an unsafe order does not relieve the nurse of liability.","C":"Incorrect. The nurse cannot unilaterally alter a prescribed dose.","D":"Incorrect. The prescriber must clarify or revise their own order."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying and implementing orders', 'Questioning an order', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348007', 'MCQ', 'A competent client with terminal cancer decides to stop chemotherapy and enroll in hospice. The client''s spouse privately asks the nurse to ''talk them out of it.'' Which response best demonstrates client advocacy?', 'The advocate upholds the competent client''s autonomy and facilitates supportive family communication.', '{"options":[{"id":"A","text":"''This is your loved one''s decision to make. I can arrange for us all to talk together about what matters most to them.''"},{"id":"B","text":"''I''ll encourage them to reconsider one more round of treatment.''"},{"id":"C","text":"''You should get the provider to declare them incompetent.''"},{"id":"D","text":"''There is nothing I can do; it''s out of my hands.''"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Advocacy supports the competent client''s autonomous choice while facilitating family communication.","B":"Incorrect. Undermining the client''s decision violates autonomy.","C":"Incorrect. There is no basis to challenge a competent client''s capacity.","D":"Incorrect. Dismissing the spouse fails to facilitate communication and support."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy', 'Ethical dilemma', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348008', 'MCQ', 'A nurse is giving a telephone SBAR handoff transferring a deteriorating client to the ICU. Which statement best belongs in the ''Recommendation'' component?', 'In SBAR, Recommendation names the specific action the nurse is requesting and why.', '{"options":[{"id":"A","text":"''I recommend immediate transfer and evaluation for possible sepsis; the client needs closer monitoring than we can provide here.''"},{"id":"B","text":"''The client''s blood pressure is 84/50 and lactate is 4.2.''"},{"id":"C","text":"''The client was admitted two days ago with pneumonia.''"},{"id":"D","text":"''I''m calling about Mr. Owusu in room 12 who has become unstable.''"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Recommendation states the requested action and rationale.","B":"Incorrect. That is Assessment/objective data, not Recommendation.","C":"Incorrect. That is Background.","D":"Incorrect. That is Situation."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff communication', 'SBAR', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348009', 'MCQ', 'A client with new heart failure and limited health literacy is being discharged home alone on six new medications. Which discharge action is the priority to prevent readmission?', 'Effective care coordination — home-health follow-up plus teach-back — addresses the literacy and complexity risks that drive readmission.', '{"options":[{"id":"A","text":"Arrange a home-health nurse visit and teach-back of the medication schedule before discharge"},{"id":"B","text":"Provide a printed medication list and instruct the client to read it at home"},{"id":"C","text":"Tell the client to call the clinic if any problems arise"},{"id":"D","text":"Schedule a cardiology appointment in six weeks"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Coordinated follow-up plus confirmed understanding via teach-back directly targets the readmission risk.","B":"Incorrect. A printed list alone does not verify understanding in a low-literacy client.","C":"Incorrect. Reactive advice does not proactively secure adherence.","D":"Incorrect. Six weeks is too distant for the high-risk early period and omits medication support."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Continuity of care', 'Discharge planning', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348010', 'MCQ', 'A float nurse with no telemetry training is assigned four monitored cardiac clients. After stating the concern, the charge nurse says no other staff are available. What should the float nurse do?', 'The nurse cannot abandon clients but must not act beyond competence; documenting and securing competent coverage manages the risk safely.', '{"options":[{"id":"A","text":"Accept the assignment, document the concern, and request that a telemetry-competent nurse co-cover the monitors"},{"id":"B","text":"Refuse the assignment entirely and leave the unit"},{"id":"C","text":"Accept the assignment and interpret the rhythms without assistance"},{"id":"D","text":"Care for the clients but ignore the cardiac monitors"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Outright abandonment endangers clients; the nurse mitigates risk by documenting and arranging competent backup for the tasks outside their competence.","B":"Incorrect. Walking off after accepting duty constitutes client abandonment.","C":"Incorrect. Performing tasks beyond one''s competence is unsafe and outside scope.","D":"Incorrect. Ignoring ordered monitoring is negligent."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Legal scope of practice', 'Assignment refusal', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348011', 'MCQ', 'Following a serious medication error that reached a client, the unit manager convenes a root cause analysis. Which approach best reflects the purpose of the analysis?', 'Root cause analysis in a just culture identifies system and process failures to prevent recurrence, not individual blame.', '{"options":[{"id":"A","text":"Examine the system and process failures that allowed the error to occur"},{"id":"B","text":"Identify the individual nurse responsible and issue disciplinary action"},{"id":"C","text":"Determine which shift had the fewest staff to reassign blame"},{"id":"D","text":"Postpone the review until the client outcome is known"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Root cause analysis targets latent system factors rather than individual blame.","B":"Incorrect. A punitive focus undermines a just culture and error reporting.","C":"Incorrect. Blame assignment is not the goal of RCA.","D":"Incorrect. Timely analysis is needed regardless of eventual outcome."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Quality improvement', 'Sentinel event response', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348012', 'MCQ', 'Two nurses openly argue at the desk about who should have restocked the code cart, disrupting the unit. Which initial approach by the charge nurse is most effective?', 'Effective conflict management moves the discussion to privacy and collaborates on the problem rather than assigning blame.', '{"options":[{"id":"A","text":"Move the discussion to a private area and facilitate a collaborative, problem-focused resolution"},{"id":"B","text":"Direct both nurses to stop and reassign the restocking to a third nurse"},{"id":"C","text":"Determine who is at fault and document it in each nurse''s file"},{"id":"D","text":"Ignore it since the nurses will resolve it themselves"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Addressing conflict privately and focusing on the problem, not the persons, promotes a durable resolution.","B":"Incorrect. Avoidance leaves the underlying conflict unresolved.","C":"Incorrect. Blame framing escalates rather than resolves conflict.","D":"Incorrect. Ignoring disruptive conflict at the desk allows it to continue."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Conflict management', 'Interprofessional', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_348013', 'MCQ', 'A community health nurse confirms a client has newly diagnosed active pulmonary tuberculosis. The client begs the nurse not to tell anyone. What is the nurse''s obligation?', 'Active TB is a mandatory reportable disease; the nurse must notify public health regardless of the client''s wishes.', '{"options":[{"id":"A","text":"Report the case to the public health department as legally required and initiate contact tracing"},{"id":"B","text":"Honor the client''s request to protect confidentiality"},{"id":"C","text":"Report only if the client refuses treatment"},{"id":"D","text":"Ask the client to notify contacts personally instead of reporting"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Active TB is a reportable communicable disease; mandatory reporting protects public health and overrides the request for secrecy.","B":"Incorrect. Confidentiality does not extend to legally reportable communicable diseases.","C":"Incorrect. Reporting is required upon diagnosis, not contingent on refusal.","D":"Incorrect. The legal duty to report cannot be delegated to the client."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Community Health', 'Multisystem', 'Mandatory reporting', 'Communicable disease', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_348014', 'SATA', 'A nurse is deciding which tasks may be delegated to unlicensed assistive personnel for a group of clients. Which tasks are appropriate to delegate? Select all that apply.', 'UAP may perform stable ADLs and data collection; assessment, evaluation, and teaching remain with the RN.', '{"options":[{"id":"A","text":"Obtaining routine vital signs on a stable client"},{"id":"B","text":"Assisting a stable client to transfer with a gait belt"},{"id":"C","text":"Measuring and recording a client''s oral intake and output"},{"id":"D","text":"Evaluating a client''s response to a new pain medication"},{"id":"E","text":"Teaching a newly diagnosed diabetic to self-inject insulin"},{"id":"F","text":"Assessing the surgical wound of a client with new drainage"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Within UAP scope for stable clients.","B":"A standard ADL task within UAP scope.","C":"Data collection UAP may perform.","D":"Evaluation of response is an RN function.","E":"Client education is not delegable to UAP.","F":"Assessment of a changing condition is an RN function."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation to UAP', 'Five rights of delegation', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_348015', 'SATA', 'A nurse completes an occurrence (incident) report after a client fall. Which principles apply to proper incident reporting? Select all that apply.', 'Incident reports contain objective facts, prompt assessment/notification, and stay out of the medical record without assigning blame.', '{"options":[{"id":"A","text":"Document objective facts about what occurred"},{"id":"B","text":"Notify the provider and assess the client"},{"id":"C","text":"Keep the incident report separate from the medical record"},{"id":"D","text":"Record in the chart that an incident report was filed"},{"id":"E","text":"Include the nurse''s opinion about who was to blame"},{"id":"F","text":"Withhold the report until the shift ends to avoid disruption"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"The report should contain factual, objective information.","B":"Client assessment and provider notification are required follow-up.","C":"The report is a quality/risk-management document, not part of the chart.","D":"The medical record should not reference that a report was filed.","E":"Subjective blame has no place in an occurrence report.","F":"Reports should be completed promptly."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Incident and error reporting', 'Occurrence report', 'Hard', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_348016', 'SATA', 'A nurse coordinates care for a client recovering from a stroke with dysphagia, left-sided weakness, and no home support. Which referrals are appropriate for the nurse to initiate? Select all that apply.', 'Stroke recovery with dysphagia and no home support warrants SLP, PT, OT, and social work referrals; hospice and mandatory chaplaincy are not indicated.', '{"options":[{"id":"A","text":"Speech-language pathology for swallowing evaluation"},{"id":"B","text":"Physical therapy for mobility and strengthening"},{"id":"C","text":"Social work for discharge and home support planning"},{"id":"D","text":"Occupational therapy for activities of daily living retraining"},{"id":"E","text":"Hospice for immediate end-of-life care"},{"id":"F","text":"Chaplaincy as a mandatory referral for all stroke clients"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Appropriate for dysphagia.","B":"Appropriate for left-sided weakness.","C":"Appropriate given lack of home support.","D":"Appropriate for ADL relearning after stroke.","E":"Not indicated for a client in active rehabilitation.","F":"Spiritual care is offered based on need, not mandated."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary collaboration', 'Referrals', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_348017', 'SATA', 'A nurse reviews client rights during an ethics in-service. Which statements accurately reflect a hospitalized client''s rights? Select all that apply.', 'Client rights include refusal, record access, and leaving AMA; they exclude convenience restraint, family override, and nonconsensual research enrollment.', '{"options":[{"id":"A","text":"A competent client may refuse a treatment even if refusal risks harm"},{"id":"B","text":"A client may request a copy of their own medical record"},{"id":"C","text":"A client may leave against medical advice after being informed of the risks"},{"id":"D","text":"A client may be restrained for staff convenience when short-staffed"},{"id":"E","text":"A client''s family may override the competent client''s stated wishes"},{"id":"F","text":"A client may be enrolled in research without consent if it benefits others"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Autonomy includes the right to refuse.","B":"Clients have the right to access their records.","C":"A competent client may leave AMA.","D":"Restraint for convenience is prohibited.","E":"Family cannot override a competent client''s decisions.","F":"Research participation requires informed consent."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client rights', 'Advocacy', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_348018', 'SATA', 'A nurse educator reviews charting standards with new graduates. Which documentation practices are correct? Select all that apply.', 'Correct documentation is prompt, objective, and error-corrected with a single line; pre-charting, correction fluid, and blank lines are prohibited.', '{"options":[{"id":"A","text":"Correct an error by drawing a single line through it, initialing, and dating"},{"id":"B","text":"Chart nursing actions promptly after they are performed"},{"id":"C","text":"Document objective findings and the client''s own words in quotes"},{"id":"D","text":"Chart interventions in advance to save time during a busy shift"},{"id":"E","text":"Use correction fluid to obscure a mistaken entry"},{"id":"F","text":"Leave blank lines so entries can be added later"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"The standard method for correcting a charting error.","B":"Timely documentation improves accuracy.","C":"Objective and verbatim subjective data are appropriate.","D":"Pre-charting is falsification and prohibited.","E":"Obscuring entries is prohibited in legal records.","F":"Blank lines allow tampering and are not acceptable."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Documentation', 'Legal principles', 'Hard', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_348019', 'SELECT_N', 'A nurse begins a shift with six clients. Select the 3 clients the nurse should assess before the others.', 'Hypoxemia, a falling blood pressure, and a possible anticoagulant-related bleed are the unstable, time-critical priorities.', '{"options":[{"id":"A","text":"A client with a new pulse oximetry reading of 86% on room air"},{"id":"B","text":"A postoperative client whose blood pressure dropped from 118/70 to 88/54"},{"id":"C","text":"A client on heparin reporting a sudden severe headache"},{"id":"D","text":"A stable client requesting a PRN laxative"},{"id":"E","text":"A client due for routine 0900 oral medications"},{"id":"F","text":"A client asking about the lunch menu"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Hypoxemia is an urgent airway/breathing concern.","B":"A falling pressure signals possible hemorrhage/shock.","C":"Possible intracranial bleed — a neurologic emergency.","D":"Non-urgent comfort request.","E":"Scheduled and non-urgent.","F":"Non-clinical, non-urgent."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation', 'Which client to see first', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_348020', 'SELECT_N', 'A case manager seeks to reduce unnecessary length of stay while maintaining quality. Select the 2 actions that best support cost-effective, quality care.', 'Cost-effective, quality case management pairs early discharge planning with timely diagnostics, avoiding both premature discharge and unnecessary utilization.', '{"options":[{"id":"A","text":"Begin discharge planning at admission and coordinate needed services early"},{"id":"B","text":"Facilitate timely completion of ordered diagnostics to avoid delays"},{"id":"C","text":"Discharge clients before follow-up support is arranged to free beds"},{"id":"D","text":"Order additional tests to be thorough regardless of indication"},{"id":"E","text":"Keep stable clients admitted longer for observation to be safe"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{"A":"Early planning prevents avoidable delays and readmissions.","B":"Preventing test delays shortens avoidable stay days.","C":"Premature discharge risks readmission and harm.","D":"Non-indicated testing raises cost without benefit.","E":"Unnecessary days increase cost without added value."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Case management', 'Cost-effective care', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_348021', 'TF', 'When a registered nurse delegates a task to unlicensed assistive personnel, accountability for the client outcome transfers entirely to the UAP.', 'The delegating RN retains accountability for the delegation decision and supervision; only the task itself, not overall accountability, is transferred.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation accountability', NULL, 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_348022', 'MATRIX', 'For each task, click the most appropriate personnel to whom it may be assigned or delegated.', 'Care planning and initial assessment are RN-only; the LPN may give routine meds and reinforce teaching; UAP may feed stable clients.', '{"row_label":"Task","rows":[{"id":"r1","text":"Developing the initial nursing care plan"},{"id":"r2","text":"Administering an oral medication to a stable client"},{"id":"r3","text":"Feeding a stable client without swallowing precautions"},{"id":"r4","text":"Performing the first assessment of a newly admitted client"},{"id":"r5","text":"Reinforcing standardized discharge teaching"}],"columns":[{"id":"c1","text":"RN only"},{"id":"c2","text":"LPN"},{"id":"c3","text":"UAP"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice', 'RN vs LPN vs UAP', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_348023', 'MATRIX_MR', 'For each scenario, select all disclosures of protected health information that are permitted without additional client authorization (a scenario may have more than one).', 'Treatment-team communication is permitted for treatment; reportable diseases and abuse are permitted by law; disclosure to a coworker is prohibited.', '{"row_label":"Scenario","rows":[{"id":"r1","text":"Reporting a confirmed case of measles to public health"},{"id":"r2","text":"Giving SBAR report to the nurse assuming care"},{"id":"r3","text":"Telling a client''s coworker the diagnosis on request"},{"id":"r4","text":"Reporting suspected child abuse to authorities"},{"id":"r5","text":"Sharing labs with the consulting nephrologist"}],"columns":[{"id":"c1","text":"Permitted for treatment"},{"id":"c2","text":"Permitted by law"},{"id":"c3","text":"Prohibited"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1"],"r3":["c3"],"r4":["c2"],"r5":["c1"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Disclosure rules', 'Permitted vs prohibited', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_348024', 'CLOZE', 'Applying priority-setting frameworks, the nurse should attend first to the client with {1}, because {2} takes precedence over other needs.', 'The ABC/Maslow frameworks place airway and breathing above all other needs, so the client with airway compromise is seen first.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"a partially obstructed airway and stridor"},{"id":"c2","text":"a scheduled dressing change"},{"id":"c3","text":"a request for discharge paperwork"}]},{"id":"b2","choices":[{"id":"c1","text":"airway and breathing"},{"id":"c2","text":"self-esteem"},{"id":"c3","text":"documentation completeness"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation framework', 'ABC and Maslow', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_348025', 'HIGHLIGHT', 'A nurse observes a colleague during a shift. Highlight the findings that represent unsafe practice requiring the nurse to intervene. The colleague [[performs hand hygiene before entering a room]], [[administers a medication without checking the client''s identifiers]], [[documents an assessment that was not performed]], [[double-checks a high-alert insulin dose with a second nurse]], and [[leaves a controlled-substance count unsigned]].', 'Skipping client identification, false charting, and an unsigned narcotic count are unsafe practices requiring intervention; hand hygiene and independent double-checks are safe.', '{"chunks":[{"id":"h1","text":"performs hand hygiene before entering a room"},{"id":"h2","text":"administers a medication without checking the client''s identifiers"},{"id":"h3","text":"documents an assessment that was not performed"},{"id":"h4","text":"double-checks a high-alert insulin dose with a second nurse"},{"id":"h5","text":"leaves a controlled-substance count unsigned"}]}'::jsonb, '{"correct_ids":["h2","h3","h5"],"feedback":{"h1":"Correct and safe practice.","h2":"Skipping identification is unsafe and violates the rights of administration.","h3":"Falsified documentation is unsafe and illegal.","h4":"This is a recommended safety practice.","h5":"An unsigned narcotic count breaches accountability requirements."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Recognizing unsafe practice', 'Duty to intervene', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_348026', 'BOWTIE', 'A ward client becomes confused with a rising heart rate, falling blood pressure, and a fever. Complete the diagram by selecting the priority concern, the immediate actions to coordinate, and the outcomes to monitor.', 'Confusion with tachycardia, hypotension, and fever signals sepsis with early shock; the nurse coordinates rapid response and sepsis workup and monitors perfusion and lactate.', '{"left":{"label":"Actions to coordinate","tokens":[{"id":"lt1","text":"Activate the rapid response team"},{"id":"lt2","text":"Obtain blood cultures and lactate per protocol"},{"id":"lt3","text":"Reassure the client and recheck in four hours"},{"id":"lt4","text":"Delay notification until the next provider rounds"}]},"centre":{"label":"Priority concern","tokens":[{"id":"ct1","text":"Sepsis with early shock"},{"id":"ct2","text":"Simple dehydration"},{"id":"ct3","text":"Situational anxiety"}]},"right":{"label":"Outcomes to monitor","tokens":[{"id":"rt1","text":"Mean arterial pressure and urine output"},{"id":"rt2","text":"Serum lactate trend"},{"id":"rt3","text":"Daily caloric intake"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Rapid deterioration coordination', 'Escalation', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_348027', 'DRAG_ORDER', 'A nurse is coordinating the transfer of a stable client from the medical unit to a rehabilitation facility. Place the coordination steps in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Confirm the transfer order and that the accepting facility has a bed"},{"id":"t2","text":"Complete the interfacility transfer/handoff documentation"},{"id":"t3","text":"Give a verbal SBAR report to the receiving nurse"},{"id":"t4","text":"Ensure the client and belongings are ready and transport is arranged"},{"id":"t5","text":"Document the time of transfer and the client''s condition on departure"},{"id":"t6","text":"Order new outpatient prescriptions unrelated to the transfer"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Admission process', 'Transfer coordination', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349001', 'MCQ', 'A charge nurse receives report on four clients at shift change. Which client should the nurse assess FIRST?', 'New confusion with rising respiratory rate suggests hypoxia and possible sepsis, an unstable trend requiring immediate assessment.', '{"options":[{"id":"A","text":"A client 1 day post-op knee arthroplasty rating pain 7/10 who is due for scheduled analgesia"},{"id":"B","text":"A client with pneumonia whose respiratory rate rose from 20 to 30 with new confusion"},{"id":"C","text":"A client with heart failure whose morning weight increased 0.5 kg"},{"id":"D","text":"A client awaiting discharge whose ride has not arrived"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Pain is a priority but not immediately life-threatening compared with an airway/perfusion cue.","B":"Correct. A rising respiratory rate with new confusion signals impending decompensation and takes priority.","C":"Incorrect. A small weight change warrants follow-up but is not the most urgent.","D":"Incorrect. This is a logistical, non-clinical concern."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', 'Charge nurse rounds', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349002', 'MCQ', 'An RN is assigning tasks on a busy medical unit. Which task is MOST appropriate to delegate to a licensed practical/vocational nurse (LPN/LVN)?', 'LPNs may reinforce (not initiate) teaching and care for stable clients; initial assessment, care planning, and high-risk IV meds remain RN responsibilities.', '{"options":[{"id":"A","text":"Developing the initial nursing care plan for a newly admitted client"},{"id":"B","text":"Reinforcing teaching about a low-sodium diet with a stable client"},{"id":"C","text":"Administering the first dose of IV chemotherapy"},{"id":"D","text":"Performing the admission assessment on an unstable client"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Initial care planning is within RN scope only.","B":"Correct. Reinforcing established teaching for a stable client is within LPN scope.","C":"Incorrect. First-dose and high-risk IV agents require RN administration.","D":"Incorrect. Assessment of an unstable client is RN scope."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation & supervision', 'LPN scope', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349003', 'MCQ', 'Just before surgery, a client asks the nurse to explain the risks of the procedure because "the doctor went too fast." The consent form is already signed. Which action by the nurse is MOST appropriate?', 'When a client expresses lack of understanding, informed consent is in question; the nurse must halt and notify the provider who is responsible for disclosure.', '{"options":[{"id":"A","text":"Explain the surgical risks in detail so the client understands"},{"id":"B","text":"Reassure the client that the surgeon is highly experienced and proceed"},{"id":"C","text":"Notify the surgeon that the client has questions before proceeding"},{"id":"D","text":"Witness that the signature is valid and send the client to the OR"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. Disclosing procedure risks is the provider''s legal duty, not the nurse''s.","B":"Incorrect. This dismisses the client''s expressed lack of understanding.","C":"Correct. Expressed uncertainty means consent may not be informed; the provider must return.","D":"Incorrect. A signature without understanding is not valid informed consent."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', 'Nurse role', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349004', 'MCQ', 'A nurse receives an order to administer 40 units of insulin glargine subcutaneously; the client normally receives 4 units. The prescriber cannot be reached. What should the nurse do?', 'A suspected error requires the nurse to hold the medication and pursue clarification through the chain of command, never to administer or alter it independently.', '{"options":[{"id":"A","text":"Administer 40 units because the order is written clearly"},{"id":"B","text":"Administer 4 units based on the usual dose"},{"id":"C","text":"Hold the dose and escalate to the on-call provider or nursing supervisor"},{"id":"D","text":"Document that the order was questionable and give half the dose"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. A clearly written order that appears unsafe must still be clarified.","B":"Incorrect. The nurse cannot unilaterally change the dose.","C":"Correct. A tenfold discrepancy must be clarified before administration; escalate.","D":"Incorrect. Guessing a compromise dose is unsafe."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying & implementing orders', 'Questioning an order', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349005', 'MCQ', 'A nurse is caring for a client who is a local celebrity. A colleague from another unit, not involved in the client''s care, asks the nurse for an update. Which response is BEST?', 'Protected health information is disclosed only to those with a legitimate need to know for the client''s care, regardless of the requester''s profession.', '{"options":[{"id":"A","text":"Share only the diagnosis since the colleague is a nurse"},{"id":"B","text":"Decline and explain that only those involved in care may access the information"},{"id":"C","text":"Provide an update after the colleague promises confidentiality"},{"id":"D","text":"Refer the colleague to the client''s social media for updates"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Being a nurse does not authorize access without a care relationship.","B":"Correct. Access is limited to the client''s care team on a need-to-know basis.","C":"Incorrect. A promise does not create authorized access.","D":"Incorrect. This is inappropriate and does not address the privacy breach."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality/privacy', 'HIPAA', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349006', 'MCQ', 'A client with a valid do-not-resuscitate (DNR) order becomes unresponsive and pulseless. The family at the bedside begs the nurse to "do everything." What should the nurse do?', 'A valid DNR representing the client''s autonomous wishes must be honored; the nurse provides comfort measures and supports the grieving family.', '{"options":[{"id":"A","text":"Begin CPR because the family is now requesting it"},{"id":"B","text":"Honor the DNR order and provide comfort care and support to the family"},{"id":"C","text":"Call a code and let the provider decide on arrival"},{"id":"D","text":"Ask the family to sign a form rescinding the DNR"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Family wishes do not override a competent client''s valid directive.","B":"Correct. A valid DNR reflecting the client''s wishes is followed; support the family.","C":"Incorrect. Initiating resuscitation contradicts the valid directive.","D":"Incorrect. Family cannot rescind a competent client''s directive."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', 'DNR conflict', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349007', 'MCQ', 'A home health nurse notes a pattern of unexplained bruises and withheld meals in an older adult client cared for by an adult child. The client denies any problem. What is the nurse''s priority action?', 'Nurses are mandatory reporters; reasonable suspicion of elder abuse must be reported to the appropriate agency regardless of the client''s denial.', '{"options":[{"id":"A","text":"Respect the client''s denial and document the observations"},{"id":"B","text":"Confront the adult child directly about the bruising"},{"id":"C","text":"Report the suspected abuse to Adult Protective Services"},{"id":"D","text":"Wait for a second visit to confirm the pattern before acting"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. A competent client''s denial does not remove the nurse''s legal duty to report suspected abuse.","B":"Incorrect. Confrontation may escalate risk and is not the priority.","C":"Correct. Nurses are mandatory reporters of suspected abuse based on reasonable suspicion.","D":"Incorrect. Reporting is based on reasonable suspicion, not proof."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', 'Suspected abuse', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349008', 'MCQ', 'A nurse is giving an SBAR handoff for a client transferring to the ICU. Which statement belongs in the "Recommendation" component?', 'In SBAR, Recommendation states what the nurse thinks should happen next, such as increased monitoring or a specific intervention.', '{"options":[{"id":"A","text":"\"The client''s blood pressure dropped to 82/48 over the last hour.\""},{"id":"B","text":"\"The client was admitted yesterday with sepsis from a urinary source.\""},{"id":"C","text":"\"I think the client needs closer monitoring and possibly vasopressors.\""},{"id":"D","text":"\"I''m calling because the client is becoming hemodynamically unstable.\""}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. This is Assessment data.","B":"Incorrect. This is Background.","C":"Correct. Suggesting next steps is the Recommendation component.","D":"Incorrect. This is the Situation."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff (SBAR)', 'Transfer report', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349009', 'MCQ', 'A competent adult client with cancer decides to stop chemotherapy against the oncologist''s strong recommendation. The nurse''s role as an advocate is BEST demonstrated by which action?', 'A competent client has the right to refuse treatment; the nurse advocates by ensuring the decision is informed and supporting the client''s autonomy.', '{"options":[{"id":"A","text":"Persuading the client to reconsider the physician''s advice"},{"id":"B","text":"Ensuring the client understands the consequences and supporting the informed decision"},{"id":"C","text":"Notifying the ethics committee to overturn the decision"},{"id":"D","text":"Documenting that the client is noncompliant"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Advocacy supports the client''s autonomous choice, not persuasion.","B":"Correct. Advocacy means ensuring understanding and honoring the client''s autonomous choice.","C":"Incorrect. A competent client''s decision is not overturned.","D":"Incorrect. Exercising autonomy is not noncompliance."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy & rights', 'Refusal of treatment', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349010', 'MCQ', 'Two staff nurses have an ongoing conflict over dividing admissions that is affecting unit morale. Which approach by the nurse manager is MOST likely to produce a durable resolution?', 'Collaboration, seeking a win-win by uncovering shared goals, produces the most durable conflict resolution.', '{"options":[{"id":"A","text":"Assign admissions strictly by alternating turns to remove discretion"},{"id":"B","text":"Meet with both nurses to identify shared goals and negotiate a mutually acceptable workload plan"},{"id":"C","text":"Separate their schedules so they rarely work together"},{"id":"D","text":"Side with the more experienced nurse to settle it quickly"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This is compromise/avoidance and does not address the underlying issue.","B":"Correct. Collaboration addresses root causes and yields durable win-win outcomes.","C":"Incorrect. Avoidance leaves the conflict unresolved.","D":"Incorrect. Forcing a winner damages morale and does not resolve the issue."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Conflict management', 'Team disagreement', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349011', 'MCQ', 'A nurse is planning care to be both safe and cost-effective. Which action BEST reflects cost-effective care without compromising safety?', 'Cost-effective care conserves resources, such as by clustering care and not opening unneeded supplies, without ever sacrificing client safety.', '{"options":[{"id":"A","text":"Changing a peripheral IV site every 24 hours to prevent all infections"},{"id":"B","text":"Clustering care to reduce the number of supplies opened and unused"},{"id":"C","text":"Reusing single-use suction catheters between clients after cleaning"},{"id":"D","text":"Delaying a needed dressing change to conserve supplies"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Routine 24-hour changes exceed evidence-based intervals and waste resources.","B":"Correct. Clustering care and avoiding unused supplies reduces cost while maintaining safety.","C":"Incorrect. Reusing single-use items violates safety standards.","D":"Incorrect. Withholding needed care compromises safety."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Cost-effective care', 'Resource stewardship', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_349012', 'MCQ', 'A nurse is preparing to discharge a client on a new anticoagulant. Which finding requires the nurse to delay discharge and notify the provider?', 'A supratherapeutic INR with active bleeding is a clinical instability that makes discharge unsafe and requires provider notification.', '{"options":[{"id":"A","text":"The client verbalizes understanding of bleeding precautions"},{"id":"B","text":"The client has no ride home yet but a family member is en route"},{"id":"C","text":"The client''s INR is 6.5 with new gum bleeding this morning"},{"id":"D","text":"The client requests a written copy of the medication schedule"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. This indicates readiness, not a barrier.","B":"Incorrect. A logistical delay does not require provider notification.","C":"Correct. A supratherapeutic INR with active bleeding is unsafe for discharge and must be reported.","D":"Incorrect. This is a reasonable, easily met request."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Admit/transfer/discharge', 'Discharge readiness', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_349013', 'SATA', 'A nurse is delegating to unlicensed assistive personnel (UAP) during a heavy shift. Which tasks are appropriate to delegate? Select all that apply.', 'UAP may perform stable ADLs, data collection, and protocol-based tasks, but not feeding at-risk clients, evaluation, or teaching.', '{"options":[{"id":"A","text":"Feeding a client with dysphagia who requires aspiration precautions"},{"id":"B","text":"Obtaining routine vital signs on a stable client"},{"id":"C","text":"Assisting a stable client to ambulate to the bathroom"},{"id":"D","text":"Evaluating a client''s response to a new pain medication"},{"id":"E","text":"Performing a bladder scan on a stable postoperative client per protocol"},{"id":"F","text":"Providing perineal care to a stable incontinent client"},{"id":"G","text":"Reinforcing dietary teaching about carbohydrate counting"}]}'::jsonb, '{"answers":["B","C","E","F"],"feedback":{"A":"Incorrect. A client at aspiration risk needs nursing judgment during feeding.","D":"Incorrect. Evaluation of response requires the RN.","G":"Incorrect. Teaching, even reinforcement, is not within UAP scope."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation & supervision', 'UAP scope', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_349014', 'SATA', 'A unit is implementing a quality improvement program. Which actions are consistent with a just-culture, quality-improvement approach? Select all that apply.', 'Effective QI relies on nonpunitive reporting, root-cause analysis, trend monitoring, and process redesign, not individual blame or secrecy.', '{"options":[{"id":"A","text":"Encouraging staff to report near-misses without fear of punishment"},{"id":"B","text":"Conducting a root-cause analysis after a medication error"},{"id":"C","text":"Tracking central-line infection rates over time to identify trends"},{"id":"D","text":"Terminating the first nurse involved in any error to set an example"},{"id":"E","text":"Using aggregated data to redesign an error-prone process"},{"id":"F","text":"Keeping error reports secret from the involved staff to avoid conflict"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"D":"Incorrect. Blame-based punishment suppresses reporting and undermines safety.","F":"Incorrect. Transparency and shared learning are central to QI."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Quality/performance improvement', 'Sentinel events', 'Hard', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_349015', 'SATA', 'A nurse is coordinating discharge for a client who had a stroke with residual left-sided weakness and difficulty swallowing. Which referrals are appropriate for the nurse to initiate or recommend? Select all that apply.', 'Post-stroke rehabilitation is multidisciplinary; PT, OT, speech, and social work referrals address mobility, ADLs, swallowing, and discharge resources.', '{"options":[{"id":"A","text":"Physical therapy for mobility and gait training"},{"id":"B","text":"Speech-language pathology for swallowing evaluation"},{"id":"C","text":"Occupational therapy for activities of daily living"},{"id":"D","text":"Social work for home-care resources and support"},{"id":"E","text":"Anesthesiology for routine outpatient follow-up"},{"id":"F","text":"Pastoral care only if the client requests it"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"E":"Incorrect. Anesthesiology is not indicated for this client''s needs.","F":"Incorrect. This is a distractor; spiritual care is offered but not a stroke-rehab discipline referral here."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary collaboration', 'Referrals', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_349016', 'SATA', 'A nurse is correcting a charting error and documenting an incident. Which documentation practices are correct? Select all that apply.', 'Legal documentation requires single-line corrections, objective/timely entries, and signatures; it never obscures errors or references incident reports in the chart.', '{"options":[{"id":"A","text":"Drawing a single line through the error, initialing, and dating it"},{"id":"B","text":"Charting objective findings and the client''s own words"},{"id":"C","text":"Documenting care immediately after it is provided"},{"id":"D","text":"Recording that an incident report was filed within the chart note"},{"id":"E","text":"Using correction fluid to obscure the erroneous entry"},{"id":"F","text":"Signing each entry with name and credentials"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{"D":"Incorrect. The chart should not reference that an incident report was completed.","E":"Incorrect. Obscuring entries is prohibited in legal records."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Documentation terminology', 'Legal documentation', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_349017', 'SATA', 'A nurse observes a colleague who appears impaired, with slurred speech and the smell of alcohol, preparing to administer medications. Which actions should the nurse take? Select all that apply.', 'An impaired colleague must be removed from care, reported, and documented objectively while ensuring client coverage; ignoring the situation is a breach of duty.', '{"options":[{"id":"A","text":"Remove the colleague from client care immediately"},{"id":"B","text":"Report the concern to the nurse manager or supervisor"},{"id":"C","text":"Ensure the colleague''s assigned clients are safely covered"},{"id":"D","text":"Say nothing to avoid getting a coworker in trouble"},{"id":"E","text":"Document the objective observations of the behavior"},{"id":"F","text":"Send the colleague home to drive without further action"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"D":"Incorrect. Failing to act endangers clients and violates the duty to report.","F":"Incorrect. Allowing an impaired person to drive and skipping escalation is unsafe and incomplete."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Legal scope of practice', 'Reporting unsafe practice', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_349018', 'SELECT_N', 'During a mass-casualty event using START triage, which 3 clients should be tagged RED (immediate) priority? Select the 3 highest-priority clients.', 'RED/immediate tags go to salvageable clients with airway/breathing/perfusion compromise; walking-wounded are GREEN and the apneic-after-repositioning client is BLACK/expectant.', '{"options":[{"id":"A","text":"An adult with a respiratory rate of 34 and a capillary refill of 4 seconds"},{"id":"B","text":"An adult with an open femur fracture and a heart rate of 130 who cannot follow commands"},{"id":"C","text":"An adult with sucking chest wound and rapid shallow breathing"},{"id":"D","text":"An adult with a closed forearm fracture who is walking and talking"},{"id":"E","text":"An adult with superficial abrasions requesting a bandage"},{"id":"F","text":"An adult with no spontaneous respirations after airway repositioning"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', 'Post-disaster triage', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_349019', 'SELECT_N', 'A case manager is coordinating care for a client with newly diagnosed heart failure who lives alone. Which 2 interventions best support safe continuity of care after discharge? Select 2.', 'Timely follow-up and home-health coordination for monitoring reduce readmission and support safe transitions for a client living alone.', '{"options":[{"id":"A","text":"Arranging a follow-up appointment within 7 days of discharge"},{"id":"B","text":"Coordinating home-health visits for medication and weight monitoring"},{"id":"C","text":"Scheduling all specialist visits on the same distant future date"},{"id":"D","text":"Providing verbal instructions only, without written materials"},{"id":"E","text":"Delaying the referral to cardiac rehab until symptoms worsen"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Case management', 'Continuity of care', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_349020', 'TF', 'When a registered nurse delegates a task to unlicensed assistive personnel, accountability for the outcome of that task transfers entirely to the assistive personnel.', 'The RN who delegates remains accountable for the delegation decision and supervision; accountability for the nursing outcome is not transferred.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation & supervision', NULL, 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_349021', 'MATRIX', 'For each task, click to indicate the lowest-level provider to whom it may be appropriately assigned.', 'Assessment and care planning are RN-only; LPNs give routine meds and reinforce teaching; UAP handle stable ADLs and data collection.', '{"row_label":"Task","rows":[{"id":"r1","text":"Initial admission assessment of an unstable client"},{"id":"r2","text":"Administering a scheduled oral antibiotic to a stable client"},{"id":"r3","text":"Recording a stable client''s intake and output"},{"id":"r4","text":"Developing and revising the plan of care"},{"id":"r5","text":"Reinforcing previously taught wound-care instructions"},{"id":"r6","text":"Assisting a stable client with morning hygiene"}],"columns":[{"id":"c1","text":"UAP"},{"id":"c2","text":"LPN/LVN"},{"id":"c3","text":"RN only"}]}'::jsonb, '{"cells":{"r1":"c3","r2":"c2","r3":"c1","r4":"c3","r5":"c2","r6":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation & supervision', 'Scope by role', 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_349022', 'MATRIX_MR', 'For each situation, select which principles apply (more than one may apply).', 'Communicable-disease and abuse reporting are mandatory and permitted without consent; care-team sharing is permitted; employer disclosure needs consent.', '{"row_label":"Situation","rows":[{"id":"r1","text":"Reporting a confirmed case of active tuberculosis to public health"},{"id":"r2","text":"Releasing records to a client''s employer for a promotion"},{"id":"r3","text":"Sharing information with the treating specialist on the care team"},{"id":"r4","text":"Reporting suspected child abuse to protective services"}],"columns":[{"id":"c1","text":"Requires client consent"},{"id":"c2","text":"Permitted without consent"},{"id":"c3","text":"Mandatory report"}]}'::jsonb, '{"cells":{"r1":["c2","c3"],"r2":["c1"],"r3":["c2"],"r4":["c2","c3"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client rights & advocacy', 'Disclosure without consent', 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_349023', 'CLOZE', 'Among four stable-appearing clients, the nurse should assess the client with {1} first, because this cue reflects a threat to {2}.', 'Using the ABC framework, a threat to airway patency (new stridor) outranks lower-priority comfort and routine needs.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"new-onset stridor after extubation"},{"id":"c2","text":"a scheduled dressing change"},{"id":"c3","text":"a request for a warm blanket"}]},{"id":"b2","choices":[{"id":"c1","text":"airway patency"},{"id":"c2","text":"comfort"},{"id":"c3","text":"self-esteem"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', 'ABC framework', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_349024', 'HIGHLIGHT', 'Highlight the findings in the new admission orders that require the nurse to clarify before implementing. Orders: [[Heparin 25,000 units IV push now]]. [[Regular diet]]. [[Potassium chloride 40 mEq IV push over 2 minutes]]. Ambulate as tolerated. [[Furosemide 40 mg IV once]] for a client with a potassium of 2.8 mEq/L. Vital signs every 4 hours.', 'IV push potassium is lethal, a massive heparin bolus is unsafe, and furosemide with hypokalemia is contradictory; each must be clarified before implementing.', '{"chunks":[{"id":"h1","text":"Heparin 25,000 units IV push now"},{"id":"h2","text":"Potassium chloride 40 mEq IV push over 2 minutes"},{"id":"h3","text":"Furosemide 40 mg IV once"},{"id":"h4","text":"Regular diet"}]}'::jsonb, '{"correct_ids":["h1","h2","h3"],"feedback":{"h1":"This dose and route are unsafe; heparin is not given as a large IV push bolus like this without clarification.","h2":"IV push potassium is never given; it must be diluted and infused slowly.","h3":"Giving a potassium-wasting diuretic to a client with K 2.8 needs clarification.","h4":"A routine diet order requires no clarification."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying & implementing orders', 'Unsafe order cues', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_349025', 'BOWTIE', 'A postoperative client on the surgical unit shows early deterioration. Complete the diagram by selecting the priority problem, the immediate actions, and the parameters to monitor.', 'Early deterioration requires activating rapid response and staying with the client while monitoring neuro and respiratory status.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Activate the rapid response team"},{"id":"lt2","text":"Reassess and stay with the client"},{"id":"lt3","text":"Wait for the next scheduled vitals round"},{"id":"lt4","text":"Delegate ongoing assessment to UAP"},{"id":"lt5","text":"Document and leave to finish other tasks"}]},"centre":{"label":"Priority problem","tokens":[{"id":"ct1","text":"Clinical deterioration requiring escalation"},{"id":"ct2","text":"Stable expected postoperative course"},{"id":"ct3","text":"Nonurgent comfort need"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Level of consciousness"},{"id":"rt2","text":"Respiratory rate and oxygen saturation"},{"id":"rt3","text":"Client''s meal preferences"},{"id":"rt4","text":"Visitor log"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation & escalation', 'Deteriorating client', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_349026', 'DRAG_CLOZE', 'On a short-staffed shift, the charge nurse should assign the [1] to the experienced RN and the [2] to the newly oriented nurse.', 'The most acute, unstable client goes to the experienced RN; a stable, predictable client is appropriate for the newer nurse.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"unstable client on a titratable vasoactive drip"},{"id":"t2","text":"stable client awaiting routine discharge teaching"},{"id":"t3","text":"client requesting extra pillows"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation & assignment', 'Matching staff to acuity', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_349027', 'DRAG_ORDER', 'A nurse realizes a medication was given to the wrong client. Place the nurse''s actions in the correct priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Assess the client for adverse effects"},{"id":"t2","text":"Notify the provider of the error"},{"id":"t3","text":"Implement any new orders and monitor the client"},{"id":"t4","text":"Complete an incident/occurrence report"},{"id":"t5","text":"Review the process to prevent recurrence"},{"id":"t6","text":"Tell the client''s family it was a minor issue"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying & implementing orders', 'Medication error response', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_359001', 'MCQ', 'A client on a continuous heparin infusion for a pulmonary embolism has an aPTT result of 120 seconds (control 30 seconds; therapeutic goal 1.5-2.5 times control). The client''s gums are oozing. Which action should the nurse take FIRST?', 'An aPTT well above therapeutic with bleeding indicates heparin excess; stopping the infusion is the priority before protamine is considered.', '{"options":[{"id":"A","text":"Stop the heparin infusion and notify the provider"},{"id":"B","text":"Decrease the infusion rate per protocol and recheck in 6 hours"},{"id":"C","text":"Administer vitamin K intramuscularly"},{"id":"D","text":"Apply pressure to the gums and continue the infusion"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An aPTT of 120 s is far above the 45-75 s therapeutic range with active bleeding; the infusion must be stopped.","B":"Incorrect. Active bleeding with a critically high aPTT requires stopping, not merely titrating down.","C":"Incorrect. Vitamin K reverses warfarin, not heparin; the antidote for heparin is protamine sulfate.","D":"Incorrect. Local measures do not address the systemic over-anticoagulation."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Heparin monitoring', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_359002', 'MCQ', 'A client receiving IV vancomycin every 12 hours has a trough level drawn before the fourth dose that is 24 mcg/mL (target trough 10-20 mcg/mL). The serum creatinine has risen from 0.9 to 1.6 mg/dL. Which is the most appropriate nursing action?', 'A high vancomycin trough with rising creatinine indicates nephrotoxic accumulation; the dose is held and the provider notified for adjustment.', '{"options":[{"id":"A","text":"Hold the next dose and notify the provider of the elevated trough and rising creatinine"},{"id":"B","text":"Administer the next dose over a longer infusion time to prevent red man syndrome"},{"id":"C","text":"Give the dose as scheduled since the trough is only slightly elevated"},{"id":"D","text":"Increase the client''s IV fluids and redraw the trough after the next dose"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A supratherapeutic trough with rising creatinine signals nephrotoxic accumulation; the dose is held pending provider adjustment.","B":"Incorrect. Slowing the infusion addresses histamine release, not the toxic accumulation and renal decline.","C":"Incorrect. The trough is above target and creatinine is rising — continuing risks worsening nephrotoxicity.","D":"Incorrect. Hydration alone does not justify giving a dose when accumulation is already evident."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Aminoglycosides', 'Vancomycin trough', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_359003', 'MCQ', 'At 0730 a client receives 10 units of regular insulin and 20 units of NPH insulin subcutaneously before breakfast. The nurse should be most alert for hypoglycemia related to the NPH insulin at which time?', 'NPH is intermediate-acting with a peak of about 6-10 hours; a 0730 dose peaks in the mid-to-late afternoon.', '{"options":[{"id":"A","text":"1500-1730"},{"id":"B","text":"0800-0830"},{"id":"C","text":"0930-1130"},{"id":"D","text":"2200-2400"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. NPH peaks roughly 6-10 hours after administration, placing the highest hypoglycemia risk in the mid-to-late afternoon.","B":"Incorrect. This reflects the very early onset window, not the NPH peak.","C":"Incorrect. This 2-4 hour window is the peak of regular insulin, not NPH.","D":"Incorrect. This is beyond the expected NPH peak from a 0730 dose."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Peak action', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_359004', 'MCQ', 'A client maintained on lithium reports having had gastroenteritis with vomiting and diarrhea for two days. The client now has coarse hand tremors, slurred speech, and unsteady gait. The lithium level is 1.9 mEq/L. Which factor most likely precipitated these findings?', 'Volume and sodium depletion increase renal lithium reabsorption, driving levels into the toxic range; lithium''s narrow index makes this dangerous.', '{"options":[{"id":"A","text":"Sodium and fluid depletion from the illness increased lithium reabsorption"},{"id":"B","text":"The client''s dietary sodium intake was excessive"},{"id":"C","text":"Lithium has a wide therapeutic index that tolerates fluid shifts"},{"id":"D","text":"The findings are expected side effects unrelated to the level"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sodium loss and dehydration cause the kidneys to retain lithium, raising the level into the toxic range.","B":"Incorrect. High sodium would lower, not raise, the lithium level.","C":"Incorrect. Lithium has a narrow therapeutic index and is highly sensitive to fluid and sodium changes.","D":"Incorrect. Coarse tremor, slurred speech, and ataxia with a level of 1.9 mEq/L are signs of toxicity."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Psychiatric/Mental Health', 'Psychotropics', 'Lithium toxicity', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_359005', 'MCQ', 'A postoperative client receiving morphine via patient-controlled analgesia is difficult to arouse with a respiratory rate of 7 breaths/min and SpO2 of 86%. Naloxone is prescribed. Which statement best guides the nurse''s administration?', 'Naloxone is titrated to restore ventilation; its short half-life relative to morphine means the nurse must anticipate resedation and repeat dosing.', '{"options":[{"id":"A","text":"Titrate small IV doses every 2-3 minutes to restore adequate respirations, anticipating that repeat dosing may be needed"},{"id":"B","text":"Administer the full vial rapidly to fully reverse all opioid effects at once"},{"id":"C","text":"Give one dose and discontinue monitoring once the client responds"},{"id":"D","text":"Withhold naloxone and simply stop the PCA pump until the client awakens"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone is titrated to effect, and because its half-life is shorter than morphine''s, resedation and repeat dosing are anticipated.","B":"Incorrect. A large rapid dose can precipitate severe pain, agitation, and cardiovascular instability.","C":"Incorrect. Naloxone''s short duration means the client can re-sedate as it wears off.","D":"Incorrect. With a respiratory rate of 7 and SpO2 of 86%, reversal is required now, not observation alone."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Respiratory', 'Opioids', 'Naloxone', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_359006', 'MCQ', 'A prescription reads: ''Potassium chloride 40 mEq IV push now'' for a client with a serum potassium of 2.8 mEq/L. What is the nurse''s most appropriate action?', 'IV push potassium chloride causes fatal arrhythmias; it must always be diluted and infused, so an order to push it is clarified.', '{"options":[{"id":"A","text":"Clarify the order because IV potassium is never given by push and must be diluted and infused"},{"id":"B","text":"Administer the dose slowly over 2 minutes using a filter needle"},{"id":"C","text":"Give the potassium intramuscularly instead to avoid the IV push"},{"id":"D","text":"Hold the dose and recheck the potassium in the morning"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. IV push potassium is fatal; it must always be diluted and given as a controlled infusion, so the order requires clarification.","B":"Incorrect. No push rate is safe for IV potassium — it must be infused diluted.","C":"Incorrect. Potassium chloride is not given IM; it is highly irritating and can cause tissue necrosis.","D":"Incorrect. A level of 2.8 mEq/L requires replacement, but the route in the order is unsafe and must be clarified."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Electrolytes', 'IV potassium', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_359007', 'MCQ', 'Fifteen minutes into a packed red blood cell transfusion, a client develops flank pain, chills, and a temperature rise from 37.0°C to 38.6°C, with pink-tinged urine. After stopping the transfusion, which action should the nurse take NEXT?', 'After stopping a suspected hemolytic reaction, the nurse maintains IV access with normal saline via fresh tubing to protect the kidneys.', '{"options":[{"id":"A","text":"Keep the IV line open with 0.9% normal saline using new tubing"},{"id":"B","text":"Slow the transfusion and continue observing the client"},{"id":"C","text":"Administer the next unit of blood to complete the order"},{"id":"D","text":"Flush the existing blood tubing with dextrose 5% in water"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Maintaining IV access with saline through new tubing preserves renal perfusion and avoids infusing more incompatible blood.","B":"Incorrect. A hemolytic reaction requires stopping the blood entirely, not slowing it.","C":"Incorrect. Further transfusion is contraindicated during an acute reaction.","D":"Incorrect. Dextrose causes RBC hemolysis and the contaminated tubing must be replaced, not flushed into the client."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood-product administration', 'Transfusion reaction', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_359008', 'MCQ', 'A nurse discovers that the next bag of total parenteral nutrition has not arrived from the pharmacy and the current bag will empty in 20 minutes. Which action is most appropriate?', 'When TPN is interrupted, 10% dextrose at the same rate maintains the glucose load and prevents rebound hypoglycemia.', '{"options":[{"id":"A","text":"Hang 10% dextrose in water at the same rate until the new TPN bag is available"},{"id":"B","text":"Stop the infusion and flush the central line until the new bag arrives"},{"id":"C","text":"Slow the current bag to a keep-vein-open rate to make it last longer"},{"id":"D","text":"Substitute a bag of lactated Ringer''s solution at the TPN rate"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Infusing dextrose prevents the rebound hypoglycemia that can occur when high-concentration TPN is abruptly stopped.","B":"Incorrect. Abruptly stopping TPN risks rebound hypoglycemia.","C":"Incorrect. Deliberately underdosing does not deliver adequate glucose and alters the prescribed rate.","D":"Incorrect. Lactated Ringer''s contains no dextrose and will not prevent hypoglycemia."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'Parenteral nutrition', 'TPN safety', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_359009', 'MCQ', 'A client started on lisinopril 3 days ago now has a serum potassium of 5.8 mEq/L and a creatinine that has risen from 1.0 to 1.9 mg/dL. Which additional home medication is the most important for the nurse to report to the provider?', 'Potassium-sparing diuretics like spironolactone combined with ACE inhibitors sharply increase hyperkalemia and renal risk.', '{"options":[{"id":"A","text":"Spironolactone taken for heart failure"},{"id":"B","text":"Acetaminophen taken for occasional headache"},{"id":"C","text":"A daily multivitamin without minerals"},{"id":"D","text":"Loratadine taken for seasonal allergies"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Combining a potassium-sparing diuretic with an ACE inhibitor compounds hyperkalemia and renal risk, so it must be reported.","B":"Incorrect. Acetaminophen does not raise potassium or worsen ACE-related renal effects.","C":"Incorrect. A mineral-free multivitamin does not contribute to hyperkalemia.","D":"Incorrect. Loratadine has no clinically significant effect on potassium or renal function here."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antihypertensives', 'ACE inhibitors', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_359010', 'MCQ', 'A heparin drip is prescribed at 18 units/kg/hour for a client who weighs 80 kg. The bag contains 25,000 units of heparin in 500 mL of 0.9% normal saline. At what rate in mL/hour should the nurse set the infusion pump? (Round to the nearest whole number.)', '18 units/kg × 80 kg = 1,440 units/hr; at a concentration of 50 units/mL, the rate is 28.8 mL/hr, rounded to 29 mL/hr.', '{"options":[{"id":"A","text":"29 mL/hour"},{"id":"B","text":"14 mL/hour"},{"id":"C","text":"58 mL/hour"},{"id":"D","text":"36 mL/hour"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. 18 units × 80 kg = 1,440 units/hr; the bag is 50 units/mL, so 1,440 ÷ 50 = 28.8, rounded to 29 mL/hr.","B":"Incorrect. This roughly halves the required dose, likely from a concentration error.","C":"Incorrect. This doubles the correct rate, delivering an unsafe amount of heparin.","D":"Incorrect. This does not correspond to the 1,440 units/hr dose at 50 units/mL."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Dosage calculation', 'Weight-based infusion', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_359011', 'SATA', 'A client receiving myelosuppressive chemotherapy has an absolute neutrophil count of 480/mm3. Which findings or actions require the nurse''s immediate attention or intervention? Select all that apply.', 'Neutropenic precautions require urgent attention to fever, infectious exposure, raw foods, and rectal procedures, while hand hygiene and masking are protective.', '{"options":[{"id":"A","text":"Temperature of 38.3°C"},{"id":"B","text":"A visitor with an active upper respiratory infection at the bedside"},{"id":"C","text":"Fresh raw salad and unpeeled fruit on the meal tray"},{"id":"D","text":"Rectal temperature being taken by unlicensed personnel"},{"id":"E","text":"Client performing frequent hand hygiene"},{"id":"F","text":"Client wearing a mask when leaving the room"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. In neutropenia, a low-grade fever may be the only sign of life-threatening infection and requires urgent action.","B":"Correct. Exposure to infection is dangerous for a neutropenic client and must be stopped.","C":"Correct. A neutropenic diet avoids raw produce that can carry organisms.","D":"Correct. Rectal manipulation risks mucosal injury and bacterial translocation and must be avoided.","E":"Incorrect. Hand hygiene is protective and should be encouraged.","F":"Incorrect. Masking during transport is an appropriate protective measure."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Chemotherapy', 'Neutropenia teaching', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_359012', 'SATA', 'A nurse is preparing to administer insulin to several clients. Which actions reflect safe practice for this high-alert medication? Select all that apply.', 'Independent double-checks, clear-before-cloudy mixing, unit-calibrated syringes, and a current glucose are core insulin safety practices.', '{"options":[{"id":"A","text":"Have a second nurse independently verify the insulin type and dose"},{"id":"B","text":"Draw up regular insulin before NPH when mixing in one syringe"},{"id":"C","text":"Use a syringe calibrated in units, never a tuberculin syringe"},{"id":"D","text":"Confirm the client''s most recent blood glucose before administration"},{"id":"E","text":"Administer sliding-scale coverage without checking the glucose if it was normal earlier"},{"id":"F","text":"Store the mixed insulin syringe for use later in the shift"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Independent double-checks are standard for high-alert medications like insulin.","B":"Correct. Clear is drawn before cloudy to avoid contaminating the regular insulin vial.","C":"Correct. Insulin must be measured in an insulin syringe to prevent dosing errors.","D":"Correct. The current glucose guides whether the dose is appropriate.","E":"Incorrect. Sliding-scale doses require a current glucose value each time.","F":"Incorrect. Mixed insulin should be given promptly, as delay alters the action profile."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'High-risk medications', 'Insulin safety', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_359013', 'SATA', 'A client with a newly inserted central venous catheter suddenly develops dyspnea, chest pain, and a drop in blood pressure. Which nursing actions are appropriate? Select all that apply.', 'Sudden dyspnea and hypotension after CVAD insertion suggest air embolism or pneumothorax; clamp, position, oxygenate, image, and monitor closely.', '{"options":[{"id":"A","text":"Clamp the catheter and place the client in a left lateral Trendelenburg position"},{"id":"B","text":"Administer oxygen and monitor oxygen saturation"},{"id":"C","text":"Notify the provider and prepare for a stat chest x-ray"},{"id":"D","text":"Stay with the client and continuously assess vital signs"},{"id":"E","text":"Flush the catheter briskly to confirm patency"},{"id":"F","text":"Sit the client fully upright and encourage deep breathing exercises"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. This positioning traps a suspected air embolism in the right atrium away from the pulmonary outflow.","B":"Correct. Supplemental oxygen supports the client during a suspected air embolism or pneumothorax.","C":"Correct. Imaging confirms complications such as pneumothorax and guides treatment.","D":"Correct. Continuous monitoring is essential during an acute deterioration.","E":"Incorrect. Flushing could push an air embolus further and worsen the event.","F":"Incorrect. Upright positioning is not the priority for a suspected air embolism, which requires left lateral Trendelenburg."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Central venous access devices', 'Complication recognition', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_359014', 'SATA', 'A client is prescribed phenelzine, a monoamine oxidase inhibitor. Which foods and instructions should the nurse include to prevent hypertensive crisis? Select all that apply.', 'MAOIs require strict avoidance of tyramine-rich foods and sympathomimetics; sudden severe headache signals hypertensive crisis.', '{"options":[{"id":"A","text":"Avoid aged cheeses and cured or smoked meats"},{"id":"B","text":"Avoid draft beer and red wine"},{"id":"C","text":"Report a severe throbbing headache or stiff neck immediately"},{"id":"D","text":"Avoid soy sauce and other fermented soy products"},{"id":"E","text":"Fresh cottage cheese and fresh chicken are acceptable"},{"id":"F","text":"Over-the-counter cold remedies with pseudoephedrine are safe to use"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. These tyramine-rich foods can trigger a hypertensive crisis with MAOIs.","B":"Correct. These beverages contain tyramine and are contraindicated.","C":"Correct. These can signal a hypertensive crisis and warrant urgent attention.","D":"Correct. Fermented soy products are high in tyramine.","E":"This statement is accurate teaching, so it should not be flagged as something to avoid.","F":"Incorrect. Sympathomimetics like pseudoephedrine are dangerous with MAOIs and must be avoided."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Psychiatric/Mental Health', 'Psychotropics', 'MAOI teaching', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_359015', 'SATA', 'A client on digoxin and furosemide is being evaluated. Which findings increase the risk of digoxin toxicity and warrant follow-up? Select all that apply.', 'Hypokalemia, renal impairment, bradycardia, and visual halos all raise or signal digoxin toxicity.', '{"options":[{"id":"A","text":"Serum potassium of 2.9 mEq/L"},{"id":"B","text":"Serum creatinine of 2.4 mg/dL"},{"id":"C","text":"Apical heart rate of 52 beats/min"},{"id":"D","text":"Report of seeing yellow-green halos around lights"},{"id":"E","text":"Serum potassium of 4.4 mEq/L"},{"id":"F","text":"Apical heart rate of 78 beats/min"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Hypokalemia potentiates digoxin binding and increases toxicity risk.","B":"Correct. Impaired renal function reduces digoxin excretion, causing accumulation.","C":"Correct. Bradycardia can be an early manifestation of toxicity.","D":"Correct. Visual disturbances are a classic sign of digoxin toxicity.","E":"Incorrect. A normal potassium does not increase toxicity risk.","F":"Incorrect. A normal rate is not a concerning finding."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Digoxin', 'Toxicity risk factors', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_359016', 'SELECT_N', 'A client on high-dose IV furosemide for pulmonary edema is being monitored. Which 3 findings most require the nurse to intervene?', 'Severe hypokalemia, ototoxicity from rapid infusion, and orthostatic hypotension are the concerning effects of high-dose loop diuretics.', '{"options":[{"id":"A","text":"Serum potassium of 2.7 mEq/L"},{"id":"B","text":"New-onset ringing in the ears after rapid IV administration"},{"id":"C","text":"Orthostatic drop in blood pressure with dizziness on standing"},{"id":"D","text":"Urine output of 80 mL/hour"},{"id":"E","text":"Serum sodium of 139 mEq/L"},{"id":"F","text":"Client reports decreased ankle swelling"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Severe hypokalemia predisposes to dangerous arrhythmias.","B":"Correct. Ototoxicity is associated with rapid loop diuretic infusion and requires slowing the rate.","C":"Correct. Volume depletion causing orthostatic hypotension increases fall risk and needs intervention.","D":"Incorrect. This is an expected therapeutic response to the diuretic.","E":"Incorrect. This sodium value is within normal limits.","F":"Incorrect. Reduced edema is a desired outcome."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Diuretics', 'Loop diuretic monitoring', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_359017', 'MATRIX', 'For each medication, select whether the listed agent is the correct reversal/antidote or an incorrect pairing.', 'Vitamin K reverses warfarin, protamine reverses heparin, and calcium gluconate reverses magnesium toxicity; flumazenil reverses benzodiazepines and acetylcysteine treats acetaminophen overdose.', '{"row_label":"Antidote pairing","rows":[{"id":"r1","text":"Warfarin — vitamin K (phytonadione)"},{"id":"r2","text":"Heparin — protamine sulfate"},{"id":"r3","text":"Opioid overdose — flumazenil"},{"id":"r4","text":"Magnesium sulfate toxicity — calcium gluconate"},{"id":"r5","text":"Acetaminophen overdose — naloxone"}],"columns":[{"id":"c1","text":"Correct antidote"},{"id":"c2","text":"Incorrect pairing"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c1","r3":"c2","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'High-risk medications', 'Reversal agents', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_359018', 'MATRIX_MR', 'For each medication, select all laboratory values the nurse should review before and during therapy (more than one may apply).', 'Warfarin is monitored by INR/PT; digoxin therapy requires potassium and drug levels; spironolactone requires potassium; vancomycin requires serum trough levels.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Warfarin"},{"id":"r2","text":"Digoxin"},{"id":"r3","text":"Spironolactone"},{"id":"r4","text":"Vancomycin"}],"columns":[{"id":"c1","text":"Potassium"},{"id":"c2","text":"INR/PT"},{"id":"c3","text":"Serum drug level"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1","c3"],"r3":["c1"],"r4":["c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Pre-administration data review', 'Lab monitoring', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_359019', 'CLOZE', 'A client with preeclampsia is receiving an IV magnesium sulfate infusion. The nurse must hold the infusion and notify the provider if the {1} are absent, because this is an early sign of {2}.', 'Loss of deep tendon reflexes is an early sign of magnesium toxicity and precedes respiratory depression, prompting the nurse to hold the infusion.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"deep tendon reflexes"},{"id":"c2","text":"bowel sounds"},{"id":"c3","text":"pedal pulses"}]},{"id":"b2","choices":[{"id":"c1","text":"magnesium toxicity"},{"id":"c2","text":"hypomagnesemia"},{"id":"c3","text":"eclamptic seizure"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Reproductive', 'Titration to parameters', 'Magnesium sulfate', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_359020', 'HIGHLIGHT', 'A client 2 hours after receiving IV hydromorphone is assessed. Highlight the findings that require immediate follow-up. The client [[respiratory rate of 8 breaths/min]], [[oxygen saturation of 88% on room air]], is [[difficult to arouse]], has a pain rating of 3/10, [[pinpoint pupils]], and a [[heart rate of 74 beats/min]].', 'Respiratory rate of 8, SpO2 of 88%, difficulty arousing, and pinpoint pupils together indicate opioid-induced respiratory depression needing follow-up.', '{"chunks":[{"id":"h1","text":"respiratory rate of 8 breaths/min"},{"id":"h2","text":"oxygen saturation of 88% on room air"},{"id":"h3","text":"difficult to arouse"},{"id":"h4","text":"pinpoint pupils"},{"id":"h5","text":"heart rate of 74 beats/min"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h4"],"feedback":{"h1":"Correct. Respiratory depression is the hallmark danger of opioids.","h2":"Correct. Hypoxemia requires immediate intervention.","h3":"Correct. Decreased level of consciousness signals over-sedation.","h4":"Correct. Miosis with sedation and low respirations points to opioid toxicity.","h5":"A normal heart rate does not require follow-up."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Respiratory', 'Response evaluation', 'Opioid safety', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_359021', 'BOWTIE', 'During a transfusion a client develops wheezing, hives, and hypotension. Complete the diagram by selecting the condition, the actions to take, and the parameters to monitor.', 'Wheezing, hives, and hypotension indicate an anaphylactic reaction; stop the blood, give epinephrine and antihistamine, and monitor airway and blood pressure.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Stop the transfusion immediately"},{"id":"lt2","text":"Prepare to administer epinephrine and antihistamine"},{"id":"lt3","text":"Slow the transfusion and continue"},{"id":"lt4","text":"Apply warming blankets"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Anaphylactic transfusion reaction"},{"id":"ct2","text":"Febrile nonhemolytic reaction"},{"id":"ct3","text":"Circulatory overload"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Airway patency and breath sounds"},{"id":"rt2","text":"Blood pressure"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Bowel sounds"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Blood-product administration', 'Anaphylactic reaction', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_359022', 'DRAG_CLOZE', 'A client on warfarin for atrial fibrillation has an INR of 5.6 with no active bleeding. The nurse anticipates that the provider will [1] the next warfarin dose and may prescribe [2] as the reversal agent.', 'An INR of 5.6 is supratherapeutic, so warfarin is held and vitamin K is the reversal agent.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"hold"},{"id":"t2","text":"vitamin K"},{"id":"t3","text":"increase"},{"id":"t4","text":"protamine sulfate"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Warfarin monitoring', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_359023', 'DRAG_ORDER', 'Moments after an IV antibiotic is started, a client develops stridor, facial swelling, and hypotension. Place the nurse''s actions in priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Stop the antibiotic infusion"},{"id":"t2","text":"Maintain a patent airway and apply oxygen"},{"id":"t3","text":"Administer prescribed epinephrine"},{"id":"t4","text":"Notify the rapid response team"},{"id":"t5","text":"Document the reaction and update the allergy record"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'IV infusion monitoring', 'Anaphylaxis to IV antibiotic', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_359024', 'TF', 'When a vesicant chemotherapy agent extravasates into the tissue, the nurse''s correct first action is to immediately remove the peripheral IV catheter and apply firm pressure to the site.', 'The infusion is stopped but the catheter is left in place to aspirate residual drug and instill an antidote; removing it and applying pressure would spread the vesicant and worsen tissue injury.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Musculoskeletal', 'IV site care', 'Extravasation of a vesicant', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360001', 'MCQ', 'A client on a continuous IV heparin infusion has an aPTT result of 110 seconds (control 30 seconds; therapeutic range 46–70). The client''s platelet count has dropped from 250,000 to 90,000/mm3 over 48 hours. Which action should the nurse take FIRST?', 'A precipitous platelet drop during heparin therapy signals possible HIT; the nurse stops heparin and notifies the provider before other measures.', '{"options":[{"id":"A","text":"Stop the heparin infusion and notify the provider"},{"id":"B","text":"Decrease the infusion rate per the titration protocol and recheck aPTT in 6 hours"},{"id":"C","text":"Administer protamine sulfate at the calculated reversal dose"},{"id":"D","text":"Continue the infusion and transfuse one unit of platelets"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A >50% platelet drop with supratherapeutic aPTT suggests heparin-induced thrombocytopenia; heparin must be discontinued immediately.","B":"Incorrect. Simply lowering the rate does not address the suspected HIT signalled by the platelet fall.","C":"Incorrect. Protamine is not first-line here and requires an order; stopping the drug and notifying come first.","D":"Incorrect. Platelet transfusion in HIT can worsen thrombosis and does not correct the cause."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Heparin monitoring', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360002', 'MCQ', 'A client receives IV gentamicin every 8 hours. The morning trough level drawn just before the scheduled dose is 2.8 mcg/mL (therapeutic trough <2 mcg/mL). Serum creatinine has risen from 0.9 to 1.6 mg/dL. Which action is the priority?', 'An elevated aminoglycoside trough with rising creatinine signals accumulation and nephrotoxicity; the nurse holds the dose and notifies the provider.', '{"options":[{"id":"A","text":"Hold the dose and notify the provider of the elevated trough and rising creatinine"},{"id":"B","text":"Administer the dose now and draw a peak level 30 minutes after"},{"id":"C","text":"Administer the dose over a longer infusion time to reduce toxicity"},{"id":"D","text":"Encourage oral fluids and reassess the trough with the next scheduled dose"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A high trough with rising creatinine indicates drug accumulation and nephrotoxicity risk; the dose is held and the provider notified.","B":"Incorrect. Giving another dose when the trough is elevated compounds nephrotoxicity.","C":"Incorrect. Slower infusion does not lower an already-elevated trough or protect the kidneys.","D":"Incorrect. This delays action while accumulation continues."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Aminoglycosides', 'Peak and trough', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360003', 'MCQ', 'Fifteen minutes into an IV vancomycin infusion, a client develops flushing and an erythematous rash over the face, neck, and upper torso with mild pruritus. Vital signs are stable. Which is the most appropriate nursing action?', 'Vancomycin flushing reaction is caused by rapid infusion and is managed by slowing the rate, not by stopping the drug or treating for anaphylaxis.', '{"options":[{"id":"A","text":"Slow the infusion rate and continue monitoring; this is an infusion-related reaction"},{"id":"B","text":"Stop the drug permanently and document a true vancomycin allergy"},{"id":"C","text":"Administer IM epinephrine for anaphylaxis"},{"id":"D","text":"Increase the infusion rate to finish the dose quickly and remove the drug"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Flushing of the upper body from rapid vancomycin infusion (vancomycin flushing reaction) is rate-related; slowing the infusion typically resolves it.","B":"Incorrect. This histamine-mediated reaction is not an IgE allergy and does not contraindicate future use.","C":"Incorrect. Stable vitals and isolated upper-body flushing do not indicate anaphylaxis.","D":"Incorrect. A faster rate worsens the histamine release."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Integumentary', 'Vancomycin', 'Infusion reaction', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360004', 'MCQ', 'A postoperative client receiving IV morphine via PCA has a respiratory rate of 6/min, is difficult to arouse, and has an SpO2 of 84%. Naloxone is prescribed. Which administration approach is most appropriate?', 'Naloxone is titrated in small IV increments in opioid-tolerant clients to reverse respiratory depression while avoiding acute withdrawal.', '{"options":[{"id":"A","text":"Administer small titrated IV doses of naloxone while monitoring respiratory rate"},{"id":"B","text":"Give the full ampule of naloxone as a rapid IV push to fully reverse the opioid"},{"id":"C","text":"Withhold naloxone and simply stop the PCA, then reassess in 30 minutes"},{"id":"D","text":"Administer naloxone subcutaneously and delay reassessment until it is absorbed"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. In an opioid-dependent postoperative client, naloxone is titrated in small increments to restore ventilation without precipitating severe withdrawal and uncontrolled pain.","B":"Incorrect. A large rapid dose can trigger acute withdrawal, severe pain, hypertension, and pulmonary edema.","C":"Incorrect. With RR 6 and SpO2 84%, waiting is unsafe; reversal is indicated.","D":"Incorrect. In an emergency with hypoventilation, the IV titrated route provides rapid, controllable reversal."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Naloxone titration', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360005', 'MCQ', 'A client stabilized on lithium presents with coarse hand tremor, ataxia, slurred speech, and vomiting. The client recently started a new medication. Which newly added drug most likely precipitated these findings?', 'Thiazide diuretics decrease renal lithium clearance, raising levels into the toxic range and producing neurologic and GI toxicity.', '{"options":[{"id":"A","text":"Hydrochlorothiazide"},{"id":"B","text":"Acetaminophen"},{"id":"C","text":"Loratadine"},{"id":"D","text":"Docusate sodium"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Thiazide diuretics reduce renal lithium clearance and raise serum lithium, precipitating toxicity (tremor, ataxia, dysarthria, vomiting).","B":"Incorrect. Acetaminophen does not significantly alter lithium levels.","C":"Incorrect. This antihistamine does not affect lithium excretion.","D":"Incorrect. A stool softener has no meaningful interaction with lithium."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Psychiatric/Mental Health', 'Lithium', 'Toxicity and interactions', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360006', 'MCQ', 'A client receives a morning dose of NPH insulin at 0700 and regular insulin at 0700 before breakfast. At which time is the client at greatest risk for hypoglycemia from the NPH component?', 'NPH is an intermediate-acting insulin peaking about 4–12 hours after dosing, placing greatest hypoglycemia risk in the afternoon for a morning dose.', '{"options":[{"id":"A","text":"Between 1500 and 1900 (late afternoon)"},{"id":"B","text":"Between 0715 and 0745"},{"id":"C","text":"Between 0900 and 1100 (mid-morning)"},{"id":"D","text":"Between 0300 and 0500 the next morning"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. NPH peaks roughly 4–12 hours after administration, so a 0700 dose places peak hypoglycemia risk in the mid-to-late afternoon.","B":"Incorrect. That reflects the very early onset window, not NPH''s peak.","C":"Incorrect. This is closer to the regular insulin peak, not NPH.","D":"Incorrect. That window is beyond NPH''s duration for a morning dose."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Peak-action timing', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360007', 'MCQ', 'A provider prescribes a dopamine infusion at 5 mcg/kg/min for a client weighing 80 kg. The bag contains 400 mg of dopamine in 250 mL of D5W. At what rate (mL/hr) should the nurse set the infusion pump? Round to the nearest whole number.', 'Dose = 5 mcg/kg/min × 80 kg = 24 mg/hr; dividing by the 1.6 mg/mL concentration gives 15 mL/hr.', '{"options":[{"id":"A","text":"15 mL/hr"},{"id":"B","text":"24 mL/hr"},{"id":"C","text":"9 mL/hr"},{"id":"D","text":"30 mL/hr"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. 5 mcg × 80 kg = 400 mcg/min = 24,000 mcg/hr = 24 mg/hr. Concentration = 400 mg/250 mL = 1.6 mg/mL. 24 ÷ 1.6 = 15 mL/hr.","B":"Incorrect. This is the mg/hr dose, not the volumetric rate after dividing by concentration.","C":"Incorrect. This underestimates by using an incorrect weight or concentration step.","D":"Incorrect. This doubles the correct rate."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Dosage calculation', 'Weight-based drip', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360008', 'MCQ', 'Thirty minutes into a packed red blood cell transfusion, a client develops fever, chills, flank pain, and reports a sense of impending doom; urine appears dark. Which action should the nurse take FIRST?', 'Fever, flank pain, dark urine, and doom indicate acute hemolytic transfusion reaction; the nurse stops the blood first and maintains saline through fresh tubing.', '{"options":[{"id":"A","text":"Stop the transfusion and keep the IV line open with normal saline via new tubing"},{"id":"B","text":"Slow the transfusion rate and administer an antipyretic"},{"id":"C","text":"Notify the blood bank and complete the reaction paperwork before intervening"},{"id":"D","text":"Administer diphenhydramine and resume the transfusion once symptoms ease"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These findings suggest an acute hemolytic reaction; stopping the blood immediately and maintaining IV access with saline protects renal perfusion and is the first action.","B":"Incorrect. Signs of hemolysis require stopping the transfusion, not slowing it.","C":"Incorrect. Documentation follows stopping the transfusion and stabilizing the client.","D":"Incorrect. Antihistamines treat mild allergic reactions, not hemolysis; the unit must not be resumed."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood products', 'Transfusion reaction', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360009', 'MCQ', 'While a nurse changes the cap on a client''s central venous catheter, the client suddenly becomes dyspneic, anxious, and hypotensive with a churning murmur auscultated over the precordium. Which position should the nurse place the client in FIRST?', 'For suspected venous air embolism from a central line, left lateral Trendelenburg traps air in the right ventricle and reduces pulmonary outflow obstruction.', '{"options":[{"id":"A","text":"Left lateral Trendelenburg (left side down, head lowered)"},{"id":"B","text":"High Fowler''s position"},{"id":"C","text":"Right lateral with head elevated"},{"id":"D","text":"Supine with legs elevated only"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Suspected air embolism is managed by positioning left side down with head lowered to trap air in the right ventricle apex, away from the pulmonary outflow tract.","B":"Incorrect. Upright positioning can worsen air migration into the pulmonary circulation.","C":"Incorrect. Right side down promotes air passage into the pulmonary artery.","D":"Incorrect. Leg elevation alone does not trap air in the right ventricle."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Central venous access devices', 'Air embolism', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360010', 'MCQ', 'A client''s total parenteral nutrition (TPN) bag runs empty and the next bag will be delayed 3 hours because the pharmacy is compounding it. Which nursing action best prevents the most immediate complication?', 'Interrupting high-dextrose TPN risks rebound hypoglycemia, so a dextrose-containing solution is infused at the same rate until the next bag is ready.', '{"options":[{"id":"A","text":"Hang 10% dextrose in water at the same rate until the TPN is available"},{"id":"B","text":"Flush the central line with heparin and leave it capped until the next bag"},{"id":"C","text":"Increase the rate of the maintenance normal saline line to keep the vein open"},{"id":"D","text":"Administer the client''s scheduled subcutaneous insulin as ordered"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Abruptly stopping high-dextrose TPN can cause rebound hypoglycemia; infusing dextrose maintains the glucose supply until the new bag arrives.","B":"Incorrect. Capping the line risks rebound hypoglycemia from the sudden loss of dextrose.","C":"Incorrect. Saline provides no glucose and does not prevent hypoglycemia.","D":"Incorrect. Giving insulin without dextrose would deepen hypoglycemia."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'Parenteral nutrition', 'Abrupt discontinuation', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_360011', 'MCQ', 'A nurse is about to administer the first dose of lisinopril to a client newly admitted with hypertension. Which laboratory value most warrants holding the drug and contacting the provider?', 'ACE inhibitors promote potassium retention, so a pre-dose potassium of 5.9 mEq/L should be reported before administration to avoid worsening hyperkalemia.', '{"options":[{"id":"A","text":"Serum potassium 5.9 mEq/L"},{"id":"B","text":"Serum sodium 138 mEq/L"},{"id":"C","text":"Fasting glucose 105 mg/dL"},{"id":"D","text":"Hemoglobin 13.2 g/dL"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. ACE inhibitors reduce aldosterone and cause potassium retention; giving lisinopril with a potassium of 5.9 mEq/L risks dangerous hyperkalemia.","B":"Incorrect. This sodium is within normal limits.","C":"Incorrect. This value does not contraindicate an ACE inhibitor.","D":"Incorrect. This hemoglobin is normal and unrelated to ACE-inhibitor safety."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antihypertensives', 'Pre-administration data review', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_360012', 'SATA', 'A nurse reviews the record of a client discharged on warfarin. Which findings require follow-up before the client leaves? Select all that apply.', 'Bleeding-risk supplements, a supratherapeutic INR with bleeding, major vitamin-K diet changes, and interacting antibiotics all require follow-up on warfarin.', '{"options":[{"id":"A","text":"The client started an over-the-counter regimen of high-dose vitamin E and fish oil"},{"id":"B","text":"The client''s INR today is 5.2 with reported gum bleeding"},{"id":"C","text":"The client plans to greatly increase intake of dark leafy greens for a new diet"},{"id":"D","text":"The client was newly prescribed trimethoprim-sulfamethoxazole for a UTI"},{"id":"E","text":"The client takes the warfarin dose at the same time each evening"},{"id":"F","text":"The client wears a medical-alert bracelet noting anticoagulation"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. These supplements increase bleeding risk and can alter warfarin effect.","B":"Correct. A supratherapeutic INR with bleeding needs intervention before discharge.","C":"Correct. Large swings in vitamin K intake destabilize INR and warrant counseling.","D":"Correct. This antibiotic potentiates warfarin and raises INR.","E":"Incorrect. Consistent timing is appropriate practice.","F":"Incorrect. This is a recommended safety measure."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Warfarin', 'Interactions and teaching', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_360013', 'SATA', 'A nurse cares for a client receiving cytotoxic chemotherapy with an absolute neutrophil count of 400/mm3. Which interventions are appropriate? Select all that apply.', 'Severe neutropenia demands protective precautions, low-microbial-risk environment, hazardous-drug PPE, and prompt fever reporting, while avoiding aspirin and rectal temperatures.', '{"options":[{"id":"A","text":"Place the client in protective (neutropenic) precautions"},{"id":"B","text":"Wear chemotherapy-rated gloves and gown when handling the client''s body fluids for 48 hours"},{"id":"C","text":"Avoid fresh flowers and uncooked fruits and vegetables in the room"},{"id":"D","text":"Assess temperature and report a single reading of 38.0°C promptly"},{"id":"E","text":"Administer scheduled aspirin for mild discomfort"},{"id":"F","text":"Take a rectal temperature for accuracy"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. An ANC of 400 indicates severe neutropenia requiring protective precautions.","B":"Correct. Cytotoxic drugs are excreted in body fluids; hazardous-drug PPE is used.","C":"Correct. These carry microbial risk for the neutropenic client.","D":"Correct. Neutropenic fever is an emergency; even a low-grade fever is reported.","E":"Incorrect. Aspirin increases bleeding risk and masks fever; it is avoided.","F":"Incorrect. Rectal measurement risks mucosal injury and infection in neutropenia."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Chemotherapy', 'Safe handling and neutropenia', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_360014', 'SATA', 'A client taking a selective serotonin reuptake inhibitor was recently started on tramadol. Which findings would lead the nurse to suspect serotonin syndrome? Select all that apply.', 'Serotonin syndrome presents with hyperthermia, altered mentation, neuromuscular hyperactivity (myoclonus, hyperreflexia), and autonomic signs such as diaphoresis.', '{"options":[{"id":"A","text":"Hyperthermia"},{"id":"B","text":"Agitation and confusion"},{"id":"C","text":"Myoclonus and hyperreflexia"},{"id":"D","text":"Diaphoresis"},{"id":"E","text":"Bradycardia and hypothermia"},{"id":"F","text":"Flaccid paralysis with absent reflexes"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Hyperthermia is a hallmark of serotonin syndrome.","B":"Correct. Altered mental status reflects serotonergic excess.","C":"Correct. Neuromuscular hyperactivity is characteristic.","D":"Correct. Autonomic instability includes profuse sweating.","E":"Incorrect. Serotonin syndrome typically causes tachycardia and hyperthermia.","F":"Incorrect. Reflexes are increased, not absent, in serotonin syndrome."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Psychotropics', 'Serotonin syndrome', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_360015', 'SATA', 'A nurse prepares to administer IV potassium chloride to a client with a potassium of 2.8 mEq/L. Which principles guide safe administration? Select all that apply.', 'Safe IV potassium requires dilution, pump control, no IV push, confirmed urine output, and site and cardiac monitoring.', '{"options":[{"id":"A","text":"Never administer potassium chloride by IV push"},{"id":"B","text":"Use only premixed diluted solutions and an infusion pump"},{"id":"C","text":"Verify adequate urine output before and during the infusion"},{"id":"D","text":"Assess the IV site for infiltration and phlebitis during infusion"},{"id":"E","text":"Administer the ordered dose as a rapid bolus to correct the level quickly"},{"id":"F","text":"Withhold cardiac monitoring since the level is only mildly low"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. IV push potassium can cause fatal cardiac arrest and is prohibited.","B":"Correct. Premixed, pump-controlled infusion prevents inadvertent bolus.","C":"Correct. Potassium is renally excreted; oliguria risks hyperkalemia.","D":"Correct. Potassium is irritating to veins and can cause phlebitis or tissue injury.","E":"Incorrect. Rapid administration is dangerous and can be fatal.","F":"Incorrect. Continuous or frequent monitoring is important during potassium replacement."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Potassium chloride', 'Safe IV administration', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_360016', 'SATA', 'A client receives a continuous IV aminophylline infusion titrated to a serum theophylline level. Which findings suggest theophylline toxicity requiring the nurse to reassess the titration? Select all that apply.', 'Theophylline toxicity presents with dysrhythmias, GI upset, CNS stimulation, and serum levels above about 20 mcg/mL.', '{"options":[{"id":"A","text":"Tachycardia with new premature ventricular contractions"},{"id":"B","text":"Persistent nausea and vomiting"},{"id":"C","text":"Restlessness and tremor"},{"id":"D","text":"A serum theophylline level of 26 mcg/mL"},{"id":"E","text":"A serum theophylline level of 12 mcg/mL"},{"id":"F","text":"Resolution of wheezing with improved air movement"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Cardiac dysrhythmias are a toxicity sign.","B":"Correct. GI upset is an early toxicity indicator.","C":"Correct. CNS stimulation reflects rising levels.","D":"Correct. Levels above roughly 20 mcg/mL are toxic.","E":"Incorrect. This is within the therapeutic range.","F":"Incorrect. This is a therapeutic response, not toxicity."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Respiratory', 'Aminophylline titration', 'Toxicity monitoring', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_360017', 'SELECT_N', 'A nurse is about to give the morning dose of digoxin to a client with heart failure. Which 3 findings should prompt the nurse to hold the dose and notify the provider?', 'Digoxin is held for bradycardia below 60, hypokalemia, and supratherapeutic digoxin levels, all of which increase toxicity risk.', '{"options":[{"id":"A","text":"Apical heart rate of 52 beats per minute"},{"id":"B","text":"Serum potassium of 2.9 mEq/L"},{"id":"C","text":"Serum digoxin level of 2.4 ng/mL"},{"id":"D","text":"Blood pressure of 128/78 mmHg"},{"id":"E","text":"Apical heart rate of 76 beats per minute"},{"id":"F","text":"Serum potassium of 4.2 mEq/L"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. An apical rate below 60 warrants holding digoxin.","B":"Correct. Hypokalemia potentiates digoxin toxicity.","C":"Correct. This exceeds the therapeutic range (0.5–2.0 ng/mL).","D":"Incorrect. This is a normal blood pressure.","E":"Incorrect. This rate is acceptable for administration.","F":"Incorrect. This is a normal potassium level."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Digoxin', 'Pre-administration checks', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_360018', 'TF', 'Protamine sulfate is the appropriate reversal agent for a client with a supratherapeutic INR caused by warfarin who is actively bleeding.', 'Protamine reverses heparin; warfarin-related bleeding is reversed with vitamin K and, for urgent reversal, prothrombin complex concentrate or fresh frozen plasma.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulant reversal', NULL, 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_360019', 'MATRIX', 'For each medication, click the correct antidote or reversal agent.', 'Vitamin K reverses warfarin, flumazenil reverses benzodiazepines, and N-acetylcysteine treats acetaminophen toxicity.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Warfarin"},{"id":"r2","text":"Midazolam"},{"id":"r3","text":"Acetaminophen"},{"id":"r4","text":"Diazepam"}],"columns":[{"id":"c1","text":"Vitamin K"},{"id":"c2","text":"Flumazenil"},{"id":"c3","text":"N-acetylcysteine"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'High-risk medication antidotes', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_360020', 'MATRIX_MR', 'For each medication, select all adverse effects the nurse should monitor for (each drug may have more than one).', 'Loop and aminoglycoside agents cause ototoxicity; ACE inhibitors cause hyperkalemia and dry cough; potassium-sparing diuretics cause hyperkalemia.', '{"row_label":"Medication class","rows":[{"id":"r1","text":"Furosemide"},{"id":"r2","text":"Lisinopril"},{"id":"r3","text":"Spironolactone"},{"id":"r4","text":"Gentamicin"}],"columns":[{"id":"c1","text":"Hyperkalemia"},{"id":"c2","text":"Ototoxicity"},{"id":"c3","text":"Dry cough"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1","c3"],"r3":["c1"],"r4":["c2"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Adverse effects by class', NULL, 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_360021', 'CLOZE', 'A client with diabetic ketoacidosis is on an IV insulin infusion. The nurse anticipates adding {1} to the IV fluids once the serum glucose reaches about 200 mg/dL, and will closely monitor for {2} during the infusion.', 'Dextrose is added as glucose falls to prevent hypoglycemia while ketoacidosis clears, and insulin drives potassium intracellularly, risking hypokalemia.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"dextrose"},{"id":"c2","text":"additional insulin"},{"id":"c3","text":"calcium gluconate"}]},{"id":"b2","choices":[{"id":"c1","text":"hypokalemia"},{"id":"c2","text":"hypercalcemia"},{"id":"c3","text":"hypernatremia"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin infusion in DKA', NULL, 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_360022', 'HIGHLIGHT', 'A nurse reviews a client 1 hour after IV hydromorphone. Findings: client is [[unarousable to sternal rub]], respiratory rate [[5 breaths per minute]], [[pinpoint pupils]], SpO2 [[82% on room air]], blood pressure [[118/70]], temperature [[37.1°C]]. Highlight the findings that indicate opioid toxicity requiring immediate intervention.', 'Opioid toxicity is recognized by depressed consciousness, bradypnea, miosis, and hypoxemia; normal blood pressure and temperature are not the concerning cues.', '{"chunks":[{"id":"h1","text":"unarousable to sternal rub"},{"id":"h2","text":"5 breaths per minute"},{"id":"h3","text":"pinpoint pupils"},{"id":"h4","text":"82% on room air"},{"id":"h5","text":"118/70"},{"id":"h6","text":"37.1°C"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h4"],"feedback":{"h1":"Correct. Profound sedation is a sign of opioid toxicity.","h2":"Correct. Severe respiratory depression requires immediate action.","h3":"Correct. Miosis is a classic opioid effect.","h4":"Correct. Hypoxemia demands urgent intervention.","h5":"Incorrect. This blood pressure is normal.","h6":"Incorrect. This temperature is normal."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioid overdose recognition', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_360023', 'BOWTIE', 'A laboring client on an IV magnesium sulfate infusion for preeclampsia becomes lethargic with slurred speech. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Lethargy and slurred speech signal magnesium toxicity; the nurse stops the infusion, prepares calcium gluconate, and monitors reflexes and respirations.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Stop the magnesium sulfate infusion"},{"id":"lt2","text":"Prepare to administer calcium gluconate"},{"id":"lt3","text":"Increase the magnesium infusion rate"},{"id":"lt4","text":"Administer an additional bolus of magnesium"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Magnesium toxicity"},{"id":"ct2","text":"Eclamptic seizure"},{"id":"ct3","text":"Hypoglycemia"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Deep tendon reflexes"},{"id":"rt2","text":"Respiratory rate"},{"id":"rt3","text":"Blood glucose"},{"id":"rt4","text":"Pupillary response"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Magnesium sulfate toxicity', NULL, 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_360024', 'DRAG_ORDER', 'A client develops laryngeal stridor, wheezing, and hypotension immediately after an IV antibiotic dose. Place the nurse''s actions in the correct priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Stop the antibiotic infusion"},{"id":"t2","text":"Administer intramuscular epinephrine"},{"id":"t3","text":"Apply high-flow oxygen and maintain the airway"},{"id":"t4","text":"Give ordered IV fluids and antihistamine"},{"id":"t5","text":"Document the reaction and update the allergy record"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Anaphylaxis medication response', NULL, 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361001', 'MCQ', 'A client on a continuous heparin infusion for a pulmonary embolism has an aPTT of 96 seconds (control 30 seconds; therapeutic goal 1.5-2.5 times control). The client''s platelet count has dropped from 240,000 to 88,000/mm3 over 3 days. Which action should the nurse take FIRST?', 'A platelet drop over 50% during heparin therapy signals HIT; stopping the drug is the priority to prevent thrombosis.', '{"options":[{"id":"A","text":"Stop the heparin infusion and notify the provider"},{"id":"B","text":"Decrease the heparin rate per the titration protocol"},{"id":"C","text":"Administer protamine sulfate 1 mg IV"},{"id":"D","text":"Draw a repeat aPTT in 6 hours"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A >50% platelet drop suggests heparin-induced thrombocytopenia; heparin must be stopped immediately and the provider notified.","B":"Incorrect. Titrating down addresses the aPTT but not the life-threatening HIT reaction.","C":"Incorrect. Protamine reverses heparin but is not the first nursing action and requires an order.","D":"Incorrect. Delaying action ignores the falling platelet count."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Heparin monitoring', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361002', 'MCQ', 'At 0730 a nurse is preparing to give a client 6 units of regular insulin and 14 units of NPH insulin subcutaneously before breakfast. The client''s breakfast tray has not yet arrived and the point-of-care glucose is 78 mg/dL. Which action is MOST appropriate?', 'A borderline-low glucose with no available food and peaking insulins warrants holding and clarifying to prevent hypoglycemia.', '{"options":[{"id":"A","text":"Hold the insulin, recheck glucose, and notify the provider before administering"},{"id":"B","text":"Give only the NPH now and the regular when the tray arrives"},{"id":"C","text":"Administer both insulins as scheduled since the value is within normal range"},{"id":"D","text":"Give the regular insulin and hold the NPH"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A glucose of 78 mg/dL with no food available risks hypoglycemia from the peaking insulins; hold and clarify.","B":"Incorrect. Splitting the dose is not ordered and NPH still lowers glucose.","C":"Incorrect. Regular insulin peaks in 2-3 hours with no incoming carbohydrate, risking hypoglycemia.","D":"Incorrect. Regular insulin has a rapid onset and would drop the glucose further without food."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Insulin timing', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361003', 'MCQ', 'A client receiving IV gentamicin every 8 hours has a trough level drawn before the next dose that returns at 3.2 mcg/mL (therapeutic trough less than 2 mcg/mL). Serum creatinine has risen from 0.9 to 1.6 mg/dL. What should the nurse do?', 'A supratherapeutic trough plus rising creatinine signals aminoglycoside accumulation and nephrotoxicity; the dose is held and reported.', '{"options":[{"id":"A","text":"Hold the next dose and report the elevated trough and creatinine to the provider"},{"id":"B","text":"Administer the dose and increase the client''s IV fluids"},{"id":"C","text":"Administer the dose but draw a repeat trough after it"},{"id":"D","text":"Redraw the trough level in 30 minutes before deciding"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An elevated trough with rising creatinine indicates drug accumulation and nephrotoxicity; hold and report.","B":"Incorrect. Giving the dose worsens accumulation despite hydration.","C":"Incorrect. The elevated trough already indicates the dose should be held.","D":"Incorrect. A trough is drawn just before the dose; redrawing wastes time."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Aminoglycosides', 'Peak and trough', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361004', 'MCQ', 'Fifteen minutes into a unit of packed red blood cells, a client develops flank pain, chills, a temperature rise from 37.0 to 38.9 C, and dark red-brown urine. After stopping the transfusion, which action should the nurse take NEXT?', 'Flank pain, fever, and hemoglobinuria signal an acute hemolytic reaction; after stopping, saline through new tubing preserves renal perfusion.', '{"options":[{"id":"A","text":"Keep the IV line open with 0.9% sodium chloride using new tubing"},{"id":"B","text":"Administer the prescribed acetaminophen for the fever"},{"id":"C","text":"Slow the transfusion and continue observing"},{"id":"D","text":"Send the remaining blood to the laboratory before establishing new access"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Maintaining IV access with normal saline supports renal perfusion and treats the acute hemolytic reaction.","B":"Incorrect. This is hemolysis, not a simple febrile reaction; maintaining perfusion is the priority.","C":"Incorrect. The transfusion is already stopped and must not resume.","D":"Incorrect. Maintaining IV access with saline comes before returning the unit."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Blood-product administration', 'Transfusion reaction', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361005', 'MCQ', 'A postoperative client receiving morphine via PCA has a respiratory rate of 6/min, pinpoint pupils, and is difficult to arouse. The nurse administers naloxone. Which finding indicates the nurse must be prepared to give repeat doses?', 'Naloxone''s duration is shorter than most opioids, so respiratory depression can return and repeat doses are often required.', '{"options":[{"id":"A","text":"Naloxone has a shorter duration of action than morphine"},{"id":"B","text":"Morphine is metabolized faster than naloxone"},{"id":"C","text":"Naloxone causes rebound hypertension that requires titration"},{"id":"D","text":"The client will develop tolerance to naloxone quickly"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone''s effect can wear off before the opioid is cleared, so re-sedation and respiratory depression may recur.","B":"Incorrect. Morphine''s active metabolites outlast naloxone, which is the reason for repeat dosing.","C":"Incorrect. While it can raise BP, that is not why repeat dosing is anticipated.","D":"Incorrect. Tolerance is not the mechanism; the short half-life is."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Opioid reversal', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361006', 'MCQ', 'A provider prescribes a dopamine infusion at 5 mcg/kg/min for a client weighing 70 kg. The bag contains 400 mg of dopamine in 250 mL of D5W. At what rate (mL/hr) should the nurse set the infusion pump? Round to the nearest whole number.', '5 mcg/kg/min x 70 kg x 60 = 21,000 mcg/hr = 21 mg/hr; divided by the 1.6 mg/mL concentration equals 13 mL/hr.', '{"options":[{"id":"A","text":"13 mL/hr"},{"id":"B","text":"16 mL/hr"},{"id":"C","text":"21 mL/hr"},{"id":"D","text":"9 mL/hr"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. 5 x 70 = 350 mcg/min = 21,000 mcg/hr = 21 mg/hr; concentration is 1.6 mg/mL, so 21 / 1.6 = 13 mL/hr.","B":"Incorrect. This uses an incorrect concentration.","C":"Incorrect. This is the mg/hr value, not the volumetric rate.","D":"Incorrect. This underestimates the required dose."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Dosage calculation', 'Weight-based infusion', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361007', 'MCQ', 'A client with a potassium level of 2.8 mEq/L has an order for potassium chloride 40 mEq in 100 mL over 1 hour via a peripheral IV. Which action by the nurse is correct?', 'Peripheral KCl is limited to roughly 10 mEq/hr; 40 mEq over 1 hour peripherally is unsafe and must be clarified.', '{"options":[{"id":"A","text":"Contact the provider because the concentration and rate exceed safe peripheral limits"},{"id":"B","text":"Administer the potassium as ordered using an infusion pump"},{"id":"C","text":"Give the potassium as an IV push over 5 minutes"},{"id":"D","text":"Dilute the dose further and infuse over 20 minutes"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Peripheral KCl should not exceed 10 mEq/hr or ~10 mEq/100 mL; this order requires clarification or central access.","B":"Incorrect. The rate and concentration are unsafe peripherally and can cause cardiac arrest and vein damage.","C":"Incorrect. IV push potassium is never administered and is fatal.","D":"Incorrect. Speeding infusion increases cardiac risk regardless of dilution."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Electrolytes', 'Potassium administration', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361008', 'MCQ', 'During an IV vancomycin infusion, a client develops flushing, pruritus, and an erythematous rash over the face and upper torso. Blood pressure is stable. What is the nurse''s priority action?', 'Vancomycin flushing reaction results from rapid infusion; stopping and slowing the rate is the appropriate response.', '{"options":[{"id":"A","text":"Stop the infusion and prepare to restart it at a slower rate after symptoms resolve"},{"id":"B","text":"Discontinue vancomycin permanently and document a drug allergy"},{"id":"C","text":"Administer the prescribed epinephrine IM"},{"id":"D","text":"Continue the infusion and give diphenhydramine"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This is vancomycin flushing (infusion) reaction from rapid infusion; slowing the rate resolves it.","B":"Incorrect. This is a rate-related reaction, not a true allergy.","C":"Incorrect. The client is hemodynamically stable; this is not anaphylaxis.","D":"Incorrect. The infusion must be paused first before any antihistamine."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Antibiotics', 'Vancomycin infusion reaction', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361009', 'MCQ', 'A client receiving total parenteral nutrition through a central line suddenly becomes diaphoretic, shaky, and confused two hours after the bag unexpectedly ran dry and no new bag was available. Which is the nurse''s priority intervention?', 'Abrupt interruption of TPN causes rebound hypoglycemia; a dextrose infusion at the same rate bridges until TPN resumes.', '{"options":[{"id":"A","text":"Hang 10% dextrose in water at the previous TPN rate"},{"id":"B","text":"Flush the central line with heparin and wait for pharmacy"},{"id":"C","text":"Administer the client''s scheduled subcutaneous insulin"},{"id":"D","text":"Restart the TPN at double the rate to catch up"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Abrupt TPN cessation causes rebound hypoglycemia; dextrose infusion prevents a severe drop.","B":"Incorrect. This delays treatment of the hypoglycemia.","C":"Incorrect. Insulin would worsen the hypoglycemia.","D":"Incorrect. Doubling the rate risks hyperglycemia and fluid overload."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'Parenteral nutrition', 'TPN complications', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361010', 'MCQ', 'A client on maintenance lithium reports coarse hand tremors, vomiting, and unsteady gait. The lithium level is 2.1 mEq/L. The client started a new low-sodium diet and a thiazide diuretic last week. Which factor MOST likely explains the toxicity?', 'Lithium and sodium compete for renal reabsorption; sodium loss from a low-sodium diet and thiazides raises lithium to toxic levels.', '{"options":[{"id":"A","text":"Sodium depletion increased renal lithium reabsorption"},{"id":"B","text":"The thiazide directly binds lithium and raises the level"},{"id":"C","text":"The low-sodium diet increased lithium excretion"},{"id":"D","text":"Dehydration diluted the serum sodium and lowered lithium"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Low sodium and thiazides cause the kidneys to retain lithium, raising serum levels into the toxic range.","B":"Incorrect. The mechanism is sodium-related renal handling, not direct binding.","C":"Incorrect. Low sodium decreases excretion, not increases it.","D":"Incorrect. Dehydration raises lithium levels, but the level here is elevated, not lowered."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Psychiatric/Mental Health', 'Psychotropics', 'Lithium toxicity', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_361011', 'MCQ', 'A client with a hypertensive emergency is on an IV sodium nitroprusside infusion titrated to keep the mean arterial pressure at 110 mmHg. The MAP is now 95 mmHg and the client reports blurred vision and headache. Which nurse action reflects correct titration judgment?', 'The MAP has fallen below the titration target with symptoms of overshoot, so the nurse decreases the rate to return to the ordered parameter.', '{"options":[{"id":"A","text":"Decrease the infusion rate to bring the MAP back toward the target"},{"id":"B","text":"Increase the infusion rate to relieve the headache"},{"id":"C","text":"Stop the infusion abruptly and place the client flat"},{"id":"D","text":"Maintain the current rate since the MAP is within 20 mmHg of goal"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The MAP is below target with symptoms of overshoot; titrating down restores the ordered parameter.","B":"Incorrect. Increasing the rate would lower the MAP further, worsening hypoperfusion.","C":"Incorrect. Abrupt cessation causes rebound hypertension; titration is preferred.","D":"Incorrect. The MAP is below goal with symptoms, requiring adjustment."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antihypertensives', 'Nitroprusside titration', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_361012', 'SATA', 'A nurse provides discharge teaching to a client newly prescribed warfarin. Which client statements indicate a correct understanding? Select all that apply.', 'Consistent vitamin K intake, bleeding precautions, reporting bleeding, and INR monitoring are correct; NSAIDs and doubling doses increase bleeding risk.', '{"options":[{"id":"A","text":"I will keep my intake of green leafy vegetables consistent from week to week"},{"id":"B","text":"I should use an electric razor and a soft toothbrush"},{"id":"C","text":"I will report black tarry stools or blood in my urine right away"},{"id":"D","text":"I can take ibuprofen freely for aches and pains"},{"id":"E","text":"I will double my dose if I miss one to catch up"},{"id":"F","text":"I will keep my scheduled INR blood tests"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Warfarin teaching', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_361013', 'SATA', 'A nurse is preparing to administer several high-alert medications. Which actions require an independent double-check by a second nurse per standard safety practice? Select all that apply.', 'IV insulin, heparin, PCA opioids, and chemotherapy are high-alert medications requiring independent double-checks; vitamins and compresses are not.', '{"options":[{"id":"A","text":"Programming an IV insulin infusion pump"},{"id":"B","text":"Administering IV heparin as a weight-based bolus"},{"id":"C","text":"Hanging a patient-controlled analgesia opioid syringe"},{"id":"D","text":"Giving an oral multivitamin"},{"id":"E","text":"Administering IV chemotherapy"},{"id":"F","text":"Applying a warm compress to an IV site"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'High-risk medications', 'Safety verification', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_361014', 'SATA', 'A nurse assesses a peripheral IV site infusing an antibiotic. Which findings indicate infiltration rather than phlebitis? Select all that apply.', 'Infiltration presents with coolness, swelling, blanching, and slowed flow; warmth and a red streak along the vein indicate phlebitis.', '{"options":[{"id":"A","text":"Cool, taut skin around the insertion site"},{"id":"B","text":"Swelling and edema at the site"},{"id":"C","text":"Blanching of the skin over the site"},{"id":"D","text":"A red streak tracking up the vein"},{"id":"E","text":"Warmth along the vein path"},{"id":"F","text":"Slowed or stopped infusion flow"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Respiratory', 'IV site care', 'Infiltration and phlebitis', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_361015', 'SATA', 'A nurse is caring for a client with a central venous catheter. Which actions reduce the risk of air embolism? Select all that apply.', 'Valsalva, Trendelenburg positioning, clamping, and priming tubing prevent air entry; an open hub or upright removal increases air-embolism risk.', '{"options":[{"id":"A","text":"Have the client perform the Valsalva maneuver during tubing changes"},{"id":"B","text":"Position the client in Trendelenburg for catheter removal"},{"id":"C","text":"Clamp the catheter when it is not in use"},{"id":"D","text":"Prime all tubing to remove air before connecting"},{"id":"E","text":"Leave the catheter hub open to air between infusions"},{"id":"F","text":"Remove the catheter with the client sitting upright"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Central venous access', 'Air embolism prevention', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_361016', 'SATA', 'A client is discharged on a tapering course of prednisone. Which teaching points should the nurse include? Select all that apply.', 'Steroids must be tapered, taken with food, and monitored for infection and hyperglycemia; they cause weight gain and hypertension, not loss.', '{"options":[{"id":"A","text":"Do not stop the medication abruptly"},{"id":"B","text":"Take the dose with food to reduce stomach upset"},{"id":"C","text":"Report signs of infection such as fever or sore throat"},{"id":"D","text":"Expect your blood glucose readings may rise"},{"id":"E","text":"Weight loss and low blood pressure are expected effects"},{"id":"F","text":"You can skip doses once you feel better"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Corticosteroids', 'Prednisone teaching', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_361017', 'SELECT_N', 'During medication reconciliation, a client reports taking these agents. Which 3 combinations should the nurse flag as clinically significant interactions requiring provider review?', 'Warfarin/TMP-SMX (bleeding), MAOI/SSRI (serotonin syndrome), and simvastatin/clarithromycin (rhabdomyolysis) are significant interactions; the others are benign.', '{"options":[{"id":"A","text":"Warfarin plus a new prescription for sulfamethoxazole-trimethoprim"},{"id":"B","text":"An MAO inhibitor plus a newly started SSRI"},{"id":"C","text":"Simvastatin plus clarithromycin"},{"id":"D","text":"Acetaminophen plus a daily multivitamin"},{"id":"E","text":"Metformin plus a calcium supplement"},{"id":"F","text":"Docusate sodium plus a bulk-forming fiber"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication reconciliation', 'Interaction screening', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_361018', 'TF', 'It is appropriate to piggyback a unit of packed red blood cells with lactated Ringer''s solution to prime the line before transfusion.', 'Only 0.9% sodium chloride is compatible with blood products; the calcium in lactated Ringer''s can promote clotting in the tubing.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood-product administration', 'Compatible fluids', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_361019', 'MATRIX_MR', 'For each medication, select all laboratory values the nurse should verify before administration (more than one may apply).', 'Warfarin requires INR; potassium-sparing diuretics, ACE inhibitors, and digoxin require potassium and renal function; enoxaparin dosing depends on creatinine clearance.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Warfarin"},{"id":"r2","text":"Spironolactone"},{"id":"r3","text":"Enoxaparin"},{"id":"r4","text":"Digoxin"},{"id":"r5","text":"Lisinopril"}],"columns":[{"id":"c1","text":"Serum potassium"},{"id":"c2","text":"INR/PT"},{"id":"c3","text":"Serum creatinine"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1","c3"],"r3":["c3"],"r4":["c1","c3"],"r5":["c1","c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Pre-administration data review', 'Labs to check', 'Hard', 'Analyze', '{}', 8, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_361020', 'CLOZE', 'A client on IV hydromorphone has a respiratory rate of 8/min and a sedation score indicating difficulty staying awake. The nurse should first {1}, and if respiratory depression persists, anticipate administering {2}.', 'Opioid-induced respiratory depression is managed by holding the opioid and stimulating the client, then reversing with naloxone if needed.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"hold the next opioid dose and stimulate the client"},{"id":"c2","text":"increase the opioid dose for comfort"},{"id":"c3","text":"start a lactated Ringer''s bolus"}]},{"id":"b2","choices":[{"id":"c1","text":"naloxone"},{"id":"c2","text":"flumazenil"},{"id":"c3","text":"protamine sulfate"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Titration to parameters', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_361021', 'HIGHLIGHT', 'A client started IV penicillin 10 minutes ago. Highlight the findings that require immediate intervention. The client reports [[tightness in the throat]]. Blood pressure is [[84/50 mmHg]]. Temperature 37.1 C. There is [[audible wheezing]] on auscultation. The client has [[hives on the chest]]. [[The IV site is dry and intact]].', 'Throat tightness, hypotension, wheezing, and hives indicate an evolving anaphylactic reaction requiring immediate intervention.', '{"chunks":[{"id":"h1","text":"tightness in the throat"},{"id":"h2","text":"84/50 mmHg"},{"id":"h3","text":"audible wheezing"},{"id":"h4","text":"hives on the chest"},{"id":"h5","text":"The IV site is dry and intact"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h4"],"feedback":{"h1":"Airway involvement signals anaphylaxis.","h2":"Hypotension indicates anaphylactic shock.","h3":"Bronchospasm is a hallmark of anaphylaxis.","h4":"Urticaria reflects the allergic reaction.","h5":"A normal IV site is not concerning."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Response evaluation', 'Adverse effects', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_361022', 'BOWTIE', 'A client develops anaphylaxis during an IV antibiotic infusion. Complete the diagram by selecting the priority actions, the condition, and the parameters to monitor.', 'Anaphylaxis is managed by stopping the trigger and giving IM epinephrine, while monitoring airway, oxygenation, and blood pressure.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Stop the antibiotic infusion"},{"id":"lt2","text":"Administer IM epinephrine"},{"id":"lt3","text":"Give the client oral antihistamines and reassess in 1 hour"},{"id":"lt4","text":"Place the client in reverse Trendelenburg to lower BP"},{"id":"lt5","text":"Slow the infusion and continue monitoring"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Anaphylactic reaction"},{"id":"ct2","text":"Vasovagal syncope"},{"id":"ct3","text":"Sepsis"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Airway and oxygen saturation"},{"id":"rt2","text":"Blood pressure"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Bowel sounds"},{"id":"rt5","text":"Pupil accommodation"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'High-risk medications', 'Anaphylaxis management', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_361023', 'DRAG_ORDER', 'A nurse is initiating a packed red blood cell transfusion. Place the steps in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"},{"id":"s6","target_text":"6th action"}],"tokens":[{"id":"t1","text":"Verify the order and confirm informed consent"},{"id":"t2","text":"Obtain baseline vital signs"},{"id":"t3","text":"Verify blood product and client identity with a second nurse"},{"id":"t4","text":"Start the infusion slowly and stay with the client for the first 15 minutes"},{"id":"t5","text":"Reassess vital signs after 15 minutes"},{"id":"t6","text":"Document the transfusion"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5","s6":"t6"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood-product administration', 'Transfusion procedure', 'Hard', 'Apply', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_361024', 'MATRIX', 'For each clinical finding in a client receiving insulin, specify whether it indicates hypoglycemia or hyperglycemia.', 'Adrenergic symptoms (diaphoresis, tremor, clammy skin, confusion relieved by carbohydrate) mark hypoglycemia; fruity breath and polyuria mark hyperglycemia.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Diaphoresis and tremors"},{"id":"r2","text":"Fruity breath odor"},{"id":"r3","text":"Cool, clammy skin"},{"id":"r4","text":"Polyuria and increased thirst"},{"id":"r5","text":"Sudden confusion relieved by juice"}],"columns":[{"id":"c1","text":"Hypoglycemia"},{"id":"c2","text":"Hyperglycemia"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Hypo vs hyperglycemia', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362001', 'MCQ', 'A client on a continuous IV heparin infusion has an aPTT of 96 seconds (control 30 seconds; therapeutic range 46-70 seconds) and now reports a new headache with one episode of dark, tarry stool. Which action should the nurse take FIRST?', 'A markedly elevated aPTT with signs of bleeding means the priority is to stop the anticoagulant infusion before giving the antidote or notifying.', '{"options":[{"id":"A","text":"Stop the heparin infusion"},{"id":"B","text":"Administer protamine sulfate per protocol"},{"id":"C","text":"Decrease the infusion rate per the titration nomogram"},{"id":"D","text":"Draw a repeat aPTT to confirm the value"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Supratherapeutic aPTT with signs of bleeding requires immediately stopping the infusion before other steps.","B":"Incorrect. The antidote may be needed, but the infusion must be stopped first.","C":"Incorrect. Active bleeding signs make continued infusion at any rate unsafe.","D":"Incorrect. Confirming labs delays stopping ongoing heparin during active bleeding."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Heparin monitoring', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362002', 'MCQ', 'A client receiving IV vancomycin every 12 hours has a trough level of 24 mcg/mL (target trough 10-20 mcg/mL), a rising serum creatinine from 0.9 to 1.6 mg/dL, and decreasing urine output. Which action is most appropriate?', 'A supratherapeutic vancomycin trough with rising creatinine indicates nephrotoxicity; the dose should be held and the prescriber notified for redosing.', '{"options":[{"id":"A","text":"Hold the next dose and notify the prescriber"},{"id":"B","text":"Administer the next scheduled dose on time"},{"id":"C","text":"Infuse the dose over 30 minutes instead of 60"},{"id":"D","text":"Increase the dosing interval to every 8 hours"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An elevated trough plus rising creatinine signals nephrotoxicity; hold and notify.","B":"Incorrect. Giving another dose with a supratherapeutic trough worsens nephrotoxicity.","C":"Incorrect. Faster infusion risks red-man syndrome and does not address the trough.","D":"Incorrect. Shortening the interval increases accumulation and toxicity."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Aminoglycosides', 'Vancomycin trough', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362003', 'MCQ', 'A client with a hypertensive emergency is on an IV nitroglycerin drip titrated to keep MAP 100-110 mmHg. The current BP is 142/70 mmHg (MAP 94) and the client reports lightheadedness. What should the nurse do?', 'When a titrated vasodilator drips the MAP below the ordered range with symptoms, the correct titration is to reduce the infusion rate.', '{"options":[{"id":"A","text":"Decrease the nitroglycerin infusion rate"},{"id":"B","text":"Increase the nitroglycerin infusion rate"},{"id":"C","text":"Maintain the current rate and recheck in one hour"},{"id":"D","text":"Administer a 500 mL normal saline bolus"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The MAP is below the ordered range with symptoms, so the drip is titrated down.","B":"Incorrect. Increasing would lower the MAP further, worsening hypotension.","C":"Incorrect. The MAP is already below range with symptoms; action is needed now.","D":"Incorrect. A bolus is not first-line for drip-induced hypotension when titration can correct it."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antihypertensives', 'IV nitroglycerin titration', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362004', 'MCQ', 'Fifteen minutes into a packed red blood cell transfusion, a client develops flank pain, chills, a temperature rise from 37.0°C to 38.9°C, and pink-tinged urine. After stopping the transfusion, which action should the nurse take NEXT?', 'Flank pain, fever, and hemoglobinuria signal an acute hemolytic reaction; after stopping, saline via new tubing maintains access and renal perfusion.', '{"options":[{"id":"A","text":"Infuse normal saline through new tubing to maintain the line"},{"id":"B","text":"Administer the prescribed antipyretic and resume the transfusion"},{"id":"C","text":"Slow the transfusion rate and continue monitoring"},{"id":"D","text":"Flush the existing blood tubing with saline into the client"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. After stopping, maintain IV access and renal perfusion with saline via fresh tubing.","B":"Incorrect. These are signs of an acute hemolytic reaction; the unit must not be resumed.","C":"Incorrect. A hemolytic reaction requires stopping completely, not slowing.","D":"Incorrect. Flushing existing tubing would push more incompatible blood into the client."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Blood-product administration', 'Transfusion reaction', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362005', 'MCQ', 'A client is prescribed an insulin infusion at 0.1 unit/kg/hr. The client weighs 176 lb, and the pharmacy supplies 100 units of regular insulin in 100 mL of normal saline. At what rate (mL/hr) should the nurse set the pump?', '176 lb divided by 2.2 = 80 kg; 80 kg x 0.1 unit/kg/hr = 8 units/hr; the concentration is 1 unit/mL, so 8 mL/hr.', '{"options":[{"id":"A","text":"8 mL/hr"},{"id":"B","text":"16 mL/hr"},{"id":"C","text":"4 mL/hr"},{"id":"D","text":"18 mL/hr"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. 176 lb = 80 kg; 80 x 0.1 = 8 units/hr; at 1 unit/mL this is 8 mL/hr.","B":"Incorrect. This doubles the weight-based dose.","C":"Incorrect. This halves the correct dose.","D":"Incorrect. This uses the pound value without converting to kilograms."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Dosage calculation', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362006', 'MCQ', 'While the nurse changes the injection cap on a client''s central venous catheter, the client suddenly becomes dyspneic, hypotensive, and reports chest pain. Which position should the nurse place the client in immediately?', 'A suspected air embolism from a central line is managed with left lateral Trendelenburg to trap air in the right ventricle.', '{"options":[{"id":"A","text":"Left lateral Trendelenburg (left side down, head lower)"},{"id":"B","text":"High Fowler''s, sitting fully upright"},{"id":"C","text":"Right lateral with head elevated"},{"id":"D","text":"Supine with legs elevated only"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This traps a suspected air embolus in the right ventricle, away from the pulmonary outflow.","B":"Incorrect. Sitting upright encourages air to move into the pulmonary circulation.","C":"Incorrect. Right side down can allow air into the pulmonary artery.","D":"Incorrect. Leg elevation alone does not trap the air in the right heart."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Central venous access devices', 'Air embolism', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362007', 'MCQ', 'A postoperative client receiving IV morphine via PCA has a respiratory rate of 6/min, is difficult to arouse, and has an SpO2 of 84%. The nurse administers naloxone. Which finding best indicates the naloxone should be re-dosed?', 'Because naloxone is shorter-acting than morphine, recurrence of respiratory depression is the key indication for re-dosing.', '{"options":[{"id":"A","text":"Respiratory rate falls again to 7/min after initial improvement"},{"id":"B","text":"The client reports increased incisional pain"},{"id":"C","text":"The client becomes agitated and diaphoretic"},{"id":"D","text":"The heart rate increases from 70 to 92/min"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone has a shorter half-life than morphine, so recurring respiratory depression warrants re-dosing.","B":"Incorrect. Return of pain is an expected effect of reversal, not an indication to re-dose.","C":"Incorrect. These reflect acute withdrawal, not continued opioid-induced respiratory depression.","D":"Incorrect. Mild tachycardia alone does not indicate recurrent respiratory depression."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Naloxone dosing', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362008', 'MCQ', 'A client receiving total parenteral nutrition through a central line has the bag run out, and the next bag is delayed 90 minutes in pharmacy. Which action should the nurse take while waiting?', 'When TPN is interrupted, 10% dextrose at the same rate prevents rebound hypoglycemia caused by the sudden loss of high glucose delivery.', '{"options":[{"id":"A","text":"Hang 10% dextrose in water at the same rate"},{"id":"B","text":"Flush the line and hang normal saline at a keep-vein-open rate"},{"id":"C","text":"Stop all infusion and wait for the new TPN bag"},{"id":"D","text":"Double the rate of the next bag once it arrives to catch up"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Dextrose infusion prevents rebound hypoglycemia when TPN is interrupted.","B":"Incorrect. Saline provides no glucose and risks rebound hypoglycemia.","C":"Incorrect. Abrupt cessation without dextrose risks hypoglycemia.","D":"Incorrect. Rate should never be doubled; it causes hyperglycemia and fluid overload."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'Parenteral nutrition', 'TPN complications', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362009', 'MCQ', 'A prescriber orders potassium chloride 40 mEq IV for a client with a serum potassium of 2.8 mEq/L. The client has a peripheral IV. Which action by the nurse is most appropriate before administration?', 'IV potassium is high-risk: it must be diluted, given on a pump, and infused peripherally at no more than about 10 mEq/hr to avoid fatal dysrhythmias.', '{"options":[{"id":"A","text":"Clarify the order, as the concentration and rate must limit KCl to no more than 10 mEq/hr peripherally"},{"id":"B","text":"Administer the 40 mEq as an IV push over 2 minutes"},{"id":"C","text":"Infuse the full 40 mEq over 30 minutes peripherally"},{"id":"D","text":"Give the potassium as a rapid gravity infusion without a pump"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. IV potassium must be diluted and infused slowly; peripheral rates should not exceed about 10 mEq/hr.","B":"Incorrect. IV potassium push is fatal and never administered undiluted.","C":"Incorrect. This exceeds the safe peripheral rate and risks cardiac arrest and vein irritation.","D":"Incorrect. IV potassium always requires an infusion pump for rate control."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Electrolytes', 'IV potassium', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362010', 'MCQ', 'A client on maintenance lithium develops a viral illness with vomiting and diarrhea for two days. The client now has coarse tremors, ataxia, and confusion. Which lithium level would the nurse most expect?', 'Dehydration reduces lithium clearance; coarse tremor, ataxia, and confusion reflect a toxic level (>1.5 mEq/L), consistent with 2.1 mEq/L.', '{"options":[{"id":"A","text":"2.1 mEq/L"},{"id":"B","text":"0.4 mEq/L"},{"id":"C","text":"0.8 mEq/L"},{"id":"D","text":"1.1 mEq/L"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Volume depletion raises lithium; coarse tremor, ataxia, and confusion match a toxic level above 1.5 mEq/L.","B":"Incorrect. This subtherapeutic level would not cause toxicity signs.","C":"Incorrect. This is within the therapeutic range and inconsistent with the findings.","D":"Incorrect. This is upper-therapeutic but does not produce marked ataxia and confusion."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Psychiatric/Mental Health', 'Psychotropics', 'Lithium toxicity', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_362011', 'MCQ', 'Shortly after the first dose of IV piperacillin-tazobactam begins, a client develops stridor, facial swelling, and a BP of 78/40 mmHg. After stopping the infusion, which medication should the nurse anticipate administering FIRST?', 'Anaphylaxis is treated first with IM epinephrine; antihistamines, steroids, and bronchodilators are secondary adjuncts.', '{"options":[{"id":"A","text":"Epinephrine intramuscularly"},{"id":"B","text":"Diphenhydramine IV"},{"id":"C","text":"Methylprednisolone IV"},{"id":"D","text":"Albuterol nebulizer"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. IM epinephrine is the first-line, life-saving drug for anaphylaxis.","B":"Incorrect. Antihistamines are adjuncts given after epinephrine.","C":"Incorrect. Corticosteroids prevent late-phase reactions but are not first.","D":"Incorrect. Bronchodilators are adjuncts and do not reverse airway edema or shock as epinephrine does."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Antibiotics', 'Anaphylaxis', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_362012', 'SATA', 'A nurse teaches a client newly prescribed warfarin. Which statements by the client indicate correct understanding? Select all that apply.', 'Consistent vitamin K intake, bleeding precautions, reporting bleeding, and INR monitoring are correct; NSAIDs increase bleeding and doses are never doubled.', '{"options":[{"id":"A","text":"\"I will keep my green leafy vegetable intake consistent from week to week.\""},{"id":"B","text":"\"I should report unusual bruising or blood in my urine.\""},{"id":"C","text":"\"I will use a soft toothbrush and an electric razor.\""},{"id":"D","text":"\"I will take an over-the-counter NSAID for headaches.\""},{"id":"E","text":"\"I need regular INR blood tests to monitor my dose.\""},{"id":"F","text":"\"I can double the dose if I miss one to catch up.\""}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Warfarin', 'Client teaching', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_362013', 'SATA', 'A client on high-dose IV furosemide is being monitored. Which findings should the nurse recognize as adverse effects requiring intervention? Select all that apply.', 'Furosemide can cause hypokalemia, ototoxicity, orthostatic hypotension, and hyponatremia; good urine output and modest weight loss are expected therapeutic effects.', '{"options":[{"id":"A","text":"Serum potassium of 2.9 mEq/L"},{"id":"B","text":"New-onset ringing in the ears"},{"id":"C","text":"Orthostatic blood pressure drop of 24 mmHg"},{"id":"D","text":"Urine output of 80 mL/hr"},{"id":"E","text":"Serum sodium of 126 mEq/L"},{"id":"F","text":"Weight loss of 1 kg over 24 hours"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Diuretics', 'Monitoring', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_362014', 'SATA', 'A client on IV heparin for 6 days develops a platelet drop from 250,000 to 90,000/mm3 and a new limb clot. Which nursing actions are appropriate? Select all that apply.', 'HIT requires stopping all heparin exposure (including flushes and LMWH) and switching to a non-heparin anticoagulant; platelet transfusion is avoided and heparin is not restarted.', '{"options":[{"id":"A","text":"Discontinue all heparin, including line flushes"},{"id":"B","text":"Notify the prescriber about suspected HIT"},{"id":"C","text":"Anticipate an order for a non-heparin anticoagulant such as argatroban"},{"id":"D","text":"Administer a platelet transfusion to raise the count"},{"id":"E","text":"Remove low-molecular-weight heparin from the medication list"},{"id":"F","text":"Restart heparin once the platelet count normalizes"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Respiratory', 'Heparin-induced thrombocytopenia', 'Recognition', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_362015', 'SATA', 'Which nursing practices are required safeguards when administering high-alert IV medications such as insulin and heparin? Select all that apply.', 'Independent double-checks, smart pumps, concentration verification, and two-identifier checks are safeguards; rounding to a vial and floor-stocking concentrated electrolytes are unsafe.', '{"options":[{"id":"A","text":"Perform an independent double-check with a second nurse"},{"id":"B","text":"Use a programmable smart infusion pump with dose limits"},{"id":"C","text":"Verify the concentration against the standardized order"},{"id":"D","text":"Round the dose up to the nearest whole vial for convenience"},{"id":"E","text":"Store concentrated electrolytes on the general unit floor stock"},{"id":"F","text":"Confirm the correct client using two identifiers"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'High-alert medications', 'Safe administration', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_362016', 'SATA', 'A nurse suspects extravasation of a vesicant chemotherapy agent from a peripheral IV. Which immediate actions are appropriate? Select all that apply.', 'Extravasation management stops the infusion, aspirates residual drug through the catheter, notifies the provider for antidotes, and applies agent-specific compresses; flushing and continuing infusion worsen tissue injury.', '{"options":[{"id":"A","text":"Stop the infusion immediately"},{"id":"B","text":"Leave the catheter in place and aspirate residual drug"},{"id":"C","text":"Notify the provider and follow the antidote protocol"},{"id":"D","text":"Flush the site briskly with normal saline to dilute the drug"},{"id":"E","text":"Apply warm or cold compresses per the agent-specific guideline"},{"id":"F","text":"Continue the infusion at a slower rate to finish the dose"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Chemotherapy', 'Extravasation', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_362017', 'SELECT_N', 'A client receives NPH insulin at 0730. The nurse wants to identify the times of greatest hypoglycemia risk related to insulin peaks and mistimed meals. Which 3 assessments best reduce this client''s hypoglycemia risk?', 'NPH peaks roughly 4-12 hours after dosing, so covering the peak with food, monitoring for late-afternoon hypoglycemia, and ensuring a bedtime snack reduce risk; withholding carbs, peak-time exercise, and skipping glucose checks increase it.', '{"options":[{"id":"A","text":"Ensure lunch is eaten during the mid-afternoon NPH peak"},{"id":"B","text":"Assess for hypoglycemia symptoms in the late afternoon"},{"id":"C","text":"Confirm the client will have a bedtime snack available"},{"id":"D","text":"Withhold all carbohydrate until the evening meal"},{"id":"E","text":"Plan the client''s most vigorous exercise during the peak"},{"id":"F","text":"Administer the NPH dose without checking a glucose level"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Peak times', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_362018', 'TF', 'For a client experiencing life-threatening bleeding from dabigatran, the appropriate reversal agent is protamine sulfate.', 'Idarucizumab is the specific reversal agent for dabigatran; protamine reverses heparin, not direct thrombin inhibitors.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antidotes', NULL, 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_362019', 'MATRIX', 'For each medication overdose, click the correct reversal agent or antidote.', 'Naloxone reverses opioids, flumazenil reverses benzodiazepines, and vitamin K reverses warfarin''s effect on the INR.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Morphine overdose"},{"id":"r2","text":"Midazolam over-sedation"},{"id":"r3","text":"Warfarin-induced elevated INR"},{"id":"r4","text":"Fentanyl respiratory depression"}],"columns":[{"id":"c1","text":"Naloxone"},{"id":"c2","text":"Flumazenil"},{"id":"c3","text":"Vitamin K"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Antidotes', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_362020', 'MATRIX_MR', 'For each medication, select all pre-administration parameters the nurse must verify before giving the dose (more than one may apply).', 'Digoxin requires apical rate and potassium; metformin requires renal function; spironolactone requires potassium and renal function; beta-blockers require the apical rate.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Digoxin"},{"id":"r2","text":"Metformin"},{"id":"r3","text":"Spironolactone"},{"id":"r4","text":"Metoprolol"}],"columns":[{"id":"c1","text":"Apical heart rate"},{"id":"c2","text":"Serum potassium"},{"id":"c3","text":"Serum creatinine"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c3"],"r3":["c2","c3"],"r4":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Pre-administration data review', NULL, 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_362021', 'CLOZE', 'A laboring client on an IV magnesium sulfate infusion for preeclampsia has absent deep tendon reflexes and a respiratory rate of 10/min. The nurse first {1}, then anticipates administering {2}.', 'Loss of reflexes and respiratory depression signal magnesium toxicity; the infusion is stopped and calcium gluconate, the antidote, is given.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"stops the magnesium infusion"},{"id":"c2","text":"increases the magnesium infusion"},{"id":"c3","text":"administers an oxytocin bolus"}]},{"id":"b2","choices":[{"id":"c1","text":"calcium gluconate"},{"id":"c2","text":"additional magnesium"},{"id":"c3","text":"potassium chloride"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Magnesium sulfate', 'Toxicity', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_362022', 'HIGHLIGHT', 'A client on an IV aminophylline (theophylline) infusion is assessed. Highlight the findings that indicate possible theophylline toxicity. Vital signs: HR [[132 and irregular]], BP 128/78. The client reports [[nausea and vomiting]] and [[a racing, pounding heart]]. Temperature [[37.1°C]]. The client is [[restless and tremulous]]. Respiratory rate [[16/min]].', 'Theophylline toxicity presents with tachydysrhythmias, GI upset, palpitations, and CNS stimulation; a normal temperature and respiratory rate are not cues.', '{"chunks":[{"id":"h1","text":"132 and irregular"},{"id":"h2","text":"nausea and vomiting"},{"id":"h3","text":"a racing, pounding heart"},{"id":"h4","text":"37.1°C"},{"id":"h5","text":"restless and tremulous"},{"id":"h6","text":"16/min"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h5"],"feedback":{"h1":"Tachydysrhythmia is a hallmark of theophylline toxicity.","h2":"GI upset is an early sign of toxicity.","h3":"Palpitations reflect the drug''s excess stimulant effect.","h4":"Normal temperature is not a toxicity sign.","h5":"CNS stimulation and tremor indicate toxicity.","h6":"A normal respiratory rate is not a toxicity cue."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Respiratory', 'Aminophylline toxicity', 'Cue recognition', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_362023', 'BOWTIE', 'A client with a PCA morphine pump is barely arousable with a respiratory rate of 7/min and pinpoint pupils. Complete the diagram by selecting the actions to take, the condition, and the parameters to monitor.', 'Opioid over-sedation is managed by stopping the opioid and giving naloxone, while monitoring respiratory rate and level of consciousness.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Stop the PCA infusion"},{"id":"lt2","text":"Prepare to administer naloxone"},{"id":"lt3","text":"Administer an additional morphine bolus"},{"id":"lt4","text":"Increase the PCA lockout dose"},{"id":"lt5","text":"Encourage the client to self-dose"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Opioid-induced respiratory depression"},{"id":"ct2","text":"Anaphylactic reaction"},{"id":"ct3","text":"Hypoglycemia"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Respiratory rate"},{"id":"rt2","text":"Level of consciousness"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Bowel sounds"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioid over-sedation', NULL, 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_362024', 'DRAG_CLOZE', 'A client is prescribed a dopamine infusion at 5 mcg/kg/min. The client weighs 70 kg, and the bag contains 400 mg of dopamine in 250 mL of D5W. The concentration is [1] mcg/mL, and the pump should be set at [2] mL/hr.', '400 mg in 250 mL = 1600 mcg/mL; 5 mcg/kg/min x 70 kg = 350 mcg/min = 21,000 mcg/hr; 21,000 / 1600 = about 13 mL/hr.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"1600"},{"id":"t2","text":"13"},{"id":"t3","text":"800"},{"id":"t4","text":"26"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Dosage calculation', 'IV drip rate', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366001', 'MCQ', 'A client with a chest tube for a hemothorax has a water-seal chamber that suddenly shows continuous, vigorous bubbling that was not present an hour ago. The client''s oxygen saturation has fallen from 96% to 89%. Which action should the nurse take FIRST?', 'New continuous bubbling with desaturation indicates an air leak; the first step is to trace the system for the disconnection or loose seal.', '{"options":[{"id":"A","text":"Assess all connections and the insertion site for an air leak"},{"id":"B","text":"Clamp the chest tube close to the client''s chest"},{"id":"C","text":"Increase the wall suction pressure"},{"id":"D","text":"Milk the chest tube toward the drainage chamber"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. New continuous bubbling signals an air leak; the nurse must first locate the break in the system.","B":"Incorrect. Clamping a bubbling tube risks a tension pneumothorax.","C":"Incorrect. Raising suction does not correct an air leak and worsens gas loss.","D":"Incorrect. Milking/stripping is not indicated and can raise intrapleural pressure dangerously."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', 'Complication recognition', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366002', 'MCQ', 'A client in septic shock has received 30 mL/kg of crystalloid. Vitals now: BP 82/48 mmHg, HR 118, MAP 59 mmHg, lactate rising to 4.8 mmol/L, and urine output 10 mL/hr. Which order should the nurse anticipate as the priority next intervention?', 'Fluid-refractory septic shock (persistent MAP <65 after 30 mL/kg) is treated with norepinephrine as the first-line vasopressor.', '{"options":[{"id":"A","text":"Start a norepinephrine infusion titrated to a MAP of at least 65 mmHg"},{"id":"B","text":"Administer a second 30 mL/kg crystalloid bolus"},{"id":"C","text":"Transfuse one unit of packed red blood cells"},{"id":"D","text":"Give a 40 mg IV furosemide dose for the low urine output"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. After adequate fluid resuscitation with persistent hypotension, a vasopressor is indicated to restore perfusion pressure.","B":"Incorrect. Fluid-refractory shock after adequate resuscitation calls for vasopressors, not indiscriminate more fluid.","C":"Incorrect. There is no evidence of hemorrhage or anemia driving the hypotension.","D":"Incorrect. The oliguria is from hypoperfusion; diuresis would worsen hypovolemia."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Sepsis', 'Hemodynamics', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366003', 'MCQ', 'A client is intubated on volume-control ventilation. The high-pressure alarm sounds repeatedly. The nurse notes the client is biting the tube, coughing, and has coarse audible secretions. Breath sounds are present bilaterally and the trachea is midline. Which is the MOST appropriate initial action?', 'A high-pressure alarm reflects increased airway resistance; secretions and tube biting are corrected by suctioning and a bite block.', '{"options":[{"id":"A","text":"Suction the airway and insert a bite block"},{"id":"B","text":"Prepare for immediate needle decompression"},{"id":"C","text":"Disconnect the ventilator and manually bag the client"},{"id":"D","text":"Decrease the set tidal volume"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. High-pressure alarms from secretions and biting are relieved by clearing the airway and preventing tube occlusion.","B":"Incorrect. Bilateral breath sounds and a midline trachea make tension pneumothorax unlikely.","C":"Incorrect. This is reserved for suspected equipment failure, not an obvious secretion/biting cause.","D":"Incorrect. Reducing tidal volume masks the problem rather than addressing the airway obstruction."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Mechanical ventilation', 'Alarm troubleshooting', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366004', 'MCQ', 'During the first hemodialysis treatment of a client with a markedly elevated BUN, the client develops a worsening headache, nausea, restlessness, and confusion. Which complication should the nurse suspect and act on?', 'Dialysis disequilibrium syndrome results from rapid urea clearance and osmotic cerebral edema, especially in a first, high-BUN treatment.', '{"options":[{"id":"A","text":"Dialysis disequilibrium syndrome"},{"id":"B","text":"Air embolism"},{"id":"C","text":"First-use hypersensitivity reaction"},{"id":"D","text":"Hypervolemia"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Rapid solute removal causes cerebral edema; slowing the rate and notifying the provider is indicated.","B":"Incorrect. Air embolism presents with sudden dyspnea, chest pain, and cyanosis, not a gradual neuro decline.","C":"Incorrect. That presents with itching, urticaria, and dyspnea early in the run.","D":"Incorrect. Dialysis removes fluid; hypervolemia is not the cause of these neuro symptoms."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Hemodialysis', 'Disequilibrium syndrome', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366005', 'MCQ', 'A client in DKA has been on an insulin infusion for 3 hours. Latest labs: glucose 240 mg/dL (down from 520), potassium 3.3 mEq/L, pH 7.28. Which action should the nurse anticipate?', 'Insulin drives potassium intracellularly; with K at 3.3 mEq/L, replacement is added while insulin continues to resolve the acidosis.', '{"options":[{"id":"A","text":"Add potassium to the IV fluids and continue the insulin infusion"},{"id":"B","text":"Stop the insulin infusion until potassium normalizes"},{"id":"C","text":"Administer a bolus of 50% dextrose"},{"id":"D","text":"Give sodium bicarbonate for the acidosis"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Potassium below 3.3-3.5 requires replacement while insulin therapy continues to prevent dangerous hypokalemia.","B":"Incorrect. Insulin should continue with potassium replacement; stopping it allows ketoacidosis to persist.","C":"Incorrect. Glucose is 240; a dextrose bolus is not indicated until it approaches 200 mg/dL, and then as maintenance dextrose.","D":"Incorrect. Bicarbonate is reserved for severe acidosis (pH <6.9) and can worsen hypokalemia."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Diabetic ketoacidosis', 'Electrolyte management', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366006', 'MCQ', 'A client with a traumatic brain injury has an intraventricular catheter reading an ICP of 24 mmHg and a MAP of 78 mmHg. Which value should the nurse calculate and report as the priority concern?', 'CPP = MAP - ICP; a value of 54 mmHg is below the therapeutic range and signals cerebral ischemia risk.', '{"options":[{"id":"A","text":"Cerebral perfusion pressure of 54 mmHg"},{"id":"B","text":"Cerebral perfusion pressure of 102 mmHg"},{"id":"C","text":"Mean arterial pressure of 42 mmHg"},{"id":"D","text":"Cerebral perfusion pressure of 24 mmHg"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. CPP = MAP - ICP = 78 - 24 = 54 mmHg, below the 60-70 target, indicating inadequate cerebral perfusion.","B":"Incorrect. That adds the values rather than subtracting ICP from MAP.","C":"Incorrect. MAP is given as 78 mmHg, not a calculated value here.","D":"Incorrect. That is the ICP, not the CPP."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Neurological', 'Increased intracranial pressure', 'Internal monitoring', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366007', 'MCQ', 'A newborn is receiving intensive phototherapy for hyperbilirubinemia. Which finding requires the nurse to intervene immediately?', 'Phototherapy can cause hyperthermia and insensible fluid loss; fever with lethargy demands immediate intervention, while loose stools and rash are expected.', '{"options":[{"id":"A","text":"Temperature of 38.9°C (102°F) with lethargy"},{"id":"B","text":"Loose, greenish stools"},{"id":"C","text":"A fine maculopapular rash on the trunk"},{"id":"D","text":"Bronze discoloration of the skin"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Hyperthermia and lethargy under phototherapy signal overheating/dehydration and must be addressed at once.","B":"Incorrect. Loose green stools are an expected effect of bilirubin excretion.","C":"Incorrect. A transient rash is a benign, expected phototherapy effect.","D":"Incorrect. Bronze-baby discoloration is usually benign and resolves after therapy."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Pediatrics', 'Hematologic', 'Phototherapy', 'Neonatal hyperbilirubinemia', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366008', 'MCQ', 'A client with a temporary transvenous pacemaker set at a rate of 70 has a monitor showing pacer spikes that are frequently not followed by a QRS complex. The client is dizzy with a palpable rate of 44. Which action should the nurse take FIRST?', 'Spikes without a following QRS indicate failure to capture; increasing output (mA) is the first corrective step to regain capture.', '{"options":[{"id":"A","text":"Increase the milliamperes (output) on the pacemaker generator"},{"id":"B","text":"Reposition the client onto the right side"},{"id":"C","text":"Decrease the pacemaker rate to 50"},{"id":"D","text":"Turn off the pacemaker and observe the underlying rhythm"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Pacer spikes without capture indicate failure to capture; increasing the mA raises stimulus strength to restore capture.","B":"Incorrect. Repositioning may help lead contact but does not reliably or immediately restore capture in a symptomatic client.","C":"Incorrect. Lowering the rate worsens the client''s bradycardia and symptoms.","D":"Incorrect. Turning off pacing in a symptomatic bradycardic client is dangerous."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Pacing devices', 'Failure to capture', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366009', 'MCQ', 'On the second postoperative day, a nurse assessing a client''s new colostomy notes the stoma is dusky purple-black and dry. Which is the priority nursing action?', 'A healthy stoma is pink-red and moist; a dusky-black, dry stoma signals ischemia and warrants immediate surgeon notification.', '{"options":[{"id":"A","text":"Notify the surgeon immediately"},{"id":"B","text":"Apply a barrier paste and reapply the pouch"},{"id":"C","text":"Document the finding as an expected early appearance"},{"id":"D","text":"Irrigate the stoma with warm saline"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A dusky, dark, dry stoma indicates ischemia/necrosis and requires urgent surgical evaluation.","B":"Incorrect. Routine pouch care does not address a necrotic stoma.","C":"Incorrect. A healthy stoma is pink-red and moist; dusky-black is never expected.","D":"Incorrect. Irrigation does not restore perfusion and delays needed intervention."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Ostomy care', 'Complication recognition', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366010', 'MCQ', 'Thirty minutes after a thoracentesis that removed 1500 mL of fluid, a client reports sudden dyspnea, a persistent cough, and pink frothy sputum. Which complication should the nurse suspect?', 'Rapid removal of large pleural volumes causes re-expansion pulmonary edema, marked by acute dyspnea and pink frothy sputum.', '{"options":[{"id":"A","text":"Re-expansion pulmonary edema"},{"id":"B","text":"Vasovagal syncope"},{"id":"C","text":"Expected post-procedure discomfort"},{"id":"D","text":"Anxiety-related hyperventilation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Removing a large volume rapidly can cause re-expansion pulmonary edema, presenting with dyspnea, cough, and frothy sputum.","B":"Incorrect. Vasovagal reactions cause bradycardia and hypotension, not frothy sputum.","C":"Incorrect. Frothy pink sputum and acute dyspnea are never expected.","D":"Incorrect. Hyperventilation would not produce pink frothy sputum."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Thoracentesis', 'Invasive-procedure assist', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366011', 'MCQ', 'A nurse performing peritoneal dialysis notes that the effluent draining from a client''s abdomen has become cloudy and the client reports abdominal pain and a low-grade fever. Which action is the priority?', 'Cloudy PD effluent with abdominal pain and fever is the classic presentation of peritonitis; the nurse cultures the effluent and notifies the provider.', '{"options":[{"id":"A","text":"Obtain a sample of the effluent for culture and notify the provider"},{"id":"B","text":"Increase the dwell time of the next exchange"},{"id":"C","text":"Warm the dialysate to reduce cramping"},{"id":"D","text":"Document cloudy effluent as normal for peritoneal dialysis"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cloudy effluent with pain and fever indicates peritonitis; culture and provider notification guide antibiotic therapy.","B":"Incorrect. Adjusting dwell time does not treat the suspected infection.","C":"Incorrect. Warming helps comfort but ignores the infection.","D":"Incorrect. Effluent should be clear; cloudiness is a hallmark of peritonitis."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Peritoneal dialysis', 'Complication recognition', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366012', 'MCQ', 'A client with acute kidney injury has a serum potassium of 7.1 mEq/L with peaked T waves on the monitor. Which prescribed intervention should the nurse administer FIRST to protect the client?', 'With ECG changes from severe hyperkalemia, IV calcium is given first to stabilize the myocardium before agents that shift or remove potassium.', '{"options":[{"id":"A","text":"IV calcium gluconate"},{"id":"B","text":"IV regular insulin with dextrose"},{"id":"C","text":"Sodium polystyrene sulfonate orally"},{"id":"D","text":"Nebulized albuterol"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Calcium gluconate stabilizes the myocardium against lethal arrhythmias and is given first, before potassium-lowering agents.","B":"Incorrect. Insulin shifts potassium intracellularly but does not protect the heart as immediately as calcium.","C":"Incorrect. This removes potassium slowly over hours, not for acute cardiac protection.","D":"Incorrect. Albuterol shifts potassium but is adjunctive, not the first cardioprotective step."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Fluid and electrolyte imbalance', 'Hyperkalemia', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_366013', 'MCQ', 'A nurse notes that a client''s arterial line waveform has become dampened and the displayed pressures are lower than the cuff blood pressure taken simultaneously. What should the nurse do FIRST?', 'A dampened arterial waveform usually reflects a mechanical problem in the tubing/transducer system; the nurse troubleshoots the line before trusting or acting on the value.', '{"options":[{"id":"A","text":"Check the line for kinks, air bubbles, or a loose connection and assess the flush system"},{"id":"B","text":"Document the arterial reading and treat the client for hypotension"},{"id":"C","text":"Remove the arterial catheter immediately"},{"id":"D","text":"Zero the transducer at the level of the client''s phlebostatic axis only after giving a fluid bolus"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A dampened waveform is most often caused by system problems (kinks, air, clot, low flush pressure) that should be corrected first.","B":"Incorrect. A dampened trace underreads pressure; treating a falsely low value is unsafe.","C":"Incorrect. Removal is premature before troubleshooting the system.","D":"Incorrect. Re-leveling/zeroing may be needed, but a fluid bolus based on a dampened reading is unsafe."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Arterial line monitoring', 'Waveform interpretation', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_366014', 'SATA', 'A nurse is caring for a client developing acute respiratory distress syndrome (ARDS). Which findings support this diagnosis? Select all that apply.', 'ARDS features refractory hypoxemia, bilateral infiltrates, low compliance, and a reduced P/F ratio, and is not primarily due to cardiogenic edema.', '{"options":[{"id":"A","text":"Refractory hypoxemia that does not improve with increasing oxygen"},{"id":"B","text":"Bilateral infiltrates on chest x-ray"},{"id":"C","text":"Decreased lung compliance (stiff lungs)"},{"id":"D","text":"A PaO2/FiO2 ratio of 150"},{"id":"E","text":"Elevated jugular venous distention from left heart failure as the primary cause"},{"id":"F","text":"Improvement in oxygenation when the FiO2 is lowered"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Acute respiratory distress syndrome', 'Complication recognition', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_366015', 'SATA', 'A client is progressing from the compensatory to the progressive stage of hypovolemic shock. Which findings should the nurse expect in the progressive stage? Select all that apply.', 'The progressive stage brings lactic acidosis, worsening mental status, hypotension, and oliguria; skin is cool and clammy with weak pulses, not warm and bounding.', '{"options":[{"id":"A","text":"Metabolic acidosis with a rising serum lactate"},{"id":"B","text":"Deteriorating level of consciousness"},{"id":"C","text":"Falling blood pressure despite tachycardia"},{"id":"D","text":"Decreasing urine output progressing toward anuria"},{"id":"E","text":"Warm, flushed, dry skin"},{"id":"F","text":"Bounding peripheral pulses"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Shock', 'Hemodynamics', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_366016', 'SATA', 'A postoperative client''s abdominal incision suddenly opens and a loop of bowel protrudes through the wound. Which nursing actions are appropriate? Select all that apply.', 'Evisceration is a surgical emergency: cover with moist sterile gauze, position to reduce tension, keep NPO, and notify the surgeon; never reinsert the bowel or let it dry out.', '{"options":[{"id":"A","text":"Cover the wound with sterile gauze moistened with normal saline"},{"id":"B","text":"Place the client in low Fowler''s position with knees slightly flexed"},{"id":"C","text":"Notify the surgeon and prepare the client for emergency surgery"},{"id":"D","text":"Keep the client NPO"},{"id":"E","text":"Attempt to gently push the bowel back into the abdomen"},{"id":"F","text":"Cover the wound with dry gauze and leave it until the surgeon arrives"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Wound care', 'Dehiscence and evisceration', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_366017', 'SATA', 'A client is diagnosed with syndrome of inappropriate antidiuretic hormone (SIADH). Which assessment findings should the nurse expect? Select all that apply.', 'SIADH causes water retention with dilutional hyponatremia, low serum osmolality, concentrated urine, and neurologic symptoms — the opposite of diabetes insipidus.', '{"options":[{"id":"A","text":"Serum sodium of 118 mEq/L"},{"id":"B","text":"Concentrated urine with high specific gravity"},{"id":"C","text":"Confusion and headache"},{"id":"D","text":"Low serum osmolality"},{"id":"E","text":"Polyuria with dilute urine"},{"id":"F","text":"Signs of dehydration and hypernatremia"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Syndrome of inappropriate ADH', 'Fluid and electrolyte imbalance', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_366018', 'SATA', 'A client with known adrenal insufficiency who missed several doses of hydrocortisone presents to the emergency department. Which findings indicate an acute adrenal (Addisonian) crisis? Select all that apply.', 'Cortisol and aldosterone deficiency in adrenal crisis produce hypotension, hyperkalemia, hyponatremia, and hypoglycemia.', '{"options":[{"id":"A","text":"Profound hypotension"},{"id":"B","text":"Hyperkalemia"},{"id":"C","text":"Hyponatremia"},{"id":"D","text":"Hypoglycemia"},{"id":"E","text":"Hypertension with fluid overload"},{"id":"F","text":"Hypokalemia"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Adrenal crisis', 'Complication recognition', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_366019', 'SATA', 'A nurse is performing endotracheal suctioning on a mechanically ventilated client. Which techniques reduce the risk of complications? Select all that apply.', 'Safe suctioning uses pre/post hyperoxygenation, brief passes, suction only on withdrawal, and continuous monitoring; routine saline instillation and suction on insertion are harmful.', '{"options":[{"id":"A","text":"Hyperoxygenate the client before and after suctioning"},{"id":"B","text":"Limit each suction pass to 10-15 seconds"},{"id":"C","text":"Apply suction only while withdrawing the catheter"},{"id":"D","text":"Monitor the heart rate and oxygen saturation throughout"},{"id":"E","text":"Instill 5-10 mL of normal saline before each pass to loosen secretions"},{"id":"F","text":"Apply continuous suction during insertion of the catheter"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Airway suctioning', 'Pulmonary hygiene', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_366020', 'SELECT_N', 'A client with sepsis is developing disseminated intravascular coagulation (DIC). Which 3 laboratory findings support this diagnosis?', 'DIC consumes clotting factors and platelets: D-dimer rises, platelets fall, PT/PTT prolong, and fibrinogen drops.', '{"options":[{"id":"A","text":"Elevated D-dimer"},{"id":"B","text":"Decreased platelet count"},{"id":"C","text":"Prolonged prothrombin time (PT)"},{"id":"D","text":"Elevated fibrinogen level"},{"id":"E","text":"Shortened partial thromboplastin time (PTT)"},{"id":"F","text":"Increased platelet count"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Disseminated intravascular coagulation', 'Hemostasis', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_366021', 'TF', 'A client with a chest tube in the water-seal chamber shows tidaling (fluctuation of the water level with respiration); the nurse should interpret this as an urgent sign that the tube has become obstructed and requires immediate replacement.', 'Tidaling is a normal, expected finding reflecting pressure changes with breathing; sudden cessation of tidaling — not its presence — may indicate obstruction or lung re-expansion.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', 'Tidaling', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_366022', 'MATRIX', 'For each set of arterial blood gas values, click to identify the primary acid-base disturbance.', 'A low pH with high PaCO2 is respiratory acidosis; low pH with low HCO3 is metabolic acidosis; high pH with low PaCO2 is respiratory alkalosis.', '{"row_label":"Arterial blood gas","rows":[{"id":"r1","text":"pH 7.30, PaCO2 58, HCO3 26"},{"id":"r2","text":"pH 7.28, PaCO2 34, HCO3 16"},{"id":"r3","text":"pH 7.50, PaCO2 28, HCO3 23"},{"id":"r4","text":"pH 7.31, PaCO2 60, HCO3 27"}],"columns":[{"id":"c1","text":"Respiratory acidosis"},{"id":"c2","text":"Metabolic acidosis"},{"id":"c3","text":"Respiratory alkalosis"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Acid-base imbalance', 'ABG interpretation', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_366023', 'MATRIX_MR', 'For each acute condition, select all clinical findings the nurse would expect to assess (each condition may have more than one).', 'Tamponade and tension pneumothorax both cause obstructive shock with hypotension, tachycardia, and JVD, whereas early hypovolemia shows compensatory tachycardia with flat neck veins.', '{"row_label":"Condition","rows":[{"id":"r1","text":"Cardiac tamponade"},{"id":"r2","text":"Early hypovolemic shock"},{"id":"r3","text":"Tension pneumothorax"}],"columns":[{"id":"c1","text":"Hypotension"},{"id":"c2","text":"Tachycardia"},{"id":"c3","text":"Jugular venous distention"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c2"],"r3":["c1","c2","c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Complication recognition', 'Assessment cues', 'Hard', 'Analyze', '{}', 7, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_366024', 'CLOZE', 'A client passing 6 L of dilute urine per day with a rising serum sodium is most likely experiencing {1}, and the nurse anticipates treatment with {2}.', 'Large volumes of dilute urine with hypernatremia indicate diabetes insipidus, treated with the ADH analog desmopressin.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"diabetes insipidus"},{"id":"c2","text":"SIADH"},{"id":"c3","text":"acute kidney injury"}]},{"id":"b2","choices":[{"id":"c1","text":"desmopressin"},{"id":"c2","text":"a fluid restriction"},{"id":"c3","text":"hypertonic saline"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Diabetes insipidus', 'Fluid and electrolyte imbalance', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_366025', 'HIGHLIGHT', 'The nurse reviews a postoperative client''s assessment. Highlight the findings that indicate the client may be developing sepsis. Temperature [[38.9°C]]. Heart rate [[124]]. Blood pressure [[86/50]]. Respiratory rate [[26]]. SpO2 [[96% on room air]]. Skin warm and [[mottled]]. Alert and oriented. Urine output [[12 mL/hr]].', 'Fever, tachycardia, hypotension, tachypnea, mottling, and oliguria all indicate evolving sepsis; a normal SpO2 does not.', '{"chunks":[{"id":"h1","text":"38.9°C"},{"id":"h2","text":"124"},{"id":"h3","text":"86/50"},{"id":"h4","text":"26"},{"id":"h5","text":"mottled"},{"id":"h6","text":"12 mL/hr"},{"id":"h7","text":"96% on room air"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h4","h5","h6"],"feedback":{"h1":"Fever is a systemic response to infection.","h2":"Tachycardia is a sepsis criterion.","h3":"Hypotension signals sepsis-related hypoperfusion.","h4":"Tachypnea is a systemic inflammatory response cue.","h5":"Mottled skin reflects poor perfusion.","h6":"Oliguria indicates end-organ hypoperfusion.","h7":"A normal oxygen saturation is not a sign of sepsis."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Sepsis', 'Complication recognition', 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_366026', 'BOWTIE', 'A client with untreated Graves disease presents with a temperature of 40.2°C, HR 148, agitation, and delirium. Complete the diagram by selecting the condition, the priority actions, and the parameters to monitor.', 'Thyroid storm is a hypermetabolic emergency managed with beta-blockade and cooling, monitoring cardiac rhythm and temperature.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer a beta-blocker as prescribed"},{"id":"lt2","text":"Initiate active cooling measures"},{"id":"lt3","text":"Apply warming blankets"},{"id":"lt4","text":"Encourage vigorous ambulation"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Thyroid storm"},{"id":"ct2","text":"Myxedema coma"},{"id":"ct3","text":"Adrenal crisis"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Cardiac rhythm"},{"id":"rt2","text":"Core temperature"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Stool frequency"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Thyroid storm', 'Emergency care', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_366027', 'DRAG_CLOZE', 'Fifteen minutes into a transfusion, a client develops fever, flank pain, and dark urine. The nurse recognizes a likely [1] reaction and the first action is to [2].', 'Fever, flank pain, and hemoglobinuria signal an acute hemolytic reaction; the transfusion must be stopped immediately while saline is infused through new tubing.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"acute hemolytic"},{"id":"t2","text":"stop the transfusion and keep the vein open with saline"},{"id":"t3","text":"febrile nonhemolytic"},{"id":"t4","text":"slow the transfusion rate"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Blood transfusion reaction', 'Complication recognition', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_366028', 'DRAG_ORDER', 'A client''s central venous catheter becomes disconnected and the nurse suspects an air embolism. Place the nurse''s actions in the correct priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Clamp the catheter to prevent further air entry"},{"id":"t2","text":"Position the client on the left side in Trendelenburg"},{"id":"t3","text":"Administer 100% oxygen"},{"id":"t4","text":"Notify the provider and rapid response team"},{"id":"t5","text":"Document the event"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Air embolism', 'Central line complication', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367001', 'MCQ', 'A nurse is caring for a client with a chest tube for a pneumothorax. The nurse notes that the water-seal chamber previously had tidaling with respiration, but tidaling has now suddenly stopped and the client reports increasing dyspnea and chest tightness. Which action should the nurse take FIRST?', 'Abrupt loss of tidaling with new respiratory distress suggests a kinked/obstructed tube or re-accumulating air; the nurse first assesses the system and client.', '{"options":[{"id":"A","text":"Assess the tubing for kinks or obstruction and the client''s breath sounds"},{"id":"B","text":"Document that the lung has fully re-expanded"},{"id":"C","text":"Increase the wall suction to restore tidaling"},{"id":"D","text":"Clamp the chest tube and notify the provider"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Sudden loss of tidaling with worsening dyspnea suggests obstruction or re-accumulating pneumothorax — assess the system and client before other action.","B":"Incorrect. Cessation of tidaling with new dyspnea signals obstruction, not resolution.","C":"Incorrect. Increasing suction does not address an obstruction and is not first.","D":"Incorrect. Clamping a chest tube with a possible pneumothorax risks tension pneumothorax."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', 'Complication recognition', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367002', 'MCQ', 'A client with suspected septic shock has received 30 mL/kg of isotonic crystalloid. Vital signs are now BP 82/44 mmHg, HR 122 bpm, MAP 56 mmHg, and lactate 4.6 mmol/L. Which prescription should the nurse anticipate implementing next?', 'Persistent hypotension and elevated lactate after adequate fluids in septic shock warrant a vasopressor; norepinephrine is first-line to achieve MAP >= 65 mmHg.', '{"options":[{"id":"A","text":"Start a norepinephrine infusion titrated to a MAP of at least 65 mmHg"},{"id":"B","text":"Administer a 1 L bolus of 0.45% sodium chloride"},{"id":"C","text":"Give furosemide to improve urine output"},{"id":"D","text":"Transfuse one unit of packed red blood cells"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. After adequate fluid resuscitation with persistent hypotension, a vasopressor (norepinephrine first-line) is indicated to restore perfusion pressure.","B":"Incorrect. Hypotonic fluid is inappropriate and additional fluid alone is not first after adequate resuscitation.","C":"Incorrect. A diuretic in a hypotensive, hypoperfused client would worsen shock.","D":"Incorrect. There is no indication of anemia or hemorrhage in this scenario."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Septic shock', 'Hemodynamics', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367003', 'MCQ', 'A client is intubated and receiving volume-controlled mechanical ventilation. The high-pressure alarm sounds repeatedly. The nurse notes the client is biting the tube and coughing, with rhonchi on auscultation and increased secretions. Which intervention is the priority?', 'A high-pressure ventilator alarm reflects increased airway resistance (secretions, biting, coughing); clearing secretions with suction addresses the cause.', '{"options":[{"id":"A","text":"Suction the airway to clear secretions"},{"id":"B","text":"Add positive end-expiratory pressure (PEEP)"},{"id":"C","text":"Silence the alarm and continue to monitor"},{"id":"D","text":"Increase the set tidal volume"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A high-pressure alarm from secretions and coughing indicates increased airway resistance; suctioning addresses the reversible cause.","B":"Incorrect. Adding PEEP does not relieve resistance from secretions and could worsen pressures.","C":"Incorrect. Silencing without addressing the cause risks hypoxia.","D":"Incorrect. Increasing tidal volume raises peak pressures further."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Mechanical ventilation', 'Ventilator alarms', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367004', 'MCQ', 'During the first hemodialysis treatment for a client with newly diagnosed end-stage renal disease, the client develops a headache, nausea, restlessness, and confusion near the end of the session. Which complication should the nurse suspect?', 'Disequilibrium syndrome results from rapid decrease in BUN/solutes during early dialysis, causing an osmotic shift and cerebral edema with neurologic symptoms.', '{"options":[{"id":"A","text":"Dialysis disequilibrium syndrome"},{"id":"B","text":"Air embolism"},{"id":"C","text":"Hemolysis"},{"id":"D","text":"Hyperkalemia"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Rapid solute removal during initial dialysis creates an osmotic gradient causing cerebral edema — headache, nausea, restlessness, and confusion are classic.","B":"Incorrect. Air embolism presents with sudden dyspnea, chest pain, and cyanosis, not this gradual neuro picture.","C":"Incorrect. Hemolysis causes back/chest pain and cherry-red blood, not primarily neurologic change.","D":"Incorrect. Dialysis lowers potassium; the findings are not consistent with hyperkalemia."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Hemodialysis', 'Disequilibrium syndrome', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367005', 'MCQ', 'A client with a traumatic brain injury and an intraventricular ICP monitor has an ICP of 24 mmHg and a MAP of 78 mmHg. Which value best reflects the adequacy of cerebral perfusion, and how should the nurse interpret it?', 'CPP = MAP - ICP = 54 mmHg, which is below the recommended 60-70 mmHg and signals inadequate cerebral perfusion requiring intervention.', '{"options":[{"id":"A","text":"Cerebral perfusion pressure is 54 mmHg — below the target range and concerning"},{"id":"B","text":"Cerebral perfusion pressure is 102 mmHg — adequate"},{"id":"C","text":"Cerebral perfusion pressure is 24 mmHg — normal"},{"id":"D","text":"Cerebral perfusion pressure is 78 mmHg — adequate"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. CPP = MAP - ICP = 78 - 24 = 54 mmHg, below the 60-70 mmHg target, indicating inadequate cerebral perfusion.","B":"Incorrect. CPP is MAP minus ICP, not the sum.","C":"Incorrect. 24 mmHg is the ICP, not the CPP.","D":"Incorrect. 78 mmHg is the MAP; CPP must subtract the ICP."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Neurological', 'Increased intracranial pressure', 'ICP monitoring', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367006', 'MCQ', 'A client with diabetic ketoacidosis has been receiving an insulin infusion and IV fluids. Current labs: glucose 245 mg/dL, potassium 3.3 mEq/L, pH 7.28. The nurse is about to titrate care. Which action is the priority?', 'In DKA, insulin shifts potassium into cells; with K+ of 3.3 mEq/L, potassium must be replaced and insulin held/adjusted to prevent fatal hypokalemia.', '{"options":[{"id":"A","text":"Hold or delay further insulin and administer potassium replacement per protocol"},{"id":"B","text":"Increase the insulin infusion rate to normalize glucose faster"},{"id":"C","text":"Add dextrose and continue insulin unchanged"},{"id":"D","text":"Administer sodium bicarbonate for the acidosis"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Potassium of 3.3 mEq/L is low; insulin drives potassium intracellularly and can cause life-threatening hypokalemia, so replace potassium and address it before continuing insulin.","B":"Incorrect. Increasing insulin would worsen the hypokalemia.","C":"Incorrect. Dextrose is added around glucose 200 mg/dL, but the urgent issue is the low potassium.","D":"Incorrect. Bicarbonate is reserved for severe acidosis (pH < 6.9) and could worsen hypokalemia."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Diabetic ketoacidosis', 'Fluid and electrolyte', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367007', 'MCQ', 'On the second postoperative day after colostomy creation, the nurse assesses the stoma and finds it dusky bluish-purple and dry. Which action should the nurse take FIRST?', 'A healthy stoma is pink-red and moist; a dusky, dry, purple stoma indicates compromised blood supply and must be reported immediately.', '{"options":[{"id":"A","text":"Notify the surgeon immediately"},{"id":"B","text":"Apply a warm compress to improve circulation"},{"id":"C","text":"Document the expected postoperative appearance"},{"id":"D","text":"Increase oral fluid intake to perfuse the stoma"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A dusky/bluish, dry stoma indicates ischemia or necrosis — a surgical emergency requiring immediate provider notification.","B":"Incorrect. Warm compresses will not reverse ischemia and delay definitive care.","C":"Incorrect. A healthy stoma is pink/red and moist; this appearance is abnormal.","D":"Incorrect. Oral fluids will not restore stoma perfusion; this needs urgent evaluation."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Ostomy care', 'Stoma complication', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367008', 'MCQ', 'A client with a temporary transvenous pacemaker set at a rate of 70 bpm has a monitor showing pacing spikes that are NOT followed by QRS complexes, and the client''s palpable pulse is 46 bpm. Which pacemaker malfunction is occurring?', 'Pacing spikes without a following QRS indicate failure to capture — the electrical stimulus does not depolarize the myocardium, so the effective rate is low.', '{"options":[{"id":"A","text":"Failure to capture"},{"id":"B","text":"Failure to sense"},{"id":"C","text":"Failure to pace (output failure)"},{"id":"D","text":"Oversensing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Pacing spikes not followed by depolarization (QRS) indicate failure to capture — the stimulus fails to produce myocardial contraction.","B":"Incorrect. Failure to sense produces spikes inappropriately placed on intrinsic beats, not spikes without capture.","C":"Incorrect. Failure to pace shows absent spikes; here spikes are present.","D":"Incorrect. Oversensing inhibits pacing output, producing pauses without spikes."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Pacing devices', 'Pacemaker malfunction', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367009', 'MCQ', 'A client has negative pressure wound therapy (NPWT) on an abdominal wound. The nurse finds the foam dressing expanded and no longer collapsed, the device alarming, and an audible hissing at the dressing edge. Which is the nurse''s best initial action?', 'An expanded (non-collapsed) foam with hissing and alarms signals a broken seal/air leak; resealing the occlusive drape restores negative pressure.', '{"options":[{"id":"A","text":"Inspect the transparent drape for a leak and reseal it to restore the seal"},{"id":"B","text":"Turn off the device and leave the wound open to air"},{"id":"C","text":"Increase the negative pressure setting to overcome the leak"},{"id":"D","text":"Irrigate the wound with sterile saline and repack it"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Loss of collapse, alarming, and hissing indicate an air leak; resealing the drape restores negative pressure and therapy effectiveness.","B":"Incorrect. Discontinuing therapy without correcting the leak interrupts wound healing.","C":"Incorrect. Raising pressure does not fix a broken seal and may harm tissue.","D":"Incorrect. The immediate problem is the air leak, not the packing itself."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Integumentary', 'Negative pressure wound therapy', 'NPWT troubleshooting', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367010', 'MCQ', 'A nurse notes that a client''s arterial line waveform is dampened and the displayed pressure is lower than a cuff reading taken simultaneously. The line flushes sluggishly. Which action should the nurse perform FIRST?', 'A dampened arterial waveform underestimates pressure; the nurse first troubleshoots kinks, clot, air, and transducer setup before trusting or acting on the value.', '{"options":[{"id":"A","text":"Check for kinks and assess the catheter/tubing for clot or air, then perform a square-wave test"},{"id":"B","text":"Document the arterial pressure and treat the hypotension with fluids"},{"id":"C","text":"Zero and re-level the transducer to the phlebostatic axis only"},{"id":"D","text":"Remove the arterial catheter immediately"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A dampened waveform with sluggish flush suggests a kink, clot, or air; assessing the system and performing a square-wave (dynamic response) test identifies the cause before treating readings.","B":"Incorrect. A dampened waveform gives inaccurate low readings; treating them risks harm.","C":"Incorrect. Re-leveling is reasonable but does not address a kink/clot causing damping and is not the priority action.","D":"Incorrect. Removal is premature before troubleshooting the reversible causes."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Arterial line', 'Hemodynamic monitoring', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367011', 'MCQ', 'A newborn is receiving phototherapy for hyperbilirubinemia. Which finding requires the nurse to intervene?', 'Phototherapy increases insensible water loss and can cause hyperthermia and dehydration; fever with reduced output requires intervention, whereas loose stools and rash are expected.', '{"options":[{"id":"A","text":"Temperature of 38.6°C (101.5°F) with decreased urine output"},{"id":"B","text":"Loose green stools"},{"id":"C","text":"A fine maculopapular rash"},{"id":"D","text":"The newborn wearing only a diaper with eye shields in place"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Hyperthermia and signs of dehydration are complications of phototherapy requiring intervention to prevent fluid loss and overheating.","B":"Incorrect. Loose green stools are an expected effect of increased bilirubin excretion.","C":"Incorrect. A transient rash is a common, benign effect of phototherapy.","D":"Incorrect. This is the correct positioning to maximize skin exposure while protecting the eyes."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Pediatrics', 'Hematologic', 'Phototherapy', 'Neonatal hyperbilirubinemia', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367012', 'MCQ', 'A client is brought to the emergency department after collapsing during outdoor labor in hot weather. Temperature is 41.2°C (106.2°F), skin is hot and dry, and the client is confused. Which intervention is the priority?', 'Heat stroke (hot/dry skin, altered mentation, core temp > 40°C) requires immediate active cooling; antipyretics are ineffective.', '{"options":[{"id":"A","text":"Begin rapid active cooling with cool water/ice packs to the groin, axillae, and neck"},{"id":"B","text":"Administer acetaminophen to reduce the temperature"},{"id":"C","text":"Encourage the client to drink cold oral fluids"},{"id":"D","text":"Cover the client with a warming blanket to prevent shivering"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Heat stroke with CNS dysfunction is a medical emergency; rapid cooling to lower core temperature is the priority to prevent organ damage.","B":"Incorrect. Antipyretics are ineffective in heat stroke because the hyperthermia is not hypothalamically mediated.","C":"Incorrect. A confused client is at risk for aspiration and this does not rapidly cool the core.","D":"Incorrect. Warming would worsen the life-threatening hyperthermia."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Temperature regulation', 'Heat stroke', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_367013', 'MCQ', 'A laboring client with an internal fetal scalp electrode and intrauterine pressure catheter shows recurrent late decelerations with minimal variability. Which action should the nurse take FIRST?', 'Late decelerations reflect uteroplacental insufficiency; intrauterine resuscitation begins with repositioning to improve perfusion (along with stopping oxytocin, O2, and fluids).', '{"options":[{"id":"A","text":"Reposition the client to a lateral position"},{"id":"B","text":"Prepare for immediate cesarean delivery"},{"id":"C","text":"Increase the oxytocin infusion to speed delivery"},{"id":"D","text":"Document the pattern as reassuring and continue monitoring"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Recurrent late decelerations indicate uteroplacental insufficiency; lateral positioning improves placental perfusion and is the first intrauterine resuscitation step.","B":"Incorrect. Intrauterine resuscitation measures are attempted first before surgical delivery.","C":"Incorrect. Oxytocin would worsen uteroplacental insufficiency and should be stopped.","D":"Incorrect. Recurrent late decelerations with minimal variability are non-reassuring."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Maternity', 'Reproductive', 'Internal fetal monitoring', 'Fetal heart rate patterns', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_367014', 'SATA', 'A client with acute kidney injury has a serum potassium of 6.8 mEq/L. Which findings and interventions are appropriate for the nurse to anticipate? Select all that apply.', 'Hyperkalemia causes peaked T waves; management stabilizes the myocardium (calcium), shifts K+ intracellularly (insulin/dextrose), and removes it (kayexalate/dialysis) while avoiding K+ intake.', '{"options":[{"id":"A","text":"Peaked T waves on the ECG"},{"id":"B","text":"Administering IV calcium gluconate to stabilize the myocardium"},{"id":"C","text":"Giving IV regular insulin with dextrose to shift potassium intracellularly"},{"id":"D","text":"Administering sodium polystyrene sulfonate or preparing for dialysis"},{"id":"E","text":"Encouraging a diet high in bananas and oranges"},{"id":"F","text":"Administering a potassium-sparing diuretic"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Peaked T waves are an early ECG change of hyperkalemia.","B":"Correct. Calcium gluconate stabilizes the cardiac membrane against dysrhythmia.","C":"Correct. Insulin (with dextrose) temporarily drives potassium into cells.","D":"Correct. These remove potassium from the body.","E":"Incorrect. These are high-potassium foods and would worsen hyperkalemia.","F":"Incorrect. Potassium-sparing diuretics raise potassium further."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Fluid and electrolyte imbalance', 'Hyperkalemia', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_367015', 'SATA', 'A nurse is monitoring a mechanically ventilated client with acute respiratory distress syndrome (ARDS). Which findings are consistent with worsening ARDS? Select all that apply.', 'ARDS features refractory hypoxemia, low compliance, bilateral infiltrates, and a falling P/F ratio with normal wedge pressure (non-cardiogenic edema).', '{"options":[{"id":"A","text":"Refractory hypoxemia not improving with increased FiO2"},{"id":"B","text":"Decreasing lung compliance requiring higher ventilator pressures"},{"id":"C","text":"Bilateral diffuse infiltrates on chest x-ray"},{"id":"D","text":"A decreasing PaO2/FiO2 ratio"},{"id":"E","text":"Elevated pulmonary capillary wedge pressure above 18 mmHg"},{"id":"F","text":"Improved oxygen saturation with each increase in FiO2"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Refractory hypoxemia is a hallmark of ARDS.","B":"Correct. Stiff, non-compliant lungs are characteristic of ARDS.","C":"Correct. Bilateral ''white-out'' infiltrates are a diagnostic feature.","D":"Correct. A falling P/F ratio reflects worsening oxygenation impairment.","E":"Incorrect. ARDS is non-cardiogenic; wedge pressure is normal or low (< 18 mmHg).","F":"Incorrect. Responsiveness to oxygen argues against ARDS."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Acute respiratory distress syndrome', 'Impaired oxygenation', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_367016', 'SATA', 'A nurse assesses a client on the third day after abdominal surgery. Which findings should prompt the nurse to suspect wound dehiscence or evisceration and act? Select all that apply.', 'Dehiscence/evisceration is heralded by a popping sensation, a gush of serosanguineous drainage, protruding viscera, and signs of deterioration; normal healing and expected pain are not red flags.', '{"options":[{"id":"A","text":"The client reports a sudden ''popping'' or ''giving way'' sensation at the incision"},{"id":"B","text":"A sudden increase in serosanguineous drainage from the incision"},{"id":"C","text":"Visible loops of bowel protruding through the incision"},{"id":"D","text":"Well-approximated wound edges with a healing ridge"},{"id":"E","text":"Mild incisional discomfort relieved by prescribed analgesia"},{"id":"F","text":"Increasing abdominal distention with new tachycardia"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{"A":"Correct. A sudden popping sensation is a classic warning of dehiscence.","B":"Correct. A gush of serosanguineous fluid often precedes dehiscence.","C":"Correct. Protruding viscera indicate evisceration, a surgical emergency.","D":"Incorrect. This indicates normal healing.","E":"Incorrect. Expected postoperative discomfort is not a red flag.","F":"Correct. Distention and tachycardia can accompany dehiscence/impending evisceration and warrant assessment."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Postoperative care', 'Complication recognition', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_367017', 'SATA', 'A client with an acute anterior myocardial infarction is developing cardiogenic shock. Which assessment findings does the nurse expect? Select all that apply.', 'Cardiogenic shock reflects pump failure: low output (cool skin, oliguria, narrow pulse pressure) with backward congestion (crackles, high wedge pressure).', '{"options":[{"id":"A","text":"Cool, clammy, mottled skin"},{"id":"B","text":"Crackles and frothy pink sputum"},{"id":"C","text":"Decreased urine output (< 30 mL/hr)"},{"id":"D","text":"Elevated pulmonary capillary wedge pressure"},{"id":"E","text":"Bounding peripheral pulses with warm skin"},{"id":"F","text":"Widened pulse pressure"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Poor forward output produces peripheral vasoconstriction and cool, mottled skin.","B":"Correct. Pump failure causes pulmonary congestion and edema.","C":"Correct. Reduced renal perfusion lowers urine output.","D":"Correct. Left ventricular failure raises left-sided filling pressures.","E":"Incorrect. This describes a distributive/hyperdynamic state, not cardiogenic shock.","F":"Incorrect. Cardiogenic shock produces a narrowed pulse pressure."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Cardiogenic shock', 'Hemodynamics', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_367018', 'SATA', 'A client with known adrenal insufficiency presents with an acute Addisonian crisis. Which interventions and findings should the nurse anticipate? Select all that apply.', 'Addisonian crisis is treated with IV hydrocortisone and isotonic fluids; expect hyponatremia, hyperkalemia, and hypoglycemia from cortisol/aldosterone deficiency.', '{"options":[{"id":"A","text":"Administering IV hydrocortisone"},{"id":"B","text":"Rapid IV infusion of 0.9% sodium chloride"},{"id":"C","text":"Monitoring for hyperkalemia"},{"id":"D","text":"Monitoring for hypoglycemia"},{"id":"E","text":"Restricting fluids and administering a diuretic"},{"id":"F","text":"Anticipating hypernatremia and hypokalemia"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. IV glucocorticoids are the cornerstone of treating adrenal crisis.","B":"Correct. Volume resuscitation with isotonic saline corrects hypovolemia and hyponatremia.","C":"Correct. Aldosterone deficiency causes potassium retention.","D":"Correct. Cortisol deficiency predisposes to hypoglycemia.","E":"Incorrect. The client is hypovolemic; fluid restriction and diuresis are harmful.","F":"Incorrect. Addisonian crisis causes hyponatremia and hyperkalemia."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Addisonian crisis', 'Adrenal insufficiency', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_367019', 'SATA', 'A nurse is performing suctioning through a client''s tracheostomy. Which actions demonstrate safe technique? Select all that apply.', 'Safe tracheal suctioning: hyperoxygenate, sterile technique, suction only on withdrawal for 10-15 seconds; avoid suction on insertion and routine saline lavage.', '{"options":[{"id":"A","text":"Hyperoxygenate the client before and after suctioning"},{"id":"B","text":"Apply suction only while withdrawing the catheter"},{"id":"C","text":"Limit each suction pass to 10-15 seconds"},{"id":"D","text":"Use sterile technique for the suction catheter"},{"id":"E","text":"Apply continuous suction while inserting the catheter"},{"id":"F","text":"Instill 5-10 mL of normal saline routinely before each pass"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Pre/post oxygenation prevents suction-induced hypoxemia.","B":"Correct. Suction is applied intermittently on withdrawal to limit mucosal trauma.","C":"Correct. Brief passes minimize hypoxia.","D":"Correct. Tracheal suctioning is a sterile procedure.","E":"Incorrect. Applying suction on insertion causes hypoxia and mucosal trauma.","F":"Incorrect. Routine saline instillation is not recommended and can worsen oxygenation."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Tracheostomy suctioning', 'Pulmonary hygiene', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_367020', 'SELECT_N', 'A client with sepsis is developing disseminated intravascular coagulation (DIC). Which 3 laboratory findings support this diagnosis?', 'DIC consumes clotting factors and platelets while activating fibrinolysis: elevated D-dimer, low platelets, low fibrinogen, and prolonged PT/aPTT.', '{"options":[{"id":"A","text":"Elevated D-dimer"},{"id":"B","text":"Decreased platelet count"},{"id":"C","text":"Decreased fibrinogen level"},{"id":"D","text":"Shortened prothrombin time (PT)"},{"id":"E","text":"Elevated platelet count"},{"id":"F","text":"Decreased D-dimer"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. D-dimer rises with the widespread fibrinolysis of DIC.","B":"Correct. Platelets are consumed in microthrombi, causing thrombocytopenia.","C":"Correct. Fibrinogen is consumed during widespread clotting.","D":"Incorrect. PT is prolonged in DIC, not shortened.","E":"Incorrect. Platelets are decreased in DIC.","F":"Incorrect. D-dimer is elevated in DIC."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Disseminated intravascular coagulation', 'Hemostasis', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_367021', 'TF', 'Continuous bubbling in the water-seal chamber of a chest drainage system on the fourth postoperative day is an expected finding that requires no further assessment.', 'Continuous bubbling in the water-seal chamber indicates an air leak in the system or the client and requires investigation, not reassurance.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', 'Air leak assessment', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_367022', 'MATRIX', 'For each arterial blood gas result, click to classify the primary acid-base disturbance.', 'Low pH with high PaCO2 is respiratory acidosis; low pH with low HCO3 is metabolic acidosis; high pH with low PaCO2 is respiratory alkalosis.', '{"row_label":"Arterial blood gas","rows":[{"id":"r1","text":"pH 7.28, PaCO2 58 mmHg, HCO3 24 mEq/L"},{"id":"r2","text":"pH 7.30, PaCO2 34 mmHg, HCO3 16 mEq/L"},{"id":"r3","text":"pH 7.50, PaCO2 28 mmHg, HCO3 23 mEq/L"},{"id":"r4","text":"pH 7.22, PaCO2 38 mmHg, HCO3 15 mEq/L"}],"columns":[{"id":"c1","text":"Respiratory acidosis"},{"id":"c2","text":"Metabolic acidosis"},{"id":"c3","text":"Respiratory alkalosis"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Acid-base imbalance', 'ABG interpretation', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_367023', 'MATRIX_MR', 'For each assessment finding, select every type of shock in which it is a characteristic feature (a finding may apply to more than one).', 'All shock states share tachycardia/hypotension and rising lactate; early warm skin is distributive, JVD/congestion is cardiogenic, and low CVP is hypovolemic.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Tachycardia with hypotension"},{"id":"r2","text":"Warm, flushed skin in the early phase"},{"id":"r3","text":"Jugular venous distention and pulmonary congestion"},{"id":"r4","text":"Low central venous pressure from volume loss"},{"id":"r5","text":"Elevated serum lactate from hypoperfusion"}],"columns":[{"id":"c1","text":"Hypovolemic"},{"id":"c2","text":"Cardiogenic"},{"id":"c3","text":"Distributive (septic)"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c3"],"r3":["c2"],"r4":["c1"],"r5":["c1","c2","c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Shock stages', 'Complication recognition', 'Hard', 'Analyze', '{}', 9, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_367024', 'CLOZE', 'A client with a small-cell lung cancer has a serum sodium of 118 mEq/L, low serum osmolality, and concentrated urine. The nurse recognizes this as {1}, and the priority intervention is {2}.', 'SIADH causes dilutional hyponatremia with low serum and high urine osmolality; the primary treatment is fluid restriction.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"syndrome of inappropriate antidiuretic hormone (SIADH)"},{"id":"c2","text":"diabetes insipidus"},{"id":"c3","text":"hyperosmolar hyperglycemic state"}]},{"id":"b2","choices":[{"id":"c1","text":"fluid restriction"},{"id":"c2","text":"administering IV hypotonic fluids"},{"id":"c3","text":"encouraging free water intake"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'SIADH', 'Fluid and electrolyte imbalance', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_367025', 'HIGHLIGHT', 'A nurse assesses a client after central line placement. Highlight the findings that indicate a developing tension pneumothorax. The client is [[increasingly short of breath]]. Trachea is [[deviated to the left]]. Breath sounds are [[absent on the right]]. Skin is [[warm and dry]]. There is [[jugular venous distention]]. Capillary refill is [[less than 2 seconds]]. Blood pressure is [[falling to 84/50]].', 'Tension pneumothorax produces dyspnea, tracheal deviation away from the affected side, absent breath sounds, JVD, and hypotension; normal skin and refill are not red flags.', '{"chunks":[{"id":"h1","text":"increasingly short of breath"},{"id":"h2","text":"deviated to the left"},{"id":"h3","text":"absent on the right"},{"id":"h4","text":"warm and dry"},{"id":"h5","text":"jugular venous distention"},{"id":"h6","text":"less than 2 seconds"},{"id":"h7","text":"falling to 84/50"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h5","h7"],"feedback":{"h1":"Worsening dyspnea is an early sign of tension pneumothorax.","h2":"Tracheal deviation away from the affected side is a hallmark.","h3":"Absent breath sounds on the affected side indicate collapse.","h4":"Warm, dry skin is a normal finding, not a sign of tension pneumothorax.","h5":"Rising intrathoracic pressure impedes venous return, causing JVD.","h6":"Normal capillary refill is not a sign of decompensation.","h7":"Obstructive shock from reduced venous return causes hypotension."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Tension pneumothorax', 'Emergency recognition', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_367026', 'BOWTIE', 'A client develops stridor, hypotension, and diffuse urticaria minutes after an IV antibiotic. Complete the diagram by selecting the condition, the priority actions, and the parameters to monitor.', 'Anaphylaxis is treated by stopping the trigger and giving IM epinephrine, while monitoring airway/oxygenation and blood pressure for the distributive shock and airway compromise.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer IM epinephrine"},{"id":"lt2","text":"Stop the antibiotic infusion"},{"id":"lt3","text":"Administer a beta-blocker"},{"id":"lt4","text":"Place the client in Trendelenburg only and observe"},{"id":"lt5","text":"Restrict IV fluids"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Anaphylactic (distributive) shock"},{"id":"ct2","text":"Cardiogenic shock"},{"id":"ct3","text":"Hypovolemic shock"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Airway patency and oxygen saturation"},{"id":"rt2","text":"Blood pressure"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Serum amylase"},{"id":"rt5","text":"Bladder pressure"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Anaphylactic shock', 'Emergency care', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_367027', 'DRAG_CLOZE', 'A nurse caring for a client on peritoneal dialysis notes cloudy effluent, abdominal pain, and fever. The nurse recognizes this as [1] and anticipates obtaining [2] of the effluent.', 'Cloudy effluent with abdominal pain and fever indicates peritonitis; effluent is sent for cell count, Gram stain, and culture to guide antibiotics.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"peritonitis"},{"id":"t2","text":"a culture"},{"id":"t3","text":"hypoglycemia"},{"id":"t4","text":"a chest x-ray"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Peritoneal dialysis', 'Complication recognition', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_367028', 'DRAG_ORDER', 'A client with a central venous catheter suddenly develops dyspnea, hypotension, and a churning heart murmur, and the nurse suspects an air embolism. Place the nurse''s actions in the correct priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Clamp the central catheter"},{"id":"t2","text":"Position the client on the left side in Trendelenburg"},{"id":"t3","text":"Administer high-flow oxygen"},{"id":"t4","text":"Notify the provider and rapid response"},{"id":"t5","text":"Document the event"},{"id":"t6","text":"Offer the client oral fluids"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Emergency care procedures', 'Air embolism response', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368001', 'MCQ', 'A nurse caring for a client with a chest tube for a pneumothorax observes continuous vigorous bubbling in the water-seal chamber that was not present an hour ago. Which action should the nurse take FIRST?', 'New continuous water-seal bubbling indicates an air leak; the nurse first inspects the system for a correctable cause before escalating.', '{"options":[{"id":"A","text":"Assess the tubing and connections for an air leak"},{"id":"B","text":"Clamp the chest tube near the insertion site"},{"id":"C","text":"Notify the provider immediately"},{"id":"D","text":"Increase the wall suction pressure"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. New continuous bubbling in the water-seal chamber signals an air leak; check the system before other actions.","B":"Incorrect. Clamping can cause a tension pneumothorax.","C":"Incorrect. First assess the system; a loose connection is easily corrected.","D":"Incorrect. This does not address the leak and can worsen it."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tubes', 'Drainage system', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368002', 'MCQ', 'A mechanically ventilated client suddenly triggers the high-pressure alarm, becomes agitated, and the SpO2 falls to 86%. Auscultation reveals diminished breath sounds and the client is biting the tube. Which is the priority nursing action?', 'A high-pressure alarm with desaturation points to obstruction (secretions, biting); clearing the airway is the priority.', '{"options":[{"id":"A","text":"Suction the airway and insert a bite block"},{"id":"B","text":"Increase the set tidal volume"},{"id":"C","text":"Silence the alarm and reassess in 5 minutes"},{"id":"D","text":"Administer a scheduled bronchodilator"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Secretions and biting increase airway resistance; clearing the airway and preventing biting restores ventilation.","B":"Incorrect. This raises pressures further and does not treat the obstruction.","C":"Incorrect. Silencing without acting risks hypoxic injury.","D":"Incorrect. Not the immediate cause of the acute obstruction."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Mechanical ventilation', 'High-pressure alarm', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368003', 'MCQ', 'During the first hemodialysis treatment for a client with newly diagnosed end-stage renal disease, the client develops a headache, nausea, restlessness, and confusion. Which complication should the nurse suspect?', 'Disequilibrium syndrome from rapid urea clearance during early dialysis produces cerebral edema with headache, nausea, and confusion.', '{"options":[{"id":"A","text":"Dialysis disequilibrium syndrome"},{"id":"B","text":"Air embolism"},{"id":"C","text":"Hypervolemia"},{"id":"D","text":"Hyperkalemia"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Rapid solute shifts during initial dialysis cause cerebral edema and neurologic symptoms.","B":"Incorrect. Air embolism causes acute dyspnea, chest pain, and cyanosis.","C":"Incorrect. Dialysis removes fluid; symptoms here reflect osmotic shifts.","D":"Incorrect. Dialysis lowers potassium; symptoms are neurologic, not cardiac."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Hemodialysis', 'Disequilibrium syndrome', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368004', 'MCQ', 'A client with suspected sepsis has received a 30 mL/kg crystalloid bolus. After the bolus: BP 82/48 mmHg, HR 122, lactate rising from 3.2 to 4.5 mmol/L, urine output 10 mL/hr. Which finding most strongly indicates the client needs vasopressor support now?', 'Septic shock is defined by hypotension and hyperlactatemia persisting after adequate fluids, indicating a need for vasopressors.', '{"options":[{"id":"A","text":"Persistent hypotension with a rising lactate despite adequate fluid resuscitation"},{"id":"B","text":"Heart rate of 122 beats per minute"},{"id":"C","text":"Urine output of 10 mL/hr"},{"id":"D","text":"The volume of fluid already administered"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Fluid-refractory hypotension with rising lactate defines septic shock requiring vasopressors.","B":"Incorrect. Tachycardia alone is nonspecific.","C":"Incorrect. Oliguria is concerning but reflects the same hypoperfusion, not the trigger alone.","D":"Incorrect. The volume itself is appropriate initial therapy."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Sepsis', 'Lactate/perfusion', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368005', 'MCQ', 'A client in diabetic ketoacidosis is receiving an insulin infusion and IV fluids. Initial potassium was 5.2 mEq/L; a repeat level is now 3.3 mEq/L. The provider has been notified. Which prescription should the nurse anticipate?', 'Insulin shifts potassium into cells during DKA treatment; falling potassium requires replacement to prevent lethal hypokalemia.', '{"options":[{"id":"A","text":"Add potassium to the IV fluids and continue the insulin infusion"},{"id":"B","text":"Stop the insulin infusion permanently"},{"id":"C","text":"Administer IV sodium bicarbonate"},{"id":"D","text":"Give a bolus of regular insulin"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Insulin drives potassium intracellularly; replacement is needed while insulin continues.","B":"Incorrect. Insulin is needed to resolve ketoacidosis; it is only held transiently if K+ is critically low.","C":"Incorrect. Bicarbonate would worsen hypokalemia.","D":"Incorrect. This further lowers potassium."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Diabetic ketoacidosis', 'Potassium during treatment', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368006', 'MCQ', 'A client with a traumatic brain injury shows: BP 178/62 mmHg, HR 52, irregular respirations, and a widening pulse pressure. Which is the nurse''s priority interpretation and action?', 'The Cushing triad signals impending brain herniation from severely elevated ICP and requires immediate escalation.', '{"options":[{"id":"A","text":"These signs indicate rising intracranial pressure; notify the provider urgently"},{"id":"B","text":"These signs indicate hypovolemic shock; give a fluid bolus"},{"id":"C","text":"These are expected findings; continue routine monitoring"},{"id":"D","text":"Administer a beta-blocker for the hypertension"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cushing triad (hypertension with widening pulse pressure, bradycardia, irregular respirations) is a late sign of dangerously high ICP.","B":"Incorrect. Shock causes hypotension and tachycardia.","C":"Incorrect. Cushing triad is an emergency.","D":"Incorrect. Lowering BP may reduce cerebral perfusion pressure."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Neurological', 'Increased ICP', 'Cushing triad', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368007', 'MCQ', 'On postoperative day 2, a nurse assesses a new colostomy and finds the stoma is dusky purple-black and dry. What is the nurse''s priority action?', 'A healthy stoma is beefy red and moist; a dusky, dark, dry stoma signals compromised blood supply and possible necrosis.', '{"options":[{"id":"A","text":"Notify the surgeon immediately"},{"id":"B","text":"Document the expected postoperative appearance"},{"id":"C","text":"Apply a barrier cream to the stoma"},{"id":"D","text":"Increase oral fluid intake"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A dusky or black stoma indicates ischemia/necrosis and requires urgent surgical evaluation.","B":"Incorrect. A healthy stoma is pink-red and moist; dark and dry is abnormal.","C":"Incorrect. This does not address ischemia.","D":"Incorrect. Irrelevant to stoma perfusion."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Ostomy care', 'Stoma assessment', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368008', 'MCQ', 'A client with a temporary transvenous pacemaker set at 70 bpm shows pacer spikes on the monitor that are NOT followed by QRS complexes, and the client''s pulse is 44 and irregular. Which problem does the nurse identify?', 'Failure to capture is pacer spikes not followed by a QRS; the nurse should check output/milliamperes and connections.', '{"options":[{"id":"A","text":"Failure to capture"},{"id":"B","text":"Failure to sense"},{"id":"C","text":"Appropriate pacemaker function"},{"id":"D","text":"Oversensing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Spikes without subsequent QRS complexes indicate the stimulus is not depolarizing the myocardium.","B":"Incorrect. Failure to sense produces spikes that ignore the client''s intrinsic beats.","C":"Incorrect. Each spike should capture and produce a QRS.","D":"Incorrect. Oversensing causes inappropriate pacing inhibition, not uncaptured spikes."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Pacing devices', 'Failure to capture', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368009', 'MCQ', 'A nurse notices that a client''s arterial line waveform has become flattened and the displayed pressure is now much lower than a manual cuff reading. Which action should the nurse take FIRST?', 'A damped arterial waveform with a discrepant cuff pressure is typically a system problem (clot, air, kink, loose connection) and should be troubleshot first.', '{"options":[{"id":"A","text":"Check the line for kinks, air, or a loose connection and assess the flush system"},{"id":"B","text":"Administer a fluid bolus for hypotension"},{"id":"C","text":"Start a vasopressor infusion"},{"id":"D","text":"Remove the arterial catheter"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A damped waveform is usually mechanical; troubleshoot the system before treating a false low pressure.","B":"Incorrect. The cuff shows the pressure is adequate; the arterial reading is artifactual.","C":"Incorrect. Treating an artifactual low pressure could harm the client.","D":"Incorrect. Premature removal is not indicated before troubleshooting."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Arterial line', 'Damped waveform', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368010', 'MCQ', 'A neonate is receiving intensive phototherapy for hyperbilirubinemia. Which finding requires the nurse to intervene immediately?', 'Phototherapy raises the risk of overheating and dehydration; fever with lethargy and poor feeding needs immediate action.', '{"options":[{"id":"A","text":"Temperature 39.1°C with poor feeding and lethargy"},{"id":"B","text":"Loose greenish stools"},{"id":"C","text":"A transient bronze discoloration of the skin"},{"id":"D","text":"Eye shields intact over closed eyes"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Hyperthermia and dehydration with lethargy are complications of phototherapy that require prompt intervention.","B":"Incorrect. Loose stools are an expected effect of bilirubin excretion.","C":"Incorrect. Bronze baby appearance is a benign phototherapy effect.","D":"Incorrect. This is correct protective care."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Pediatrics', 'Hematologic', 'Phototherapy', 'Neonatal hyperbilirubinemia', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368011', 'MCQ', 'Shortly after receiving a volatile anesthetic and succinylcholine, a client develops masseter rigidity, a rapidly rising end-tidal CO2, tachycardia, and a temperature climbing past 40°C. Which medication should the nurse prepare to administer?', 'Malignant hyperthermia is a life-threatening hypermetabolic reaction to anesthetic triggers; dantrolene is the definitive treatment.', '{"options":[{"id":"A","text":"Dantrolene"},{"id":"B","text":"Acetaminophen"},{"id":"C","text":"Labetalol"},{"id":"D","text":"Naloxone"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Dantrolene is the antidote for malignant hyperthermia, halting sustained muscle contraction.","B":"Incorrect. Antipyretics do not treat this hypermetabolic crisis.","C":"Incorrect. A beta-blocker does not address the underlying pathology.","D":"Incorrect. Naloxone reverses opioids, not malignant hyperthermia."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Temperature regulation', 'Malignant hyperthermia', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_368012', 'MCQ', 'A critically ill client on continuous renal replacement therapy (CRRT) develops a mean arterial pressure of 58 mmHg with a net fluid removal rate of 250 mL/hr. Which adjustment should the nurse anticipate?', 'CRRT is chosen for hemodynamic instability precisely because removal rates can be titrated; hypotension is managed by reducing the ultrafiltration rate.', '{"options":[{"id":"A","text":"Reduce the fluid removal (ultrafiltration) rate"},{"id":"B","text":"Increase the fluid removal rate to clear volume faster"},{"id":"C","text":"Discontinue CRRT entirely"},{"id":"D","text":"Clamp the return line for 30 minutes"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Excessive fluid removal causes hypotension; lowering the ultrafiltration rate improves hemodynamics.","B":"Incorrect. This worsens hypotension.","C":"Incorrect. CRRT is generally better tolerated with adjustment rather than abrupt stopping.","D":"Incorrect. Clamping risks clotting the circuit and does not address volume status safely."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'CRRT', 'Hypotension management', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_368013', 'SATA', 'A client with a chest tube suddenly develops severe dyspnea, tracheal deviation to the unaffected side, absent breath sounds on the affected side, and hypotension. Which nursing actions are appropriate? Select all that apply.', 'Tracheal deviation, absent breath sounds, and hypotension indicate a tension pneumothorax, an emergency requiring oxygen, patency checks, escalation, and decompression.', '{"options":[{"id":"A","text":"Notify the provider or rapid response team immediately"},{"id":"B","text":"Ensure the chest drainage tubing is not kinked or clamped"},{"id":"C","text":"Administer high-flow oxygen"},{"id":"D","text":"Prepare for emergency needle decompression"},{"id":"E","text":"Lower the head of the bed flat and leave the client alone to rest"},{"id":"F","text":"Milk and strip the chest tube vigorously to restore drainage"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tubes', 'Tension pneumothorax', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_368014', 'SATA', 'A nurse assesses a client following a large anterior myocardial infarction for signs of cardiogenic shock. Which findings support this diagnosis? Select all that apply.', 'Cardiogenic shock produces low cardiac output: hypotension, poor perfusion, pulmonary congestion, and oliguria.', '{"options":[{"id":"A","text":"Cool, mottled, clammy extremities"},{"id":"B","text":"Systolic blood pressure below 90 mmHg"},{"id":"C","text":"New crackles and an S3 gallop"},{"id":"D","text":"Urine output of 15 mL/hr"},{"id":"E","text":"Bounding peripheral pulses and warm, flushed skin"},{"id":"F","text":"Widened pulse pressure with a slow heart rate"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Cardiogenic shock', 'Assessment', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_368015', 'SATA', 'A client with adrenal insufficiency presents with hypotension, severe weakness, hyperkalemia, hyponatremia, and hypoglycemia consistent with an Addisonian crisis. Which interventions should the nurse anticipate? Select all that apply.', 'Addisonian crisis is treated with glucocorticoid replacement, fluid and sodium restoration, glucose correction, and management of hyperkalemia.', '{"options":[{"id":"A","text":"Administer IV hydrocortisone"},{"id":"B","text":"Infuse IV normal saline for volume replacement"},{"id":"C","text":"Administer IV dextrose for hypoglycemia"},{"id":"D","text":"Treat the hyperkalemia per protocol"},{"id":"E","text":"Restrict all sodium intake"},{"id":"F","text":"Administer insulin to lower blood glucose"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Addisonian crisis', 'Interventions', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_368016', 'SATA', 'On postoperative day 4, a client coughs and reports that the abdominal incision "gave way," with a loop of bowel now protruding through the wound. Which nursing actions are appropriate? Select all that apply.', 'Evisceration is a surgical emergency: cover with saline-moistened sterile dressing, reduce abdominal tension, keep NPO, and notify the surgeon; never reinsert the bowel.', '{"options":[{"id":"A","text":"Cover the wound with sterile gauze moistened with normal saline"},{"id":"B","text":"Place the client in low Fowler position with knees flexed"},{"id":"C","text":"Notify the surgeon immediately"},{"id":"D","text":"Keep the client NPO in anticipation of surgery"},{"id":"E","text":"Attempt to gently push the bowel back into the abdomen"},{"id":"F","text":"Apply dry gauze and firm pressure to the protruding bowel"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Postoperative complications', 'Dehiscence/evisceration', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_368017', 'SATA', 'A client with pancreatitis develops acute respiratory distress syndrome (ARDS). Which findings would the nurse expect? Select all that apply.', 'ARDS causes noncardiogenic pulmonary edema with refractory hypoxemia, bilateral infiltrates, worsening respiratory distress, and stiff lungs.', '{"options":[{"id":"A","text":"Refractory hypoxemia that does not improve with supplemental oxygen"},{"id":"B","text":"Bilateral diffuse infiltrates on chest x-ray"},{"id":"C","text":"Increasing dyspnea and tachypnea"},{"id":"D","text":"Decreased lung compliance (stiff lungs)"},{"id":"E","text":"Jugular venous distension from left-sided heart failure"},{"id":"F","text":"Rapid resolution of hypoxemia with a nonrebreather mask"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'ARDS', 'Recognition', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_368018', 'SATA', 'A client on peritoneal dialysis reports abdominal pain and the nurse notes cloudy effluent and a low-grade fever. Which actions are appropriate? Select all that apply.', 'Cloudy effluent with pain and fever indicates peritonitis; the nurse cultures the effluent, notifies the provider, and anticipates intraperitoneal antibiotics.', '{"options":[{"id":"A","text":"Obtain a sample of the effluent for culture"},{"id":"B","text":"Notify the provider about suspected peritonitis"},{"id":"C","text":"Anticipate adding antibiotics to the dialysate"},{"id":"D","text":"Assess the exit site for redness or drainage"},{"id":"E","text":"Continue exchanges without further assessment since cloudy effluent is normal"},{"id":"F","text":"Discontinue peritoneal dialysis permanently and prepare for transplant"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Peritoneal dialysis', 'Peritonitis', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_368019', 'SELECT_N', 'A client with acute kidney injury has a potassium of 6.9 mEq/L with peaked T waves on the ECG. Which 3 interventions should the nurse anticipate to protect the myocardium and shift potassium intracellularly?', 'Calcium stabilizes the myocardium; insulin/dextrose and beta-agonists shift potassium into cells during emergent hyperkalemia management.', '{"options":[{"id":"A","text":"IV calcium gluconate"},{"id":"B","text":"IV regular insulin with dextrose"},{"id":"C","text":"Nebulized albuterol"},{"id":"D","text":"IV potassium chloride infusion"},{"id":"E","text":"Spironolactone"},{"id":"F","text":"Salt substitute containing potassium"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Fluid and electrolyte imbalance', 'Hyperkalemia', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_368020', 'SELECT_N', 'A nurse performs endotracheal suctioning of an intubated client. Which 4 actions reflect safe, evidence-based technique?', 'Safe suctioning hyperoxygenates, suctions only on withdrawal, limits pass duration, and monitors for hypoxia/dysrhythmias; deep continuous suction and routine saline lavage are avoided.', '{"options":[{"id":"A","text":"Hyperoxygenate the client before and after suctioning"},{"id":"B","text":"Apply suction only while withdrawing the catheter"},{"id":"C","text":"Limit each suction pass to about 10 to 15 seconds"},{"id":"D","text":"Monitor for dysrhythmias and desaturation during the procedure"},{"id":"E","text":"Apply continuous suction while advancing the catheter"},{"id":"F","text":"Instill 10 mL of normal saline routinely before each pass"}],"select_count":4}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Suctioning', 'Safe technique', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_368021', 'TF', 'If a client''s chest tube becomes accidentally disconnected from the drainage system, the nurse should immediately clamp the chest tube with two clamps until a new system is available.', 'The tube should be placed in sterile water to restore a water seal, not clamped; clamping risks a tension pneumothorax.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tubes', 'Accidental disconnection', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_368022', 'MATRIX', 'For each clinical finding, click to indicate whether it is most associated with hyponatremia or hypernatremia.', 'Hyponatremia shifts water into cells causing cerebral edema; hypernatremia pulls water out, causing thirst, dehydration, and neuro irritability.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Cerebral edema with seizures and confusion"},{"id":"r2","text":"Intense thirst with dry, flushed mucous membranes"},{"id":"r3","text":"Muscle cramps with nausea in a marathon runner who over-drank water"},{"id":"r4","text":"Restlessness and agitation from cellular dehydration"}],"columns":[{"id":"c1","text":"Hyponatremia"},{"id":"c2","text":"Hypernatremia"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Fluid and electrolyte imbalance', 'Sodium disorders', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_368023', 'MATRIX_MR', 'For each type of shock, select all hemodynamic features that typically apply (more than one may apply).', 'All shock states produce hypotension; distributive types (early sepsis, neurogenic) cause warm skin, while hypovolemic and cardiogenic cause low output and cool skin.', '{"row_label":"Shock type","rows":[{"id":"r1","text":"Hypovolemic shock"},{"id":"r2","text":"Early (warm) septic shock"},{"id":"r3","text":"Cardiogenic shock"},{"id":"r4","text":"Neurogenic shock"}],"columns":[{"id":"c1","text":"Hypotension"},{"id":"c2","text":"Warm skin early"},{"id":"c3","text":"Low cardiac output"}]}'::jsonb, '{"cells":{"r1":["c1","c3"],"r2":["c1","c2"],"r3":["c1","c3"],"r4":["c1","c2"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Shock', 'Classification', 'Hard', 'Analyze', '{}', 8, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_368024', 'CLOZE', 'A client with a COPD exacerbation has an ABG of pH 7.31, PaCO2 62 mmHg, HCO3 30 mEq/L. The nurse interprets this as {1} that is {2}.', 'Low pH with high PaCO2 is respiratory acidosis; an elevated HCO3 with a still-abnormal pH indicates partial metabolic compensation.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"respiratory acidosis"},{"id":"c2","text":"respiratory alkalosis"},{"id":"c3","text":"metabolic acidosis"}]},{"id":"b2","choices":[{"id":"c1","text":"partially compensated"},{"id":"c2","text":"fully compensated"},{"id":"c3","text":"uncompensated"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Acid-base balance', 'ABG interpretation', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_368025', 'HIGHLIGHT', 'A client returns from a thoracentesis. Highlight the findings that require immediate follow-up. The client is [[resting comfortably]], reports [[sudden sharp chest pain]], has [[diminished breath sounds on the procedure side]], SpO2 [[88% on room air]], respiratory rate [[28]], and a [[dry, intact dressing]].', 'Post-thoracentesis pneumothorax presents with sharp chest pain, diminished breath sounds, hypoxemia, and tachypnea.', '{"chunks":[{"id":"h1","text":"resting comfortably"},{"id":"h2","text":"sudden sharp chest pain"},{"id":"h3","text":"diminished breath sounds on the procedure side"},{"id":"h4","text":"88% on room air"},{"id":"h5","text":"28"},{"id":"h6","text":"dry, intact dressing"}]}'::jsonb, '{"correct_ids":["h2","h3","h4","h5"],"feedback":{"h1":"Reassuring; no follow-up needed.","h2":"May indicate pneumothorax after thoracentesis.","h3":"Suggests pneumothorax.","h4":"Hypoxemia requiring intervention.","h5":"Tachypnea consistent with a respiratory complication.","h6":"Expected; no follow-up needed."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Complication recognition', 'Post-thoracentesis', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_368026', 'BOWTIE', 'A client with Graves disease develops fever 40.2°C, HR 160 atrial fibrillation, agitation, and delirium. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Thyroid storm is a hypermetabolic emergency managed with beta-blockade and cooling, monitoring cardiac rhythm and temperature.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer prescribed beta-blocker"},{"id":"lt2","text":"Initiate active cooling measures"},{"id":"lt3","text":"Administer levothyroxine"},{"id":"lt4","text":"Apply warming blankets"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Thyroid storm"},{"id":"ct2","text":"Myxedema coma"},{"id":"ct3","text":"Diabetic ketoacidosis"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Cardiac rhythm and heart rate"},{"id":"rt2","text":"Core temperature"},{"id":"rt3","text":"Serum amylase"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Thyroid storm', 'Management', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_368027', 'DRAG_CLOZE', 'A client in hypovolemic shock is expected to have a [1] central venous pressure and a [2] systemic vascular resistance as the body compensates.', 'Hypovolemia lowers preload (low CVP) and triggers compensatory vasoconstriction (high SVR).', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"low"},{"id":"t2","text":"high"},{"id":"t3","text":"unchanged"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Hemodynamic monitoring', 'Preload/afterload', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_368028', 'DRAG_ORDER', 'A client''s central venous catheter becomes disconnected and the nurse suspects an air embolism. Place the nurse''s actions in priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Clamp or occlude the catheter to stop further air entry"},{"id":"t2","text":"Position the client on the left side in Trendelenburg"},{"id":"t3","text":"Administer 100% oxygen"},{"id":"t4","text":"Notify the provider and rapid response team"},{"id":"t5","text":"Document the event and response"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Emergency care procedures', 'Air embolism', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355001', 'MCQ', 'A client hospitalized for major depressive disorder says quietly, "I''ve decided everything is finally going to be okay, and I''ve given my guitar to my brother." Which response by the nurse is MOST appropriate?', 'A sudden sense of peace after depression, combined with giving away valued possessions, is a classic cue of suicidal intent requiring direct assessment.', '{"options":[{"id":"A","text":"\"That sounds like you''re feeling more hopeful about the future.\""},{"id":"B","text":"\"Are you thinking about killing yourself, and do you have a plan?\""},{"id":"C","text":"\"It''s good that you''re giving your things to family who will appreciate them.\""},{"id":"D","text":"\"Let''s talk about what has helped your mood improve so much.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Sudden calm plus giving away possessions is a warning sign, not reassurance to accept at face value.","B":"Correct. A sudden mood lift with giving away belongings suggests suicidal intent; direct assessment of ideation and plan is the priority.","C":"Incorrect. This normalizes a possible cue of suicidal planning.","D":"Incorrect. This misses the danger cue and delays safety assessment."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', 'Depression', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355002', 'MCQ', 'A client admitted 48 hours ago after abruptly stopping heavy daily alcohol use is now disoriented, sees insects on the wall, has a temperature of 38.6°C, BP 178/104, and tremors. Which understanding should MOST guide the nurse''s priority?', 'Delirium tremens presents 48-72 hours after cessation with autonomic hyperactivity, fever, confusion, and hallucinations, and carries significant mortality.', '{"options":[{"id":"A","text":"These are expected anxiety symptoms that will resolve with reassurance"},{"id":"B","text":"This presentation reflects delirium tremens, a medical emergency with mortality risk"},{"id":"C","text":"The hallucinations indicate an underlying primary psychotic disorder"},{"id":"D","text":"The client is seeking attention and should be redirected to group"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This underestimates a life-threatening emergency.","B":"Correct. Autonomic instability, fever, disorientation, and hallucinations 48-72h after cessation indicate delirium tremens, which can be fatal.","C":"Incorrect. The timing and autonomic signs point to withdrawal, not primary psychosis.","D":"Incorrect. Dismissing physiologic withdrawal risks death."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Substance withdrawal', 'Alcohol withdrawal', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355003', 'MCQ', 'A client in an acute manic episode is loud, intrusive, and moving quickly between other clients in the day room, escalating the group. Which nursing action should the nurse take FIRST?', 'Reducing stimulation and setting calm, firm limits is the least restrictive effective intervention for acute mania.', '{"options":[{"id":"A","text":"Set firm limits and calmly escort the client to a low-stimulation area"},{"id":"B","text":"Confront the client about the disruptive behavior in front of the group"},{"id":"C","text":"Encourage the client to channel energy into a competitive group game"},{"id":"D","text":"Place the client in seclusion immediately"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Reducing environmental stimulation while setting clear limits protects the client and others without confrontation.","B":"Incorrect. Public confrontation can escalate a manic client.","C":"Incorrect. Stimulating activities worsen mania.","D":"Incorrect. Seclusion is a last resort after less restrictive measures fail."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Bipolar disorder', 'Acute mania', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355004', 'MCQ', 'A client with schizophrenia says, "The voices are telling me the other patients are demons who must be stopped." Which nursing response is the priority?', 'Command hallucinations to harm others are a safety emergency; the nurse must acknowledge the experience and directly assess the command''s content and imminent risk.', '{"options":[{"id":"A","text":"\"Those voices aren''t real; the other patients are not demons.\""},{"id":"B","text":"\"I know the voices are frightening. Are they telling you to hurt anyone right now?\""},{"id":"C","text":"\"Try to ignore the voices and join the activity group.\""},{"id":"D","text":"\"What do you think the demons want you to do about them?\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Arguing about reality is nontherapeutic and misses the safety threat.","B":"Correct. Command hallucinations directing harm require immediate assessment of the content and risk to others.","C":"Incorrect. This dismisses a potential command to harm others.","D":"Incorrect. This reinforces the delusion rather than assessing command content directly."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Schizophrenia', 'Command hallucinations', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355005', 'MCQ', 'A client in the emergency department is pacing, hyperventilating, unable to focus on questions, and says "I can''t breathe, I''m going to die." Physical workup is unremarkable. Which nursing approach is MOST appropriate?', 'At panic-level anxiety the perceptual field is greatly reduced; the nurse stays present, uses simple directions, and helps reduce physiologic arousal before any teaching.', '{"options":[{"id":"A","text":"Provide detailed discharge teaching about anxiety triggers now"},{"id":"B","text":"Stay with the client, speak in short simple sentences, and guide slow breathing"},{"id":"C","text":"Leave the client alone in a quiet room to calm down independently"},{"id":"D","text":"Explore the childhood origins of the client''s anxiety"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. A client in panic-level anxiety cannot process complex teaching.","B":"Correct. During panic-level anxiety, perceptual field is severely narrowed; a calm presence and simple direction are most effective.","C":"Incorrect. Leaving a panicking client alone increases fear and risk.","D":"Incorrect. Insight work is inappropriate during acute panic."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety', 'Panic-level anxiety', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355006', 'MCQ', 'During triage a woman with a facial bruise says she "walked into a door," while her partner answers all questions for her and refuses to leave the room. Which nursing action is the priority?', 'A controlling partner who won''t leave and an inconsistent injury story are red flags; the nurse must interview the client privately to enable disclosure and safety planning.', '{"options":[{"id":"A","text":"Document that the injury is consistent with an accidental fall"},{"id":"B","text":"Find a reason to interview the client privately, away from the partner"},{"id":"C","text":"Directly ask the partner whether he caused the injury"},{"id":"D","text":"Report the couple to police before assessing the client"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. The nurse should not accept the explanation uncritically given red flags.","B":"Correct. Separating the client from the potential abuser allows safe, honest disclosure and assessment.","C":"Incorrect. Confronting the suspected abuser can increase danger to the client.","D":"Incorrect. Adult IPV reporting depends on the client''s wishes; private assessment comes first."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Abuse and neglect', 'Intimate partner violence', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355007', 'MCQ', 'An older client with moderate dementia becomes increasingly agitated, confused, and restless each evening. Which intervention should the nurse implement FIRST to manage sundowning?', 'Environmental modification with adequate lighting and reduced stimulation is the first-line, least restrictive approach to sundowning.', '{"options":[{"id":"A","text":"Request a PRN antipsychotic to sedate the client each evening"},{"id":"B","text":"Increase evening lighting and reduce noise and environmental stimulation"},{"id":"C","text":"Introduce a new engaging group activity in the evening"},{"id":"D","text":"Encourage a long afternoon nap so the client is less tired"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Sedation is not first-line and increases fall and delirium risk.","B":"Correct. Adequate lighting and a calm, consistent, low-stimulus environment reduce evening confusion and agitation.","C":"Incorrect. New stimulation typically worsens sundowning.","D":"Incorrect. Long daytime naps disrupt sleep-wake cycles and can worsen sundowning."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Medical-Surgical', 'Neurological', 'Dementia', 'Sundowning', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355008', 'MCQ', 'A client with anorexia nervosa is admitted at 68% of ideal body weight and begins refeeding. On day 3 the nurse notes new confusion, weakness, and a serum phosphate of 1.2 mg/dL. Which action is the priority?', 'Refeeding syndrome causes hypophosphatemia with neuromuscular and cardiac dysfunction; feeds are slowed and electrolytes corrected urgently.', '{"options":[{"id":"A","text":"Encourage the client to eat more to correct the weakness"},{"id":"B","text":"Hold the current feeding rate and notify the provider of refeeding syndrome"},{"id":"C","text":"Attribute the confusion to the client''s body-image distortion"},{"id":"D","text":"Document the findings and reassess in the morning"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Increasing intake without correcting electrolytes worsens refeeding syndrome.","B":"Correct. Hypophosphatemia with neuromuscular symptoms during refeeding signals refeeding syndrome, which can be fatal and requires slowing feeds and electrolyte correction.","C":"Incorrect. This ignores a dangerous metabolic emergency.","D":"Incorrect. Refeeding syndrome requires immediate intervention."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Eating disorders', 'Anorexia nervosa', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355009', 'MCQ', 'A client with borderline personality disorder tells the nurse, "You''re the only one who really understands me; the other nurses are cruel and incompetent." Which response best supports the therapeutic milieu?', 'Clients who split staff into all-good and all-bad are managed by a consistent team approach and clear, uniform boundaries.', '{"options":[{"id":"A","text":"\"Thank you. I''ll make sure I''m the one assigned to you each shift.\""},{"id":"B","text":"\"The staff work as a team, and we all care about your progress.\""},{"id":"C","text":"\"Which nurses have been cruel so I can report them?\""},{"id":"D","text":"\"You shouldn''t say negative things about your other nurses.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This reinforces splitting and special relationships.","B":"Correct. Presenting a consistent, united team counters splitting and maintains healthy boundaries.","C":"Incorrect. This validates the splitting and undermines the team.","D":"Incorrect. This is judgmental and does not address the dynamic therapeutically."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic milieu', 'Manipulative behavior', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355010', 'MCQ', 'A dying client''s family from a culture that values collective decision-making asks that the client not be told the terminal prognosis so the family can decide together. The client is alert and has not asked about the diagnosis. Which nursing action is MOST appropriate?', 'Culturally competent care assesses the client''s own preferences about receiving information and involving family rather than imposing a single model of autonomy.', '{"options":[{"id":"A","text":"Immediately tell the client the prognosis to honor autonomy"},{"id":"B","text":"Explore with the client how much information they wish to receive and who they want involved"},{"id":"C","text":"Agree to withhold all information from the client permanently"},{"id":"D","text":"Refer the entire matter to the ethics committee before speaking to anyone"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Forcing disclosure disregards the client''s cultural values and may not reflect the client''s wishes.","B":"Correct. Assessing the client''s own preferences for information and family involvement respects both autonomy and cultural context.","C":"Incorrect. The nurse cannot promise indefinite nondisclosure without the client''s input.","D":"Incorrect. Direct, culturally sensitive assessment of the client''s wishes comes first."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Medical-Surgical', 'Multisystem', 'End-of-life care', 'Cultural care', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355011', 'MCQ', 'Fourteen months after her spouse''s death, a client remains unable to work, keeps the bedroom exactly as it was, sets a place for her spouse at meals, and says life stopped that day. Which interpretation should guide the nurse''s plan of care?', 'Grief that remains intense and functionally disabling well beyond expected timeframes, with an inability to accept the loss, characterizes complicated grief and warrants referral.', '{"options":[{"id":"A","text":"This is normal grief that requires only continued reassurance"},{"id":"B","text":"This suggests complicated (prolonged) grief warranting referral for focused therapy"},{"id":"C","text":"This indicates the client has reached acceptance in the grief process"},{"id":"D","text":"This is denial that should be confronted directly to force acceptance"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Persistent, disabling grief beyond a year with impaired functioning exceeds normal grieving.","B":"Correct. Intense, functionally impairing grief persisting well beyond expected timeframes indicates complicated grief needing specialized intervention.","C":"Incorrect. Maintaining the deceased''s presence and stalled functioning is not acceptance.","D":"Incorrect. Confrontation is not therapeutic; referral for grief-focused therapy is indicated."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Grief and loss', 'Complicated grief', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_355012', 'MCQ', 'A client is standing rigidly with clenched fists, jaw set, and speaking in a low, controlled tone while pacing near the nurses'' station. Which nursing action is MOST appropriate at this point?', 'Clenched fists, rigid posture, and pacing signal impending aggression; safe de-escalation uses calm tone, personal space, and maintained exit routes.', '{"options":[{"id":"A","text":"Move close and place a reassuring hand on the client''s shoulder"},{"id":"B","text":"Maintain a calm voice, keep a safe distance, and ensure a clear exit for both"},{"id":"C","text":"Firmly order the client to sit down and stop pacing immediately"},{"id":"D","text":"Ignore the behavior to avoid reinforcing it"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Touch and invading space during escalation can trigger aggression.","B":"Correct. During pre-assault escalation the nurse uses a calm approach, respects personal space, and preserves escape routes for safety.","C":"Incorrect. Authoritarian commands can escalate an agitated client.","D":"Incorrect. Escalating cues require active, calm de-escalation, not being ignored."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'De-escalation', 'Violence potential', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_355013', 'SATA', 'A nurse assesses a client for suicide risk. Which findings increase the client''s risk and warrant heightened precautions? Select all that apply.', 'A lethal accessible plan, giving away possessions, prior attempts, and sudden unexplained calm all elevate suicide risk; connectedness and future orientation are protective.', '{"options":[{"id":"A","text":"A specific, detailed plan with access to a firearm"},{"id":"B","text":"Recent giving away of prized possessions"},{"id":"C","text":"A prior suicide attempt within the last year"},{"id":"D","text":"Sudden calmness after a period of severe depression"},{"id":"E","text":"Strong future-oriented plans and a supportive family present daily"},{"id":"F","text":"Active engagement in a new hobby the client finds meaningful"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk', 'Risk factors', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_355014', 'SATA', 'A nurse is interviewing a newly admitted client who is anxious and withdrawn. Which statements by the nurse reflect therapeutic communication techniques? Select all that apply.', 'Broad openings, offering self, and restating/validating are therapeutic; asking ''why'', false reassurance, and giving advice are barriers to communication.', '{"options":[{"id":"A","text":"\"You seem tense. Tell me more about what''s on your mind.\""},{"id":"B","text":"\"I''ll sit here with you for a while.\""},{"id":"C","text":"\"What I hear you saying is that you feel unsafe at home. Is that right?\""},{"id":"D","text":"\"Why did you wait so long to come in for help?\""},{"id":"E","text":"\"Don''t worry, everything will be just fine.\""},{"id":"F","text":"\"If I were you, I would leave that relationship.\""}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', 'Techniques', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_355015', 'SATA', 'A nurse monitors a client 24 hours after the last drink of alcohol. Which findings are consistent with early alcohol withdrawal? Select all that apply.', 'Early alcohol withdrawal produces autonomic hyperactivity: tremor, tachycardia, hypertension, diaphoresis, and anxiety; bradycardia and pinpoint pupils suggest opioid effects instead.', '{"options":[{"id":"A","text":"Tremors of the hands"},{"id":"B","text":"Tachycardia and elevated blood pressure"},{"id":"C","text":"Diaphoresis"},{"id":"D","text":"Anxiety and irritability"},{"id":"E","text":"Bradycardia and hypotension"},{"id":"F","text":"Constricted, pinpoint pupils"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Alcohol withdrawal', 'Assessment', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_355016', 'SATA', 'A home health nurse assesses an older adult cared for by an adult child. Which findings raise concern for elder mistreatment? Select all that apply.', 'Patterned injuries, a controlling caregiver, neglect with untreated wounds and dehydration, and financial exploitation are markers of elder mistreatment.', '{"options":[{"id":"A","text":"Multiple bruises in various stages of healing on the upper arms"},{"id":"B","text":"The caregiver answers all questions and won''t let the client speak"},{"id":"C","text":"Untreated pressure injuries and evidence of dehydration"},{"id":"D","text":"The client''s pension is spent while bills go unpaid"},{"id":"E","text":"The client has a well-organized weekly medication planner"},{"id":"F","text":"The client attends a senior social group twice a week"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Abuse and neglect', 'Elder abuse', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_355017', 'SATA', 'A client recovering from a stroke that caused permanent left-sided weakness is adjusting to disability. Which client statements indicate adaptive coping? Select all that apply.', 'Seeking rehabilitation, building new self-care skills, and communicating with support systems reflect adaptive coping; hopelessness, withdrawal, and substance use are maladaptive.', '{"options":[{"id":"A","text":"\"I''ve signed up for the outpatient rehab program next week.\""},{"id":"B","text":"\"I''m learning to dress myself using the techniques therapy taught me.\""},{"id":"C","text":"\"My family and I are talking openly about how to reorganize the house.\""},{"id":"D","text":"\"There''s no point in trying; I''ll never be useful again.\""},{"id":"E","text":"\"I''ve stopped answering calls from my friends.\""},{"id":"F","text":"\"I have a few drinks every night now so I don''t have to think about it.\""}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Coping with life changes', 'Adaptive coping', 'Hard', 'Evaluate', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_355018', 'SATA', 'A nurse reviews a client with schizophrenia. Which findings are negative symptoms of the disorder? Select all that apply.', 'Negative symptoms are deficits: flat affect, avolition, alogia, and anhedonia; hallucinations and delusions are positive symptoms.', '{"options":[{"id":"A","text":"Flat affect"},{"id":"B","text":"Avolition (lack of motivation)"},{"id":"C","text":"Alogia (poverty of speech)"},{"id":"D","text":"Anhedonia (inability to feel pleasure)"},{"id":"E","text":"Auditory hallucinations"},{"id":"F","text":"Delusions of persecution"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Schizophrenia', 'Negative symptoms', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_355019', 'SELECT_N', 'A client on an inpatient unit is escalating toward possible aggression. Which 3 actions should the nurse prioritize to maintain safety?', 'Safety with an escalating client requires visible staff support, removing potential weapons, and maintaining access to an exit; approaching alone, touching, and crowding increase danger.', '{"options":[{"id":"A","text":"Ensure adequate staff are visibly available before approaching"},{"id":"B","text":"Remove objects that could be used as weapons from the area"},{"id":"C","text":"Position self between the client and an unobstructed exit"},{"id":"D","text":"Approach alone to build a trusting one-to-one connection"},{"id":"E","text":"Touch the client''s arm to convey calm reassurance"},{"id":"F","text":"Stand directly in front of and very close to the client"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Violence potential', 'Safety precautions', 'Hard', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_355020', 'TF', 'Directly asking a depressed client whether they are thinking about suicide will plant the idea and increase the likelihood that they will attempt it.', 'Directly and openly asking about suicidal ideation does not increase risk; it allows accurate assessment and demonstrates concern.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide assessment', 'Myths', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_355021', 'MATRIX', 'For each nurse statement, click to indicate whether it is a therapeutic technique or a communication barrier.', 'General leads, exploring, and reflecting are therapeutic; false reassurance and ''why'' questions are barriers.', '{"row_label":"Statement","rows":[{"id":"r1","text":"\"Go on, I''m listening.\""},{"id":"r2","text":"\"Everyone feels that way sometimes; don''t worry.\""},{"id":"r3","text":"\"You mentioned feeling alone. Tell me more about that.\""},{"id":"r4","text":"\"Why would you do something like that?\""},{"id":"r5","text":"\"It sounds like you''re feeling overwhelmed right now.\""}],"columns":[{"id":"c1","text":"Therapeutic technique"},{"id":"c2","text":"Communication barrier"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', 'Techniques vs barriers', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_355022', 'MATRIX_MR', 'For each client behavior, select all defense mechanisms that could reasonably be represented (some behaviors reflect more than one).', 'Denial rejects reality, projection attributes one''s own feelings to others, and displacement transfers feelings to a safer target.', '{"row_label":"Finding","rows":[{"id":"r1","text":"A man with a new terminal diagnosis insists the labs must be someone else''s"},{"id":"r2","text":"A woman angry at her boss comes home and yells at her children"},{"id":"r3","text":"A client who is attracted to a coworker accuses the coworker of flirting with everyone"},{"id":"r4","text":"A client denying an alcohol problem blames coworkers for ''making'' him drink"}],"columns":[{"id":"c1","text":"Denial"},{"id":"c2","text":"Projection"},{"id":"c3","text":"Displacement"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c3"],"r3":["c2"],"r4":["c1","c2"]},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Defense mechanisms', 'Identification', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_355023', 'CLOZE', 'A client is found unresponsive with a respiratory rate of 6 and pinpoint pupils. The nurse recognizes this as {1} and anticipates administering {2}.', 'Respiratory depression with pinpoint pupils indicates opioid overdose, reversed with the opioid antagonist naloxone.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"opioid overdose"},{"id":"c2","text":"stimulant intoxication"},{"id":"c3","text":"alcohol withdrawal"}]},{"id":"b2","choices":[{"id":"c1","text":"naloxone"},{"id":"c2","text":"flumazenil"},{"id":"c3","text":"lorazepam"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Substance toxicity', 'Opioid overdose', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_355024', 'HIGHLIGHT', 'Highlight the statements in the nurse''s note that indicate increased suicide risk. Client reports [[I finally have a plan to end all of this]]. States [[I gave my necklace to my sister yesterday]]. Reports [[sleeping better the past two nights]]. Denies current appetite changes. States [[there''s a rifle at home I''ve been thinking about]]. Reports [[looking forward to my granddaughter''s graduation next year]].', 'A plan, giving away possessions, and access to lethal means indicate elevated suicide risk; improved sleep and future orientation are not warning signs.', '{"chunks":[{"id":"h1","text":"I finally have a plan to end all of this"},{"id":"h2","text":"I gave my necklace to my sister yesterday"},{"id":"h3","text":"sleeping better the past two nights"},{"id":"h4","text":"there''s a rifle at home I''ve been thinking about"},{"id":"h5","text":"looking forward to my granddaughter''s graduation next year"}]}'::jsonb, '{"correct_ids":["h1","h2","h4"],"feedback":{"h1":"A specific plan is a major risk factor.","h2":"Giving away possessions is a warning sign.","h3":"Improved sleep alone is not a suicide cue.","h4":"Access to a lethal means is high risk.","h5":"Future orientation is a protective factor."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk', 'Cue recognition', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_355025', 'BOWTIE', 'A client is admitted in an acute manic episode of bipolar I disorder. Complete the diagram by selecting the priority actions, the condition, and the parameters to monitor.', 'Acute mania is managed with reduced stimulation and portable nutrition, monitoring the exhausted, poorly-eating client''s nutrition, hydration, and sleep.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Provide a low-stimulation environment"},{"id":"lt2","text":"Offer high-calorie finger foods"},{"id":"lt3","text":"Schedule the client for competitive group games"},{"id":"lt4","text":"Encourage prolonged one-to-one debates"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Acute manic episode"},{"id":"ct2","text":"Major depressive episode"},{"id":"ct3","text":"Catatonic stupor"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Nutrition and hydration status"},{"id":"rt2","text":"Sleep and rest patterns"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Wound healing"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Acute mania', 'Nursing management', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_355026', 'DRAG_CLOZE', 'A client whose spouse just died says, "If I had only made him go to the doctor sooner, he''d still be alive." Using the Kubler-Ross framework, the nurse recognizes this as the [1] stage, and the most therapeutic initial response is to [2].', 'Statements of ''if only'' reflect bargaining; the therapeutic response is to acknowledge feelings and remain present rather than correcting the client.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"bargaining"},{"id":"t2","text":"acceptance"},{"id":"t3","text":"acknowledge the client''s feelings and stay present"},{"id":"t4","text":"correct the client''s reasoning"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t3"}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Grief theory', 'Stages', 'Hard', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_355027', 'DRAG_ORDER', 'A client on the unit is rapidly escalating and threatening staff. Place the nurse''s actions in the correct priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Ensure personal safety and call for additional staff assistance"},{"id":"t2","text":"Use a calm voice and verbal de-escalation techniques"},{"id":"t3","text":"Offer PRN medication to help the client regain control"},{"id":"t4","text":"Implement seclusion or restraint if less restrictive measures fail"},{"id":"t5","text":"Debrief with the client and staff after the client is calm"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Violence potential', 'Escalation response', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356001', 'MCQ', 'A client with schizophrenia tells the nurse, "The voices are telling me I deserve to be punished." Which response by the nurse is MOST therapeutic and safest?', 'Content of command hallucinations must be assessed directly for self-harm to determine safety needs.', '{"options":[{"id":"A","text":"\"The voices are not real; try to ignore what they say.\""},{"id":"B","text":"\"Are the voices telling you to hurt yourself in any way?\""},{"id":"C","text":"\"What do you think the voices mean by punishment?\""},{"id":"D","text":"\"You should not listen to voices that say negative things.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Dismissing the experience is non-therapeutic and misses the safety risk.","B":"Correct. Command hallucinations directing self-harm require immediate risk assessment.","C":"Incorrect. Exploring meaning delays urgent safety screening.","D":"Incorrect. This is advice-giving and does not assess danger."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Schizophrenia', 'Command hallucinations', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356002', 'MCQ', 'A widow states one year after her husband''s death, "I still set his place at dinner every night and cannot bear to give away his clothes." Which assessment finding most strongly suggests complicated (prolonged) grief rather than normal grieving?', 'Complicated grief is marked by persistent intense yearning and functional impairment extending well beyond the culturally expected period.', '{"options":[{"id":"A","text":"She becomes tearful when discussing her husband"},{"id":"B","text":"Persistent, intense yearning that impairs daily functioning after 12 months"},{"id":"C","text":"She keeps a photo of her husband on her nightstand"},{"id":"D","text":"She occasionally attends a bereavement support group"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Tearfulness at reminders is normal grief.","B":"Correct. Enduring functional impairment beyond expected timeframe signals complicated grief.","C":"Incorrect. Maintaining mementos is a healthy continuing bond.","D":"Incorrect. Seeking support reflects adaptive coping."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Grief and loss', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356003', 'MCQ', 'A client admitted 48 hours ago after stopping heavy daily alcohol use becomes disoriented, sees insects on the wall, and has a heart rate of 128 and temperature of 38.4°C. Which interpretation should guide the nurse''s priority action?', 'Delirium tremens presents 48-72 hours after cessation with confusion, hallucinations, and autonomic hyperactivity and can be fatal.', '{"options":[{"id":"A","text":"Expected mild withdrawal that will resolve without escalation"},{"id":"B","text":"Delirium tremens, a medical emergency requiring urgent intervention"},{"id":"C","text":"Primary psychotic disorder unrelated to substance use"},{"id":"D","text":"Attention-seeking behavior best managed by limit-setting"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. These findings exceed uncomplicated withdrawal.","B":"Correct. Disorientation, hallucinations, and autonomic instability at 48-72h indicate DTs.","C":"Incorrect. The timeline and autonomic signs point to withdrawal.","D":"Incorrect. This dismisses a life-threatening condition."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Substance withdrawal', 'Alcohol withdrawal', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356004', 'MCQ', 'A client in an acute manic episode is intrusive, hyperverbal, and has not eaten or slept in two days. Which nursing intervention best addresses the priority need?', 'During mania, physical exhaustion and poor intake are priorities; portable high-calorie foods accommodate hyperactivity.', '{"options":[{"id":"A","text":"Encourage the client to join a group art therapy session"},{"id":"B","text":"Provide high-calorie finger foods the client can eat while moving"},{"id":"C","text":"Set firm limits requiring the client to sit for a full meal"},{"id":"D","text":"Offer detailed teaching about medication side effects now"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Stimulating group settings worsen mania.","B":"Correct. Portable nutrition meets physiologic needs given the inability to sit and eat.","C":"Incorrect. A manic client cannot tolerate prolonged sitting; this provokes conflict.","D":"Incorrect. Complex teaching is ineffective during acute mania."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Bipolar disorder', 'Acute mania', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356005', 'MCQ', 'An adolescent hospitalized for anorexia nervosa has begun refeeding. On day 3 the nurse notes a phosphorus of 1.4 mg/dL, new peripheral edema, and confusion. Which is the priority nursing concern?', 'Refeeding syndrome causes dangerous drops in phosphate, potassium, and magnesium with cardiac and neurologic risk.', '{"options":[{"id":"A","text":"Body-image disturbance from weight gain"},{"id":"B","text":"Refeeding syndrome with life-threatening electrolyte shifts"},{"id":"C","text":"Noncompliance with the meal plan"},{"id":"D","text":"Manipulative behavior to avoid discharge"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Psychological concerns are secondary to the physiologic emergency.","B":"Correct. Hypophosphatemia, edema, and confusion during refeeding signal refeeding syndrome.","C":"Incorrect. Findings reflect metabolic complications of feeding, not refusal.","D":"Incorrect. This mischaracterizes a genuine medical crisis."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anorexia nervosa', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356006', 'MCQ', 'A client newly diagnosed with terminal cancer says, "There''s no point in talking about any of this." Which nurse response best reflects therapeutic communication?', 'Reflecting feelings validates emotion and keeps communication open without pressuring the client.', '{"options":[{"id":"A","text":"\"You should stay positive; many people beat the odds.\""},{"id":"B","text":"\"It sounds like this feels overwhelming right now.\""},{"id":"C","text":"\"Why do you feel that way about your treatment?\""},{"id":"D","text":"\"Let''s focus on your care plan instead.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. False reassurance blocks expression of feelings.","B":"Correct. Reflecting the underlying feeling invites the client to share at their own pace.","C":"Incorrect. ''Why'' questions can feel confrontational and demand justification.","D":"Incorrect. Changing the subject dismisses the client''s emotion."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', NULL, 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356007', 'MCQ', 'During a clinic visit a woman with multiple bruises in various stages of healing is accompanied by a partner who answers all questions for her. Which action should the nurse take FIRST?', 'The client must be interviewed privately without the potential abuser present before any further steps.', '{"options":[{"id":"A","text":"Document the bruises and provide the community shelter hotline"},{"id":"B","text":"Arrange to interview the client alone in a private area"},{"id":"C","text":"Confront the partner about the suspected abuse"},{"id":"D","text":"Call the police to report suspected abuse immediately"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Resources come after private assessment.","B":"Correct. Separating the client from the partner enables safe, honest disclosure and assessment.","C":"Incorrect. Confrontation can escalate danger to the client.","D":"Incorrect. Adult IPV reporting depends on client wishes and jurisdiction; assess first."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Abuse and neglect', 'Intimate partner violence', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356008', 'MCQ', 'A Muslim client scheduled for surgery asks to complete prayer before being taken to the operating room, which will delay transport by about ten minutes. The OR is not yet ready. Which nurse response demonstrates culturally competent care?', 'Supporting religious practices when clinically feasible is a core element of culturally sensitive care.', '{"options":[{"id":"A","text":"\"I''m sorry, hospital routine doesn''t allow delays before surgery.\""},{"id":"B","text":"\"Of course — let me give you privacy, and I''ll confirm transport timing.\""},{"id":"C","text":"\"You can pray silently on the way to the operating room.\""},{"id":"D","text":"\"I''ll ask the chaplain to decide whether we can wait.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This dismisses a meaningful spiritual need without cause.","B":"Correct. Accommodating the spiritual practice when feasible respects the client''s beliefs.","C":"Incorrect. This disregards the ritual requirements of the practice.","D":"Incorrect. The nurse can accommodate a feasible request without deferring."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Cultural and spiritual care', NULL, 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356009', 'MCQ', 'A client with moderate Alzheimer dementia becomes increasingly agitated and combative every evening around sundown. Which intervention should the nurse implement first to manage this behavior?', 'Sundowning is best managed first with environmental modification: consistent routine, reduced stimulation, and adequate lighting.', '{"options":[{"id":"A","text":"Request a PRN antipsychotic to give each afternoon"},{"id":"B","text":"Reduce environmental stimulation and increase lighting in late afternoon"},{"id":"C","text":"Move the client to a new room to provide a change of scenery"},{"id":"D","text":"Engage the client in a stimulating group activity each evening"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Nonpharmacologic environmental measures are tried before medication.","B":"Correct. Managing the environment addresses sundowning triggers without medication.","C":"Incorrect. Unfamiliar surroundings worsen confusion.","D":"Incorrect. Increased stimulation aggravates sundowning agitation."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Dementia', 'Behavioral management', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356010', 'MCQ', 'A young man who underwent an emergency colostomy refuses to look at the stoma and says, "I''m not the same person anymore." Which nursing action best supports adaptive coping at this stage?', 'Body-image adaptation requires acknowledgment of loss and client-directed pacing before self-care mastery.', '{"options":[{"id":"A","text":"Insist he participate in stoma care today to build confidence"},{"id":"B","text":"Acknowledge his feelings and let him set the pace for viewing the stoma"},{"id":"C","text":"Reassure him that the colostomy may be reversible someday"},{"id":"D","text":"Arrange for discharge teaching to proceed on schedule"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Forcing participation before he is ready increases distress.","B":"Correct. Validating grief and allowing gradual involvement supports adjustment.","C":"Incorrect. False or premature reassurance dismisses his current distress.","D":"Incorrect. Emotional readiness precedes effective self-care learning."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Coping with life changes', 'Body image', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356011', 'MCQ', 'A client in the emergency department is pacing, hyperventilating, and states, "I feel like I''m dying." Chest pain and cardiac workup are negative. Which nurse action is the priority?', 'During panic-level anxiety the nurse remains present and gives simple, calm directions to help the client regain control.', '{"options":[{"id":"A","text":"Provide detailed education about panic disorder"},{"id":"B","text":"Stay with the client and use a calm, low voice to guide slow breathing"},{"id":"C","text":"Leave the client alone in a quiet room to self-soothe"},{"id":"D","text":"Ask the client to describe the childhood origins of the anxiety"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Teaching is ineffective during peak anxiety.","B":"Correct. Presence and simple directives reduce escalating panic-level anxiety.","C":"Incorrect. Abandonment heightens panic; the client cannot self-regulate yet.","D":"Incorrect. Insight work is inappropriate during an acute panic attack."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety disorders', 'Panic attack', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356012', 'MCQ', 'On a psychiatric unit a client with borderline personality disorder praises the night nurse as "the only one who cares" while calling the day staff "cruel and useless." Which staff response best manages this dynamic?', 'Splitting is countered by consistent limits and clear, unified team communication so the client cannot pit staff against each other.', '{"options":[{"id":"A","text":"The night nurse spends extra time with the client to reinforce trust"},{"id":"B","text":"Staff maintain consistent limits and communicate as a unified team"},{"id":"C","text":"Day staff confront the client about the unfair accusations"},{"id":"D","text":"The charge nurse assigns only the night nurse to the client"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This rewards splitting and undermines team consistency.","B":"Correct. A consistent, coordinated team approach counters splitting.","C":"Incorrect. Confrontation escalates conflict and reinforces the dynamic.","D":"Incorrect. Accommodating the split validates the maladaptive pattern."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic milieu', 'Splitting', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_356013', 'SATA', 'A nurse assesses a client for acute suicide risk. Which findings indicate the HIGHEST level of immediate concern? Select all that apply.', 'A lethal plan with access, sudden unexplained calm, giving away possessions, and stated intent are high-risk indicators of imminent suicide.', '{"options":[{"id":"A","text":"The client has a specific plan and access to a firearm"},{"id":"B","text":"The client is suddenly calm and peaceful after weeks of despair"},{"id":"C","text":"The client is giving away valued possessions"},{"id":"D","text":"The client expresses hope about an upcoming family event"},{"id":"E","text":"The client states a clear intent to die tonight"},{"id":"F","text":"The client reports sleeping well and eating regularly"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_356014', 'SATA', 'A nurse reviews a colleague''s interaction with a grieving client. Which statements are non-therapeutic communication blocks? Select all that apply.', 'Claiming to know feelings, clichés, giving advice/minimizing feelings block communication; open invitations and validation are therapeutic.', '{"options":[{"id":"A","text":"\"I know exactly how you feel; I lost someone too.\""},{"id":"B","text":"\"Everything happens for a reason.\""},{"id":"C","text":"\"Tell me more about what you''re experiencing.\""},{"id":"D","text":"\"You shouldn''t cry; you need to be strong for your children.\""},{"id":"E","text":"\"At least she is no longer suffering.\""},{"id":"F","text":"\"It''s okay to feel however you feel right now.\""}]}'::jsonb, '{"answers":["A","B","D","E"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', 'Blocks', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_356015', 'SATA', 'A client on the unit is pacing, clenching fists, speaking loudly, and glaring at staff. Which de-escalation actions are appropriate? Select all that apply.', 'Calm voice, personal space, an unobstructed exit, and offering choices de-escalate; touch and confrontational posture escalate agitation.', '{"options":[{"id":"A","text":"Maintain a calm, low tone of voice"},{"id":"B","text":"Provide the client extra personal space"},{"id":"C","text":"Position yourself near an exit and ensure a clear path"},{"id":"D","text":"Touch the client''s shoulder to convey reassurance"},{"id":"E","text":"Offer simple choices to give the client a sense of control"},{"id":"F","text":"Stand directly in front of the client with sustained eye contact"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'De-escalation', 'Violence potential', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_356016', 'SATA', 'A nurse assesses an older adult for major depression. Which findings support the diagnosis? Select all that apply.', 'Anhedonia, worthlessness/guilt, psychomotor retardation, and impaired concentration are core depressive features; flight of ideas and grandiosity indicate mania.', '{"options":[{"id":"A","text":"Anhedonia — loss of interest in previously enjoyed activities"},{"id":"B","text":"Feelings of worthlessness and excessive guilt"},{"id":"C","text":"Psychomotor retardation"},{"id":"D","text":"Flight of ideas and pressured speech"},{"id":"E","text":"Difficulty concentrating and indecisiveness"},{"id":"F","text":"Grandiose sense of self-importance"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Depression', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_356017', 'SELECT_N', 'A veteran with post-traumatic stress disorder is admitted for an unrelated surgery. Which 3 nursing approaches reflect trauma-informed care?', 'Trauma-informed care emphasizes predictability, client control, and reducing triggers; forced retelling and startling approaches are harmful.', '{"options":[{"id":"A","text":"Explain each procedure before touching the client"},{"id":"B","text":"Ask the client how they prefer to be approached when startled"},{"id":"C","text":"Minimize unexpected loud noises and abrupt awakenings"},{"id":"D","text":"Encourage detailed retelling of the traumatic combat event"},{"id":"E","text":"Approach the client quietly from behind to avoid disturbing rest"},{"id":"F","text":"Restrict visitors to reduce the client''s stimulation"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'PTSD', 'Trauma-informed care', 'Hard', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_356018', 'TF', 'Accepting a personal social media friend request from a client after discharge is an appropriate way to maintain a supportive therapeutic relationship.', 'Accepting social media connections blurs professional boundaries and violates the therapeutic relationship regardless of discharge status.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic relationship', 'Boundaries', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_356019', 'TF', 'Loud wailing and highly expressive public mourning at a death can be a culturally normative grief response rather than evidence of a pathological reaction.', 'Grief expression varies widely across cultures; expressive mourning may be a normative practice and should not be pathologized.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Grief', 'Cultural expression', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_356020', 'MATRIX', 'For each client statement, click to identify the defense mechanism being demonstrated.', 'Displacement redirects feelings to a safer target; rationalization justifies with excuses; projection attributes one''s own feelings to others.', '{"row_label":"Statement","rows":[{"id":"r1","text":"A man angry at his boss yells at his spouse when he gets home"},{"id":"r2","text":"A student who cheated says, \"Everyone else was doing it too\""},{"id":"r3","text":"A woman who dislikes a coworker insists the coworker hates her"},{"id":"r4","text":"A client who failed an exam says, \"That test was unfair anyway\""}],"columns":[{"id":"c1","text":"Projection"},{"id":"c2","text":"Rationalization"},{"id":"c3","text":"Displacement"}]}'::jsonb, '{"cells":{"r1":"c3","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Defense mechanisms', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_356021', 'MATRIX_MR', 'For each client finding, select all mental-health conditions in which it commonly appears (may apply to more than one).', 'Symptoms overlap across disorders; concentration impairment is nonspecific, delusions occur in mania and schizophrenia, flight of ideas is characteristic of mania.', '{"row_label":"Behavior","rows":[{"id":"r1","text":"Anhedonia"},{"id":"r2","text":"Disturbed sleep"},{"id":"r3","text":"Impaired concentration"},{"id":"r4","text":"Delusions"},{"id":"r5","text":"Flight of ideas"}],"columns":[{"id":"c1","text":"Major depression"},{"id":"c2","text":"Acute mania"},{"id":"c3","text":"Schizophrenia"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c1","c2"],"r3":["c1","c2","c3"],"r4":["c2","c3"],"r5":["c2"]},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Mental status exam', NULL, 'Hard', 'Analyze', '{}', 9, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_356022', 'CLOZE', 'A client taking an SSRI who recently started a second serotonergic drug presents with agitation, diaphoresis, hyperthermia, and clonus. The nurse recognizes these findings as {1}, and the priority action is to {2}.', 'Agitation, autonomic instability, hyperthermia, and clonus after adding a serotonergic drug indicate serotonin syndrome; offending agents are stopped immediately.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"serotonin syndrome"},{"id":"c2","text":"neuroleptic malignant syndrome"},{"id":"c3","text":"an acute dystonic reaction"}]},{"id":"b2","choices":[{"id":"c1","text":"hold the serotonergic agents and notify the provider"},{"id":"c2","text":"administer the next scheduled SSRI dose"},{"id":"c3","text":"encourage increased fluid restriction"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Serotonin syndrome', 'Psychotropic toxicity', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_356023', 'HIGHLIGHT', 'Highlight the findings in the nurse''s note that increase this client''s acute suicide risk. Client states [["I have decided everyone would be better off without me"]]. Reports [[giving away his guitar and savings this week]]. Denies current plan but has [[a prior attempt two years ago]]. Attends [[weekly church services]]. States he [[recently purchased a rope]]. Reports [[good relationship with his sister]].', 'Perceived burden, giving away possessions, prior attempt, and acquiring means raise risk; social and religious connection are protective.', '{"chunks":[{"id":"h1","text":"\"I have decided everyone would be better off without me\""},{"id":"h2","text":"giving away his guitar and savings this week"},{"id":"h3","text":"a prior attempt two years ago"},{"id":"h4","text":"weekly church services"},{"id":"h5","text":"recently purchased a rope"},{"id":"h6","text":"good relationship with his sister"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h5"],"feedback":{"h1":"Perceived burdensomeness is a strong risk indicator.","h2":"Giving away possessions signals possible finalizing behavior.","h3":"Prior attempts are a leading predictor of future risk.","h4":"Religious/community connection is a protective factor.","h5":"Acquiring means indicates preparation and elevates risk.","h6":"Social support is a protective factor, not a risk factor."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk assessment', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_356024', 'BOWTIE', 'A client 36 hours after last alcohol intake is tremulous, anxious, and hypertensive with CIWA rising. Complete the diagram by selecting actions, the condition, and parameters to monitor.', 'Alcohol withdrawal is managed with symptom-triggered benzodiazepines and a calm environment, monitoring CIWA, vitals, LOC, and seizure activity.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer prescribed benzodiazepine per CIWA protocol"},{"id":"lt2","text":"Provide a quiet, low-stimulation environment"},{"id":"lt3","text":"Encourage caffeine to keep the client alert"},{"id":"lt4","text":"Apply restraints preemptively"},{"id":"lt5","text":"Withhold all sedation until seizures occur"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Alcohol withdrawal"},{"id":"ct2","text":"Major depressive episode"},{"id":"ct3","text":"Bipolar mania"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"CIWA score and vital signs"},{"id":"rt2","text":"Level of consciousness and seizure activity"},{"id":"rt3","text":"Deep tendon reflexes only"},{"id":"rt4","text":"Daily weight trend"},{"id":"rt5","text":"Pupillary light reflex"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Alcohol withdrawal', NULL, 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_356025', 'DRAG_CLOZE', 'When a client becomes physically aggressive, the nurse first attempts [1]; physical restraint is used only as [2] and requires [3] obtained after application in an emergency.', 'Least-restrictive interventions such as de-escalation are tried first; restraint is a last resort and requires a provider order, obtained promptly when applied emergently.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""},{"id":"s3","target_text":""}],"tokens":[{"id":"t1","text":"verbal de-escalation"},{"id":"t2","text":"a last resort"},{"id":"t3","text":"a provider order"},{"id":"t4","text":"immediate seclusion"},{"id":"t5","text":"family consent"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3"}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Restraint use', 'Least restrictive', 'Hard', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_356026', 'DRAG_ORDER', 'A client admitted to a medical unit voices active suicidal intent. Place the nurse''s actions in priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Ensure the client is not left alone (initiate 1:1 observation)"},{"id":"t2","text":"Remove potentially harmful objects from the environment"},{"id":"t3","text":"Notify the provider and mental health team"},{"id":"t4","text":"Complete a formal suicide-risk assessment"},{"id":"t5","text":"Document findings and interventions"},{"id":"t6","text":"Provide teaching on outpatient coping resources"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide precautions', NULL, 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_356027', 'MCQ', 'A family sits at the bedside of a dying, unresponsive client and asks the nurse whether continuing to talk to the client is worthwhile. Which response is most accurate and supportive?', 'Hearing is generally considered the last sense to be lost, so families should be encouraged to continue speaking to a dying client.', '{"options":[{"id":"A","text":"\"He can''t hear you anymore, but talking may comfort you.\""},{"id":"B","text":"\"Hearing is thought to remain, so your words may still reach him.\""},{"id":"C","text":"\"It''s better to sit quietly so you don''t disturb his rest.\""},{"id":"D","text":"\"There''s no way to know if any senses are still working.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Hearing is believed to persist; this statement is inaccurate.","B":"Correct. Hearing is believed to be the last sense lost; families are encouraged to speak.","C":"Incorrect. This discourages meaningful connection without basis.","D":"Incorrect. This dismisses established end-of-life understanding."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'End-of-life care', 'Sensory changes', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363001', 'MCQ', 'A client with chronic kidney disease has these morning labs: potassium 6.4 mEq/L, creatinine 4.1 mg/dL, and a peaked T wave on the monitor. Which finding should the nurse report to the provider FIRST?', 'Peaked T waves reflect cardiac membrane effects of hyperkalemia and take priority over the numeric value or a chronic creatinine.', '{"options":[{"id":"A","text":"The peaked T wave on the cardiac monitor"},{"id":"B","text":"The potassium level of 6.4 mEq/L"},{"id":"C","text":"The creatinine of 4.1 mg/dL"},{"id":"D","text":"The client''s report of muscle weakness"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Peaked T waves signal hyperkalemic cardiac membrane instability, the most immediately life-threatening cue.","B":"Concerning, but the ECG change indicates the potassium is already affecting the myocardium — the priority cue.","C":"Chronically elevated in CKD; not the acute threat.","D":"A hyperkalemia symptom but far less urgent than the ECG change."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Lab-value interpretation', 'Potassium', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363002', 'MCQ', 'During a colonoscopy under moderate sedation, a client''s SpO2 drops to 86%, respiratory rate is 6/min, and the client is difficult to arouse after receiving midazolam and fentanyl. Which action should the nurse take FIRST?', 'Oversedation is managed by supporting airway and breathing first; reversal agents follow if the client does not respond.', '{"options":[{"id":"A","text":"Stimulate the client and deliver supplemental oxygen with airway repositioning"},{"id":"B","text":"Administer flumazenil intravenously"},{"id":"C","text":"Administer naloxone intravenously"},{"id":"D","text":"Prepare for endotracheal intubation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Airway/breathing support is first for oversedation-related hypoventilation before pharmacologic reversal.","B":"Reversal may be needed but airway and oxygenation come first.","C":"Reversal may be needed but support airway/breathing first.","D":"Premature; basic airway maneuvers and oxygen usually restore ventilation."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Moderate sedation', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363003', 'MCQ', 'A client on a telemetry unit suddenly shows a wide-complex rhythm at 180/min. The client is alert, talking, and has a BP of 138/82 mmHg. Which action should the nurse take FIRST?', 'A stable wide-complex tachycardia warrants a 12-lead ECG and monitoring rather than immediate electrical therapy.', '{"options":[{"id":"A","text":"Obtain a 12-lead ECG and stay with the client"},{"id":"B","text":"Prepare for immediate synchronized cardioversion"},{"id":"C","text":"Deliver an unsynchronized defibrillation shock"},{"id":"D","text":"Administer IV adenosine rapid push"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A stable client with a wide-complex tachycardia needs a 12-lead to characterize the rhythm while the nurse monitors.","B":"Cardioversion is for unstable clients; this client is hemodynamically stable.","C":"Defibrillation is for pulseless VT/VF, not a stable, talking client.","D":"Adenosine is not first-line for stable wide-complex tachycardia and can be harmful if the rhythm is VT."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'ECG monitoring', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363004', 'MCQ', 'A nurse is verifying placement of a newly inserted nasogastric tube before use. Which finding is the MOST reliable indicator that the tube requires repositioning before feeding?', 'Radiographic confirmation is the definitive placement check; a tip above the diaphragm requires repositioning.', '{"options":[{"id":"A","text":"An X-ray shows the tube tip above the diaphragm"},{"id":"B","text":"Aspirate pH is 5.0"},{"id":"C","text":"Auscultation of air over the epigastrium"},{"id":"D","text":"Aspirate is grassy-green in color"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Radiographic confirmation is the gold standard; a tip above the diaphragm indicates the tube is not in the stomach.","B":"A pH of 1–5 is consistent with gastric placement.","C":"The auscultatory ''whoosh'' is unreliable and no longer recommended.","D":"Green aspirate is consistent with gastric contents."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG tube', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363005', 'MCQ', 'Two days after open reduction of a femur fracture, a young adult becomes confused, tachypneic with SpO2 89%, and develops a petechial rash over the chest and axillae. Which complication should the nurse suspect FIRST?', 'Hypoxemia, altered mentation, and petechiae after a long-bone fracture are the hallmark triad of fat embolism syndrome.', '{"options":[{"id":"A","text":"Fat embolism syndrome"},{"id":"B","text":"Pulmonary embolism from DVT"},{"id":"C","text":"Compartment syndrome of the thigh"},{"id":"D","text":"Postoperative pneumonia"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The triad of hypoxemia, neurologic change, and petechiae after a long-bone fracture is classic for fat embolism.","B":"PE causes hypoxia but not the petechial rash of fat embolism.","C":"Compartment syndrome causes pain and neurovascular changes in the limb, not petechiae and confusion.","D":"Pneumonia would not produce a petechial rash or acute confusion in this pattern."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Musculoskeletal', 'Post-operative complication prevention', 'Fat embolism', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363006', 'MCQ', 'A laboring client''s fetal monitor shows recurrent late decelerations with minimal variability. After repositioning the client to the left side, the pattern persists. Which action should the nurse take NEXT?', 'Persistent late decelerations after repositioning call for stopping oxytocin and increasing fluids to improve uteroplacental perfusion.', '{"options":[{"id":"A","text":"Discontinue oxytocin and increase the IV fluid rate"},{"id":"B","text":"Document the pattern as reassuring and continue monitoring"},{"id":"C","text":"Encourage the client to begin pushing"},{"id":"D","text":"Apply a fetal scalp electrode for a clearer tracing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Recurrent late decelerations indicate uteroplacental insufficiency; stopping oxytocin and boosting perfusion are the next intrauterine resuscitation steps.","B":"Recurrent lates with minimal variability are Category III/non-reassuring, not reassuring.","C":"Pushing would worsen fetal stress and is not indicated.","D":"Clarifying the tracing does not address the ongoing hypoxic pattern."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive', 'Fetal monitoring', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363007', 'MCQ', 'A nurse assesses a peripheral IV site infusing a vesicant chemotherapy agent and finds the area cool, swollen, and blanched, with the client reporting burning. There is no blood return. Which action should the nurse take FIRST?', 'Suspected vesicant extravasation requires stopping the infusion while leaving the catheter in place to aspirate and treat.', '{"options":[{"id":"A","text":"Stop the infusion and leave the catheter in place"},{"id":"B","text":"Remove the catheter and apply warm compresses"},{"id":"C","text":"Flush the catheter briskly with normal saline"},{"id":"D","text":"Slow the infusion rate and continue observing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. For suspected extravasation, stop the infusion but leave the catheter to aspirate residual drug and instill antidote.","B":"The catheter should stay in initially to aspirate the drug; removal is not first.","C":"Flushing pushes vesicant into tissue and worsens injury.","D":"Continuing any infusion of a vesicant into tissue causes further damage."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV complications', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363008', 'MCQ', 'A client with type 1 diabetes has a point-of-care glucose of 48 mg/dL but is alert and able to swallow. Fifteen minutes after receiving 15 g of oral glucose, a repeat reading is 52 mg/dL. Which action should the nurse take NEXT?', 'The rule of 15 directs repeating 15 g of fast carbohydrate when a conscious client remains hypoglycemic after 15 minutes.', '{"options":[{"id":"A","text":"Give a second 15 g of fast-acting oral carbohydrate"},{"id":"B","text":"Administer IV dextrose 50%"},{"id":"C","text":"Administer intramuscular glucagon"},{"id":"D","text":"Provide a complex carbohydrate and protein snack now"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Per the rule of 15, repeat carbohydrate is given when the level remains below 70 mg/dL after 15 minutes in an alert client.","B":"IV dextrose is reserved for clients unable to swallow safely; this client is alert.","C":"Glucagon is for clients who cannot take oral carbohydrate.","D":"A lasting snack follows only after glucose exceeds 70 mg/dL."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Lab-value interpretation', 'Point-of-care glucose', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363009', 'MCQ', 'A nurse reviews serial vital signs for a client with a head injury: BP trending from 132/78 to 176/62 mmHg, HR from 88 to 52/min, and irregular respirations developing. Which interpretation is correct?', 'Widening pulse pressure, bradycardia, and irregular respirations form Cushing''s triad, a late sign of increased intracranial pressure.', '{"options":[{"id":"A","text":"The trend reflects rising intracranial pressure and requires immediate provider notification"},{"id":"B","text":"The changes indicate developing hypovolemic shock"},{"id":"C","text":"The findings are an expected response to pain and can be monitored"},{"id":"D","text":"The trend suggests improving cerebral perfusion"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Widening pulse pressure, bradycardia, and irregular respirations are Cushing''s triad — a late sign of rising ICP.","B":"Shock produces hypotension and tachycardia, the opposite pattern.","C":"This ominous triad is not a benign pain response.","D":"Cushing''s triad indicates dangerous brainstem compression, not improvement."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Neurological', 'Vital-sign trend recognition', 'Cushing''s triad', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363010', 'MCQ', 'A client on a heparin infusion has an aPTT result of 110 seconds (therapeutic range 60–80 seconds). The client has no active bleeding. Which action should the nurse anticipate FIRST?', 'A supratherapeutic aPTT on heparin is managed by holding the infusion and titrating per protocol, reserving protamine for bleeding.', '{"options":[{"id":"A","text":"Hold the heparin infusion and notify the provider for a rate adjustment"},{"id":"B","text":"Administer protamine sulfate immediately"},{"id":"C","text":"Continue the infusion and recheck the aPTT in 6 hours"},{"id":"D","text":"Administer vitamin K"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A supratherapeutic aPTT indicates over-anticoagulation; the infusion is held and titrated down.","B":"Protamine is reserved for significant bleeding or severe overdose, not an asymptomatic elevated aPTT.","C":"Continuing at the current rate risks bleeding with a value this high.","D":"Vitamin K reverses warfarin, not heparin."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Blood specimen collection', 'Coagulation monitoring', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_363011', 'MCQ', 'During a preoperative assessment for elective surgery, a client reports taking several supplements. Which one is MOST important to report because it increases perioperative bleeding risk?', 'Ginkgo biloba impairs platelet function and should be reported and stopped before surgery to reduce bleeding risk.', '{"options":[{"id":"A","text":"Ginkgo biloba"},{"id":"B","text":"Calcium carbonate"},{"id":"C","text":"Vitamin D"},{"id":"D","text":"Probiotic capsules"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Ginkgo inhibits platelet aggregation and raises bleeding risk perioperatively.","B":"Calcium does not meaningfully affect bleeding.","C":"Vitamin D does not increase bleeding risk.","D":"Probiotics are not associated with perioperative bleeding."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Pre-operative education', 'Anticoagulation risk', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_363012', 'SATA', 'A nurse monitors a client 4 hours after a cardiac catheterization via the right femoral artery. Which findings require immediate follow-up? Select all that apply.', 'Expanding hematoma, lost pulse, cool pale limb, and falling BP all point to post-catheterization vascular compromise or bleeding.', '{"options":[{"id":"A","text":"A growing hematoma at the femoral insertion site"},{"id":"B","text":"Absent right pedal pulse compared with the left"},{"id":"C","text":"Cool, pale right foot"},{"id":"D","text":"Blood pressure trending from 128/76 to 96/58 mmHg"},{"id":"E","text":"Puncture site clean and dry with intact dressing"},{"id":"F","text":"Client requesting to sit up to eat lunch"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. An expanding hematoma signals active bleeding.","B":"Correct. A lost distal pulse suggests arterial occlusion.","C":"Correct. Coolness and pallor indicate compromised distal perfusion.","D":"Correct. A falling BP may indicate retroperitoneal or site bleeding.","E":"This is an expected, reassuring finding.","F":"A comfort request is not an urgent complication."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Vital-sign trend recognition', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_363013', 'SATA', 'A client is scheduled for a contrast-enhanced CT scan. Which factors increase the client''s risk for contrast-induced acute kidney injury? Select all that apply.', 'Renal impairment, diabetic nephropathy, advanced age, volume depletion, and metformin use all raise the risk of contrast-induced AKI.', '{"options":[{"id":"A","text":"Baseline creatinine of 2.3 mg/dL"},{"id":"B","text":"Current metformin therapy with dehydration"},{"id":"C","text":"History of type 2 diabetes with nephropathy"},{"id":"D","text":"Age 82 with poor oral intake"},{"id":"E","text":"Well-controlled hypertension on lisinopril"},{"id":"F","text":"Normal hydration status with a creatinine of 0.8 mg/dL"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Pre-existing renal impairment is a major risk factor.","B":"Correct. Metformin plus volume depletion heightens renal and lactic-acidosis risk with contrast.","C":"Correct. Diabetic nephropathy increases nephrotoxic risk.","D":"Correct. Advanced age and volume depletion increase risk.","E":"Controlled hypertension alone is not a major independent risk.","F":"Good hydration and normal renal function are protective."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Diagnostic-test monitoring', 'Contrast media', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_363014', 'SATA', 'Fifteen minutes into a packed red blood cell transfusion, a client develops fever, chills, low-back pain, and dark urine. Which nursing actions are appropriate? Select all that apply.', 'Signs of an acute hemolytic reaction require stopping the transfusion, running saline through new tubing, notifying provider/blood bank, and monitoring renal function.', '{"options":[{"id":"A","text":"Stop the transfusion immediately"},{"id":"B","text":"Keep the IV line open with normal saline via new tubing"},{"id":"C","text":"Notify the provider and blood bank"},{"id":"D","text":"Monitor urine output and send blood/urine samples"},{"id":"E","text":"Slow the transfusion and continue observing"},{"id":"F","text":"Administer the remaining unit through a smaller-gauge catheter"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Stopping the transfusion is the first action in a suspected acute hemolytic reaction.","B":"Correct. Saline maintains access and supports renal perfusion without infusing more blood.","C":"Correct. Both must be alerted and the unit returned for analysis.","D":"Correct. Hemolysis threatens the kidneys; specimens confirm the reaction.","E":"The transfusion must be stopped, not slowed, for a hemolytic reaction.","F":"No more of the suspect unit should be given."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Pharmacology', 'Hematologic', 'Blood-product administration', 'Transfusion reaction', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_363015', 'SATA', 'A nurse plans care to prevent venous thromboembolism in a postoperative client. Which interventions are appropriate? Select all that apply.', 'SCDs, ambulation, well-fitted stockings, and hydration prevent VTE; calf massage and sharp knee flexion are harmful.', '{"options":[{"id":"A","text":"Apply sequential compression devices when the client is in bed"},{"id":"B","text":"Encourage early and frequent ambulation"},{"id":"C","text":"Ensure antiembolism stockings are wrinkle-free and correctly sized"},{"id":"D","text":"Massage the calves to relieve aching"},{"id":"E","text":"Keep the knee gatch sharply flexed to keep the client comfortable"},{"id":"F","text":"Encourage adequate hydration unless contraindicated"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{"A":"Correct. SCDs promote venous return during immobility.","B":"Correct. Ambulation is a key VTE-prevention measure.","C":"Correct. Properly fitted stockings prevent constriction and aid venous return.","D":"Calf massage can dislodge a clot and is contraindicated.","E":"Sharp knee flexion impedes venous flow and promotes stasis.","F":"Correct. Hydration reduces blood viscosity and stasis."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Musculoskeletal', 'Venous-return devices', 'DVT prevention', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_363016', 'SATA', 'A client receives continuous enteral feeding through a PEG tube. Which nursing actions reduce the risk of aspiration and tube complications? Select all that apply.', 'Head elevation, residual checks, flushing, and site assessment reduce aspiration and tube complications; flat positioning and crushing enteric-coated drugs are unsafe.', '{"options":[{"id":"A","text":"Keep the head of the bed elevated at least 30–45 degrees"},{"id":"B","text":"Check gastric residual volume per protocol"},{"id":"C","text":"Flush the tube with water before and after medications"},{"id":"D","text":"Lay the client flat during feeding to ease abdominal pressure"},{"id":"E","text":"Assess placement and skin at the insertion site"},{"id":"F","text":"Crush enteric-coated tablets and add them to the feeding bag"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. Elevation reduces reflux and aspiration.","B":"Correct. Monitoring residuals helps detect delayed emptying.","C":"Correct. Flushing maintains patency.","D":"A flat position increases reflux and aspiration risk.","E":"Correct. Confirming placement and skin integrity prevents complications.","F":"Enteric-coated drugs should not be crushed and meds should not be added to the bag."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Percutaneous feeding tube', 'Aspiration prevention', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_363017', 'SELECT_N', 'A nurse manages an indwelling urinary catheter. Which 3 actions BEST reduce the risk of catheter-associated urinary tract infection?', 'Dependent drainage, daily review of need, and a maintained closed system are core evidence-based CAUTI-prevention measures.', '{"options":[{"id":"A","text":"Keep the drainage bag below the level of the bladder"},{"id":"B","text":"Perform daily assessment of continued catheter need for early removal"},{"id":"C","text":"Maintain a closed drainage system"},{"id":"D","text":"Irrigate the catheter routinely with antibiotic solution"},{"id":"E","text":"Coil the drainage tubing on the bed near the client"},{"id":"F","text":"Disconnect the tubing to obtain routine specimens"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Dependent drainage prevents reflux of urine.","B":"Correct. Prompt removal is the single most effective CAUTI-prevention measure.","C":"Correct. An intact closed system limits bacterial entry.","D":"Routine irrigation is not recommended and can introduce infection.","E":"Dependent loops of tubing cause stasis and reflux.","F":"Breaking the closed system increases infection risk."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Urinary catheter', 'CAUTI prevention', 'Hard', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_363018', 'TF', 'A client''s arterial blood gas shows pH 7.32, PaCO2 58 mmHg, and HCO3 26 mEq/L; the nurse correctly documents this as uncompensated metabolic acidosis.', 'A low pH with an elevated PaCO2 and near-normal bicarbonate indicates uncompensated respiratory acidosis, not metabolic acidosis.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Diagnostic-test monitoring', 'Arterial blood gas', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_363019', 'MATRIX', 'For each laboratory result, click to indicate whether the value is within normal limits or a critical value requiring immediate provider notification.', 'Sodium 118, calcium 6.2, and INR 5.8 are critical values; a normal platelet count and hemoglobin need no notification.', '{"row_label":"Lab value","rows":[{"id":"r1","text":"Serum sodium 118 mEq/L"},{"id":"r2","text":"Platelet count 240,000/mm3"},{"id":"r3","text":"Serum calcium 6.2 mg/dL"},{"id":"r4","text":"INR 5.8 on warfarin"},{"id":"r5","text":"Hemoglobin 13.5 g/dL"}],"columns":[{"id":"c1","text":"Within normal limits"},{"id":"c2","text":"Critical — notify provider"}]}'::jsonb, '{"cells":{"r1":"c2","r2":"c1","r3":"c2","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Lab-value interpretation', NULL, 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_363020', 'MATRIX_MR', 'A nurse assesses a client on the first postoperative day after abdominal surgery. For each assessment cue, select all complications it could indicate (a cue may point to more than one).', 'Tachycardia/hypotension and restlessness can reflect either hemorrhage or sepsis; fever/rising WBC points to infection; diminished basal breath sounds indicate atelectasis; frank bleeding indicates hemorrhage.', '{"row_label":"Assessment cue","rows":[{"id":"r1","text":"Temperature 38.8°C with rising WBC count"},{"id":"r2","text":"Heart rate 122/min with BP 92/54 mmHg"},{"id":"r3","text":"Diminished breath sounds at the bases with SpO2 90%"},{"id":"r4","text":"Restlessness with cool, clammy skin"},{"id":"r5","text":"Saturated abdominal dressing with bright red drainage"}],"columns":[{"id":"c1","text":"Hemorrhage/hypovolemia"},{"id":"c2","text":"Infection/sepsis"},{"id":"c3","text":"Atelectasis"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1","c2"],"r3":["c3"],"r4":["c1","c2"],"r5":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Post-operative complication recognition', NULL, 'Hard', 'Analyze', '{}', 7, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_363021', 'CLOZE', 'A client receiving a loop diuretic has a magnesium level of 1.1 mg/dL. The nurse recognizes this represents {1} and prioritizes monitoring for {2}.', 'A magnesium of 1.1 mg/dL is hypomagnesemia, which predisposes to cardiac dysrhythmias; depressed reflexes and respiratory depression are features of hypermagnesemia.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"hypomagnesemia"},{"id":"c2","text":"hypermagnesemia"},{"id":"c3","text":"a normal level"}]},{"id":"b2","choices":[{"id":"c1","text":"cardiac dysrhythmias"},{"id":"c2","text":"diminished deep tendon reflexes"},{"id":"c3","text":"respiratory depression"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Lab-value interpretation', 'Magnesium', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_363022', 'HIGHLIGHT', 'The nurse assesses a client 6 hours after a thyroidectomy. Highlight the findings that require immediate follow-up. The client is drowsy but arousable. Reports [[a sensation of neck fullness and tightness]]. Voice is [[hoarse but present]]. [[Stridor]] is audible on inspiration. Dressing is [[dry and intact]]. Reports [[tingling around the mouth and fingertips]]. Temperature 37.1°C.', 'Neck fullness, stridor, and perioral tingling signal airway-threatening hematoma and hypocalcemia after thyroidectomy; mild hoarseness and a dry dressing do not require urgent action.', '{"chunks":[{"id":"h1","text":"a sensation of neck fullness and tightness"},{"id":"h2","text":"hoarse but present"},{"id":"h3","text":"Stridor"},{"id":"h4","text":"dry and intact"},{"id":"h5","text":"tingling around the mouth and fingertips"}]}'::jsonb, '{"correct_ids":["h1","h3","h5"],"feedback":{"h1":"Neck fullness may indicate expanding hematoma compressing the airway.","h2":"Mild hoarseness is common after thyroidectomy and not immediately urgent.","h3":"Stridor signals airway compromise — an emergency.","h4":"A dry, intact dressing is a reassuring finding.","h5":"Perioral and digital tingling suggests hypocalcemia from parathyroid injury."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Focused assessment', 'Post-operative bleeding', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_363023', 'BOWTIE', 'A client 3 days after total hip replacement suddenly develops pleuritic chest pain, dyspnea, SpO2 84%, and tachycardia. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Sudden dyspnea, pleuritic pain, and hypoxemia after hip surgery indicate pulmonary embolism, managed with oxygen and rapid response while monitoring oxygenation and respiratory status.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Apply high-flow supplemental oxygen"},{"id":"lt2","text":"Notify the rapid response team"},{"id":"lt3","text":"Encourage vigorous ambulation immediately"},{"id":"lt4","text":"Apply firm calf massage"},{"id":"lt5","text":"Withhold all IV fluids"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Pulmonary embolism"},{"id":"ct2","text":"Fat embolism syndrome"},{"id":"ct3","text":"Pulmonary edema"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Oxygen saturation"},{"id":"rt2","text":"Respiratory rate and effort"},{"id":"rt3","text":"Bowel sounds"},{"id":"rt4","text":"Urine specific gravity"},{"id":"rt5","text":"Pupillary response"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Post-operative complication recognition', 'Pulmonary embolism', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_363024', 'DRAG_CLOZE', 'A client presents with chest pain and an elevated troponin of [1]. Combined with ST-segment elevation on the ECG, the nurse recognizes findings consistent with [2] and prepares the client for urgent reperfusion.', 'A markedly elevated troponin with ST elevation indicates acute myocardial infarction requiring urgent reperfusion; a normal troponin and stable angina do not fit the picture.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"4.8 ng/mL"},{"id":"t2","text":"acute myocardial infarction"},{"id":"t3","text":"stable angina"},{"id":"t4","text":"0.01 ng/mL"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Diagnostic-test monitoring', 'Troponin', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364001', 'MCQ', 'A client on digoxin and furosemide has a serum potassium of 3.1 mEq/L and a digoxin level of 1.4 ng/mL. Which action should the nurse take FIRST?', 'Hypokalemia sensitizes the myocardium to digoxin, so toxicity can occur at therapeutic levels; potassium must be corrected before further dosing.', '{"options":[{"id":"A","text":"Hold the next digoxin dose and notify the provider about the potassium"},{"id":"B","text":"Document the digoxin level as therapeutic and continue as ordered"},{"id":"C","text":"Administer the scheduled digoxin dose then recheck potassium"},{"id":"D","text":"Restrict dietary potassium to prevent hyperkalemia"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Hypokalemia potentiates digoxin toxicity even when the level is therapeutic; correcting potassium is the priority safety action.","B":"Incorrect. The level is ''therapeutic'' but hypokalemia makes toxicity likely.","C":"Incorrect. Giving digoxin in hypokalemia risks precipitating toxicity.","D":"Incorrect. The client is hypokalemic; restriction worsens the risk."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Lab-value interpretation', 'Digoxin and potassium', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364002', 'MCQ', 'A client on telemetry receiving IV ondansetron and haloperidol has a corrected QT interval that has lengthened from 440 ms to 510 ms. Which action is the priority?', 'A QTc over 500 ms, especially rising on QT-prolonging drugs, predisposes to torsades de pointes; the drugs should be held and the provider notified.', '{"options":[{"id":"A","text":"Hold the QT-prolonging medications and notify the provider"},{"id":"B","text":"Continue the medications and repeat the ECG in 24 hours"},{"id":"C","text":"Administer a beta-blocker to slow the heart rate"},{"id":"D","text":"Place the client in high-Fowler position"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A QTc above 500 ms markedly raises the risk of torsades de pointes; the offending drugs must be stopped.","B":"Incorrect. Waiting a day risks a lethal arrhythmia.","C":"Incorrect. This does not address the drug-induced QT prolongation and is not ordered.","D":"Incorrect. Positioning does not reduce arrhythmia risk here."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'ECG monitoring', 'Prolonged QT', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364003', 'MCQ', 'During a colonoscopy under moderate sedation with midazolam and fentanyl, the client''s SpO2 falls to 88%, respiratory rate is 8/min, and the client is difficult to arouse. After stopping sedation and supporting the airway, which medication should the nurse anticipate administering FIRST?', 'The bradypnea and depressed arousal reflect opioid effect; naloxone reverses fentanyl-induced respiratory depression.', '{"options":[{"id":"A","text":"Flumazenil"},{"id":"B","text":"Naloxone"},{"id":"C","text":"Atropine"},{"id":"D","text":"Epinephrine"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Flumazenil reverses benzodiazepines but carries seizure risk and is not the first reversal given the opioid-dominant hypoventilation pattern.","B":"Correct. Opioid-induced respiratory depression (slow rate, hypoxia, hard to arouse) is reversed with naloxone as the priority.","C":"Incorrect. Atropine treats bradycardia, not respiratory depression.","D":"Incorrect. There is no anaphylaxis or arrest indication."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Moderate sedation', 'Respiratory monitoring', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364004', 'MCQ', 'Thirty-six hours after open reduction of a femur fracture, a client becomes confused and dyspneic with SpO2 89% and a petechial rash over the chest. Which complication should the nurse suspect?', 'Fat embolism after long-bone fracture presents with the classic triad of hypoxemia, mental status change, and petechiae within 72 hours.', '{"options":[{"id":"A","text":"Fat embolism syndrome"},{"id":"B","text":"Wound dehiscence"},{"id":"C","text":"Hypovolemic shock"},{"id":"D","text":"Atelectasis"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The triad of hypoxia, neurologic change, and petechiae 24-72 hours after a long-bone fracture is classic for fat embolism.","B":"Incorrect. Dehiscence presents as wound separation, not respiratory-neurologic findings.","C":"Incorrect. Shock would not cause petechiae over the chest.","D":"Incorrect. Atelectasis causes hypoxia but not petechiae or acute confusion."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Postoperative complications', 'Fat embolism', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364005', 'MCQ', 'Before administering medication through a newly inserted nasogastric tube, which method most reliably confirms correct placement?', 'X-ray is the gold standard to confirm initial NG tube placement; auscultation and other bedside checks are unreliable.', '{"options":[{"id":"A","text":"Review of the post-insertion chest/abdominal X-ray"},{"id":"B","text":"Auscultation of air insufflated into the tube"},{"id":"C","text":"Absence of coughing during insertion"},{"id":"D","text":"Ability to instill 30 mL of water without resistance"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Radiographic confirmation is the gold standard for verifying initial NG tube placement before use.","B":"Incorrect. The air-bolus/auscultation method is unreliable and no longer recommended.","C":"Incorrect. A tube can enter the airway without coughing, especially in sedated clients.","D":"Incorrect. Absence of resistance does not confirm gastric placement."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'GI', 'NG tube', 'Placement verification', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364006', 'MCQ', 'A client receiving IV vancomycin reports burning at the IV site. The nurse finds the site cool, pale, and swollen with a sluggish infusion and no blood return. Which is the priority action?', 'Coolness, pallor, edema, and absent blood return indicate infiltration; stopping the infusion and removing the catheter prevents further tissue injury.', '{"options":[{"id":"A","text":"Stop the infusion and remove the catheter"},{"id":"B","text":"Apply warm compresses and continue the infusion"},{"id":"C","text":"Slow the infusion rate and reassess in one hour"},{"id":"D","text":"Flush the catheter briskly with 10 mL of saline"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cool, pale, swollen tissue with no blood return indicates infiltration; the infusion must be stopped and the catheter removed to prevent tissue damage.","B":"Incorrect. Continuing infusion into infiltrated tissue worsens injury.","C":"Incorrect. The catheter is no longer in the vein; slowing does not fix infiltration.","D":"Incorrect. Flushing pushes more fluid into the tissue."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Infiltration vs phlebitis', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364007', 'MCQ', 'A laboring client''s fetal monitor shows repetitive decelerations that begin after the peak of each contraction and return to baseline after the contraction ends. After repositioning, which action should the nurse take FIRST?', 'Late decelerations reflect uteroplacental insufficiency; discontinuing oxytocin plus intrauterine resuscitation measures improves fetal oxygenation.', '{"options":[{"id":"A","text":"Discontinue the oxytocin infusion"},{"id":"B","text":"Increase the oxytocin to speed delivery"},{"id":"C","text":"Document the reassuring pattern and continue monitoring"},{"id":"D","text":"Prepare for immediate amnioinfusion"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The pattern is late decelerations indicating uteroplacental insufficiency; stopping oxytocin reduces contraction stress and improves perfusion.","B":"Incorrect. More contractions worsen uteroplacental insufficiency.","C":"Incorrect. Late decelerations are nonreassuring, not reassuring.","D":"Incorrect. Amnioinfusion treats variable, not late, decelerations."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive', 'Fetal monitoring', 'Late decelerations', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364008', 'MCQ', 'A client is scheduled for a contrast-enhanced CT. Which pre-procedure finding most requires the nurse to notify the provider before the study?', 'A creatinine of 2.4 mg/dL indicates renal impairment and heightened risk of contrast-induced nephropathy, warranting provider notification and possible mitigation.', '{"options":[{"id":"A","text":"Serum creatinine 2.4 mg/dL"},{"id":"B","text":"Blood pressure 138/84 mmHg"},{"id":"C","text":"Reported allergy to latex"},{"id":"D","text":"Fasting for 6 hours before the study"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Elevated creatinine signals impaired renal function and high risk for contrast-induced nephropathy; the provider must be notified.","B":"Incorrect. This is mildly elevated and not a contraindication.","C":"Incorrect. Latex allergy is managed but is not related to contrast risk.","D":"Incorrect. Fasting is appropriate preparation."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Diagnostic-test monitoring', 'Contrast-induced nephropathy', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364009', 'MCQ', 'A client on warfarin for atrial fibrillation reports dark stools and gum bleeding. The INR is 6.8. Which intervention should the nurse anticipate FIRST?', 'An INR of 6.8 with bleeding is a warfarin emergency; warfarin is held and vitamin K (with possible PCC) is given to reverse anticoagulation.', '{"options":[{"id":"A","text":"Hold warfarin and administer prescribed vitamin K"},{"id":"B","text":"Administer the next scheduled warfarin dose"},{"id":"C","text":"Administer protamine sulfate"},{"id":"D","text":"Encourage foods high in vitamin K to correct the INR gradually"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A markedly elevated INR with active bleeding requires holding warfarin and reversing with vitamin K.","B":"Incorrect. Continuing warfarin worsens the over-anticoagulation.","C":"Incorrect. Protamine reverses heparin, not warfarin.","D":"Incorrect. Dietary change is far too slow for active bleeding."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Pharmacology', 'Hematologic', 'Lab-value interpretation', 'INR and warfarin', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364010', 'MCQ', 'A client has had an indwelling urinary catheter for 5 days. Which nursing action best reduces the client''s risk of a catheter-associated urinary tract infection?', 'Daily review for catheter necessity and early removal is the most effective CAUTI-prevention strategy.', '{"options":[{"id":"A","text":"Assess daily whether the catheter can be removed"},{"id":"B","text":"Irrigate the catheter with saline every shift"},{"id":"C","text":"Change the catheter routinely every 48 hours"},{"id":"D","text":"Elevate the drainage bag to the level of the bladder"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Prompt removal when no longer indicated is the single most effective measure to prevent CAUTI.","B":"Incorrect. Routine irrigation increases infection risk by breaking the closed system.","C":"Incorrect. Routine scheduled changes are not recommended and add risk.","D":"Incorrect. The bag must stay below the bladder to prevent backflow."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Urinary catheter', 'CAUTI prevention', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_364011', 'MCQ', 'During preoperative teaching for elective surgery, a client lists current medications. Which statement requires the nurse to notify the surgical team before the procedure?', 'Clopidogrel is an antiplatelet agent that increases perioperative bleeding; taking it the day of surgery must be reported to the surgical team.', '{"options":[{"id":"A","text":"\"I took my usual clopidogrel this morning.\""},{"id":"B","text":"\"I stopped my multivitamin two days ago.\""},{"id":"C","text":"\"I took my morning levothyroxine with a sip of water.\""},{"id":"D","text":"\"I used my albuterol inhaler before coming in.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Antiplatelet therapy taken the day of surgery raises bleeding risk and must be reported so the team can decide on timing.","B":"Incorrect. A multivitamin is not a bleeding concern.","C":"Incorrect. Levothyroxine is typically continued and is not a bleeding risk.","D":"Incorrect. Albuterol is appropriate and not a surgical bleeding risk."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Preoperative education', 'Anticoagulant management', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_364012', 'SATA', 'A nurse plans venous thromboembolism prevention for a postoperative client with sequential compression devices ordered. Which actions are appropriate? Select all that apply.', 'SCDs plus assessment, early ambulation, and screening for contraindications reduce VTE risk; massage and prolonged immobility are unsafe.', '{"options":[{"id":"A","text":"Ensure the compression sleeves are removed only briefly for hygiene"},{"id":"B","text":"Assess the calves for warmth, redness, and unilateral swelling each shift"},{"id":"C","text":"Encourage early ambulation as tolerated"},{"id":"D","text":"Vigorously massage the calves to promote venous return"},{"id":"E","text":"Confirm no contraindication such as an existing DVT before applying"},{"id":"F","text":"Keep the client on strict bed rest to protect the surgical site"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"D":"Incorrect. Massaging the calves can dislodge a clot.","F":"Incorrect. Immobility increases VTE risk."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Injury/complication prevention', 'VTE prophylaxis', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_364013', 'SATA', 'A nurse is drawing blood cultures for a client with suspected sepsis. Which actions ensure accurate, uncontaminated results? Select all that apply.', 'Cultures drawn before antibiotics, with proper skin/bottle antisepsis and two separate sites, yield accurate results with minimal contamination.', '{"options":[{"id":"A","text":"Obtain the cultures before starting antibiotics when possible"},{"id":"B","text":"Disinfect the venipuncture site and let it dry fully"},{"id":"C","text":"Collect two sets from separate sites"},{"id":"D","text":"Draw all cultures from the existing peripheral IV catheter for convenience"},{"id":"E","text":"Scrub the tops of the culture bottles with antiseptic before inoculating"},{"id":"F","text":"Fill the anaerobic bottle first to maximize oxygen exposure"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"D":"Incorrect. Drawing from an indwelling line increases contamination risk.","F":"Incorrect. Order and technique matter; deliberately exposing to oxygen is incorrect, and the aerobic bottle is typically filled first with a syringe draw."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Immune', 'Blood/specimen collection', 'Blood cultures', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_364014', 'SATA', 'A nurse reviews serial data on a postoperative client. Which trends suggest early sepsis and warrant escalation? Select all that apply.', 'A rising temperature, tachycardia, tachypnea, and falling blood pressure form the classic trend of early sepsis that warrants rapid escalation.', '{"options":[{"id":"A","text":"Temperature rising from 37.0°C to 38.6°C over 4 hours"},{"id":"B","text":"Heart rate climbing from 82 to 112 bpm"},{"id":"C","text":"Respiratory rate increasing from 16 to 24/min"},{"id":"D","text":"Blood pressure falling from 122/78 to 98/56 mmHg"},{"id":"E","text":"Urine output steady at 60 mL/hr"},{"id":"F","text":"Oxygen saturation stable at 98% on room air"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"E":"Incorrect. This is normal, reassuring output.","F":"Incorrect. Stable normal saturation is not a warning trend."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Trend recognition', 'Early sepsis', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_364015', 'SATA', 'A nurse administers a continuous feeding through a client''s percutaneous endoscopic gastrostomy tube. Which actions reduce the risk of aspiration and complications? Select all that apply.', 'Head-of-bed elevation, residual checks, flushing, and site assessment prevent aspiration and occlusion; lying flat and crushing enteric-coated drugs are contraindicated.', '{"options":[{"id":"A","text":"Keep the head of the bed elevated at least 30 to 45 degrees"},{"id":"B","text":"Check gastric residual volume per protocol"},{"id":"C","text":"Flush the tube with water before and after medications"},{"id":"D","text":"Lay the client flat during feeding to reduce reflux"},{"id":"E","text":"Verify tube patency and site integrity each shift"},{"id":"F","text":"Crush enteric-coated tablets to pass through the tube"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"D":"Incorrect. Lying flat increases aspiration risk.","F":"Incorrect. Crushing enteric-coated or extended-release tablets is unsafe."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'GI', 'Percutaneous feeding tube', 'Aspiration prevention', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_364016', 'SATA', 'A postoperative client has a continuous epidural infusion of an opioid and local anesthetic. Which assessment findings require immediate nursing intervention? Select all that apply.', 'Respiratory depression, dense motor block, deep sedation, and hypotension are dangerous epidural complications requiring immediate action.', '{"options":[{"id":"A","text":"Respiratory rate of 7/min"},{"id":"B","text":"Inability to move the lower extremities"},{"id":"C","text":"Sedation scale score indicating the client is difficult to arouse"},{"id":"D","text":"Numbness limited to the surgical dermatome"},{"id":"E","text":"Blood pressure dropping from 124/80 to 88/50 mmHg"},{"id":"F","text":"Mild itching relieved by repositioning"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"D":"Incorrect. Expected sensory block at the surgical level is anticipated.","F":"Incorrect. Mild pruritus is a common, non-urgent opioid effect."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Neurological', 'Postoperative assessment', 'Epidural analgesia', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_364017', 'SELECT_N', 'A nurse reviews morning labs for four assigned clients. Which 3 results represent critical values requiring immediate provider notification?', 'Severe hyperkalemia, profound hyponatremia, and severe thrombocytopenia are critical values demanding immediate notification; the others are mildly abnormal or normal.', '{"options":[{"id":"A","text":"Serum potassium 6.9 mEq/L"},{"id":"B","text":"Serum sodium 118 mEq/L"},{"id":"C","text":"Platelet count 18,000/mm3"},{"id":"D","text":"Hemoglobin 11.2 g/dL"},{"id":"E","text":"Serum glucose 130 mg/dL"},{"id":"F","text":"White blood cell count 8,500/mm3"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Lab-value interpretation', 'Critical values', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_364018', 'TF', 'An arterial blood gas showing pH 7.31, PaCO2 58 mmHg, and HCO3 26 mEq/L indicates uncompensated metabolic acidosis.', 'The low pH with an elevated PaCO2 and near-normal bicarbonate indicates uncompensated respiratory acidosis, not metabolic acidosis.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Diagnostic-test monitoring', 'Arterial blood gas', 'Hard', NULL, '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_364019', 'MATRIX', 'For each laboratory result, click to indicate whether it is within normal limits or abnormal for an adult.', 'Creatinine 0.9 and potassium 4.0 are normal; an INR of 5.5, calcium of 6.4, and magnesium of 1.1 are abnormal and warrant follow-up.', '{"row_label":"Lab result","rows":[{"id":"r1","text":"Serum creatinine 0.9 mg/dL"},{"id":"r2","text":"INR 5.5 on warfarin"},{"id":"r3","text":"Serum calcium 6.4 mg/dL"},{"id":"r4","text":"Potassium 4.0 mEq/L"},{"id":"r5","text":"Magnesium 1.1 mEq/L"}],"columns":[{"id":"c1","text":"Within normal limits"},{"id":"c2","text":"Abnormal"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c2","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Lab-value interpretation', 'Recognizing abnormal values', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_364020', 'MATRIX_MR', 'For each diagnostic procedure, select all appropriate pre-procedure nursing actions.', 'Consent is required for invasive procedures, NPO applies to sedation/contrast studies, and iodine/shellfish allergy screening applies to contrast-based tests.', '{"row_label":"Procedure","rows":[{"id":"r1","text":"Cardiac catheterization with contrast"},{"id":"r2","text":"Colonoscopy with moderate sedation"},{"id":"r3","text":"CT with IV contrast"},{"id":"r4","text":"Lumbar puncture"}],"columns":[{"id":"c1","text":"Verify informed consent"},{"id":"c2","text":"Confirm NPO status"},{"id":"c3","text":"Assess for iodine/shellfish allergy"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c1","c2"],"r3":["c2","c3"],"r4":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Response to procedures/treatments', 'Pre-procedure preparation', 'Hard', 'Apply', '{}', 8, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_364021', 'CLOZE', 'A telemetry strip shows no identifiable P waves, an irregularly irregular rhythm, and a ventricular rate of 140/min. The nurse interprets this as {1}, and the priority concern for this client is {2}.', 'Absent P waves with an irregularly irregular rapid rhythm indicate atrial fibrillation with RVR, which risks clot formation, embolic stroke, and reduced cardiac output.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"atrial fibrillation with rapid ventricular response"},{"id":"c2","text":"sinus tachycardia"},{"id":"c3","text":"third-degree heart block"}]},{"id":"b2","choices":[{"id":"c1","text":"thromboembolic stroke and decreased cardiac output"},{"id":"c2","text":"hyperkalemia"},{"id":"c3","text":"hypoglycemia"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'In-scope testing (ECG)', 'Rhythm interpretation', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_364022', 'HIGHLIGHT', 'Highlight the assessment findings that require immediate follow-up in this postoperative client. The client is drowsy but rousable. Temperature [[37.1°C]]. Respiratory rate [[8/min]]. SpO2 [[86% on room air]]. Blood pressure [[104/68]]. Pain score [[3 out of 10]]. New [[decreased breath sounds at the left base]]. Capillary refill [[2 seconds]].', 'Bradypnea, hypoxemia, and new decreased breath sounds indicate respiratory deterioration requiring immediate follow-up; the other findings are normal.', '{"chunks":[{"id":"h1","text":"37.1°C"},{"id":"h2","text":"8/min"},{"id":"h3","text":"86% on room air"},{"id":"h4","text":"104/68"},{"id":"h5","text":"3 out of 10"},{"id":"h6","text":"decreased breath sounds at the left base"},{"id":"h7","text":"2 seconds"}]}'::jsonb, '{"correct_ids":["h2","h3","h6"],"feedback":{"h1":"Normal temperature.","h2":"Bradypnea suggests opioid-induced respiratory depression.","h3":"Significant hypoxemia requiring intervention.","h4":"Blood pressure is within acceptable limits.","h5":"Mild, controlled pain.","h6":"New finding suggesting atelectasis or effusion.","h7":"Normal capillary refill."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Trend recognition', 'Postoperative deterioration', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_364023', 'BOWTIE', 'A client 2 days after total hip replacement suddenly develops pleuritic chest pain, dyspnea, tachycardia, and SpO2 84%. Complete the diagram by selecting the actions to take, the condition, and the parameters to monitor.', 'Sudden dyspnea, pleuritic pain, tachycardia, and hypoxia after orthopedic surgery indicate pulmonary embolism; oxygen and rapid notification are priorities while monitoring oxygenation and respiratory status.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Apply supplemental oxygen"},{"id":"lt2","text":"Notify the provider immediately"},{"id":"lt3","text":"Encourage vigorous leg exercises"},{"id":"lt4","text":"Have the client ambulate to relieve the pain"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Pulmonary embolism"},{"id":"ct2","text":"Myocardial infarction"},{"id":"ct3","text":"Pneumothorax"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Oxygen saturation"},{"id":"rt2","text":"Respiratory rate and effort"},{"id":"rt3","text":"Bowel sounds"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Complication prevention', 'Pulmonary embolism', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_364024', 'DRAG_ORDER', 'Fifteen minutes into a packed red blood cell transfusion, a client develops fever, chills, flank pain, and dark urine. Place the nurse''s actions in the correct priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"},{"id":"s6","target_text":"6th action"}],"tokens":[{"id":"t1","text":"Stop the transfusion immediately"},{"id":"t2","text":"Keep the IV line open with normal saline using new tubing"},{"id":"t3","text":"Assess the client and check vital signs"},{"id":"t4","text":"Notify the provider and blood bank"},{"id":"t5","text":"Send the blood bag and tubing to the laboratory"},{"id":"t6","text":"Document the reaction and interventions"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5","s6":"t6"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Response to treatments', 'Transfusion reaction', 'Hard', 'Apply', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365001', 'MCQ', 'A client with chronic kidney disease has these morning labs: potassium 6.4 mEq/L, BUN 48 mg/dL, creatinine 4.1 mg/dL, and calcium 7.8 mg/dL. The nurse reviews the telemetry strip. Which finding most warrants immediate provider notification?', 'Hyperkalemia with peaked T waves indicates imminent risk of lethal dysrhythmia and takes priority over the other chronic derangements.', '{"options":[{"id":"A","text":"Peaked T waves on the ECG"},{"id":"B","text":"BUN of 48 mg/dL"},{"id":"C","text":"Calcium of 7.8 mg/dL"},{"id":"D","text":"Creatinine of 4.1 mg/dL"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Peaked T waves signal hyperkalemia-induced cardiac instability, the most life-threatening cue.","B":"Incorrect. Elevated BUN is expected in CKD and is not the acute threat.","C":"Incorrect. Mild hypocalcemia is common in CKD but not immediately life-threatening here.","D":"Incorrect. Chronic elevation reflects baseline renal impairment, not an acute emergency."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Lab-value interpretation', 'Potassium', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365002', 'MCQ', 'Two hours after a bronchoscopy with moderate sedation, a client requests something to drink. Which assessment finding must the nurse confirm BEFORE offering fluids?', 'Pharyngeal anesthesia used in bronchoscopy blunts the gag reflex; confirming its return prevents aspiration before oral intake.', '{"options":[{"id":"A","text":"Return of the gag reflex"},{"id":"B","text":"Absence of hemoptysis"},{"id":"C","text":"Oxygen saturation above 90%"},{"id":"D","text":"Blood pressure at baseline"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Topical anesthetic suppresses the gag reflex; its return prevents aspiration.","B":"Incorrect. Important to monitor, but not the specific prerequisite for oral intake.","C":"Incorrect. Relevant to recovery but does not determine swallowing safety.","D":"Incorrect. Hemodynamic stability is expected but is not the aspiration safeguard."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Post-procedure monitoring', 'Bronchoscopy', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365003', 'MCQ', 'Following a femoral cardiac catheterization, a client''s assessment reveals: pedal pulses 1+ bilaterally (were 2+ preprocedure), a dressing dry and intact, BP 96/58 mmHg (was 128/76), and complaints of low back pain. Which finding most strongly suggests a retroperitoneal bleed?', 'Retroperitoneal hemorrhage after femoral access presents with unexplained hypotension and flank/back pain despite an intact external site.', '{"options":[{"id":"A","text":"Falling blood pressure with new back pain"},{"id":"B","text":"Pedal pulses that are 1+ bilaterally"},{"id":"C","text":"A dressing that is dry and intact"},{"id":"D","text":"The client''s request to reposition"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Hypotension plus flank or back pain is the classic presentation of retroperitoneal hemorrhage.","B":"Incorrect. Symmetric diminished pulses can reflect vasospasm or hypotension, not focal bleeding into the retroperitoneum.","C":"Incorrect. A retroperitoneal bleed tracks internally, so the external site often stays dry.","D":"Incorrect. Repositioning discomfort is nonspecific."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Diagnostic-test monitoring', 'Cardiac catheterization', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365004', 'MCQ', 'A nurse prepares to administer medications through a newly inserted nasogastric tube. The most reliable bedside method to verify placement before use is to:', 'Radiographic confirmation is the standard for verifying a newly placed NG tube before instilling anything through it.', '{"options":[{"id":"A","text":"Review the radiographic confirmation of tip position"},{"id":"B","text":"Auscultate air insufflated into the stomach"},{"id":"C","text":"Confirm the external tube length matches insertion"},{"id":"D","text":"Aspirate gastric contents and note the volume"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. X-ray is the gold standard for verifying initial NG placement before first use.","B":"Incorrect. The air-bolus ''whoosh'' test is unreliable and no longer recommended.","C":"Incorrect. Length checks help monitor migration but do not verify initial placement.","D":"Incorrect. Aspirate pH can support placement, but radiography is required for a new tube."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG/GI tube', 'Placement verification', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365005', 'MCQ', 'A client on a continuous heparin infusion has an aPTT result of 110 seconds (therapeutic range 60-80 seconds) and no active bleeding. Which action should the nurse take FIRST?', 'A markedly supratherapeutic aPTT calls for holding the heparin first to limit bleeding risk, then adjusting per the nomogram.', '{"options":[{"id":"A","text":"Stop the heparin infusion"},{"id":"B","text":"Administer protamine sulfate"},{"id":"C","text":"Draw a repeat aPTT immediately"},{"id":"D","text":"Decrease the rate and continue infusing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A supratherapeutic aPTT raises bleeding risk; pausing the infusion per protocol is the priority safety action.","B":"Incorrect. Protamine is reserved for active hemorrhage or per order, not a first response to an isolated high aPTT.","C":"Incorrect. Rechecking delays reducing the bleeding risk from ongoing infusion.","D":"Incorrect. Protocols typically require holding, not merely slowing, at this level."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Pharmacology', 'Hematologic', 'Lab-value interpretation', 'Anticoagulation', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365006', 'MCQ', 'A laboring client''s fetal monitor shows recurrent late decelerations with minimal variability. After repositioning the client to the left side, the pattern persists. Which action should the nurse take NEXT?', 'Recurrent late decelerations reflect uteroplacental insufficiency; when position change fails, discontinuing oxytocin is the next intrauterine resuscitation step.', '{"options":[{"id":"A","text":"Discontinue the oxytocin infusion"},{"id":"B","text":"Increase the oxytocin to speed delivery"},{"id":"C","text":"Document the reassuring tracing"},{"id":"D","text":"Prepare for immediate amniotomy"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Persistent late decelerations indicate uteroplacental insufficiency; stopping oxytocin reduces uterine activity and improves perfusion.","B":"Incorrect. More oxytocin worsens the insult by increasing uterine activity.","C":"Incorrect. Late decelerations with minimal variability are non-reassuring.","D":"Incorrect. Amniotomy does not address uteroplacental insufficiency."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive', 'Fetal monitoring', 'Decelerations', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365007', 'MCQ', 'A client in diabetic ketoacidosis is receiving an insulin infusion. The most recent labs show glucose 248 mg/dL (down from 520) and potassium 3.2 mEq/L. Which action is the priority?', 'Insulin therapy in DKA shifts potassium into cells; a level of 3.2 mEq/L requires replacement before it precipitates arrhythmia.', '{"options":[{"id":"A","text":"Notify the provider and anticipate potassium replacement"},{"id":"B","text":"Stop the insulin infusion because glucose is falling"},{"id":"C","text":"Administer a 50% dextrose bolus"},{"id":"D","text":"Restrict IV fluids to prevent cerebral edema"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Insulin drives potassium intracellularly; hypokalemia during DKA treatment risks fatal dysrhythmia and must be corrected.","B":"Incorrect. Insulin continues until the anion gap closes; dextrose is added as glucose falls.","C":"Incorrect. A bolus is not indicated at 248 mg/dL.","D":"Incorrect. Fluid resuscitation remains part of DKA management."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Lab-value interpretation', 'Glucose', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365008', 'MCQ', 'A client with a fresh tibial cast reports pain unrelieved by opioids and a tingling sensation in the toes. The toes are pink with capillary refill under 3 seconds and pulses are present. Which interpretation is most accurate?', 'Pain out of proportion and paresthesia are the earliest signs of compartment syndrome; pulselessness and pallor appear late, so intact pulses are falsely reassuring.', '{"options":[{"id":"A","text":"Early compartment syndrome may be developing"},{"id":"B","text":"Findings are normal because pulses and color are intact"},{"id":"C","text":"The client is exhibiting drug-seeking behavior"},{"id":"D","text":"The cast simply needs additional padding"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Escalating pain and paresthesia precede pulselessness; intact pulses do not rule out compartment syndrome.","B":"Incorrect. Pulses are a late sign; normal perfusion does not exclude rising compartment pressure.","C":"Incorrect. Disproportionate pain is a hallmark warning sign, not manipulation.","D":"Incorrect. Padding does not address an evolving emergency."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Musculoskeletal', 'Complication prevention', 'Compartment syndrome', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365009', 'MCQ', 'A nurse assesses a postoperative client wearing sequential compression devices. Which finding requires the SCDs to be removed and the provider notified?', 'Signs of an existing DVT contraindicate mechanical compression, which could dislodge the clot; remove the SCDs and notify the provider.', '{"options":[{"id":"A","text":"New unilateral calf swelling, warmth, and tenderness"},{"id":"B","text":"Mild diaphoresis under the sleeves"},{"id":"C","text":"Intermittent inflation cycling of the sleeves"},{"id":"D","text":"The client reports the sleeves feel snug"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These are signs of an established DVT; compressing the limb could dislodge a thrombus and cause embolism.","B":"Incorrect. Moisture is a comfort issue, addressed with skin care, not removal for emergency.","C":"Incorrect. Cyclic inflation is normal device function.","D":"Incorrect. A snug fit is expected; this alone is not an alert."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Venous-return devices', 'Antiembolism', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365010', 'MCQ', 'A nurse monitors a client with a head injury over four hours. Which trend of vital signs most strongly indicates rising intracranial pressure?', 'Cushing''s triad, widening pulse pressure with bradycardia and irregular respirations, signals dangerously elevated intracranial pressure.', '{"options":[{"id":"A","text":"Widening pulse pressure, bradycardia, and irregular respirations"},{"id":"B","text":"Narrowing pulse pressure, tachycardia, and hypotension"},{"id":"C","text":"Rising temperature with a stable blood pressure"},{"id":"D","text":"Tachypnea with an unchanged pulse pressure"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This is Cushing''s triad, a late and ominous sign of increased ICP.","B":"Incorrect. This pattern suggests hypovolemic shock, not increased ICP.","C":"Incorrect. Fever alone does not indicate ICP changes.","D":"Incorrect. Isolated tachypnea is nonspecific."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Neurological', 'Vital-sign trends', 'Increased ICP', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_365011', 'MCQ', 'A client is scheduled for a contrast-enhanced CT. The nurse reviews the record for the finding that most increases the risk of contrast-induced nephropathy. Which lab result is most concerning?', 'Elevated creatinine indicating baseline renal impairment is the dominant risk factor for contrast-induced nephropathy and warrants hydration/holding nephrotoxins.', '{"options":[{"id":"A","text":"Serum creatinine 2.3 mg/dL"},{"id":"B","text":"Hemoglobin 11.5 g/dL"},{"id":"C","text":"Fasting glucose 118 mg/dL"},{"id":"D","text":"Sodium 138 mEq/L"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Pre-existing renal impairment is the strongest risk factor for contrast-induced nephropathy.","B":"Incorrect. Mild anemia does not drive contrast nephrotoxicity.","C":"Incorrect. Mild hyperglycemia is not the primary risk here.","D":"Incorrect. A normal sodium is unrelated to contrast nephropathy risk."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Diagnostic-test monitoring', 'Contrast media', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_365012', 'SATA', 'A nurse assesses a client 8 hours after abdominal surgery. Which findings require immediate follow-up? Select all that apply.', 'Oliguria, a rigid tender abdomen, and hypoxemia are red flags for hemorrhage, peritonitis, and respiratory compromise requiring urgent action.', '{"options":[{"id":"A","text":"Urine output of 18 mL over the past hour"},{"id":"B","text":"Rigid, distended abdomen with rebound tenderness"},{"id":"C","text":"Oxygen saturation of 88% on room air"},{"id":"D","text":"Serosanguineous drainage lightly staining the dressing"},{"id":"E","text":"Blood pressure 108/68 mmHg"},{"id":"F","text":"Pain rated 5 of 10 relieved by prescribed analgesia"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Oliguria may indicate hypovolemia or evolving shock.","B":"Correct. Suggests internal bleeding or peritonitis.","C":"Correct. Hypoxemia requires prompt intervention.","D":"Incorrect. Small amounts of serosanguineous drainage are expected early postoperatively.","E":"Incorrect. This is within an acceptable range.","F":"Incorrect. Controlled incisional pain is expected."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Post-operative care', 'Complication recognition', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_365013', 'SATA', 'Fifteen minutes into a packed red blood cell transfusion, a client develops findings suggesting an acute hemolytic reaction. Which actions should the nurse take? Select all that apply.', 'Acute hemolytic reaction requires stopping the blood, maintaining saline through fresh tubing, and notifying the provider and blood bank while preserving the unit for testing.', '{"options":[{"id":"A","text":"Stop the transfusion immediately"},{"id":"B","text":"Keep the IV line open with normal saline via new tubing"},{"id":"C","text":"Notify the provider and the blood bank"},{"id":"D","text":"Continue the transfusion at a slower rate"},{"id":"E","text":"Administer the next scheduled dose of the client''s oral iron"},{"id":"F","text":"Discard the blood bag and tubing in the sharps bin"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Halting the infusion limits the volume of incompatible blood.","B":"Correct. Saline maintains access and supports renal perfusion without adding more blood.","C":"Correct. Both must be alerted and the unit returned for analysis.","D":"Incorrect. Any continued infusion worsens hemolysis.","E":"Incorrect. Irrelevant and delays the emergency response.","F":"Incorrect. The unit and tubing must be saved and returned to the blood bank."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Pharmacology', 'Hematologic', 'Blood-product administration', 'Transfusion reaction', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_365014', 'SATA', 'A nurse cares for a client with an indwelling urinary catheter. Which actions reduce the risk of catheter-associated urinary tract infection? Select all that apply.', 'Dependent drainage, a closed system, and prompt removal are core CAUTI-prevention practices; irrigation, floor contact, and disconnection increase risk.', '{"options":[{"id":"A","text":"Keep the drainage bag below the level of the bladder"},{"id":"B","text":"Maintain a closed drainage system"},{"id":"C","text":"Perform daily assessment of continued catheter need"},{"id":"D","text":"Routinely irrigate the catheter with saline every shift"},{"id":"E","text":"Rest the drainage bag on the floor for stability"},{"id":"F","text":"Disconnect the tubing to obtain sterile samples"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. This prevents reflux of urine back into the bladder.","B":"Correct. Breaking the closed system introduces pathogens.","C":"Correct. Early removal is the most effective CAUTI-prevention measure.","D":"Incorrect. Routine irrigation breaks the closed system and increases infection risk.","E":"Incorrect. Floor contact contaminates the system.","F":"Incorrect. Samples are drawn from the sampling port, not by disconnecting."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Urinary catheter', 'CAUTI prevention', 'Hard', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_365015', 'SATA', 'A nurse provides preoperative teaching to reduce the risk of postoperative pulmonary complications. Which instructions should be included? Select all that apply.', 'Incentive spirometry, splinted coughing, and early mobility prevent atelectasis and pneumonia; immobility, shallow breathing, and fluid restriction worsen risk.', '{"options":[{"id":"A","text":"Use the incentive spirometer 10 breaths every hour while awake"},{"id":"B","text":"Splint the incision with a pillow when coughing"},{"id":"C","text":"Change position and ambulate early as permitted"},{"id":"D","text":"Avoid deep breathing to minimize incisional pain"},{"id":"E","text":"Remain flat and still to protect the surgical site"},{"id":"F","text":"Limit fluids to reduce respiratory secretions"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Sustained maximal inspiration prevents atelectasis.","B":"Correct. Splinting supports effective coughing and airway clearance.","C":"Correct. Mobility promotes lung expansion and secretion clearance.","D":"Incorrect. Shallow breathing promotes atelectasis.","E":"Incorrect. Immobility increases pulmonary and thromboembolic risk.","F":"Incorrect. Adequate hydration keeps secretions thin and clearable."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Pre-operative education', 'Complication prevention', 'Hard', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_365016', 'SATA', 'A nurse monitors a client receiving moderate sedation for a procedure. Which findings indicate the client is oversedated and require intervention? Select all that apply.', 'Bradypnea, desaturation, and loss of responsiveness signal oversedation and respiratory compromise; a purposeful response with stable vitals is the desired level.', '{"options":[{"id":"A","text":"Respiratory rate of 7 breaths per minute"},{"id":"B","text":"Oxygen saturation dropping to 88%"},{"id":"C","text":"Unresponsiveness to loud verbal stimuli"},{"id":"D","text":"Ability to respond to name with light touch"},{"id":"E","text":"Blood pressure of 118/72 mmHg"},{"id":"F","text":"Heart rate of 78 beats per minute"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Respiratory depression is the primary danger of oversedation.","B":"Correct. Desaturation reflects hypoventilation.","C":"Correct. Loss of purposeful response indicates deeper-than-intended sedation.","D":"Incorrect. Purposeful response is the goal of moderate sedation.","E":"Incorrect. This is a stable, normal reading.","F":"Incorrect. A normal rate is not a warning sign."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Moderate sedation', 'Monitoring', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_365017', 'SELECT_N', 'A nurse reviews serial vital signs on four assigned clients. Select the 3 findings that represent a deteriorating trend requiring escalation.', 'A rising respiratory rate, a falling MAP, and new confusion are classic early-warning cues of clinical deterioration requiring rapid escalation.', '{"options":[{"id":"A","text":"Respiratory rate rising from 18 to 28 over three sets"},{"id":"B","text":"MAP falling from 78 to 60 mmHg across two hours"},{"id":"C","text":"New confusion in a previously alert client"},{"id":"D","text":"Temperature steady at 37.1°C"},{"id":"E","text":"Heart rate steady at 74 beats per minute"},{"id":"F","text":"SpO2 stable at 97% on room air"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. A climbing respiratory rate is an early sensitive marker of deterioration.","B":"Correct. A dropping MAP threatens organ perfusion.","C":"Correct. Acute mentation change signals hypoperfusion or hypoxia.","D":"Incorrect. A stable normal temperature is reassuring.","E":"Incorrect. An unchanged normal heart rate is not concerning.","F":"Incorrect. Normal, stable oxygenation is not a red flag."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Vital-sign trends', 'Early warning', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_365018', 'TF', 'When a peripheral IV site becomes cool, swollen, and pale with a sluggish infusion, the nurse should first raise the infusion rate to overcome the resistance before assessing the site.', 'These signs indicate infiltration; the infusion must be stopped and the catheter removed, not accelerated, which would worsen tissue injury.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Infiltration vs extravasation', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_365019', 'MATRIX', 'For each laboratory result, click to indicate whether it is within the expected range or a critical value requiring immediate action.', 'Severe hyponatremia, profound thrombocytopenia, and hypoglycemia are critical values, whereas the normal hemoglobin and potassium require no urgent action.', '{"row_label":"Lab value","rows":[{"id":"r1","text":"Sodium 118 mEq/L"},{"id":"r2","text":"Hemoglobin 13.5 g/dL"},{"id":"r3","text":"Platelets 22,000/microliter"},{"id":"r4","text":"Potassium 4.0 mEq/L"},{"id":"r5","text":"Glucose 38 mg/dL"}],"columns":[{"id":"c1","text":"Expected range"},{"id":"c2","text":"Critical value"}]}'::jsonb, '{"cells":{"r1":"c2","r2":"c1","r3":"c2","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Lab-value interpretation', 'Critical values', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_365020', 'MATRIX_MR', 'For each client scenario, select all monitoring parameters the nurse should prioritize (more than one may apply).', 'Diuretic/digoxin and DKA clients need potassium and ECG surveillance; a fresh cast needs neurovascular checks; acute chest pain warrants an ECG.', '{"row_label":"Client","rows":[{"id":"r1","text":"Client on furosemide and digoxin"},{"id":"r2","text":"Client with a newly casted forearm fracture"},{"id":"r3","text":"Client with acute chest pain and hypertension"},{"id":"r4","text":"Client in DKA on an insulin infusion"}],"columns":[{"id":"c1","text":"Serum potassium"},{"id":"c2","text":"12-lead ECG"},{"id":"c3","text":"Neurovascular checks"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c3"],"r3":["c2"],"r4":["c1","c2"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Focused assessment', 'Diagnostic monitoring', 'Hard', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_365021', 'CLOZE', 'A client with COPD has an ABG of pH 7.31, PaCO2 62 mmHg, and HCO3 30 mEq/L. The nurse interprets this as {1}, and the priority nursing concern is {2}.', 'Low pH with high PaCO2 and elevated HCO3 is partially compensated respiratory acidosis from CO2 retention, the priority concern in COPD.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"partially compensated respiratory acidosis"},{"id":"c2","text":"uncompensated metabolic alkalosis"},{"id":"c3","text":"fully compensated respiratory alkalosis"}]},{"id":"b2","choices":[{"id":"c1","text":"impaired ventilation with CO2 retention"},{"id":"c2","text":"excessive bicarbonate loss"},{"id":"c3","text":"acute hyperventilation"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Lab-value interpretation', 'Arterial blood gas', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_365022', 'HIGHLIGHT', 'Highlight the findings that indicate possible internal hemorrhage in this client 6 hours after a splenectomy. The client is [[restless and anxious]]. Temperature [[36.8°C]]. Heart rate [[126]] and rising. Blood pressure [[92/60]], down from 122/78. Skin is [[cool and clammy]]. Bowel sounds are hypoactive. Urine output [[20 mL over 2 hours]].', 'Restlessness, rising tachycardia, falling blood pressure, cool clammy skin, and oliguria together form the classic picture of hypovolemic shock from internal hemorrhage.', '{"chunks":[{"id":"h1","text":"restless and anxious"},{"id":"h2","text":"36.8°C"},{"id":"h3","text":"126"},{"id":"h4","text":"92/60"},{"id":"h5","text":"cool and clammy"},{"id":"h6","text":"20 mL over 2 hours"}]}'::jsonb, '{"correct_ids":["h1","h3","h4","h5","h6"],"feedback":{"h1":"Restlessness is an early sign of hypovolemia and hypoxia.","h2":"A normal temperature is not a sign of hemorrhage.","h3":"Rising tachycardia is a compensatory response to blood loss.","h4":"Falling blood pressure signals decompensating hypovolemia.","h5":"Cool, clammy skin reflects peripheral vasoconstriction in shock.","h6":"Oliguria indicates reduced renal perfusion from hypovolemia."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Trend recognition', 'Post-operative hemorrhage', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_365023', 'BOWTIE', 'A postoperative client with sudden dyspnea, pleuritic chest pain, tachycardia, and a SpO2 of 86% is deteriorating. Complete the diagram by selecting the actions to take, the most likely condition, and the parameters to monitor.', 'Sudden dyspnea, pleuritic pain, and hypoxemia postoperatively point to pulmonary embolism; oxygenation and positioning are priorities while monitoring SpO2 and respiratory status.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Apply high-flow oxygen"},{"id":"lt2","text":"Elevate the head of the bed"},{"id":"lt3","text":"Encourage vigorous ambulation"},{"id":"lt4","text":"Massage the affected calf"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Pulmonary embolism"},{"id":"ct2","text":"Hypoglycemia"},{"id":"ct3","text":"Urinary retention"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Oxygen saturation"},{"id":"rt2","text":"Respiratory rate and effort"},{"id":"rt3","text":"Bowel sounds"},{"id":"rt4","text":"Pupillary reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Complication recognition', 'Pulmonary embolism', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_365024', 'DRAG_ORDER', 'A nurse is about to initiate a packed red blood cell transfusion for a client with a patent IV and completed consent. Place the steps in the correct sequence.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Verify the blood product and client identity with a second nurse"},{"id":"t2","text":"Obtain and record baseline vital signs"},{"id":"t3","text":"Prime the tubing with normal saline and connect the unit"},{"id":"t4","text":"Begin the infusion slowly and stay with the client for the first 15 minutes"},{"id":"t5","text":"Reassess and document vital signs after 15 minutes"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Fundamentals of Nursing', 'Hematologic', 'Blood/specimen collection', 'Transfusion initiation', 'Hard', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350001', 'MCQ', 'A nurse cares for four clients on a medical unit. Which client requires the nurse to use soap and water for hand hygiene rather than alcohol-based hand rub after care?', 'C. difficile forms alcohol-resistant spores, so soap-and-water friction is required to physically remove them.', '{"options":[{"id":"A","text":"A client with methicillin-resistant Staphylococcus aureus in a wound"},{"id":"B","text":"A client with Clostridioides difficile colitis and watery diarrhea"},{"id":"C","text":"A client with pulmonary tuberculosis on airborne precautions"},{"id":"D","text":"A client with influenza on droplet precautions"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. MRSA spores are not the concern; alcohol rub is effective.","B":"Correct. C. difficile spores are not killed by alcohol; mechanical removal with soap and water is required.","C":"Incorrect. TB is airborne; alcohol rub is adequate for hands.","D":"Incorrect. Alcohol-based rub is effective against influenza virus."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'GI', 'Transmission-based precautions', 'Clostridioides difficile', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350002', 'MCQ', 'A nurse is removing personal protective equipment after leaving the room of a client on contact and droplet precautions. After removing gloves and gown inside the room, which item should the nurse remove LAST, outside the room?', 'Doffing order is gloves, goggles, gown, then mask/respirator last outside the room, because the mask protects during removal of other items.', '{"options":[{"id":"A","text":"Goggles or face shield"},{"id":"B","text":"The gown"},{"id":"C","text":"The N95 respirator or mask"},{"id":"D","text":"The gloves"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. Eyewear is removed before the respirator/mask.","B":"Incorrect. The gown is removed first, inside the room.","C":"Correct. The respirator/mask is removed last, after leaving the room and performing hand hygiene.","D":"Incorrect. Gloves are removed first as the most contaminated item."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE', 'Doffing sequence', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350003', 'MCQ', 'A nurse sets up a sterile field for a dressing change. Which situation requires the nurse to consider the entire field contaminated and start over?', 'A sterile field that is out of the nurse''s sight can no longer be guaranteed sterile and must be considered contaminated.', '{"options":[{"id":"A","text":"A sterile item is placed 2.5 cm (1 inch) from the edge of the field"},{"id":"B","text":"The nurse holds sterile forceps with the tips pointed downward"},{"id":"C","text":"The nurse briefly turns to reach for supplies, leaving the field unattended and out of sight"},{"id":"D","text":"The nurse pours sterile solution into a basin from 15 cm above it"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. The outer 2.5 cm border is considered contaminated but items placed inside it are sterile.","B":"Incorrect. Holding tips down keeps moisture from wicking up to the hand; this is correct technique.","C":"Correct. A sterile field left unattended or out of vision is considered contaminated.","D":"Incorrect. Pouring from a height without touching the basin is acceptable."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Sterile field', 'Contamination', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350004', 'MCQ', 'A nurse on a postpartum unit sees an unfamiliar person in scrubs, without a visible hospital identification badge, walking toward the nursery holding an infant. What is the nurse''s PRIORITY action?', 'An unbadged person carrying an infant is a red flag; the nurse must verify identity immediately and initiate the abduction protocol without delay.', '{"options":[{"id":"A","text":"Continue documenting and report the observation at shift change"},{"id":"B","text":"Directly approach the person, ask for identification, and activate the infant-abduction (code) protocol if it cannot be verified"},{"id":"C","text":"Call security to review camera footage before intervening"},{"id":"D","text":"Assume the person is a new staff member and offer directions"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Delaying action risks an abduction in progress.","B":"Correct. Immediate verification and activating the abduction protocol protect the infant.","C":"Incorrect. This delays a time-critical response.","D":"Incorrect. Assuming legitimacy without verification is unsafe."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Multisystem', 'Newborn security', 'Abduction prevention', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350005', 'MCQ', 'A nurse discovers that a colleague nearly administered insulin to the wrong client but caught the error during the second identifier check before giving the dose. What is the most appropriate action?', 'Near-misses are reported through the occurrence-report system to analyze root causes without blaming the individual.', '{"options":[{"id":"A","text":"Take no action because no medication reached the client"},{"id":"B","text":"Complete an incident/occurrence report documenting the near-miss for quality review"},{"id":"C","text":"Verbally warn the colleague and let the matter drop"},{"id":"D","text":"File a formal complaint with the state board of nursing"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Near-misses are reportable and drive system improvement.","B":"Correct. Near-miss reporting is non-punitive and identifies system vulnerabilities.","C":"Incorrect. Informal handling loses the chance for system learning.","D":"Incorrect. A caught near-miss is a quality event, not board-reportable misconduct."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Error reporting', 'Near-miss', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350006', 'MCQ', 'A client with delirium has bilateral soft wrist restraints applied under a current provider order. Which finding requires the nurse to intervene IMMEDIATELY?', 'Restraints tied to a movable side rail can injure the limb when the rail is lowered; they must be anchored to the fixed bed frame with a quick-release knot.', '{"options":[{"id":"A","text":"The restraint is secured to the movable bed frame with a quick-release knot"},{"id":"B","text":"Two fingers fit between the restraint and the client''s wrist"},{"id":"C","text":"The nurse released the restraints 15 minutes ago for range of motion"},{"id":"D","text":"The restraint order was renewed by the provider within the past 24 hours"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Restraints must be tied to a fixed part of the bed frame, not a movable side rail, so the limb is not injured when the rail moves.","B":"Incorrect. Two-finger space is the correct snugness.","C":"Incorrect. Periodic release for circulation and ROM is expected care.","D":"Incorrect. Renewal within the required interval is appropriate."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Neurological', 'Restraints', 'Monitoring', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350007', 'MCQ', 'A client with suspected pulmonary tuberculosis must be transported to radiology. Which action by the nurse best protects others during transport?', 'During transport, source control is achieved by masking the client with a surgical mask; the negative-pressure environment cannot travel, so staff still wear N95s.', '{"options":[{"id":"A","text":"Have the client wear a surgical mask while transport staff wear N95 respirators"},{"id":"B","text":"Have the client wear an N95 respirator and staff wear surgical masks"},{"id":"C","text":"Place a HEPA filter over the client''s face and omit staff protection"},{"id":"D","text":"Transport the client quickly with no mask to minimize exposure time"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The client wears a surgical mask to contain droplet nuclei; staff wear N95s.","B":"Incorrect. The client should wear a surgical mask; the N95 protects staff, not the source.","C":"Incorrect. This is not standard and leaves staff unprotected.","D":"Incorrect. Source control with a mask is essential regardless of speed."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Airborne precautions', 'Negative-pressure room', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350008', 'MCQ', 'A client scheduled for a contrast CT reports a documented anaphylactic reaction to shellfish. A new order reads iodinated contrast. What is the nurse''s best action?', 'A documented anaphylactic reaction requires the nurse to hold the drug and clarify the order; iodine premedication protocols may be needed even though the shellfish link is a myth.', '{"options":[{"id":"A","text":"Administer the contrast because shellfish and contrast allergies are unrelated"},{"id":"B","text":"Hold the contrast and clarify with the provider, verifying premedication and reaction history"},{"id":"C","text":"Cancel the CT scan entirely without contacting the provider"},{"id":"D","text":"Administer diphenhydramine and give the contrast without further orders"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Partially reasoned, but a documented anaphylactic history still warrants clarification before proceeding.","B":"Correct. A history of anaphylaxis warrants provider clarification and possible premedication before iodinated contrast.","C":"Incorrect. The nurse does not cancel a diagnostic test unilaterally.","D":"Incorrect. The nurse cannot initiate premedication without an order."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pharmacology', 'Immune', 'Allergy assessment', 'Cross-sensitivity', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350009', 'MCQ', 'During a mass-casualty event using START triage, four clients arrive simultaneously. Which client should the nurse tag as needing IMMEDIATE (red) care?', 'Under START, a respiratory rate above 30 or capillary refill over 2 seconds marks an immediate (red) casualty who is salvageable with rapid intervention.', '{"options":[{"id":"A","text":"A client who is walking, following commands, and has a minor forearm laceration"},{"id":"B","text":"A client with a respiratory rate of 34/min and a capillary refill of 4 seconds"},{"id":"C","text":"A client who is apneic after two attempts to reposition the airway"},{"id":"D","text":"A client with a closed ankle fracture, breathing 18/min, following commands"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. An ambulatory client is tagged minor (green).","B":"Correct. Respiratory rate over 30 with delayed perfusion signals an immediate (red) priority under START.","C":"Incorrect. An apneic client not breathing after airway repositioning is triaged as expectant (black).","D":"Incorrect. This client is delayed (yellow)."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Emergency preparedness', 'Triage', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350010', 'MCQ', 'A nurse is about to administer a blood transfusion. The client is drowsy and cannot state a name. Which pair of identifiers best meets safe identification standards?', 'Two client-specific identifiers such as full name and date of birth, matched on the wristband and the blood product record, are the standard for high-risk administration.', '{"options":[{"id":"A","text":"Room number and bed position"},{"id":"B","text":"The client''s full name and date of birth verified on the wristband against the blood record"},{"id":"C","text":"The name on the door and the chart at the bedside"},{"id":"D","text":"Verbal confirmation from the client''s roommate"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Location-based identifiers are prohibited because clients move.","B":"Correct. Two client-specific identifiers on the wristband, cross-checked with the product record, are required.","C":"Incorrect. Door and bedside chart are not reliable client identifiers.","D":"Incorrect. A roommate cannot serve as an identifier."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Client identification', 'Two identifiers', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350011', 'MCQ', 'A nurse recaps a needle and it slips, causing a superficial puncture to the finger. After encouraging the wound to bleed and washing with soap and water, what is the next priority?', 'After first aid, immediate reporting triggers source-patient testing and time-sensitive post-exposure prophylaxis decisions.', '{"options":[{"id":"A","text":"Apply a bandage and finish the medication pass"},{"id":"B","text":"Report the exposure immediately per protocol to initiate source testing and post-exposure evaluation"},{"id":"C","text":"Wait until the end of the shift to complete an incident report"},{"id":"D","text":"Squeeze the wound vigorously and apply bleach to the site"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Exposure follow-up is time-sensitive and must not be delayed.","B":"Correct. Prompt reporting allows timely source testing and post-exposure prophylaxis if indicated.","C":"Incorrect. Post-exposure prophylaxis is most effective when started quickly.","D":"Incorrect. Caustic agents are not applied to the wound."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Integumentary', 'Biohazard handling', 'Sharps and spills', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_350012', 'MCQ', 'A nurse notices a coworker with slurred speech, the smell of alcohol, and repeated discrepancies in narcotic counts. What is the nurse''s most appropriate initial action?', 'Observed impairment with narcotic discrepancies is an immediate client-safety threat; the nurse escalates to the supervisor to remove the coworker from care at once.', '{"options":[{"id":"A","text":"Confront the coworker privately and offer to cover the assignment"},{"id":"B","text":"Report the observations to the charge nurse or supervisor immediately to remove the coworker from client care"},{"id":"C","text":"Wait to gather more evidence over several shifts before reporting"},{"id":"D","text":"Report directly to the state board of nursing before informing the employer"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Covering for the coworker endangers clients and enables impairment.","B":"Correct. Client safety requires immediate escalation to remove a possibly impaired nurse from care.","C":"Incorrect. Delaying leaves clients at risk during the interim.","D":"Incorrect. The immediate step is to alert the supervisor to protect current clients."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Reporting unsafe practice', 'Impaired colleague', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_350013', 'SATA', 'A nurse cares for a client with severe neutropenia. Which interventions are appropriate for protective (neutropenic) precautions? Select all that apply.', 'Neutropenic precautions protect the client from exogenous organisms: private positive-pressure room, no standing water/flowers, strict hand hygiene, low-microbial diet, and avoiding mucosal trauma.', '{"options":[{"id":"A","text":"Place the client in a private room with positive-pressure airflow"},{"id":"B","text":"Remove fresh flowers and standing water from the room"},{"id":"C","text":"Ensure all visitors and staff perform strict hand hygiene before entry"},{"id":"D","text":"Serve the client fresh, raw fruit and vegetable salads to boost intake"},{"id":"E","text":"Avoid invasive procedures such as rectal temperatures and enemas when possible"},{"id":"F","text":"Place the client in a negative-pressure room shared with a stable client"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Immune', 'Protective isolation', 'Neutropenic precautions', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_350014', 'SATA', 'A nurse plans to reposition a heavy, immobile client up in bed. Which actions reduce the risk of caregiver injury? Select all that apply.', 'Safe handling uses lifting equipment, a waist-high bed, a wide stable base, leg muscles, no twisting, and a flat surface with the load kept close to the body.', '{"options":[{"id":"A","text":"Use a mechanical lift or friction-reducing slide sheet with adequate help"},{"id":"B","text":"Raise the bed to approximately waist height before the move"},{"id":"C","text":"Keep the feet apart and bend at the knees, using the leg muscles"},{"id":"D","text":"Twist at the waist while pulling the client toward the head of the bed"},{"id":"E","text":"Lower the head of the bed flat and remove pillows if tolerated"},{"id":"F","text":"Hold the load away from the body to gain leverage"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Safe patient handling', 'Ergonomics', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_350015', 'SATA', 'A home-health nurse assesses the home of an older adult who lives alone and has had two recent falls. Which findings require intervention? Select all that apply.', 'Loose rugs, poor lighting, floor cords, and hard-to-reach items are hazards; grab bars, raised seats, and non-slip mats are protective and need no change.', '{"options":[{"id":"A","text":"Loose throw rugs on the walking path between bedroom and bathroom"},{"id":"B","text":"A grab bar installed beside the toilet and inside the tub"},{"id":"C","text":"Poor lighting in the hallway and no night light"},{"id":"D","text":"Electrical cords running across the floor of the living room"},{"id":"E","text":"A raised toilet seat and non-slip mat in the shower"},{"id":"F","text":"Frequently used items stored on a high shelf requiring a step stool"}]}'::jsonb, '{"answers":["A","C","D","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Home safety assessment', 'Fall prevention', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_350016', 'SATA', 'A nurse reviews standard precautions with a new graduate. Which practices correctly reflect standard precautions applied to ALL clients? Select all that apply.', 'Standard precautions apply to every client and include hand hygiene, gloves for fluid contact, barrier protection when splash is likely, and safe sharps disposal without recapping.', '{"options":[{"id":"A","text":"Perform hand hygiene before and after every client contact"},{"id":"B","text":"Wear gloves when contact with blood or body fluids is anticipated"},{"id":"C","text":"Wear a gown and mask only for clients with a confirmed infection"},{"id":"D","text":"Use a mask and eye protection when splashing of fluids is likely"},{"id":"E","text":"Dispose of used needles in a puncture-resistant sharps container without recapping"},{"id":"F","text":"Reserve hand hygiene for situations where visible soiling is present"}]}'::jsonb, '{"answers":["A","B","D","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Standard precautions', 'Application', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_350017', 'SATA', 'A nurse cares for a client receiving home oxygen therapy. Which safety measures should the nurse reinforce? Select all that apply.', 'Oxygen supports combustion, so keep it from flames and static, avoid petroleum products, use signage, ground electrical equipment, and secure cylinders upright.', '{"options":[{"id":"A","text":"Keep the oxygen source at least 1.5 to 3 meters (5 to 10 feet) from open flames"},{"id":"B","text":"Post ''No Smoking / Oxygen in Use'' signs in the home"},{"id":"C","text":"Use petroleum-based lubricant on the lips and nares to prevent dryness"},{"id":"D","text":"Avoid using wool blankets and synthetics that generate static"},{"id":"E","text":"Ensure electrical equipment is grounded and cords are not frayed"},{"id":"F","text":"Store the backup cylinder lying loose on the floor for easy access"}]}'::jsonb, '{"answers":["A","B","D","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Safe equipment use', 'Oxygen and electrical safety', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_350018', 'SELECT_N', 'A nurse enters the room of an agitated client who is pacing, clenching fists, and speaking loudly. Which 3 actions best promote staff and client safety?', 'Safe de-escalation uses a calm voice, increased personal space, an unobstructed exit, and backup, while avoiding touch, cornering, and confrontational eye contact.', '{"options":[{"id":"A","text":"Maintain a calm voice and allow the client extra personal space"},{"id":"B","text":"Position yourself between the client and the door with a clear exit path"},{"id":"C","text":"Ensure a second staff member is aware and nearby before intervening"},{"id":"D","text":"Touch the client''s shoulder to convey reassurance"},{"id":"E","text":"Stand close and maintain sustained direct eye contact to establish authority"},{"id":"F","text":"Corner the client to prevent pacing and contain the behavior"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health', 'Violence prevention', 'De-escalation', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_350019', 'TF', 'A client with disseminated herpes zoster (shingles) in an immunocompromised host requires only contact precautions, and airborne precautions are unnecessary.', 'Disseminated zoster requires both airborne AND contact precautions because the virus can spread through the airborne route in this presentation.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Transmission-based precautions', 'Varicella', 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_350020', 'MATRIX', 'For each infection, click to specify the primary category of transmission-based precautions required.', 'TB and measles are airborne; meningococcus and pertussis are droplet; C. difficile is contact.', '{"row_label":"Disease","rows":[{"id":"r1","text":"Pulmonary tuberculosis"},{"id":"r2","text":"Neisseria meningitidis meningitis"},{"id":"r3","text":"Clostridioides difficile colitis"},{"id":"r4","text":"Measles (rubeola)"},{"id":"r5","text":"Pertussis (whooping cough)"}],"columns":[{"id":"c1","text":"Airborne"},{"id":"c2","text":"Droplet"},{"id":"c3","text":"Contact"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Transmission-based precautions', 'Precaution matching', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_350021', 'MATRIX_MR', 'For each task, select all personal protective equipment items required.', 'PPE is matched to route and task: airborne needs an N95, contact needs gloves/gown, and aerosol-generating procedures on airborne clients need all three.', '{"row_label":"Scenario","rows":[{"id":"r1","text":"Entering the room of a client with active pulmonary tuberculosis to assess"},{"id":"r2","text":"Emptying a bedpan for a client with C. difficile"},{"id":"r3","text":"Suctioning the airway of a client with COVID-19 (aerosol-generating)"},{"id":"r4","text":"Starting a peripheral IV on a client under standard precautions"}],"columns":[{"id":"c1","text":"Gloves"},{"id":"c2","text":"Gown"},{"id":"c3","text":"N95 respirator"}]}'::jsonb, '{"cells":{"r1":["c3"],"r2":["c1","c2"],"r3":["c1","c2","c3"],"r4":["c1"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'PPE selection', 'Barrier choice', 'Hard', 'Analyze', '{}', 7, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_350022', 'CLOZE', 'A new order reads ''heparin 25,000 units IV bolus now.'' Recognizing this as a high-alert drug, the nurse should first {1} and, because it is a high-alert medication, arrange for {2} before administration.', 'An unusually large heparin bolus warrants holding and clarifying the order, and high-alert drugs require an independent double-check before administration.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"hold the dose and clarify the order with the prescriber"},{"id":"c2","text":"administer the dose as written to avoid delay"},{"id":"c3","text":"reduce the dose by half on the nurse''s own judgment"}]},{"id":"b2","choices":[{"id":"c1","text":"an independent double-check by a second nurse"},{"id":"c2","text":"a single verbal readback only"},{"id":"c3","text":"notification of the pharmacy after giving the drug"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Treatment-order verification', 'High-alert medication', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_350023', 'HIGHLIGHT', 'The nurse reviews a client''s isolation setup and notes the following. Highlight each finding that represents a breach of infection-control practice. The nurse [[reuses a single pair of gloves for two clients]]. Hand hygiene is [[performed before and after every contact]]. A [[dedicated stethoscope stays in the contact-isolation room]]. The nurse [[recaps a used needle with two hands]]. Linens are [[bagged at the bedside rather than carried in the arms]]. The isolation cart is [[stocked outside the room]].', 'Reusing gloves between clients and two-handed recapping are infection-control and sharps-safety breaches; the other actions are correct practice.', '{"chunks":[{"id":"h1","text":"reuses a single pair of gloves for two clients"},{"id":"h2","text":"performed before and after every contact"},{"id":"h3","text":"dedicated stethoscope stays in the contact-isolation room"},{"id":"h4","text":"recaps a used needle with two hands"},{"id":"h5","text":"bagged at the bedside rather than carried in the arms"},{"id":"h6","text":"stocked outside the room"}]}'::jsonb, '{"correct_ids":["h1","h4"],"feedback":{"h1":"Gloves are single-client use and must be changed and hands cleaned between clients.","h2":"Correct hand-hygiene practice — not a breach.","h3":"Correct — dedicated equipment prevents cross-transmission.","h4":"Two-handed recapping is a sharps-injury hazard and prohibited.","h5":"Correct — bagging at the point of use is proper technique.","h6":"Correct — supplies staged outside keep the room from becoming a reservoir."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Infection risk cues', 'Environmental hazards', 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_350024', 'BOWTIE', 'A nurse sustains a needlestick from a device used on a client with unknown hepatitis status. Complete the diagram by selecting the immediate actions, the priority risk, and the parameters to follow up.', 'A needlestick from an unknown source carries bloodborne transmission risk; immediate washing and reporting enable source testing and baseline serology for the exposed nurse.', '{"left":{"label":"Immediate actions","tokens":[{"id":"lt1","text":"Wash the site with soap and running water"},{"id":"lt2","text":"Report the exposure to employee health immediately"},{"id":"lt3","text":"Apply a tourniquet above the puncture"},{"id":"lt4","text":"Delay reporting until the shift ends"}]},"centre":{"label":"Priority risk","tokens":[{"id":"ct1","text":"Bloodborne pathogen transmission"},{"id":"ct2","text":"Latex allergy"},{"id":"ct3","text":"Contact dermatitis"}]},"right":{"label":"Follow-up parameters","tokens":[{"id":"rt1","text":"Source-client bloodborne pathogen testing"},{"id":"rt2","text":"Baseline and serial serology of the nurse"},{"id":"rt3","text":"Daily weight"},{"id":"rt4","text":"Serum ammonia level"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Integumentary', 'Sharps injury response', 'Bloodborne exposure', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_350025', 'DRAG_CLOZE', 'When establishing a sterile field, the nurse considers anything below [1] to be non-sterile, and treats the outer [2] border of a sterile drape as contaminated.', 'Items below waist level are considered non-sterile, and the outer 2.5 cm (1 inch) of a sterile drape is treated as contaminated.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"waist level"},{"id":"t2","text":"2.5 cm (1 inch)"},{"id":"t3","text":"shoulder level"},{"id":"t4","text":"10 cm (4 inch)"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Surgical asepsis', 'Sterile boundaries', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_350026', 'DRAG_ORDER', 'A nurse discovers smoke and flames coming from an electrical outlet in a client''s room. Place the nurse''s actions in correct priority order using the RACE sequence.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"}],"tokens":[{"id":"t1","text":"Rescue and remove the client from immediate danger"},{"id":"t2","text":"Activate the alarm and call for help"},{"id":"t3","text":"Contain the fire by closing doors and windows"},{"id":"t4","text":"Extinguish the fire or evacuate as appropriate"},{"id":"t5","text":"Unplug all equipment in the adjacent room"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Emergency response', 'Electrical fire (RACE)', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351001', 'MCQ', 'A nurse is assigned four clients on a medical unit. Which client is the HIGHEST priority for placement in a negative-pressure airborne isolation room?', 'Cough with night sweats and weight loss suggests active TB, requiring airborne (negative-pressure) isolation, which takes priority over droplet/contact conditions.', '{"options":[{"id":"A","text":"A client with a productive cough, night sweats, and a 6-kg weight loss over 2 months"},{"id":"B","text":"A client with influenza A confirmed by rapid antigen test"},{"id":"C","text":"A client with a draining MRSA wound infection"},{"id":"D","text":"A client with pertussis started on azithromycin yesterday"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This presentation strongly suggests pulmonary tuberculosis, which requires airborne precautions immediately.","B":"Incorrect. Influenza requires droplet precautions, not airborne.","C":"Incorrect. MRSA wound infection requires contact precautions.","D":"Incorrect. Pertussis requires droplet precautions."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Transmission-based precautions', 'Airborne isolation', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351002', 'MCQ', 'A nurse is removing personal protective equipment after leaving the room of a client on contact and droplet precautions. Immediately after removing and discarding the gown and gloves inside the room, which action should the nurse take NEXT?', 'Correct doffing sequence: gloves/gown, then hand hygiene, then goggles and mask by the earpieces/ties, then hand hygiene again.', '{"options":[{"id":"A","text":"Perform hand hygiene"},{"id":"B","text":"Remove the goggles from the front"},{"id":"C","text":"Remove the mask by touching the front"},{"id":"D","text":"Exit the room and document care"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Hand hygiene is performed after gown/gloves are removed and before touching the face to remove the mask/goggles.","B":"Incorrect. Eyewear is removed after hand hygiene, handled by the earpieces, not the front.","C":"Incorrect. The mask front is contaminated and is removed by the ties/loops, after hand hygiene.","D":"Incorrect. The mask and eyewear must be removed and hand hygiene repeated before leaving."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE doffing', NULL, 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351003', 'MCQ', 'A nurse on a postpartum unit observes an unfamiliar person in scrubs carrying a newborn toward a stairwell in a blanket rather than the bassinet. Which action should the nurse take FIRST?', 'Carrying an infant instead of transporting it in a bassinet is a classic abduction red flag; the code pink protocol and exit lockdown must be activated first.', '{"options":[{"id":"A","text":"Activate the infant-abduction (code pink) alert and monitor all exits"},{"id":"B","text":"Ask the person to show their hospital identification badge"},{"id":"C","text":"Return to the nurses'' station to verify the infant''s location on the census"},{"id":"D","text":"Notify the charge nurse and wait for direction"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Immediately activating the code and securing exits gives the best chance of preventing the infant from leaving the unit.","B":"Incorrect. Confronting alone may allow escape; activating the code and securing exits comes first.","C":"Incorrect. This delays the response and allows the person to leave.","D":"Incorrect. Waiting delays activation of the abduction protocol."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Multisystem', 'Security', 'Infant abduction', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351004', 'MCQ', 'During a sterile dressing change, the nurse notices that the edge of the sterile field is hanging 2 cm below the table surface and the client coughed toward the field. Which conclusion is correct?', 'A sterile field is contaminated by its 1-inch border, anything hanging below table level, and moisture/droplets from coughing.', '{"options":[{"id":"A","text":"The entire field is contaminated because the 1-inch border and anything below table level are not sterile, and moisture/droplets breach sterility"},{"id":"B","text":"Only the coughed-on area is contaminated; the rest of the field remains usable"},{"id":"C","text":"The field is sterile because the supplies never left the table"},{"id":"D","text":"The field is acceptable if the nurse re-covers it with a new sterile towel"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The outer 1-inch border and any portion below the tabletop are considered contaminated, and coughing introduces droplets.","B":"Incorrect. Droplet contamination and the below-table edge compromise the whole field.","C":"Incorrect. Height below the table and droplets both breach sterility.","D":"Incorrect. A contaminated field cannot be salvaged; a new setup is required."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Sterile technique', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351005', 'MCQ', 'A nurse has just removed gloves after caring for a client with Clostridioides difficile-associated diarrhea. Which hand hygiene method is MOST appropriate?', 'C. difficile forms spores resistant to alcohol; soap-and-water washing physically removes them.', '{"options":[{"id":"A","text":"Wash hands with soap and water"},{"id":"B","text":"Use an alcohol-based hand rub"},{"id":"C","text":"Apply an alcohol foam, then don new gloves"},{"id":"D","text":"No hand hygiene is needed because gloves were worn"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Alcohol-based rubs do not kill C. difficile spores; mechanical washing with soap and water is required.","B":"Incorrect. Alcohol does not eliminate spores.","C":"Incorrect. Alcohol is ineffective against spores.","D":"Incorrect. Hand hygiene is always required after glove removal."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Hand hygiene', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351006', 'MCQ', 'During a mass-casualty incident using disaster triage, a nurse assesses four victims. Using START triage principles, which victim should be tagged as expectant (black/lowest priority for resources)?', 'In START triage, an apneic victim who does not resume breathing after airway repositioning is classified expectant, reflecting the utilitarian goal of the greatest good for the greatest number.', '{"options":[{"id":"A","text":"A victim with no spontaneous respirations after the airway is repositioned"},{"id":"B","text":"A victim with a respiratory rate of 34 and capillary refill over 2 seconds"},{"id":"C","text":"A victim who can walk to the designated area"},{"id":"D","text":"A victim with a controlled femur fracture who is alert and following commands"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Under disaster triage, a victim who remains apneic after airway repositioning is tagged expectant to conserve scarce resources.","B":"Incorrect. This victim is immediate (red) and salvageable.","C":"Incorrect. Ambulatory victims are minor (green).","D":"Incorrect. This victim is delayed (yellow)."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Emergency preparedness', 'Triage', 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351007', 'MCQ', 'A nurse sustains a needlestick from a hollow-bore needle used on a client with unknown hepatitis and HIV status. After encouraging the puncture to bleed and washing the site, which action should the nurse take NEXT?', 'After first aid, a bloodborne-pathogen exposure must be reported immediately so baseline labs, source testing, and time-sensitive prophylaxis can begin.', '{"options":[{"id":"A","text":"Report the exposure immediately to employee/occupational health for source testing and post-exposure prophylaxis evaluation"},{"id":"B","text":"Complete the shift and file the incident report at the end of the day"},{"id":"C","text":"Apply a topical antibiotic and continue working"},{"id":"D","text":"Ask the client to consent to HIV testing before notifying anyone"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Timely reporting enables baseline testing and time-sensitive PEP, which is most effective when started within hours.","B":"Incorrect. PEP effectiveness declines with delay; reporting must be immediate.","C":"Incorrect. This ignores time-critical exposure follow-up.","D":"Incorrect. Consent for source testing is coordinated through occupational health after immediate reporting."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Integumentary', 'Biohazard handling', NULL, 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351008', 'MCQ', 'A confused client is placed in bilateral soft wrist restraints for pulling at a central line despite alternatives failing. Two hours later, which finding requires the nurse to intervene IMMEDIATELY?', 'A cool, pale, numb restrained extremity signals neurovascular compromise, demanding immediate release; the other findings reflect correct restraint practice.', '{"options":[{"id":"A","text":"The restrained hand is cool, pale, and the client reports numbness"},{"id":"B","text":"The restraint is secured to the movable bed frame with a quick-release knot"},{"id":"C","text":"The provider''s restraint order was written 2 hours ago"},{"id":"D","text":"Two fingers fit snugly between the restraint and the wrist"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cool, pale, numb extremity indicates compromised circulation and requires immediate release and reassessment.","B":"Incorrect. Securing to the movable frame with a quick-release tie is correct technique.","C":"Incorrect. A violent/non-violent restraint order timeframe is appropriate here; a fresh order is not the priority.","D":"Incorrect. Two-finger space is the correct snugness."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Restraints', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351009', 'MCQ', 'A home health nurse visits an older adult on home oxygen at 2 L/min via concentrator. Which observation poses the GREATEST safety risk requiring immediate correction?', 'Oxygen supports combustion; an open flame within a few feet of the source is the most immediately life-threatening hazard.', '{"options":[{"id":"A","text":"A lit gas stove burner is being used within 3 feet of the running concentrator"},{"id":"B","text":"The oxygen tubing is 40 feet long across two rooms"},{"id":"C","text":"There is a scatter rug in the hallway"},{"id":"D","text":"The client keeps a spare tank stored upright in a closet"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Open flame near oxygen creates an immediate fire/explosion hazard and must be corrected first.","B":"Incorrect. Long tubing is a trip hazard but not the greatest immediate danger.","C":"Incorrect. A fall risk, but not as immediately catastrophic as open flame near oxygen.","D":"Incorrect. Upright storage of a secured spare tank is acceptable."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Home safety assessment', NULL, 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351010', 'MCQ', 'A nurse discovers that a colleague nearly administered a tenfold insulin overdose but caught the error before giving it. The colleague says, ''No harm done, so there''s nothing to report.'' Which response by the nurse best reflects a culture of safety?', 'A just culture treats near-miss reporting as essential, non-punitive data used to redesign error-prone systems.', '{"options":[{"id":"A","text":"''Near misses should still be reported so the system weakness can be analyzed and prevented.''"},{"id":"B","text":"''You''re right; incident reports are only for events that actually reach the client.''"},{"id":"C","text":"''I''ll report it, but you''ll likely be disciplined for the mistake.''"},{"id":"D","text":"''Only report it if it happens again.''"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A just/safety culture treats near misses as learning opportunities to fix latent system errors.","B":"Incorrect. Near misses must be reported to identify system vulnerabilities.","C":"Incorrect. A punitive framing discourages reporting and undermines safety culture.","D":"Incorrect. Waiting for recurrence allows the latent hazard to persist."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Error and near-miss reporting', NULL, 'Hard', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351011', 'MCQ', 'A nurse is about to administer a blood transfusion. The client is sedated and cannot state their name, and the wristband is smudged and partly illegible. Which action is MOST appropriate?', 'Blood transfusion demands rigorous two-person, two-identifier verification; an illegible band must be replaced and identity re-established before administration.', '{"options":[{"id":"A","text":"Verify identity with a second nurse using two identifiers from a newly applied, legible wristband before transfusing"},{"id":"B","text":"Proceed since the room number matches the chart"},{"id":"C","text":"Ask the family member at the bedside to confirm the name and proceed"},{"id":"D","text":"Administer the blood and replace the wristband afterward"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Blood administration requires two-identifier, two-person verification; an illegible band must be replaced and re-verified first.","B":"Incorrect. Room number is never an acceptable identifier.","C":"Incorrect. Family confirmation does not replace two approved identifiers plus band verification for blood products.","D":"Incorrect. Verification must occur before, not after, transfusion."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Client identification', NULL, 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_351012', 'MCQ', 'A nurse enters the room of an agitated client who is pacing, clenching fists, and shouting. Which action by the nurse best ensures personal safety during de-escalation?', 'During de-escalation the nurse keeps a clear exit, adequate distance, and a calm nonthreatening posture to protect against workplace violence.', '{"options":[{"id":"A","text":"Stand near the door with a clear exit path and maintain a nonthreatening distance"},{"id":"B","text":"Position between the client and the door to prevent elopement"},{"id":"C","text":"Approach closely and place a hand on the client''s shoulder to reassure"},{"id":"D","text":"Match the client''s raised voice to establish authority"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Keeping an unobstructed exit and adequate personal space protects the nurse while allowing de-escalation.","B":"Incorrect. Blocking the client''s exit can escalate aggression and traps the nurse.","C":"Incorrect. Touch and closeness can provoke a violent response.","D":"Incorrect. Escalating volume intensifies agitation."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health', 'Violence/security', 'Workplace violence', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_351013', 'SATA', 'A nurse cares for a client with an absolute neutrophil count of 400/mm3 on protective (neutropenic) precautions. Which interventions should the nurse implement? Select all that apply.', 'Protective precautions use positive pressure, meticulous hand hygiene, a low-microbial diet, and removal of flowers/standing water to shield the neutropenic client.', '{"options":[{"id":"A","text":"Place the client in a private room with positive-pressure airflow"},{"id":"B","text":"Remove fresh flowers and standing water from the room"},{"id":"C","text":"Avoid serving raw fruits and vegetables"},{"id":"D","text":"Ensure staff and visitors perform strict hand hygiene"},{"id":"E","text":"Place the client in a negative-pressure room"},{"id":"F","text":"Assign the client to share a room with a client who has cellulitis"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Positive pressure protects the immunocompromised client from airborne contaminants.","B":"Correct. Flowers and standing water harbor Aspergillus and Pseudomonas.","C":"Correct. A low-microbial (neutropenic) diet avoids raw produce.","D":"Correct. Hand hygiene is the cornerstone of protecting the neutropenic client.","E":"Incorrect. Negative pressure protects others from the client, not the reverse.","F":"Incorrect. Cohorting with an infected client endangers the neutropenic client."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Immune', 'Neutropenic precautions', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_351014', 'SATA', 'A nurse plans to reposition a 120-kg client who cannot bear weight. Which safe-handling actions should the nurse take? Select all that apply.', 'Safe patient handling uses mechanical aids, elbow-height work surfaces, a wide base, keeping loads close, and avoiding spinal twisting.', '{"options":[{"id":"A","text":"Use a mechanical lift with adequate trained personnel"},{"id":"B","text":"Raise the bed to elbow height before the move"},{"id":"C","text":"Keep the load close to the body and use leg muscles"},{"id":"D","text":"Widen the stance to create a stable base of support"},{"id":"E","text":"Twist at the waist to move the client toward the far rail"},{"id":"F","text":"Lift alone quickly to minimize the client''s discomfort"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Mechanical lifts prevent musculoskeletal injury with heavy, dependent clients.","B":"Correct. Working at elbow height reduces back strain.","C":"Correct. Keeping the load close and bending the knees protects the back.","D":"Correct. A wide base improves balance and stability.","E":"Incorrect. Twisting the spine under load is a common cause of injury; pivot the feet instead.","F":"Incorrect. Solo lifting of a heavy dependent client risks injury to both."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Ergonomics/safe handling', NULL, 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_351015', 'SATA', 'A nurse is caring for multiple clients. For which clients should the nurse initiate contact precautions? Select all that apply.', 'VRE, scabies, C. difficile, and RSV are transmitted by contact; TB is airborne and meningococcus is droplet.', '{"options":[{"id":"A","text":"A client with a draining wound colonized with vancomycin-resistant Enterococcus (VRE)"},{"id":"B","text":"A client with scabies"},{"id":"C","text":"A client with active C. difficile diarrhea"},{"id":"D","text":"A client with respiratory syncytial virus (RSV)"},{"id":"E","text":"A client with pulmonary tuberculosis"},{"id":"F","text":"A client with meningococcal meningitis"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. VRE requires contact precautions.","B":"Correct. Scabies is spread by direct skin contact and requires contact precautions.","C":"Correct. C. difficile requires contact precautions with soap-and-water hand hygiene.","D":"Correct. RSV requires contact precautions.","E":"Incorrect. TB requires airborne precautions.","F":"Incorrect. Meningococcal disease requires droplet precautions."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'GI', 'Contact precautions', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_351016', 'SATA', 'A nurse identifies a hospitalized older adult as high risk for falls. Which interventions are appropriate? Select all that apply.', 'Evidence-based fall prevention uses a low bed, accessible call light, scheduled toileting, and nonslip footwear; four side rails and routine sedation are restraints that increase harm.', '{"options":[{"id":"A","text":"Keep the bed in the lowest position with the wheels locked"},{"id":"B","text":"Ensure the call light is within reach and answered promptly"},{"id":"C","text":"Implement scheduled toileting rounds"},{"id":"D","text":"Provide nonslip footwear when ambulating"},{"id":"E","text":"Raise all four side rails to keep the client in bed"},{"id":"F","text":"Routinely administer a sedative at night to keep the client in bed"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. A low, locked bed reduces fall injury.","B":"Correct. Accessible, promptly answered call lights reduce unassisted attempts.","C":"Correct. Proactive toileting prevents urgent unassisted trips.","D":"Correct. Nonslip footwear improves traction.","E":"Incorrect. Four raised rails are a restraint and increase entrapment/climbing-over injury.","F":"Incorrect. Sedatives increase fall risk and constitute chemical restraint without indication."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Fall prevention', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_351017', 'SATA', 'A nurse suspects a coworker is diverting controlled substances. Which findings support this concern and warrant reporting? Select all that apply.', 'Diversion red flags include volunteering to give others'' opioids, unexplained poor client analgesia, waste discrepancies, and unaccounted absences, all of which must be reported.', '{"options":[{"id":"A","text":"The coworker frequently volunteers to administer other nurses'' opioid doses"},{"id":"B","text":"Clients assigned to the coworker report poor pain relief despite documented full opioid doses"},{"id":"C","text":"The coworker has frequent unexplained absences and discrepancies in narcotic waste counts"},{"id":"D","text":"The coworker consistently arrives on time and completes documentation early"},{"id":"E","text":"The coworker declines overtime shifts"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Volunteering to give others'' narcotics is a diversion warning sign.","B":"Correct. Unexplained inadequate analgesia suggests the drug was diverted.","C":"Correct. Waste-count discrepancies and absences are classic diversion indicators.","D":"Incorrect. Punctuality is not a warning sign.","E":"Incorrect. Declining overtime is not indicative of diversion."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Reporting unsafe staff practice', NULL, 'Hard', 'Evaluate', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_351018', 'SELECT_N', 'A nurse must set up droplet precautions correctly. Which 3 actions are required and appropriate?', 'Droplet precautions require a surgical mask within 3 to 6 feet, masking the client during transport, and a private room or cohorting; N95, negative pressure, and closed doors are airborne measures.', '{"options":[{"id":"A","text":"Place a surgical mask on staff entering within 3 to 6 feet of the client"},{"id":"B","text":"Place a surgical mask on the client during transport out of the room"},{"id":"C","text":"Use a private room, or cohort with a client who has the same organism"},{"id":"D","text":"Use an N95 respirator for all room entries"},{"id":"E","text":"Place the client in a negative-pressure room"},{"id":"F","text":"Keep the door closed at all times as the primary control"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Droplet precautions require a surgical mask for close contact.","B":"Correct. Masking the client during transport limits droplet spread.","C":"Correct. Private room or cohorting is standard for droplet precautions.","D":"Incorrect. N95 is for airborne, not droplet, precautions.","E":"Incorrect. Negative pressure is for airborne precautions.","F":"Incorrect. A closed door is required for airborne, not droplet, precautions."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Droplet precautions', NULL, 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_351019', 'TF', 'Standard precautions require the nurse to wear gloves for all contact with intact skin during routine care such as taking a blood pressure.', 'Standard precautions apply to blood, body fluids, secretions, mucous membranes, and non-intact skin; gloves are not required for contact with intact skin during a routine BP measurement.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Standard precautions', NULL, 'Hard', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_351020', 'TF', 'For a client having a generalized tonic-clonic seizure, the nurse should avoid inserting anything into the mouth and instead turn the client to the side to protect the airway.', 'Placing objects in the mouth risks dental/airway injury; side-lying positioning promotes drainage of secretions and protects the airway.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Neurological', 'Seizure safety', NULL, 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_351021', 'MATRIX', 'For each condition, click to specify the primary type of transmission-based precaution required.', 'Measles and disseminated zoster are airborne, pertussis and mumps are droplet, and MRSA wound infection is contact.', '{"row_label":"Condition","rows":[{"id":"r1","text":"Measles (rubeola)"},{"id":"r2","text":"Pertussis (whooping cough)"},{"id":"r3","text":"MRSA wound infection"},{"id":"r4","text":"Disseminated herpes zoster (shingles)"},{"id":"r5","text":"Mumps"}],"columns":[{"id":"c1","text":"Contact"},{"id":"c2","text":"Droplet"},{"id":"c3","text":"Airborne"}]}'::jsonb, '{"cells":{"r1":"c3","r2":"c2","r3":"c1","r4":"c3","r5":"c2"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Transmission-based precautions', NULL, 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_351022', 'MATRIX_MR', 'For each client scenario, select all PPE items the nurse must don before entering the room.', 'TB requires an N95; contact-precaution wound care and C. difficile perineal care require gown and gloves; a TB client with splash-risk wound care needs all three.', '{"row_label":"Client","rows":[{"id":"r1","text":"Client with active pulmonary tuberculosis, no wound care"},{"id":"r2","text":"Client with a draining VRE wound requiring dressing change"},{"id":"r3","text":"Client with suspected TB requiring wound irrigation with splash risk"},{"id":"r4","text":"Client with active C. difficile diarrhea needing perineal care"}],"columns":[{"id":"c1","text":"Gown"},{"id":"c2","text":"Gloves"},{"id":"c3","text":"N95 respirator"}]}'::jsonb, '{"cells":{"r1":["c3"],"r2":["c1","c2"],"r3":["c1","c2","c3"],"r4":["c1","c2"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'PPE selection', NULL, 'Hard', 'Analyze', '{}', 8, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_351023', 'CLOZE', 'A client newly diagnosed with disseminated varicella must be placed on {1} precautions, and staff entering the room must wear {2}.', 'Disseminated varicella spreads by airborne and contact routes, requiring an N95 plus gown and gloves.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"airborne and contact"},{"id":"c2","text":"droplet only"},{"id":"c3","text":"standard only"}]},{"id":"b2","choices":[{"id":"c1","text":"an N95 respirator and gown with gloves"},{"id":"c2","text":"a surgical mask only"},{"id":"c3","text":"no additional PPE"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Isolation reasoning', NULL, 'Hard', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_351024', 'HIGHLIGHT', 'Highlight the findings during the pre-incision time-out that require the nurse to stop the procedure. The team confirms the [[client''s stated name matches the wristband]]. The [[surgical site is unmarked]]. The [[consent form lists a different procedure than the one scheduled]]. Antibiotic prophylaxis was given 30 minutes ago. The [[imaging displayed belongs to another client]]. The count of instruments is correct.', 'An unmarked surgical site, a consent-procedure mismatch, and wrong-client imaging are Universal Protocol violations that require halting the procedure; a matching name is a normal confirmation.', '{"chunks":[{"id":"h1","text":"client''s stated name matches the wristband"},{"id":"h2","text":"surgical site is unmarked"},{"id":"h3","text":"consent form lists a different procedure than the one scheduled"},{"id":"h4","text":"imaging displayed belongs to another client"}]}'::jsonb, '{"correct_ids":["h2","h3","h4"],"feedback":{"h1":"Matching identity is a normal, reassuring finding.","h2":"An unmarked site risks wrong-site surgery and must halt the time-out.","h3":"A consent-procedure mismatch is a critical stop point.","h4":"Wrong-client imaging must stop the procedure."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Surgical safety verification', NULL, 'Hard', 'Evaluate', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_351025', 'BOWTIE', 'A client with a central venous catheter develops fever and chills with erythema at the insertion site. Complete the diagram by selecting the priority actions, the condition, and the parameters to monitor.', 'Fever, chills, and site erythema with a central line indicate CLABSI; priorities are paired blood cultures and provider notification for line removal, monitoring temperature/WBC and the insertion site.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Obtain blood cultures from the line and a peripheral site"},{"id":"lt2","text":"Notify the provider and anticipate catheter removal"},{"id":"lt3","text":"Flush the line with a large heparin bolus"},{"id":"lt4","text":"Apply warm soaks and continue the current infusion"},{"id":"lt5","text":"Increase the infusion rate to dilute the pathogen"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Central line-associated bloodstream infection"},{"id":"ct2","text":"Air embolism"},{"id":"ct3","text":"Catheter occlusion"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Temperature and white blood cell count"},{"id":"rt2","text":"Insertion-site appearance"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Pupillary response"},{"id":"rt5","text":"Bowel sounds"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Central line infection prevention', NULL, 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_351026', 'DRAG_ORDER', 'A nurse discovers a fire in a client''s trash can that is spreading to the curtains. Place the fire-response actions in the correct priority order using the RACE sequence.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"}],"tokens":[{"id":"t1","text":"Rescue clients in immediate danger from the area"},{"id":"t2","text":"Activate the alarm and call for help"},{"id":"t3","text":"Confine the fire by closing doors and windows"},{"id":"t4","text":"Extinguish the fire if small, or evacuate"},{"id":"t5","text":"Document the incident in the chart"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Fire safety (RACE)', NULL, 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352001', 'MCQ', 'A nurse is assigned four clients on a medical unit. A single negative-pressure airborne isolation room is available. Which client should be prioritized for that room?', 'Only airborne pathogens such as suspected TB require a negative-pressure room; the others use contact or droplet precautions.', '{"options":[{"id":"A","text":"A client with suspected pulmonary tuberculosis and a productive cough"},{"id":"B","text":"A client with Clostridioides difficile diarrhea"},{"id":"C","text":"A client with meningococcal meningitis on IV antibiotics for 12 hours"},{"id":"D","text":"A client with a draining methicillin-resistant Staphylococcus aureus wound"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Suspected pulmonary TB requires airborne precautions and a negative-pressure room.","B":"Incorrect. C. difficile requires contact precautions, not a negative-pressure room.","C":"Incorrect. Meningococcus requires droplet precautions and is non-infectious after 24 hours of therapy.","D":"Incorrect. MRSA requires contact precautions."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Transmission-based precautions', 'Airborne', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352002', 'MCQ', 'A nurse is removing personal protective equipment after leaving a contact-and-droplet isolation room. After removing gloves and gown, which item should the nurse remove NEXT before exiting the anteroom?', 'CDC doffing order is gloves, gown, goggles/face shield, then respirator/mask, with hand hygiene between and after.', '{"options":[{"id":"A","text":"Goggles or face shield"},{"id":"B","text":"N95 respirator"},{"id":"C","text":"Shoe covers"},{"id":"D","text":"Surgical mask"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. After gloves and gown, eye protection is removed by the headband, before the mask.","B":"Incorrect. The respirator/mask is removed last, after eye protection and outside the room.","C":"Incorrect. Shoe covers, if used, are removed with the gown early in the sequence.","D":"Incorrect. The mask is the final item removed to protect the airway longest."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Integumentary', 'PPE', 'Doffing sequence', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352003', 'MCQ', 'A person in scrubs without a visible facility ID badge enters the postpartum unit and offers to take a newborn to the nursery for ''routine tests.'' Which action by the nurse is the priority?', 'Newborn security requires that infants be transferred only to identified personnel via the matching-band and badge verification process.', '{"options":[{"id":"A","text":"Do not release the infant and verify the person''s identity through the security process"},{"id":"B","text":"Allow the transport since the person is wearing facility scrubs"},{"id":"C","text":"Ask the mother whether she recognizes the person"},{"id":"D","text":"Escort the person and infant to the nursery together"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Infants are released only to identified staff following the security matching protocol.","B":"Incorrect. Scrubs are not proof of identity; abductors commonly impersonate staff.","C":"Incorrect. Mothers may not know all staff; identity is verified through security, not the parent.","D":"Incorrect. This still permits an unverified person access to the infant."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Multisystem', 'Newborn security', 'Infant abduction', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352004', 'MCQ', 'A client is placed in bilateral soft wrist restraints for violent behavior under an emergency provider order. Which nursing action reflects the correct legal and safety standard?', 'Safe restraint use requires frequent circulatory/skin assessment, quick-release ties to the bed frame, and time-limited orders with re-evaluation.', '{"options":[{"id":"A","text":"Assess circulation, skin, and range of motion and release the restraints per policy at least every 2 hours"},{"id":"B","text":"Tie the restraints to the side rails so they move with the bed"},{"id":"C","text":"Keep the emergency order in place for 72 hours without re-evaluation"},{"id":"D","text":"Use a quick-release knot only if the client is calm"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Restraints require frequent assessment and periodic release to check circulation and skin integrity.","B":"Incorrect. Restraints are tied to the movable bed frame, never to side rails.","C":"Incorrect. Violent-behavior restraint orders must be renewed within short intervals and require provider re-evaluation.","D":"Incorrect. A quick-release knot is always required so the restraint can be removed rapidly."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Musculoskeletal', 'Restraints', 'Monitoring', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352005', 'MCQ', 'During a sterile dressing change, the nurse notices that the outer 1-inch border of the sterile field is touching the client''s gown and that a bottle of saline was set 2 inches inside the field''s edge. Which conclusion is correct?', 'The outer 1 inch of a sterile field is treated as contaminated; sterile items must be placed within the inner boundary.', '{"options":[{"id":"A","text":"The 1-inch border is considered contaminated but the saline placed inside it remains sterile"},{"id":"B","text":"The entire field is contaminated and must be discarded"},{"id":"C","text":"The saline is contaminated because it was placed near the edge"},{"id":"D","text":"Both the field and saline are sterile because saline is a liquid"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The outer 1 inch of a sterile field is always considered contaminated; items within the inner field remain sterile.","B":"Incorrect. Only the 1-inch border is contaminated, not the whole field.","C":"Incorrect. Placement inside the sterile border keeps the item sterile.","D":"Incorrect. The border remains contaminated regardless of the saline."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Sterile technique', 'Field contamination', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352006', 'MCQ', 'A nurse cares for several clients in sequence. After which client contact is soap-and-water handwashing REQUIRED rather than alcohol-based hand rub?', 'Alcohol-based rub does not eliminate C. difficile or other spores, so soap-and-water washing is mandated after such contact.', '{"options":[{"id":"A","text":"After caring for a client with Clostridioides difficile diarrhea"},{"id":"B","text":"After caring for a client with influenza"},{"id":"C","text":"After removing gloves from a routine dressing change"},{"id":"D","text":"After administering an oral medication to a stable client"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Alcohol does not kill C. difficile spores; mechanical removal with soap and water is required.","B":"Incorrect. Alcohol-based rub is effective and acceptable for influenza when hands are not visibly soiled.","C":"Incorrect. Alcohol rub suffices when hands are not visibly soiled and no spore risk exists.","D":"Incorrect. Alcohol-based rub is appropriate here."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'GI', 'Hand hygiene', 'Spore-forming organisms', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352007', 'MCQ', 'A nurse notices a colleague drew up a medication into an unlabeled syringe and set it aside but caught the error before administration. No client was harmed. What is the most appropriate action?', 'Reporting near-misses feeds a non-punitive safety system that corrects latent hazards before patient harm occurs.', '{"options":[{"id":"A","text":"File a near-miss/incident report to support system improvement"},{"id":"B","text":"Do nothing because no client was harmed"},{"id":"C","text":"Document the event in the client''s medical record as an error"},{"id":"D","text":"Report the colleague to the board of nursing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Near-misses are reported to identify system vulnerabilities before harm occurs.","B":"Incorrect. Near-misses must be reported even without harm to prevent future events.","C":"Incorrect. Incident reports are not filed in the client record, and no medication reached the client.","D":"Incorrect. A single caught near-miss is handled through internal reporting, not a licensure complaint."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Error reporting', 'Near-miss', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352008', 'MCQ', 'A nurse must reposition a fully dependent 120-kg client up in bed. Only one other staff member is available. Which action best protects both staff and client from injury?', 'Evidence-based safe patient handling requires friction-reducing devices/mechanical lifts and adequate staffing for heavy dependent clients.', '{"options":[{"id":"A","text":"Use a mechanical friction-reducing device or lift and obtain adequate personnel per policy before moving"},{"id":"B","text":"Have the two staff members lift manually while bending at the waist"},{"id":"C","text":"Ask the client to pull on the trapeze while both staff lift the legs"},{"id":"D","text":"Raise the head of the bed and let gravity assist repositioning"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Safe-handling policy requires mechanical aids and sufficient staff for high-weight dependent transfers.","B":"Incorrect. Manual lifting of this weight and bending at the waist risks back injury.","C":"Incorrect. A fully dependent client cannot assist, and this is unsafe.","D":"Incorrect. Elevating the head moves the client down, worsening the problem."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Musculoskeletal', 'Safe client handling', 'Ergonomics', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352009', 'MCQ', 'During a mass-casualty event using START triage, the nurse assesses a client who is breathing at 34 breaths/min after airway positioning, has a capillary refill of 4 seconds, and cannot follow commands. Which triage category applies?', 'In START triage, respiratory rate greater than 30, cap refill over 2 seconds, or altered mental status classify a client as immediate (red).', '{"options":[{"id":"A","text":"Immediate (red)"},{"id":"B","text":"Delayed (yellow)"},{"id":"C","text":"Minor (green)"},{"id":"D","text":"Expectant (black)"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Respiratory rate over 30, delayed perfusion, or inability to follow commands each mark an immediate (red) tag.","B":"Incorrect. These findings exceed delayed criteria and require immediate care.","C":"Incorrect. This client cannot be an ambulatory walking-wounded.","D":"Incorrect. The client is breathing and perfusing, so is not expectant."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Emergency preparedness', 'Triage', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352010', 'MCQ', 'A client with a documented anaphylactic reaction to penicillin has a new order for cefazolin. Which nursing action is most appropriate before administration?', 'A history of penicillin anaphylaxis raises cephalosporin cross-reactivity risk, so the nurse holds and clarifies rather than administering.', '{"options":[{"id":"A","text":"Hold the dose and clarify the order with the prescriber due to cross-sensitivity risk"},{"id":"B","text":"Administer the cefazolin because it is a different drug class"},{"id":"C","text":"Give a test dose of penicillin first to confirm the allergy"},{"id":"D","text":"Premedicate with diphenhydramine and proceed"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cephalosporins carry a cross-reactivity risk with penicillin; anaphylaxis history warrants clarification.","B":"Incorrect. Cephalosporins share a beta-lactam structure and can cross-react.","C":"Incorrect. Re-exposing a client with anaphylaxis history to penicillin is dangerous.","D":"Incorrect. Premedication does not reliably prevent anaphylaxis; the order must be clarified."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pharmacology', 'Immune', 'Allergy assessment', 'Cross-sensitivity', 'Hard', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352011', 'MCQ', 'A nurse prepares to administer a blood transfusion to a client whose wristband is missing. What is the priority action?', 'Blood administration requires two client identifiers verified against an intact identification band before the transfusion begins.', '{"options":[{"id":"A","text":"Obtain a new armband with two verified identifiers before proceeding"},{"id":"B","text":"Ask the client to state and spell their name and proceed"},{"id":"C","text":"Use the room number to confirm identity"},{"id":"D","text":"Proceed and apply a new band afterward to avoid delay"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A verified identification band with two identifiers is required before transfusion.","B":"Incorrect. Verbal confirmation alone does not meet the two-identifier band requirement for high-risk transfusion.","C":"Incorrect. Room/bed number is never an acceptable identifier.","D":"Incorrect. Identity must be verified before, not after, a high-risk product is given."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Client identification', 'Two identifiers', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_352012', 'MCQ', 'A nurse discovers a small spill of a hazardous chemotherapy drug on the floor of a client''s room. What is the priority action?', 'Cytotoxic spills require immediate containment, area restriction, and the dedicated chemotherapy spill kit with appropriate PPE.', '{"options":[{"id":"A","text":"Restrict access to the area and use the designated chemotherapy spill kit with proper PPE"},{"id":"B","text":"Wipe the spill with standard paper towels and routine gloves"},{"id":"C","text":"Mop the area with a disinfectant solution"},{"id":"D","text":"Leave the spill and notify housekeeping to clean it later"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Hazardous-drug spills are contained with the dedicated spill kit and chemo-rated PPE.","B":"Incorrect. Routine gloves and towels do not protect against cytotoxic exposure.","C":"Incorrect. Mopping can spread cytotoxic residue and is not the protocol.","D":"Incorrect. The hazard must be contained immediately by trained staff."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Biohazard handling', 'Chemotherapy spill', 'Hard', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_352013', 'SATA', 'A nurse cares for a client with severe neutropenia. Which interventions should the nurse include in the plan of care? Select all that apply.', 'Neutropenic (protective) precautions minimize exposure to pathogens: private room, no flowers/standing water, low-microbial diet, and strict hand hygiene; rectal temps and infected visitors are avoided.', '{"options":[{"id":"A","text":"Place the client in a private room"},{"id":"B","text":"Avoid fresh flowers and standing water in the room"},{"id":"C","text":"Restrict fresh uncooked fruits and vegetables per protocol"},{"id":"D","text":"Perform meticulous hand hygiene before entering"},{"id":"E","text":"Assign the client to share a room with a postoperative client"},{"id":"F","text":"Take a rectal temperature every 4 hours"},{"id":"G","text":"Allow visitors with active upper respiratory infections"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Immune', 'Neutropenic precautions', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_352014', 'SATA', 'A nurse identifies a hospitalized older adult as high risk for falls. Which interventions are appropriate? Select all that apply.', 'Evidence-based fall prevention uses a low locked bed, accessible call light, nonskid footwear, and proactive rounding; four raised rails act as a restraint and restraints/dim lighting increase risk.', '{"options":[{"id":"A","text":"Keep the bed in the lowest position with wheels locked"},{"id":"B","text":"Ensure the call light is within reach"},{"id":"C","text":"Provide nonskid footwear when ambulating"},{"id":"D","text":"Implement scheduled rounding to address toileting needs"},{"id":"E","text":"Raise all four side rails at all times"},{"id":"F","text":"Keep the room dimly lit to promote rest"},{"id":"G","text":"Restrain the client at night to prevent wandering"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Neurological', 'Fall prevention', NULL, 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_352015', 'SATA', 'A home-health nurse assesses the residence of an older adult with early dementia and a history of falls. Which findings should the nurse address as safety hazards? Select all that apply.', 'Throw rugs, scald-risk hot water, absent grab bars, and unlabeled medications are hazards; smoke detectors, nightlights, and accessible phones are protective.', '{"options":[{"id":"A","text":"Loose throw rugs on the walkways"},{"id":"B","text":"Water heater set to 140°F (60°C)"},{"id":"C","text":"No grab bars in the bathtub or near the toilet"},{"id":"D","text":"Medications stored in unlabeled containers on the counter"},{"id":"E","text":"A working smoke detector in the hallway"},{"id":"F","text":"Nightlights in the hallway and bathroom"},{"id":"G","text":"A cordless phone kept in an accessible location"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Home environmental safety', NULL, 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_352016', 'SATA', 'A client is discharged home on continuous oxygen therapy. Which safety instructions should the nurse reinforce? Select all that apply.', 'Oxygen supports combustion, so clients keep it from flames, post warning signs, avoid petroleum products and static-generating materials, and secure cylinders upright.', '{"options":[{"id":"A","text":"Keep oxygen at least 6 feet away from open flames and heat sources"},{"id":"B","text":"Post ''No Smoking / Oxygen in Use'' signs"},{"id":"C","text":"Avoid petroleum-based products around the face"},{"id":"D","text":"Secure oxygen cylinders upright to prevent tipping"},{"id":"E","text":"Use a wool blanket to reduce static discomfort"},{"id":"F","text":"Store spare cylinders lying flat under the bed"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Oxygen safety', NULL, 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_352017', 'SATA', 'A nurse observes a coworker repeatedly bypassing the barcode medication scanning system and documenting doses that were not verified. Which actions are appropriate? Select all that apply.', 'Unsafe practice is reported through the chain of command with factual documentation and client safety follow-up; ignoring, public confrontation, and altering records are inappropriate.', '{"options":[{"id":"A","text":"Report the observation to the charge nurse or unit manager"},{"id":"B","text":"Document the specific observed events factually"},{"id":"C","text":"Ensure affected clients are assessed for medication errors"},{"id":"D","text":"Ignore it because no client has yet been harmed"},{"id":"E","text":"Confront the coworker publicly at the nurses'' station"},{"id":"F","text":"Alter the coworker''s documentation to correct it"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Reporting unsafe practice', NULL, 'Hard', 'Evaluate', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_352018', 'SELECT_N', 'A nurse reviews assignments during an outbreak. Which 3 conditions require contact precautions?', 'C. difficile, scabies, and multidrug-resistant organisms spread by contact; TB is airborne while influenza and pertussis are droplet.', '{"options":[{"id":"A","text":"Clostridioides difficile infection"},{"id":"B","text":"Scabies infestation"},{"id":"C","text":"Multidrug-resistant Acinetobacter wound infection"},{"id":"D","text":"Pulmonary tuberculosis"},{"id":"E","text":"Seasonal influenza"},{"id":"F","text":"Pertussis"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Transmission-based precautions', 'Contact precautions', 'Hard', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_352019', 'TF', 'When a private room is unavailable, it is acceptable to cohort a client colonized with methicillin-resistant Staphylococcus aureus in the same room as a client with a fresh surgical wound and an indwelling catheter.', 'Cohorting places clients with the SAME organism together; pairing an MRSA client with a fresh-wound, catheterized client exposes a highly susceptible host and is unsafe.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Isolation precautions', 'Cohorting', 'Hard', NULL, '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_352020', 'MATRIX', 'For each condition, click to specify the required category of transmission-based precautions.', 'Measles and disseminated varicella are airborne; meningococcus and mumps are droplet; rotavirus is contact.', '{"row_label":"Condition","rows":[{"id":"r1","text":"Measles (rubeola)"},{"id":"r2","text":"Neisseria meningitidis meningitis"},{"id":"r3","text":"Rotavirus gastroenteritis"},{"id":"r4","text":"Varicella (disseminated)"},{"id":"r5","text":"Mumps"}],"columns":[{"id":"c1","text":"Airborne"},{"id":"c2","text":"Droplet"},{"id":"c3","text":"Contact"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Transmission-based precautions', 'Category matching', 'Hard', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_352021', 'MATRIX_MR', 'For each care scenario, select all personal protective equipment the nurse must don before the task.', 'Aerosol-generating TB care adds an N95; contact and splash tasks require gown and gloves; routine venipuncture needs gloves only.', '{"row_label":"Scenario","rows":[{"id":"r1","text":"Suctioning a client with suspected active tuberculosis"},{"id":"r2","text":"Emptying the drainage bag of a client on contact precautions"},{"id":"r3","text":"Performing venipuncture on a client under standard precautions"},{"id":"r4","text":"Irrigating a copiously draining wound with splash risk"}],"columns":[{"id":"c1","text":"Gown"},{"id":"c2","text":"N95 respirator"},{"id":"c3","text":"Gloves"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c1","c3"],"r3":["c3"],"r4":["c1","c3"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'PPE selection', NULL, 'Hard', 'Analyze', '{}', 8, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_352022', 'CLOZE', 'After a nurse sustains a needlestick from a used hollow-bore needle, the first action is to {1}, and the exposure must then be {2}.', 'The exposed site is washed with soap and water immediately, and the incident is reported at once so post-exposure prophylaxis can be started within the effective window.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"wash the site with soap and water"},{"id":"c2","text":"apply a tourniquet above the site"},{"id":"c3","text":"squeeze the site to expel blood vigorously"}]},{"id":"b2","choices":[{"id":"c1","text":"reported immediately for post-exposure evaluation"},{"id":"c2","text":"documented at the end of the shift only"},{"id":"c3","text":"ignored if the source client appears healthy"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Needlestick exposure', 'Post-exposure', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_352023', 'HIGHLIGHT', 'The nurse reviews the pre-procedure checklist before a right total knee replacement. Highlight the findings that must be resolved before the incision. The [[surgical site is unmarked]]. The [[signed consent specifies the left knee]]. [[Two client identifiers are verified]]. The [[antibiotic prophylaxis has not been given]]. The [[imaging is displayed in the room]]. The [[allergy band lists a latex allergy but latex gloves are on the field]].', 'Unmarked site, mismatched consent, missing prophylaxis, and a latex hazard are all safety failures that must be resolved before incision; the verified identifiers and displayed imaging are correct.', '{"chunks":[{"id":"h1","text":"surgical site is unmarked"},{"id":"h2","text":"signed consent specifies the left knee"},{"id":"h3","text":"antibiotic prophylaxis has not been given"},{"id":"h4","text":"allergy band lists a latex allergy but latex gloves are on the field"},{"id":"h5","text":"Two client identifiers are verified"},{"id":"h6","text":"imaging is displayed in the room"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h4"],"feedback":{"h1":"Site marking is mandatory before incision to prevent wrong-site surgery.","h2":"Consent conflicts with the planned right-knee procedure and must be reconciled.","h3":"Prophylactic antibiotics should be given within the pre-incision window.","h4":"Latex on the field endangers a latex-allergic client and must be corrected.","h5":"Correct identifier verification is a normal finding, not a hazard.","h6":"Displayed imaging is appropriate and needs no follow-up."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Surgical safety', 'Time-out', 'Hard', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_352024', 'BOWTIE', 'A client with a central venous catheter develops fever and erythema at the insertion site. Complete the diagram by selecting the priority problem, actions to take, and parameters to monitor.', 'Fever with site erythema suggests a CLABSI; the nurse notifies the provider, obtains cultures, maintains asepsis, and monitors temperature, WBC, and the insertion site.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Notify the provider and obtain blood cultures"},{"id":"lt2","text":"Perform hand hygiene and use aseptic technique for line care"},{"id":"lt3","text":"Flush the line briskly to clear any occlusion"},{"id":"lt4","text":"Apply warm soaks and continue infusing"}]},"centre":{"label":"Priority problem","tokens":[{"id":"ct1","text":"Central line-associated bloodstream infection"},{"id":"ct2","text":"Air embolism"},{"id":"ct3","text":"Infiltration"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Temperature and white blood cell count"},{"id":"rt2","text":"Insertion-site appearance"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Pupillary response"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Central line infection', 'CLABSI prevention', 'Hard', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_352025', 'DRAG_CLOZE', 'A nurse receives an order reading ''give insulin 10u IV push now.'' Before acting the nurse recognizes the abbreviation [1] as error-prone and identifies insulin as a [2] medication requiring an independent double-check.', 'The abbreviation ''u'' is on the do-not-use list because it can be misread as a zero, and insulin is a high-alert drug requiring an independent double-check before administration.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"u for units"},{"id":"t2","text":"high-alert"},{"id":"t3","text":"low-risk"},{"id":"t4","text":"as-needed"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Treatment-order verification', 'High-alert medications', 'Hard', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_352026', 'DRAG_ORDER', 'A nurse discovers flames coming from an electrical device in an occupied client room. Place the nurse''s actions in the correct RACE priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"}],"tokens":[{"id":"t1","text":"Rescue clients in immediate danger from the room"},{"id":"t2","text":"Activate the alarm and call for help"},{"id":"t3","text":"Confine the fire by closing doors and windows"},{"id":"t4","text":"Extinguish the fire or evacuate using the extinguisher"},{"id":"t5","text":"Complete the incident report"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Emergency response', 'Electrical fire (RACE)', 'Hard', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP')
